// Sealed allocation (amendment of 2026-09-29): a randomisation list from
// lib/trial-tools.mjs put behind a seal, revealed one participant at a time,
// with every reveal and every unblinding written to a hash-chained audit log.
//
// What the seal is: each position carries a SHA-256 commitment to its arm (a
// secret salt, the stratum, the position and the arm), and the list's seed
// is kept only as a hash. The arms themselves sit in the allocation's `vault`
// in the project, because a local app has no one else to hold them; the
// vault is kept out of every view (publicAllocation) and the commitments show
// if it was edited. This is allocation concealment against a look over the
// shoulder and tamper evidence, not cryptographic secrecy from the project's
// owner, who can read the file.
//
// Deterministic and offline: the same list and seed give the same seal.
// State shape (mutated in place by the functions that take `state`):
//   state.allocations = [allocation], state.allocationLog = [entry]
import { randomisationList } from './trial-tools.mjs';
import { enrolmentIssues } from './trial-operations.mjs';

// ---- SHA-256 (synchronous, so a reveal needs no await) ------------------------------
const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2]);
/** SHA-256 of a text (UTF-8), as lowercase hex. */
export function sha256(message) {
  const bytes = new TextEncoder().encode(String(message));
  const len = bytes.length, total = ((len + 9 + 63) >> 6) << 6;
  const buf = new Uint8Array(total);
  buf.set(bytes); buf[len] = 0x80;
  const bits = len * 8;
  const view = new DataView(buf.buffer);
  view.setUint32(total - 8, Math.floor(bits / 2 ** 32)); view.setUint32(total - 4, bits >>> 0);
  const h = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const w = new Uint32Array(64);
  const rot = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < total; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rot(w[i - 15], 7) ^ rot(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = rot(w[i - 2], 17) ^ rot(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rot(e, 6) ^ rot(e, 11) ^ rot(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((rot(a, 2) ^ rot(a, 13) ^ rot(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h[0] += a; h[1] += b; h[2] += c; h[3] += d; h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
  }
  return [...h].map(x => x.toString(16).padStart(8, '0')).join('');
}

// ---- sealing -----------------------------------------------------------------------------------
const commit = (salt, stratum, position, arm) => sha256(`${salt}\u0000${stratum}\u0000${position}\u0000${arm}`);

/**
 * Seals a randomisation list (from randomisationList): returns
 *   { id, createdAt, createdBy, blinded, arms, strata, seedHash,
 *     entries: [{ stratum, position, block, hash, participantId?, arm?, code?, at?, by? }],
 *     vault: { seed, salts: [..], arms: [..] } }
 * Entries are numbered from 1 within each stratum. `blinded` allocations
 * reveal a pack code at allocation and the arm only on unblinding.
 */
export function sealAllocation(list, { id = null, at = null, by = '', blinded = false } = {}) {
  if (!list?.rows?.length) throw new Error('The randomisation list is empty');
  const seed = String(list.seed);
  const aid = id || `alloc${sha256(`${seed}\u0000${list.rows.length}\u0000${list.arms.join('|')}`).slice(0, 10)}`;
  const counter = {};
  const salts = [], arms = [];
  const entries = list.rows.map((r, i) => {
    const stratum = String(r.stratum ?? ''), position = (counter[stratum] = (counter[stratum] || 0) + 1);
    const salt = sha256(`salt\u0000${seed}\u0000${aid}\u0000${i}`);
    salts.push(salt); arms.push(r.arm);
    return { stratum, position, block: r.block, hash: commit(salt, stratum, position, r.arm) };
  });
  return {
    id: aid,
    createdAt: at || new Date().toISOString(),
    createdBy: by,
    blinded: !!blinded,
    arms: [...list.arms],
    weights: [...(list.weights || [])],
    blockSizes: [...(list.blockSizes || [])],
    strata: Object.keys(counter),
    size: entries.length,
    seedHash: sha256(`seed\u0000${seed}`),
    entries,
    vault: { seed, salts, arms },
  };
}

/** Builds the list (trial-tools) and seals it in one step. */
export const createSealedAllocation = (settings, options) => sealAllocation(randomisationList(settings), options);

/** The allocation without its vault, and with arms hidden where not yet revealed or, if blinded, not unblinded. */
export function publicAllocation(a) {
  if (!a) return null;
  const { vault, ...rest } = a;
  return { ...rest, entries: a.entries.map(e => ({ ...e })) };
}

/** Whether every entry's commitment matches its vault arm, and the seed its hash: { ok, problems }. */
export function verifySeal(a) {
  const problems = [];
  if (sha256(`seed\u0000${a.vault.seed}`) !== a.seedHash) problems.push('The seed does not match its hash');
  a.entries.forEach((e, i) => {
    if (commit(a.vault.salts[i], e.stratum, e.position, a.vault.arms[i]) !== e.hash) problems.push(`Position ${e.position}${e.stratum ? ` in ${e.stratum}` : ''} does not match its seal`);
    if (e.arm != null && e.arm !== a.vault.arms[i]) problems.push(`Position ${e.position}${e.stratum ? ` in ${e.stratum}` : ''} was revealed as a different arm`);
  });
  return { ok: !problems.length, problems };
}

/** Whether the list the seal came from is reproduced by these settings (for an audit, after the trial). */
export function matchesList(a, list) {
  return list?.rows?.length === a.size && list.rows.every((r, i) => r.arm === a.vault.arms[i] && String(r.stratum ?? '') === a.entries[i].stratum);
}

// ---- the audit log (hash-chained) -------------------------------------------------------------------
function log(state, entry) {
  const all = (state.allocationLog ||= []);
  const prev = [...all].reverse().find(e => e.allocationId === entry.allocationId)?.hash || '';
  const seq = all.filter(e => e.allocationId === entry.allocationId).length + 1;
  const body = { seq, ...entry, prev };
  const e = { ...body, hash: sha256(JSON.stringify(body)) };
  all.push(e);
  return e;
}

/** An allocation's log, oldest first. */
export const auditTrail = (state, allocationId) => (state?.allocationLog || []).filter(e => e.allocationId === allocationId);

/** Whether the log's chain is intact: { ok, brokenAt } (the seq of the first entry that does not follow). */
export function verifyAudit(state, allocationId) {
  let prev = '';
  for (const e of auditTrail(state, allocationId)) {
    const { hash, ...body } = e;
    if (body.prev !== prev || sha256(JSON.stringify(body)) !== hash) return { ok: false, brokenAt: e.seq };
    prev = hash;
  }
  return { ok: true, brokenAt: null };
}

const allocationById = (state, id) => (state?.allocations || []).find(a => a.id === id) || null;

/** Adds a sealed allocation to state.allocations and logs its creation. */
export function addAllocation(state, a, { by = a.createdBy, at = a.createdAt } = {}) {
  if (allocationById(state, a.id)) return { ok: false, error: 'An allocation with this id exists' };
  (state.allocations ||= []).push(a);
  log(state, { allocationId: a.id, action: 'seal', size: a.size, strata: a.strata, seedHash: a.seedHash, by, at });
  return { ok: true };
}

/**
 * Reveals the next allocation in a stratum for one participant and logs it.
 * Returns { ok: true, arm | code, position, stratum } — `arm` when the
 * allocation is open, `code` (a pack code) when blinded — or { ok: false, error }.
 * A participant is allocated once; a second call returns the first result
 * with `repeat: true` and is logged as a repeat request.
 */
export function allocateNext(state, allocationId, { participantId, stratum = '', by = '', at = null } = {}) {
  const a = allocationById(state, allocationId);
  if (!a) return { ok: false, error: 'No such allocation' };
  const pid = String(participantId ?? '').trim();
  if (!pid) return { ok: false, error: 'A participant id is required' };
  const when = at || new Date().toISOString();
  const shown = e => a.blinded ? { code: e.code } : { arm: e.arm };
  const prior = a.entries.find(e => e.participantId === pid);
  if (prior) {
    log(state, { allocationId, action: 'repeat', participantId: pid, stratum: prior.stratum, position: prior.position, by, at: when });
    return { ok: true, repeat: true, ...shown(prior), position: prior.position, stratum: prior.stratum };
  }
  if (state.project?.researchType === 'rct') {
    const issues = enrolmentIssues(state, pid, when);
    if (issues.length) return { ok: false, error: issues.join('; ') };
  }
  const st = String(stratum ?? '');
  if (!a.strata.includes(st)) return { ok: false, error: `No stratum '${st}' in this allocation` };
  const i = a.entries.findIndex(e => e.stratum === st && !e.participantId);
  if (i < 0) return { ok: false, error: `The list for ${st ? `stratum ${st}` : 'this allocation'} is used up` };
  const e = a.entries[i], arm = a.vault.arms[i];
  if (commit(a.vault.salts[i], e.stratum, e.position, arm) !== e.hash) return { ok: false, error: `Position ${e.position} does not match its seal; the allocation may have been edited` };
  Object.assign(e, { participantId: pid, by, at: when });
  if (a.blinded) e.code = `${a.id}-${st ? `${st}-` : ''}${String(e.position).padStart(3, '0')}`;
  else e.arm = arm;
  log(state, { allocationId, action: 'allocate', participantId: pid, stratum: st, position: e.position, ...(a.blinded ? { code: e.code } : { arm }), by, at: when });
  return { ok: true, ...shown(e), position: e.position, stratum: st };
}

/**
 * Reveals a participant's arm (emergency or planned unblinding); a reason is
 * required and logged with who and when. Returns { ok, arm } or { ok: false, error }.
 */
export function unblind(state, participantId, { reason = '', by = '', at = null, allocationId = null } = {}) {
  const pid = String(participantId ?? '').trim();
  const why = String(reason).trim();
  if (!why) return { ok: false, error: 'A reason for unblinding is required' };
  for (const a of state?.allocations || []) {
    if (allocationId && a.id !== allocationId) continue;
    const i = a.entries.findIndex(e => e.participantId === pid);
    if (i < 0) continue;
    const e = a.entries[i], arm = a.vault.arms[i];
    if (commit(a.vault.salts[i], e.stratum, e.position, arm) !== e.hash) return { ok: false, error: 'The allocation does not match its seal' };
    e.arm = arm; e.unblinded = true;
    log(state, { allocationId: a.id, action: 'unblind', participantId: pid, stratum: e.stratum, position: e.position, arm, reason: why, by, at: at || new Date().toISOString() });
    return { ok: true, arm, allocationId: a.id };
  }
  return { ok: false, error: 'The participant has no allocation' };
}

/** Counts by stratum: { [stratum]: { size, allocated, remaining } }, and revealed arms. */
export function allocationStatus(a) {
  const out = {};
  for (const e of a.entries) {
    const s = (out[e.stratum] ||= { size: 0, allocated: 0, remaining: 0 });
    s.size++; if (e.participantId) s.allocated++; else s.remaining++;
  }
  const arms = {};
  for (const e of a.entries) if (e.arm != null) arms[e.arm] = (arms[e.arm] || 0) + 1;
  return { strata: out, revealedArms: arms };
}

// App-wide settings (plan §6.2a): a person's name and initials, model connections with keys, the PubMed contact and key, and the Sent log
// (plan §3.3) belong to them, not to one review. Kept once per installation: in the desktop app a private file (src-tauri/src/app_settings.rs,
// mode 0600, written atomically), in a browser one IndexedDB record. Never in a project file, backup, recovery copy, export or MCP answer.
// A project reads them through settingsOf(state): app-wide first, then what the project holds of its own, which wins. adoptFrom() moves what an
// older version kept per project into the store the first time it opens, without touching the project file; `adopted` remembers what it took.
import { loadChatGptAccounts } from './chatgpt.mjs';
import { inDesktop, readAppSettingsNative, writeAppSettingsNative } from './native.mjs';

export const SCALARS = ['reviewerName', 'reviewerInitials', 'ncbiEmail', 'ncbiKey'];
/** The shell's limits (app_settings.rs). */
export const LIMITS = { reviewerName: 200, reviewerInitials: 32, ncbiEmail: 254, ncbiKey: 512, openalexKey: 512, braveKey: 512, tinyfishKey: 512, zoteroUserId: 32, zoteroKey: 64,
  provider: 64, base: 2048, key: 512, workspaceId: 128, model: 256, label: 200, id: 64, listed: 256,
  profiles: 64, models: 2000, tasks: 32, task: 64, adoptedFields: 128, adoptedValues: 16, adopted: 512, adoptedName: 96, sent: 1000, excerpt: 200 };

const DB = 'lykos-app', STORE = 'state', RECORD = 'settings';

const emptyValues = () => ({ format: 1, reviewerName: '', reviewerInitials: '', ncbiEmail: '', ncbiKey: '', openalexKey: '', braveKey: '', tinyfishKey: '', zoteroUserId: '', zoteroKey: '',
  ai: null, models: { profiles: [], tasks: {}, jevDerived: false }, adopted: {}, sentLog: [] });

const str = (v, max) => (typeof v === 'string' ? v : '').replace(/\0/g, '').slice(0, max);
const own = v => typeof v === 'string' && v.trim() !== '';
const baseOf = b => String(b || '').trim().replace(/\/+$/, '');

function cleanProfile(p) {
  if (!p || typeof p !== 'object' || Array.isArray(p)) return null;
  const id = str(p.id, LIMITS.id);
  if (!id) return null;
  const out = { id };
  for (const [k, max] of [['label', LIMITS.label], ['provider', LIMITS.provider], ['base', LIMITS.base], ['key', LIMITS.key], ['workspaceId', LIMITS.workspaceId], ['model', LIMITS.model]])
    if (p[k] != null) out[k] = str(p[k], max);
  if (Array.isArray(p.models)) out.models = p.models.filter(x => typeof x === 'string').slice(0, LIMITS.models).map(x => str(x, LIMITS.listed));
  for (const k of ['keyEdited', 'keyInherited']) if (typeof p[k] === 'boolean') out[k] = p[k];
  // the data classes allowed for a host (lib/egress.mjs)
  if (p.sends && typeof p.sends === 'object' && Array.isArray(p.sends.classes)) out.sends = { host: str(p.sends.host, 256), classes: p.sends.classes.filter(x => typeof x === 'string').slice(0, 8).map(x => str(x, 16)) };
  return out;
}
const cleanSent = e => {
  if (!e || typeof e !== 'object') return null;
  const o = { chars: Math.max(0, +e.chars || 0), parts: Math.max(0, +e.parts || 0), classes: [].concat(e.classes || []).slice(0, 8).map(x => str(x, 16)), excerpt: str(e.excerpt, LIMITS.excerpt) };
  for (const k of ['id', 'at', 'profileId', 'connection', 'provider', 'host', 'route', 'model', 'kind', 'hash']) o[k] = str(e[k], 256);
  return o.id && o.at ? o : null;
};
const cleanAi = a => a && typeof a === 'object' && !Array.isArray(a)
  ? { provider: str(a.provider, LIMITS.provider), base: str(a.base, LIMITS.base), key: str(a.key, LIMITS.key), model: str(a.model, LIMITS.model) } : null;

/** A settings document reduced to the whitelist the shell accepts, every value clamped to its limit. */
export function sanitize(doc) {
  const d = doc && typeof doc === 'object' && !Array.isArray(doc) ? doc : {};
  const out = emptyValues();
  for (const k of SCALARS) out[k] = str(d[k], LIMITS[k]);
  for (const k of ['openalexKey', 'braveKey', 'tinyfishKey', 'zoteroUserId', 'zoteroKey']) out[k] = str(d[k], LIMITS[k]);
  const ai = cleanAi(d.ai);
  out.ai = ai && (ai.provider || ai.key || ai.base || ai.model) ? ai : null;
  const seen = new Set();
  for (const p of (Array.isArray(d.models?.profiles) ? d.models.profiles : []).slice(0, LIMITS.profiles)) {
    const c = cleanProfile(p);
    if (c && !seen.has(c.id)) { seen.add(c.id); out.models.profiles.push(c); }
  }
  for (const [t, id] of Object.entries(d.models?.tasks && typeof d.models.tasks === 'object' ? d.models.tasks : {}).slice(0, LIMITS.tasks))
    if (/^[A-Za-z0-9_-]{1,32}$/.test(t) && own(id)) out.models.tasks[t] = str(id, LIMITS.task);
  out.models.jevDerived = d.models?.jevDerived === true;
  for (const [f, list] of Object.entries(d.adopted && typeof d.adopted === 'object' && !Array.isArray(d.adopted) ? d.adopted : {}).slice(0, LIMITS.adoptedFields))
    if (f && f.length <= LIMITS.adoptedName && Array.isArray(list))
      out.adopted[f] = list.filter(x => typeof x === 'string').slice(-LIMITS.adoptedValues).map(x => str(x, LIMITS.adopted));
  out.sentLog = (Array.isArray(d.sentLog) ? d.sentLog : []).slice(0, LIMITS.sent).map(cleanSent).filter(Boolean);
  return out;
}

// ---- the store
let values = emptyValues();
let ready = false;       // read (or found unreadable)
let loadError = '';      // why it could not be read; saving is then refused
let saveFailure = '';
let durable = true;      // what is in memory has been written
let loading = null;
let timer = null, inflight = null, changes = 0;
const listeners = new Set();
const emit = () => { for (const l of listeners) l(); };
export const onAppSettings = fn => { listeners.add(fn); return () => listeners.delete(fn); };

/** Where the values are kept: the desktop file, browser storage, or nowhere (a test run). */
export const appSettingsWhere = () => inDesktop() ? 'app' : typeof indexedDB !== 'undefined' ? 'browser' : 'memory';
export const appSettingsStatus = () => ({ ready, error: loadError || saveFailure, readOnly: Boolean(loadError), durable, where: appSettingsWhere() });
/** The stored values. Read only: change them through updateApp. */
export const appValues = () => values;

let idb = null;
const openDb = () => idb ||= new Promise((resolve, reject) => {
  const req = indexedDB.open(DB, 1);
  req.onupgradeneeded = () => req.result.createObjectStore(STORE);
  req.onsuccess = () => { req.result.onclose = () => { idb = null; }; resolve(req.result); };
  req.onerror = () => { idb = null; reject(req.error); };
});
const idbOp = (mode, fn) => openDb().then(d => new Promise((resolve, reject) => {
  const t = d.transaction(STORE, mode), r = fn(t.objectStore(STORE));
  t.oncomplete = () => resolve(r?.result);
  t.onerror = () => reject(t.error);
}));
const readStored = async () => inDesktop() ? readAppSettingsNative()
  : typeof indexedDB !== 'undefined' ? idbOp('readonly', s => s.get(RECORD)) : null;
const writeStored = doc => inDesktop() ? writeAppSettingsNative(doc)
  : typeof indexedDB !== 'undefined' ? idbOp('readwrite', s => s.put(doc, RECORD)) : Promise.resolve();

/** Reads the stored values once; an unreadable storage leaves them empty and read only. */
export function loadAppSettings() {
  return loading ||= (async () => {
    const early = values.sentLog;
    try { values = sanitize(await readStored()); loadError = ''; }
    catch (e) { values = emptyValues(); loadError = String(e?.message || e || 'unreadable').slice(0, 160); }
    if (early.length) { values.sentLog = mergeSent(early, values.sentLog); if (!loadError) { changes++; schedule(); } }
    try { await loadChatGptAccounts(); } catch {}
    ready = true; durable = true;
    emit();
  })();
}

// Another browser window saved the record: taken unless this one has edits waiting.
const chan = typeof BroadcastChannel !== 'undefined' ? new BroadcastChannel('lykos-app-settings') : null;
chan?.unref?.();
chan?.addEventListener('message', async () => {
  if (!ready || loadError || timer || inflight) return;
  try { const next = sanitize(await readStored()); if (!timer && !inflight) { values = next; emit(); } } catch {}
});

async function write() {
  timer = null;
  if (loadError) return;
  const at = changes;
  try {
    await writeStored(structuredClone(values));
    saveFailure = '';
    if (at === changes) durable = true;
    if (!inDesktop()) chan?.postMessage(at);
  } catch (e) {
    saveFailure = String(e?.message || e || 'not saved').slice(0, 160);
  }
  emit();
}
function schedule() {
  durable = false;
  if (timer) return;
  timer = setTimeout(() => { inflight = write().finally(() => { inflight = null; }); }, 250);
  timer?.unref?.();
}
/** Writes what is waiting; resolves once the storage answered. */
export async function flushAppSettings() {
  if (timer) { clearTimeout(timer); timer = null; inflight = write().finally(() => { inflight = null; }); }
  await inflight;
}
if (typeof addEventListener === 'function' && typeof document !== 'undefined') {
  addEventListener('pagehide', () => { if (timer) flushAppSettings(); });
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden' && timer) flushAppSettings(); });
}

/** Changes the app-wide values: `fn` receives a working copy and edits it. */
export function updateApp(fn) {
  if (loadError) throw new Error('App-wide settings could not be read, so they are not changed');
  const next = structuredClone(values);
  fn(next);
  values = sanitize(next);
  changes++;
  schedule();
  emit();
}

// ---- the Sent log (lib/sent-log.mjs; never in a project)
const mergeSent = (a, b) => [...new Map([...a, ...b].map(e => [e.id, e])).values()].sort((x, y) => (y.at > x.at) - (y.at < x.at)).slice(0, LIMITS.sent);
export const appSent = () => values.sentLog;
/** Replaces the log; unread or unreadable storage keeps it in memory only. */
export function setSent(list) {
  values.sentLog = (list || []).slice(0, LIMITS.sent).map(cleanSent).filter(Boolean);
  if (ready && !loadError) { changes++; schedule(); }
  emit();
}
export const adoptSent = list => setSent(mergeSent(values.sentLog, [].concat(list || []).map(cleanSent).filter(Boolean)));

/** Test seam. */
export function resetAppSettings() {
  clearTimeout(timer); timer = null; inflight = null;
  values = emptyValues(); ready = false; loadError = ''; saveFailure = ''; durable = true; loading = null; idb = null; changes = 0;
}

// ---- layers: app-wide, then the project
const adoptedHas = (field, v) => (values.adopted[field] || []).includes(v);
const note = (field, v) => {
  if (!v) return;
  const list = values.adopted[field] ||= [];
  if (list.includes(v)) return;
  list.push(v);
  if (list.length > LIMITS.adoptedValues) list.shift();
  if (Object.keys(values.adopted).length > LIMITS.adoptedFields) delete values.adopted[Object.keys(values.adopted)[0]];
};
const connection = p => `${p.provider || ''}|${baseOf(p.base)}|${p.model || ''}`;
/** A project's leftover copy of a connection the store holds (same endpoint and model, or the one it took; no key of its own, or the one it took): it follows the app-wide profile. */
const staleCopy = (app, mine, keyField, connField) => (connection(app) === connection(mine) || (connField && adoptedHas(connField, connection(mine))))
  && (!mine.key || mine.key === app.key || adoptedHas(keyField, mine.key));
const profileKeyField = id => `profileKey:${id}`;
const profileConnField = id => `profile:${id}`;

/** The value a project reads for one of the four plain settings. */
function scalar(k, mine) {
  const app = values[k] || '';
  return !own(mine) || mine === app || adoptedHas(k, mine) ? app : mine;
}

/** The profiles a project sees, with where each came from: 'app', 'override' (this project holds a different one under the same id) or 'project'. */
export function layers(state) {
  const mine = state?.settings || {};
  const mineProfiles = (Array.isArray(mine.models?.profiles) ? mine.models.profiles : []).filter(p => p && p.id);
  const merged = values.models.profiles.slice();
  const origin = new Map(merged.map(p => [p.id, 'app']));
  for (const pp of mineProfiles) {
    const at = merged.findIndex(x => x.id === pp.id);
    if (at < 0) { merged.push(pp); origin.set(pp.id, 'project'); continue; }
    if (origin.get(pp.id) !== 'app' || staleCopy(merged[at], pp, profileKeyField(pp.id), profileConnField(pp.id))) continue;
    merged[at] = pp; origin.set(pp.id, 'override');
  }
  // a pre-profiles project's one connection is a profile of its own beside app-wide ones
  const legacy = mine.ai;
  if (own(legacy?.provider) && !mineProfiles.length && merged.length) {
    const covered = merged.some(p => staleCopy(p, legacy, 'aiKey', 'aiConn'));
    if (!covered) {
      const id = merged.some(p => p.id === 'p1') ? 'legacy-project' : 'p1';
      merged.push({ id, label: legacy.model || legacy.provider, ...legacy }); origin.set(id, 'project');
    }
  }
  const tasks = { ...values.models.tasks };
  const pinned = [];
  for (const [t, id] of Object.entries(mine.models?.tasks || {})) {
    if (!own(id) || id === tasks[t] || adoptedHas(`task:${t}`, id)) continue;
    tasks[t] = id; pinned.push(t);
  }
  return { profiles: merged, origin, tasks, pinned };
}

/** The settings a project reads (the shape of project.settings): app-wide values, then the project's own over them. */
export function settingsOf(state) {
  const mine = state?.settings || {};
  const out = { ...mine };
  for (const k of SCALARS) out[k] = scalar(k, mine[k]);
  out.braveKey = values.braveKey || '';
  out.tinyfishKey = values.tinyfishKey || '';
  out.openalexKey = values.openalexKey || '';
  const { profiles, tasks } = layers(state);
  out.models = { ...(mine.models || {}), profiles, tasks, jevDerived: Boolean(mine.models?.jevDerived || values.models.jevDerived) };
  const app = values.ai?.provider ? values.ai : null;
  out.ai = own(mine.ai?.provider) && !(app && staleCopy(app, mine.ai, 'aiKey', 'aiConn')) ? mine.ai : (app || mine.ai);
  if (out.ai === undefined) delete out.ai;
  return out;
}

/** What this project holds of its own that differs from the app-wide value. */
export function overridesOf(state) {
  const mine = state?.settings || {};
  const { origin, pinned } = layers(state);
  const app = values.ai?.provider ? values.ai : null;
  return {
    scalars: SCALARS.filter(k => own(mine[k]) && mine[k] !== (values[k] || '') && !adoptedHas(k, mine[k])),
    profiles: [...origin].filter(([, o]) => o !== 'app').map(([id, o]) => ({ id, kind: o })),
    tasks: pinned,
    ai: own(mine.ai?.provider) && Boolean(app) && !staleCopy(app, mine.ai, 'aiKey', 'aiConn'),
  };
}

/** The project's settings with one override dropped. */
export function withoutOverride(settings, what) {
  const s = { ...(settings || {}) };
  if (SCALARS.includes(what)) delete s[what];
  else if (what === 'ai') delete s.ai;
  else if (what.startsWith('task:') && s.models) { const tasks = { ...(s.models.tasks || {}) }; delete tasks[what.slice(5)]; s.models = { ...s.models, tasks }; }
  else if (what.startsWith('profile:') && s.models) s.models = { ...s.models, profiles: (s.models.profiles || []).filter(p => p.id !== what.slice(8)) };
  return s;
}

/** A project's own value, put there on purpose, is no longer a leftover copy: forget it as such. */
export function pinOverride(field, value) {
  if (!adoptedHas(field, value) || loadError) return;
  updateApp(v => { v.adopted[field] = (v.adopted[field] || []).filter(x => x !== value); });
}

// ---- moving what a project holds into the app-wide store
/** First run on a project: its name, initials, PubMed contact and key, connections (with keys) and task assignments fill app-wide values that are empty. Nothing app-wide is replaced; a differing project value stays as an override. Answers whether the store changed; the project is not touched. */
export function adoptFrom(mine) {
  if (!ready || loadError || !mine || typeof mine !== 'object') return false;
  const before = JSON.stringify(values);
  const v = values;
  for (const k of SCALARS) {
    const pv = str(mine[k], LIMITS[k]);
    if (!own(pv)) continue;
    if (!v[k] && !adoptedHas(k, pv)) v[k] = pv;
    if (v[k] === pv) note(k, pv);
  }
  const ai = cleanAi(mine.ai);
  if (ai && own(ai.provider)) {
    const sig = connection(ai);
    if (!v.ai?.provider && !adoptedHas('aiConn', sig)) v.ai = { ...ai };
    if (v.ai && connection(v.ai) === sig) {
      if (!v.ai.key && ai.key) v.ai = { ...v.ai, key: ai.key };
      if (ai.key && v.ai.key === ai.key) note('aiKey', ai.key);
      note('aiConn', sig);
    }
  }
  const profiles = (Array.isArray(mine.models?.profiles) ? mine.models.profiles : []).map(cleanProfile).filter(Boolean);
  const fresh = v.models.profiles.length === 0;
  for (const pp of profiles) {
    const at = v.models.profiles.findIndex(x => x.id === pp.id);
    if (at < 0) {
      if (fresh && v.models.profiles.length < LIMITS.profiles && !adoptedHas(`profile:${pp.id}`, connection(pp))) v.models.profiles.push(pp);
      else continue;
    }
    const ap = v.models.profiles.find(x => x.id === pp.id);
    if (connection(ap) !== connection(pp)) continue;    // a different profile under the same id: the project's own
    if (!ap.key && pp.key) ap.key = pp.key;
    if (pp.key && ap.key === pp.key) note(profileKeyField(pp.id), pp.key);
    note(`profile:${pp.id}`, connection(pp));
  }
  for (const [t, id] of Object.entries(mine.models?.tasks || {})) {
    if (!/^[A-Za-z0-9_-]{1,32}$/.test(t) || !own(id) || !v.models.profiles.some(p => p.id === id)) continue;
    if (!v.models.tasks[t] && !adoptedHas(`task:${t}`, id)) v.models.tasks[t] = str(id, LIMITS.task);
    if (v.models.tasks[t] === id) note(`task:${t}`, id);
  }
  if (mine.models?.jevDerived === true && v.models.profiles.length) v.models.jevDerived = true;
  const after = JSON.stringify(values);
  if (after === before) return false;
  changes++;
  schedule();
  emit();
  return true;
}

/** A project's settings as its record keeps them: a key that only repeats an app-wide one is dropped, once the store has written it. */
export function storableSettings(settings) {
  if (!ready || loadError || !durable || !settings) return settings;
  const s = { ...settings };
  if (s.ncbiKey && (s.ncbiKey === values.ncbiKey || adoptedHas('ncbiKey', s.ncbiKey))) delete s.ncbiKey;
  const app = values.ai?.provider ? values.ai : null;
  if (s.ai?.key && app && staleCopy(app, s.ai, 'aiKey', 'aiConn')) s.ai = { ...s.ai, key: '' };
  if (Array.isArray(s.models?.profiles)) s.models = { ...s.models, profiles: s.models.profiles.map(p => {
    const ap = p?.key || p?.workspaceId ? values.models.profiles.find(x => x.id === p.id) : null;
    if (!ap || !staleCopy(ap, p, profileKeyField(p.id), profileConnField(p.id))) return p;
    const { workspaceId, ...rest } = p;   // a workspace id is kept beside the key, so it leaves the project with it
    return { ...rest, key: '' };
  }) };
  return s;
}

export const maskKey = key => !key ? '' : key.length < 9 ? '••••' : `••••${key.slice(-4)}`;

// The appraisal view's glue for instruments the review team defines
// (lib/custom-instrument.mjs) and for the scores the shipped instruments
// define (lib/appraisal-extra.mjs). Pure: the view and the tests call it with
// the state.
//
// A custom instrument's questions are answered beside its domains, under the
// key `domain.question` in the same answers map, so they travel with the
// assessment (reviewers, levels, the mirror in s.assessments) without a
// second store. The domain judgement stays the reviewer's. With the "worst"
// rule the overall is the least favourable domain judgement, written as the
// overall answer whenever a domain changes, so every reader (list, figures,
// exports) sees it; "manual" leaves the overall to the reviewer.
import { allTools, customTools, APPRAISAL_TOOLS } from '../schema.mjs';
import { overallFrom, toolId, validate } from './custom-instrument.mjs';
import { scoreOf, agreeScores, mmatScreen } from './appraisal-extra.mjs';
import { setAnswer, OVERALL } from './rob-review.mjs';

const plain = v => v && typeof v === 'object' && !Array.isArray(v);

/** The stored list as a list of definitions: objects with an id, the first of each id kept. */
export function normalizeInstruments(list) {
  if (!Array.isArray(list)) return [];
  const seen = new Set();
  return list.filter(x => plain(x) && typeof x.id === 'string' && x.id.trim() && !seen.has(x.id) && seen.add(x.id));
}

/** Ids a definition may not take: the shipped instruments', and the project's others. */
export function reservedIds(s, own = '') {
  return [...APPRAISAL_TOOLS.map(t => t.id), ...(s?.customInstruments || []).map(i => String(i?.id || '')).filter(id => id && id !== own)];
}

const slug = t => String(t || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);

/** An unused instrument id from a name. */
export function freeId(s, name = '') {
  const taken = new Set(reservedIds(s).flatMap(id => [id, toolId(id)]));
  const base = slug(name) || 'instrument';
  for (let n = 1; ; n++) { const id = n === 1 ? base : `${base}-${n}`; if (!taken.has(id) && !taken.has(toolId(id))) return id; }
}

/** A new definition to edit: three ranked levels, one domain, the worst-domain overall. */
export const blankInstrument = s => ({
  id: freeId(s), name: '', design: '',
  judgements: ['Low', 'Some concerns', 'High'], unranked: [],
  domains: [{ id: 'd1', name: '', questions: [] }],
  overall: 'worst',
});

/** A copy under a free id, named as a copy. */
export function duplicateInstrument(s, inst) {
  const copy = structuredClone(inst);
  copy.name = `${String(inst.name || '').trim()} (copy)`;
  copy.id = freeId(s, copy.name);
  return copy;
}

/** Problems with a definition as it would be saved in this project. */
export const checkInstrument = (s, inst, own = '') => validate(inst, { reserved: reservedIds(s, own) });

/** Adds or replaces (by `own`, the id it was saved under) a definition; the caller has validated it. */
export function saveInstrument(st, inst, own = '') {
  const list = normalizeInstruments(st.customInstruments);
  const at = own ? list.findIndex(x => x.id === own) : -1;
  st.customInstruments = at >= 0 ? list.map((x, i) => (i === at ? inst : x)) : [...list, inst];
  return st;
}

/** Studies with answers under an instrument. */
export const studiesUsing = (s, id) => Object.entries(s.assessments || {}).filter(([, rec]) => rec && rec[toolId(id)] && Object.keys(rec[toolId(id)]).length).map(([pid]) => pid);

/** Removes a definition with every answer given under it, and every choice of it. */
export function removeInstrument(st, id) {
  const tid = toolId(id);
  st.customInstruments = normalizeInstruments(st.customInstruments).filter(x => x.id !== id);
  for (const rec of Object.values(st.assessments || {})) if (rec && typeof rec === 'object') delete rec[tid];
  for (const [pid, rec] of Object.entries(st.assessments || {})) if (!rec || !Object.keys(rec).length) delete st.assessments[pid];
  const records = st.robReview?.records || {};
  for (const [pid, byTool] of Object.entries(records)) { if (byTool) delete byTool[tid]; if (!byTool || !Object.keys(byTool).length) delete records[pid]; }
  if (st.appraisalTool === tid) delete st.appraisalTool;
  if (st.appraisalByStudy) {
    for (const [pid, t] of Object.entries(st.appraisalByStudy)) if (t === tid) delete st.appraisalByStudy[pid];
    if (!Object.keys(st.appraisalByStudy).length) delete st.appraisalByStudy;
  }
  return st;
}

// ---- answering ------------------------------------------------------------------

/** The key a question's answer is kept under. */
export const questionKey = (domainId, questionId) => `${domainId}.${questionId}`;

/** The overall a custom instrument's rule gives for these answers: a level, or '' (manual, none, incomplete). */
export function ruleOverall(tool, answers = {}) {
  if (!tool?.custom || tool.overallRule !== 'worst') return '';
  try { return overallFrom(answers, 'worst', tool).value || ''; } catch { return ''; }
}

/** The instrument ids a write keeps in the s.assessments mirror (every instrument, the project's own included). */
export const toolIdsOf = s => allTools(s).map(t => t.id);

/**
 * One reviewer's answer, and with the "worst" rule the overall that follows
 * from that reviewer's domain judgements at the same level.
 */
export function answerWith(st, tool, { paperId, level, who = 'a', domain, value }) {
  const toolIds = toolIdsOf(st);
  setAnswer(st, { paperId, toolId: tool.id, level, who, domain, value, toolIds });
  if (tool.custom && tool.overallRule === 'worst' && domain !== OVERALL && tool.domains.some(d => d.id === domain)) {
    const r = st.robReview?.records?.[paperId]?.[tool.id]?.[level];
    const mine = (who === 'b' ? r?.b : r?.a) || {};
    const next = ruleOverall(tool, mine);
    if ((mine[OVERALL] || '') !== next) setAnswer(st, { paperId, toolId: tool.id, level, who, domain: OVERALL, value: next, toolIds });
  }
  return st;
}

// ---- scores -------------------------------------------------------------------------

const pct = x => (x == null ? '' : `${x}%`);

/**
 * What an instrument's own scoring says about a study, as rows of
 * { label, value, note? } for the detail. `appraisals` is every appraiser's
 * answers (reviewers A and B with two), the first being the final ones used
 * for star and point totals. Null when the instrument defines no score and
 * no screening step.
 */
export function scoreRows(tool, appraisals = []) {
  const answers = appraisals[0] || {};
  if (tool?.id?.startsWith('mmat-')) {
    const m = mmatScreen(answers);
    return { title: 'Screening', rows: [{ label: 'S1 and S2', value: m.proceed ? 'Proceed' : m.failed.length ? 'Do not proceed' : 'Not answered', note: m.reason || 'No overall score: report each criterion' }] };
  }
  if (tool?.scoring === 'agree') {
    const list = appraisals.filter(a => a && Object.keys(a).length);
    const scores = agreeScores(list.length ? list : [answers]);
    const n = Math.max(1, list.length);
    return { title: 'Scaled domain scores', rows: scores.map(d => ({ label: `${d.domain}. ${d.name}`, value: d.complete ? pct(d.pct) : `${d.items} items`, note: d.complete ? `${d.obtained} of ${d.max} · ${n} ${n === 1 ? 'appraiser' : 'appraisers'}` : '' })) };
  }
  const sc = scoreOf(tool, answers);
  if (!sc) return null;
  if (tool.scoring === 'nos') {
    const third = sc.third === 'exposure' ? 'Exposure' : 'Outcome';
    return { title: 'Stars', rows: [
      { label: 'Total', value: `${sc.total} of ${sc.max}`, note: sc.complete ? '' : `${sc.unanswered} unanswered` },
      { label: 'Selection', value: `${sc.selection} of 4` },
      { label: 'Comparability', value: `${sc.comparability} of 2` },
      { label: third, value: `${sc[sc.third]} of 3` },
      ...(sc.convention ? [{ label: 'AHRQ convention', value: sc.convention, note: sc.conventionNote }] : []),
    ] };
  }
  if (tool.scoring === 'minors') {
    return { title: 'Points', rows: [{ label: 'Total', value: `${sc.total} of ${sc.max}`, note: `${sc.comparative ? 'Comparative' : 'Non-comparative'}${sc.complete ? '' : ` · ${sc.unanswered} unanswered`}` }] };
  }
  return null;
}

/** A short score for a list row or a grid cell, or ''. */
export function scoreMark(tool, answers = {}) {
  if (tool?.scoring === 'nos' || tool?.scoring === 'minors') {
    const sc = scoreOf(tool, answers);
    if (!sc || sc.unanswered) return '';
    return tool.scoring === 'nos' ? `${sc.total} of 9 stars` : `${sc.total} of ${sc.max}`;
  }
  return '';
}

export { customTools };

// Further appraisal instruments, in the APPRAISAL_TOOLS shape (schema.mjs),
// with the scoring each instrument itself defines.
//
// Licensing (plan H6): every item keeps the instrument's official name and
// numbering, and its wording here is our own short paraphrase — never the
// published question text, which a reviewer reads from the source linked on
// each instrument. No permission has been recorded for any of them.
//
// Scoring is applied only where the instrument defines it: Newcastle–Ottawa
// stars, MINORS points and AGREE II scaled domain scores. Anything beyond the
// instrument (the Newcastle–Ottawa good/fair/poor conversion) is labelled as
// a convention. MMAT, QUIPS, RoB 1 and the JBI checklists define no score, so
// none is computed (plan H3).
//
// Pure data and functions; no imports, so schema.mjs can import this file.

const YNU = ['Yes', 'No', 'Unclear', 'Not applicable'];
const YNC = ['Yes', 'No', "Can't tell"];
const JBI_SOURCE = { url: 'https://jbi.global/critical-appraisal-tools', note: 'Item numbers as in the JBI checklist (2017–2020 editions); labels are our own paraphrase; no licence stated, use questions go to JBI' };

const items = (list, { prefix = 'q', short = n => `Q${n}` } = {}) =>
  list.map((label, i) => ({ id: `${prefix}${i + 1}`, short: short(i + 1), label }));

// ---- Newcastle–Ottawa Scale ---------------------------------------------------
// Wells et al., OHRI. Selection (four items, one star each), comparability
// (one item, up to two stars) and outcome or exposure (three items, one star
// each): nine stars at most.

const STAR = 'Star', TWO = 'Two stars', NONE = 'No star';
const oneStar = (id, short, label, group) => ({ id, short, label, group, stars: 1, judgements: [STAR, NONE] });
const twoStar = (id, short, label, group) => ({ id, short, label, group, stars: 2, judgements: [TWO, STAR, NONE] });
const NOS_SOURCE = { url: 'https://www.ohri.ca/programs/clinical_epidemiology/oxford.asp', note: 'Item names and star allocation as in the scale; labels are our own paraphrase; the good/fair/poor conversion is a convention (AHRQ), not part of the scale' };

const nosCohort = {
  id: 'nos-cohort',
  name: 'Newcastle–Ottawa, cohort',
  design: 'Cohort studies',
  judgements: [TWO, STAR, NONE],
  source: NOS_SOURCE,
  overall: false,
  scoring: 'nos',
  domains: [
    oneStar('s1', 'S1', 'Selection · exposed cohort represents the target population', 'selection'),
    oneStar('s2', 'S2', 'Selection · non-exposed cohort drawn from the same source', 'selection'),
    oneStar('s3', 'S3', 'Selection · exposure ascertained from a secure record or interview', 'selection'),
    oneStar('s4', 'S4', 'Selection · outcome shown to be absent at the start', 'selection'),
    twoStar('c1', 'C1', 'Comparability · cohorts comparable on the key factor, and on another', 'comparability'),
    oneStar('o1', 'O1', 'Outcome · assessed independently, blind, or by record linkage', 'outcome'),
    oneStar('o2', 'O2', 'Outcome · follow-up long enough for outcomes to occur', 'outcome'),
    oneStar('o3', 'O3', 'Outcome · follow-up complete, or losses unlikely to bias', 'outcome'),
  ],
};

const nosCaseControl = {
  id: 'nos-case-control',
  name: 'Newcastle–Ottawa, case–control',
  design: 'Case–control studies',
  judgements: [TWO, STAR, NONE],
  source: NOS_SOURCE,
  overall: false,
  scoring: 'nos',
  domains: [
    oneStar('s1', 'S1', 'Selection · case definition adequate, independently validated', 'selection'),
    oneStar('s2', 'S2', 'Selection · cases consecutive or clearly representative', 'selection'),
    oneStar('s3', 'S3', 'Selection · controls drawn from the community', 'selection'),
    oneStar('s4', 'S4', 'Selection · controls free of the disease by history', 'selection'),
    twoStar('c1', 'C1', 'Comparability · cases and controls comparable on the key factor, and on another', 'comparability'),
    oneStar('e1', 'E1', 'Exposure · ascertained from a secure record or blinded interview', 'exposure'),
    oneStar('e2', 'E2', 'Exposure · same ascertainment for cases and controls', 'exposure'),
    oneStar('e3', 'E3', 'Exposure · non-response rate the same in both groups', 'exposure'),
  ],
};

const NOS_MAX = { selection: 4, comparability: 2, outcome: 3, exposure: 3 };
const starsOf = (d, v) => (v === TWO ? Math.min(2, d.stars) : v === STAR ? 1 : 0);

/**
 * Stars per Newcastle–Ottawa domain and in total. `third` is 'outcome' for a
 * cohort study and 'exposure' for a case–control study. `convention` is the
 * AHRQ good/fair/poor conversion — widely used, but not part of the scale —
 * and is '' until every item is answered.
 */
export function nosScore(tool, answers = {}) {
  const third = tool.id === 'nos-case-control' ? 'exposure' : 'outcome';
  const by = { selection: 0, comparability: 0, [third]: 0 };
  let unanswered = 0;
  for (const d of tool.domains) {
    const v = answers[d.id];
    if (!v) unanswered++;
    by[d.group] += starsOf(d, v);
  }
  const total = by.selection + by.comparability + by[third];
  const complete = unanswered === 0;
  return {
    selection: by.selection, comparability: by.comparability, [third]: by[third], third,
    total, max: 9, unanswered, complete,
    convention: complete ? nosConvention(by.selection, by.comparability, by[third]) : '',
    conventionNote: 'Good/fair/poor thresholds are the AHRQ convention, not part of the Newcastle–Ottawa Scale',
  };
}

/** The AHRQ conversion: good 3–4 / 1–2 / 2–3 stars; fair 2 / 1–2 / 2–3; poor otherwise. */
export function nosConvention(selection, comparability, third) {
  if (selection <= 1 || comparability === 0 || third <= 1) return 'Poor';
  return selection >= 3 ? 'Good' : 'Fair';
}

// ---- MINORS --------------------------------------------------------------------
// Slim et al. 2003: twelve items scored 0 (not reported), 1 (reported but
// inadequate) or 2 (reported and adequate). The first eight apply to every
// study (ideal 16); items 9–12 only to comparative studies (ideal 24).

const MINORS_LEVELS = ['Reported, adequate', 'Reported, inadequate', 'Not reported'];
const MINORS_POINTS = { 'Reported, adequate': 2, 'Reported, inadequate': 1, 'Not reported': 0 };
const minors = {
  id: 'minors',
  name: 'MINORS',
  design: 'Non-randomised surgical studies',
  judgements: [...MINORS_LEVELS, 'Not applicable'],
  source: { url: 'https://doi.org/10.1046/j.1445-2197.2003.02748.x', note: 'Slim et al. ANZ J Surg 2003;73:712–6. Item numbers and 0/1/2 scoring as published; labels are our own paraphrase' },
  overall: false,
  scoring: 'minors',
  domains: [
    'Aim of the study clearly stated',
    'Consecutive patients included',
    'Data collected prospectively',
    'Endpoints suit the aim',
    'Endpoint assessed without bias',
    'Follow-up long enough for the aim',
    'Loss to follow-up under 5%',
    'Study size calculated in advance',
    'Control group adequate · comparative only',
    'Groups contemporary · comparative only',
    'Groups equivalent at baseline · comparative only',
    'Statistical analysis adequate · comparative only',
  ].map((label, i) => ({ id: `q${i + 1}`, short: String(i + 1), label, comparative: i >= 8,
    judgements: i >= 8 ? [...MINORS_LEVELS, 'Not applicable'] : MINORS_LEVELS })),
};

/**
 * MINORS points. A study is comparative when `comparative` says so, or else
 * when any of items 9–12 has an answer other than "Not applicable". The
 * maximum is 16 for a non-comparative study and 24 for a comparative one.
 */
export function minorsScore(answers = {}, { comparative } = {}) {
  const comp = comparative ?? minors.domains.some(d => d.comparative && answers[d.id] && answers[d.id] !== 'Not applicable');
  const used = minors.domains.filter(d => comp || !d.comparative);
  let total = 0, unanswered = 0;
  const points = {};
  for (const d of used) {
    const v = answers[d.id];
    if (!(v in MINORS_POINTS)) { unanswered++; continue; }
    points[d.id] = MINORS_POINTS[v];
    total += MINORS_POINTS[v];
  }
  return { comparative: comp, total, max: used.length * 2, items: used.length, points, unanswered, complete: unanswered === 0 };
}

