    methods.push('AFe = (OR − 1)/OR', 'PAF from the exposed share of cases (Miettinen), interval on ln(1 − PAF) by the delta method (Greenland 1987)');
  } else {
    need(n1 > 0 && n0 > 0, 'epi2x2: both exposure groups need people');
