  out.rateDifference = { est: rd * per, se: se * per, lo: (rd - z * se) * per, hi: (rd + z * se) * per };
  out.method = 'rate ratio with exact interval by the conditional binomial (Clopper–Pearson); exact two-sided test as poisson.test; rate difference Wald; rates by Garwood';
  return out;
}

// ---- standardisation ------------------------------------------------------------

const eventsOf = s => (Array.isArray(s) ? s[0] : s.events);
const timeOf = s => (Array.isArray(s) ? s[1] : s.time ?? s.population ?? s.n);

/**
 * Directly standardised rate. stratumRates: [{ events, time }] per stratum
 * (time may be person-time or population); standardPopulation: the standard
 * weights in the same order. Fay–Feuer (1997) gamma interval.
 */
export function directStandardise(stratumRates, standardPopulation, { conf = 0.95, per = 1 } = {}) {
  need(stratumRates.length === standardPopulation.length && stratumRates.length > 0, 'directStandardise: one standard weight per stratum');
  const W = standardPopulation.reduce((s, v) => s + v, 0), w = standardPopulation.map(v => v / W);
  const x = stratumRates.map(eventsOf), t = stratumRates.map(timeOf);
  need(x.every(isCount) && t.every(v => v > 0), 'directStandardise: events ≥ 0 and time > 0 in every stratum');
  const crude = x.reduce((s, v) => s + v, 0) / t.reduce((s, v) => s + v, 0);
  const y = w.reduce((s, wi, i) => s + wi * x[i] / t[i], 0), V = w.reduce((s, wi, i) => s + (wi / t[i]) ** 2 * x[i], 0);
  const wm = Math.max(...w.map((wi, i) => wi / t[i])), al = (1 - conf) / 2;
  const lo = y > 0 ? V / (2 * y) * qchisq(al, 2 * y * y / V) : 0;
  const hi = (V + wm * wm) / (2 * (y + wm)) * qchisq(1 - al, 2 * (y + wm) ** 2 / (V + wm * wm));
  return { est: y * per, lo: lo * per, hi: hi * per, crude: crude * per, variance: V * per * per, per, method: 'direct standardisation; Fay–Feuer (1997) gamma interval' };
}

/** Standardised mortality (incidence) ratio O/E with the exact Poisson interval and test. */
export function smr(observed, expected, { conf = 0.95 } = {}) {
  need(isCount(observed) && expected > 0, 'smr: observed ≥ 0 and expected > 0');
  const [l, u] = poissonCi(observed, conf);
  return { observed, expected, est: observed / expected, lo: l / expected, hi: u / expected, p: poissonTest(observed, expected), method: 'SMR = O/E; exact Poisson interval on O (Garwood); exact two-sided test as poisson.test' };
}

/** Indirect standardisation: expected = Σ stratum population × standard rate, then smr(). */
export function indirectStandardise(observed, stratumPopulation, standardRates, { conf = 0.95 } = {}) {
  need(stratumPopulation.length === standardRates.length, 'indirectStandardise: one standard rate per stratum');
  const expected = stratumPopulation.reduce((s, n, i) => s + n * standardRates[i], 0);
  return smr(observed, expected, { conf });
}

// ---- calibration and decision curves -------------------------------------------------

/** Logistic regression y ~ [intercept] + [slope·x] + offset by IRLS; returns coefficients and their covariance. */
function logisticFit(y, x, { offset, slope = true }) {
  const n = y.length, k = slope ? 2 : 1; let beta = slope ? [0, 1] : [0];
  let info = null;
  for (let it = 0; it < 50; it++) {
    const g = new Array(k).fill(0), H = Array.from({ length: k }, () => new Array(k).fill(0));
    for (let i = 0; i < n; i++) {
      const eta = beta[0] + (slope ? beta[1] * x[i] : 0) + (offset ? offset[i] : 0), p = expit(eta), wt = p * (1 - p), row = slope ? [1, x[i]] : [1];
      for (let r = 0; r < k; r++) { g[r] += row[r] * (y[i] - p); for (let s = 0; s < k; s++) H[r][s] += wt * row[r] * row[s]; }
    }
    info = H;
    let step;
    if (k === 1) step = [g[0] / H[0][0]];
    else { const det = H[0][0] * H[1][1] - H[0][1] * H[1][0]; step = [(H[1][1] * g[0] - H[0][1] * g[1]) / det, (H[0][0] * g[1] - H[1][0] * g[0]) / det]; }
    beta = beta.map((b, r) => b + step[r]);
    if (step.every(s => Math.abs(s) < 1e-10)) break;
  }
  const covm = k === 1 ? [[1 / info[0][0]]] : (() => { const det = info[0][0] * info[1][1] - info[0][1] * info[1][0]; return [[info[1][1] / det, -info[0][1] / det], [-info[1][0] / det, info[0][0] / det]]; })();
  return { beta, cov: covm };
}

/**
 * Calibration of predicted risks against 0/1 outcomes. Intercept: calibration
 * in the large, logit(y) ~ offset(logit p) (0 is ideal). Slope: logit(y) ~ a +
 * b·logit p (1 is ideal). O:E with interval exp(ln(O/E) ± z/√O). Brier score,
 * scaled Brier 1 − Brier/(ȳ(1 − ȳ)), and `groups` equal-sized groups by
 * predicted risk with the observed proportion's Wilson interval.
 */
export function calibration(predicted, observed, { conf = 0.95, groups = 10 } = {}) {
  need(predicted.length === observed.length && predicted.length > 1, 'calibration: predicted and observed differ in length');
  need(observed.every(v => v === 0 || v === 1), 'calibration: observed must be 0 or 1');
  need(predicted.every(p => p >= 0 && p <= 1), 'calibration: predicted risks must lie in [0, 1]');
  const z = zOf(conf), n = predicted.length, eps = 1e-12;
  const lp = predicted.map(p => logit(Math.min(1 - eps, Math.max(eps, p))));
  const O = observed.reduce((s, v) => s + v, 0), E = predicted.reduce((s, v) => s + v, 0), ybar = O / n;
  const citl = logisticFit(observed, lp, { offset: lp, slope: false }), sl = logisticFit(observed, lp, { slope: true });
  const brier = predicted.reduce((s, p, i) => s + (p - observed[i]) ** 2, 0) / n;
  const ci = (b, v) => ({ est: b, se: Math.sqrt(v), lo: b - z * Math.sqrt(v), hi: b + z * Math.sqrt(v) });
  const order = predicted.map((_, i) => i).sort((i, j) => predicted[i] - predicted[j]), G = Math.min(groups, n), pts = [];
  for (let g = 0; g < G; g++) {
    const ids = order.slice(Math.round(g * n / G), Math.round((g + 1) * n / G)); if (!ids.length) continue;
    const x = ids.reduce((s, i) => s + observed[i], 0), [lo, hi] = wilson(x, ids.length, z);
    pts.push({ group: g + 1, n: ids.length, predicted: ids.reduce((s, i) => s + predicted[i], 0) / ids.length, observed: x / ids.length, lo, hi });
  }
  return {
    n, events: O, expected: E,
    intercept: ci(citl.beta[0], citl.cov[0][0]), slope: ci(sl.beta[1], sl.cov[1][1]), slopeIntercept: sl.beta[0],
    oe: { est: O / E, lo: O ? O / E * Math.exp(-z / Math.sqrt(O)) : 0, hi: O ? O / E * Math.exp(z / Math.sqrt(O)) : NaN },
    brier, brierScaled: ybar > 0 && ybar < 1 ? 1 - brier / (ybar * (1 - ybar)) : NaN,
    groups: pts,
    method: 'calibration intercept (offset logit p) and slope (on logit p) by IRLS logistic regression, Wald intervals; O:E with exp(±z/√O); Brier score; groups of equal size by predicted risk, Wilson intervals',
  };
}

/**
 * Net benefit at each threshold probability pt (Vickers & Elkin 2006):
 * TP/n − FP/n · pt/(1 − pt), a prediction ≥ pt counting as positive; treat all
 * is prevalence − (1 − prevalence)·pt/(1 − pt); treat none is 0.
 */
export function decisionCurve(predicted, observed, thresholds) {
  need(predicted.length === observed.length && predicted.length > 0, 'decisionCurve: predicted and observed differ in length');
  const ts = thresholds || Array.from({ length: 99 }, (_, i) => (i + 1) / 100);
  const n = predicted.length, prev = observed.reduce((s, v) => s + v, 0) / n;
  const rows = ts.filter(t => t > 0 && t < 1).map(t => {
    let tp = 0, fp = 0;
    for (let i = 0; i < n; i++) if (predicted[i] >= t) { if (observed[i]) tp++; else fp++; }
    const w = t / (1 - t);
    return { threshold: t, model: tp / n - fp / n * w, all: prev - (1 - prev) * w, none: 0, tp, fp };
  });
  return { n, prevalence: prev, rows, method: 'net benefit (Vickers & Elkin 2006); a prediction ≥ threshold is positive' };
}

// The house drawings of lib/clinical-plots.mjs (FIGURE-STYLE §2, F7): ROC, Fagan nomogram, calibration, decision curve
// and Bland-Altman plots, and the scatter / Q-Q plot of lib/dataset-analysis.mjs, as the figures draw them when given a
// `style` (figureTokens). L-shaped axes with ticks, no frame, no gridlines; curves told apart by dash and weight; a
// legend row under the plot instead of a key over the data; the note under the figure is the source block. Every colour
// and size is a token of the style; degenerate input (no points, NaN) answers a short note.
import { niceTicks, fmtNumber } from './output-charts.mjs';
import { faganPoints } from './clinical-epi.mjs';
import { svgRoot, text, measure, axisLine, r1, sourceBlock } from './figure-draw.mjs';
import { xyPlot, noteFigure, legendRows, lineSample, seriesStyle, strokeOf, dashOf, seg, pathOf, dot, tip, finite, fixed, widthOf, sourceOf, within } from './plot-draw.mjs';

const pct = p => `${Number((p * 100).toFixed(p < 0.01 || p > 0.99 ? 1 : 0))}%`;
const roundness = v => { const m = Math.round(v / 10 ** Math.floor(Math.log10(v) + 1e-9)); return m === 1 ? 0 : m === 5 ? 1 : 2; };
const probRoundness = p => (p === 0.5 ? -1 : roundness(Math.min(p, 1 - p)));
const unit = { lo: 0, hi: 1, ticks: [0, 0.2, 0.4, 0.6, 0.8, 1] };
const note = (t, o, message) => noteFigure(t, { title: o.title, message, width: o.width, kind: 'single', source: o.source });
const refAttrs = t => `class="c-axis" stroke="${t.color.axis}" stroke-width="${t.line.null}" stroke-dasharray="${dashOf(t)}"`;

/** Split a polyline where it leaves [lo, ∞) on y, cutting at the crossing. */
function clipBelow(pts, lo) {
  const runs = []; let cur = [];
  for (let i = 0; i < pts.length; i++) {
    const [x, y] = pts[i], prev = pts[i - 1];
    if (y >= lo) {
      if (prev && prev[1] < lo) cur.push([prev[0] + (x - prev[0]) * (lo - prev[1]) / (y - prev[1]), lo]);
      cur.push([x, y]);
    } else if (prev && prev[1] >= lo) {
      cur.push([prev[0] + (x - prev[0]) * (lo - prev[1]) / (y - prev[1]), lo]); runs.push(cur); cur = [];
    }
  }
  if (cur.length) runs.push(cur);
  return runs;
}

/** ROC curve(s): one small marker per threshold (data-threshold), the chance diagonal dashed, the AUC in the legend row. */
export function houseRoc(curves, o = {}) {
  const { style: t, title = 'ROC curve', cutoff = null } = o;
  const list = Array.isArray(curves) ? curves : [{ label: '', result: curves }];
  if (!list.length || list.some(c => !c.result?.points?.length || !c.result.points.every(p => finite(p.fpr, p.se)))) return note(t, { ...o, title }, 'Not drawn: there are no thresholds to plot.');
  const w = widthOf(t, o.width, 'single');
  const P = xyPlot(t, { width: w, plotH: w * 0.8, xdom: [0, 1], ydom: [0, 1], xticks: unit.ticks, yticks: unit.ticks, xLabel: '1 − specificity', yLabel: 'Sensitivity', title, source: [o.note, ...sourceOf(o.source)], desc: `ROC curve${list.length > 1 ? 's' : ''}, ${list.length} series`, seed: list.map(c => c.result.points.length).join() });
  const parts = [seg(P.X(0), P.Y(0), P.X(1), P.Y(1), refAttrs(t))];
  list.forEach(({ result }, k) => {
    parts.push(pathOf(result.points.map(p => [P.X(p.fpr), P.Y(p.se)]), strokeOf(seriesStyle(t, k))));
    for (const p of result.points) {
      const th = Number.isFinite(p.threshold) ? fmtNumber(p.threshold) : '∞';
      parts.push(dot(t, P.X(p.fpr), P.Y(p.se), t.dot * 0.55, { attrs: `data-threshold="${Number.isFinite(p.threshold) ? p.threshold : String(p.threshold)}"`, inner: tip(`threshold ${th}: Se ${fmtNumber(p.se)}, Sp ${fmtNumber(p.sp)}`) }));
    }
  });
  let over = '';
  if (cutoff?.cutoff && finite(cutoff.sp, cutoff.se)) {
    const cx = P.X(1 - cutoff.sp), cy = P.Y(cutoff.se), r = t.dot * 1.8, s = `cutoff ${fmtNumber(cutoff.threshold)}`, wd = measure(t, s);
    over = `<circle class="c-line" cx="${r1(cx)}" cy="${r1(cy)}" r="${r1(r)}" fill="none" stroke="${t.color.ink}" stroke-width="${t.line.ci}"/>`
      + (cx + r + 2 + wd > P.x1 ? text(t, cx - r - 2, cy + t.size.label * 1.3, s, { anchor: 'end' }) : text(t, cx + r + 2, cy + t.size.label * 1.3, s));
  }
  const named = list.filter(c => c.label);
  const items = named.length || list.length === 1 ? list.map(({ label, result }, k) => ({ label: `${label ? `${label}, ` : ''}AUC ${fixed(result.auc?.est, 3)}`, sample: lineSample(t, k) })) : [];
  return P.finish({ under: '', clipped: parts.join(''), over, after: y => legendRows(t, t.pad, y, P.w - 2 * t.pad, items) });
}

/** Fagan nomogram: pre-test probability (left), likelihood ratio (middle), post-test probability (right); the positive-test line solid, the negative dashed. */
export function houseFagan(pretest, lrPos, lrNeg, o = {}) {
  const { style: t, title = 'Fagan nomogram' } = o;
  let g;
  try { g = faganPoints(pretest, lrPos, lrNeg); } catch { g = null; }
  if (!g || !finite(pretest, lrPos, lrNeg) || !(lrPos > 0) || !(lrNeg > 0)) return note(t, { ...o, title }, 'Not drawn: the nomogram needs a pre-test probability between 0 and 1 and positive likelihood ratios.');
  const [ulo, uhi] = g.range, w = widthOf(t, o.width, 'single'), P = t.pad, u = t.size.label, sm = t.size.small, tk = sm * 0.4;
  const fmts = { pretest: pct, lr: v => fmtNumber(v), posttest: pct };
  const leftW = Math.max(...g.axes.pretest.ticks.map(k => measure(t, pct(k.value), 'small'))) + tk + sm * 0.4;
  const rightW = Math.max(...g.axes.posttest.ticks.map(k => measure(t, pct(k.value), 'small'))) + tk + sm * 0.4;
  const edge = Math.max(P, sm * 0.8), xl = edge + leftW, xr = w - edge - rightW, xm = (xl + xr) / 2, top = P + u * 1.9, plotH = w * 1.25, y1 = top + plotH;
  const Y = v => top + plotH * (uhi - v) / (uhi - ulo), parts = [];
  const axis = (a, side, rank, fmt) => {
    const x = xl + (xr - xl) * a.x, d = side === 'left' ? -1 : 1;
    parts.push(axisLine(t, x, top, x, y1));
    const shown = [];
    for (const k of [...a.ticks].sort((p, q) => rank(p.value) - rank(q.value))) if (shown.every(s => Math.abs(Y(s.u) - Y(k.u)) >= sm * 1.35)) shown.push(k);
    for (const k of a.ticks) {
      parts.push(axisLine(t, x, Y(k.u), x + d * tk, Y(k.u)));
      if (shown.includes(k)) parts.push(text(t, x + d * (tk + sm * 0.3), Y(k.u) + sm * 0.35, fmt(k.value), { anchor: side === 'left' ? 'end' : 'start', role: 'small', cls: 'c-ink', color: t.color.ink }));
    }
  };
  axis(g.axes.pretest, 'left', probRoundness, fmts.pretest); axis(g.axes.lr, 'right', roundness, fmts.lr); axis(g.axes.posttest, 'right', probRoundness, fmts.posttest);
  const head = (s, x) => { const h = measure(t, s) / 2; return text(t, Math.min(w - P - h, Math.max(P + h, x)), P + u, s, { anchor: 'middle' }); };
  parts.push(head('Pre-test', xl), head('Likelihood ratio', xm), head('Post-test', xr));
  [[g.positive, 0, 'positive'], [g.negative, 1, 'negative']].forEach(([line, k, lab]) => {
    if (!line) return;
    const x1 = line.u1 === line.u1Clamped ? xr : xl + (xr - xl) * (line.u1Clamped - line.u0) / (line.u1 - line.u0), y2 = Y(line.u1Clamped);
    parts.push(`<line ${strokeOf(seriesStyle(t, k))} x1="${r1(xl)}" y1="${r1(Y(line.u0))}" x2="${r1(x1)}" y2="${r1(y2)}" data-test="${lab}">${tip(`${lab} test: LR ${fmtNumber(line.lr)}, post-test ${pct(line.posttest)}`)}</line>`, dot(t, x1, y2, t.dot * 0.85));
  });
  parts.push(dot(t, xl, Y(-Math.log(pretest / (1 - pretest))), t.dot * 0.85));
  const leg = legendRows(t, P, y1 + sm * 1.2, w - 2 * P, [{ label: `Positive test, LR ${fmtNumber(lrPos)}`, sample: lineSample(t, 0) }, { label: `Negative test, LR ${fmtNumber(lrNeg)}`, sample: lineSample(t, 1) }]);
  parts.push(leg.svg);
  let y = y1 + sm * 1.2 + leg.h;
  const b = sourceBlock(t, P, y + sm * 0.5, w - 2 * P, sourceOf(o.source));
  parts.push(b.svg); y += b.h ? sm * 0.5 + b.h : 0;
  return svgRoot(t, w, y + Math.max(P, sm * 0.6), parts.join(''), { title, desc: `Fagan nomogram, pre-test ${pct(pretest)}` });
}

/** Calibration plot: grouped observed proportions with Wilson whiskers against mean predicted risk, the ideal line dashed. */
export function houseCalibration(cal, o = {}) {
  const { style: t, title = 'Calibration plot' } = o;
  if (!cal?.groups?.length || !cal.groups.every(g => finite(g.predicted, g.observed, g.lo, g.hi))) return note(t, { ...o, title }, 'Not drawn: there are no risk groups to plot.');
  const top = Math.max(0.1, ...cal.groups.map(g => Math.max(g.predicted, g.hi))), ax = niceTicks(0, Math.min(1, top), 5, { zero: true }), hi = Math.min(1, ax.hi), ticks = within(ax.ticks, [0, hi]);
  const foot = o.note ?? (finite(cal.slope?.est, cal.intercept?.est, cal.oe?.est, cal.brier) ? `Slope ${fixed(cal.slope.est)}, intercept ${fixed(cal.intercept.est)}, O:E ${fixed(cal.oe.est)}, Brier ${fixed(cal.brier, 3)}` : '');
  const w = widthOf(t, o.width, 'single');
  const P = xyPlot(t, { width: w, plotH: w * 0.8, xdom: [0, hi], ydom: [0, hi], xticks: ticks, yticks: ticks, xLabel: 'Predicted risk', yLabel: 'Observed proportion', title, source: [foot, ...sourceOf(o.source)], desc: `Calibration plot, ${cal.groups.length} risk groups`, seed: String(cal.groups.length) });
  const parts = [seg(P.X(0), P.Y(0), P.X(hi), P.Y(hi), refAttrs(t))];
  for (const g of cal.groups) {
    const x = P.X(g.predicted);
    parts.push(seg(x, P.Y(Math.min(hi, g.lo)), x, P.Y(Math.min(hi, g.hi)), `class="c-line" stroke="${t.color.ink}" stroke-width="${t.line.ci}"`),
      dot(t, x, P.Y(g.observed), t.dot, { attrs: `data-group="${g.group}"`, inner: tip(`group ${g.group} (n ${g.n}): predicted ${fmtNumber(g.predicted)}, observed ${fmtNumber(g.observed)}`) }));
  }
  return P.finish({ clipped: parts.join('') });
}

/** Decision curve: net benefit of the model (solid), treat all (dashed) and treat none (the zero line) against the threshold probability. */
export function houseDecisionCurve(dc, o = {}) {
  const { style: t, title = 'Decision curve' } = o;
  const rows = dc?.rows;
  if (!rows?.length || !rows.every(r => finite(r.threshold, r.model, r.all)) || !Number.isFinite(dc.prevalence)) return note(t, { ...o, title }, 'Not drawn: there are no thresholds to plot.');
  const hiY = Math.max(0.01, dc.prevalence, ...rows.map(r => r.model)), yl = niceTicks(-hiY * 0.2, hiY, 5), xl = niceTicks(Math.min(...rows.map(r => r.threshold)), Math.max(...rows.map(r => r.threshold)), 5);
  const xr = { lo: Math.max(0, xl.lo), hi: Math.min(1, xl.hi) };
  const w = widthOf(t, o.width, 'double');
  const P = xyPlot(t, { width: w, plotH: w * 0.42, xdom: [xr.lo, xr.hi], ydom: [yl.lo, yl.hi], xticks: xl.ticks, yticks: yl.ticks, xLabel: 'Threshold probability', yLabel: 'Net benefit', title, source: [o.note, ...sourceOf(o.source)], desc: 'Net benefit of the model, treat all and treat none', seed: String(rows.length) });
  const parts = [seg(P.X(xr.lo), P.Y(0), P.X(xr.hi), P.Y(0), `class="c-axis" stroke="${t.color.axis}" stroke-width="${t.line.axis}" data-series="none"`)];
  for (const [k, si] of [['all', 1], ['model', 0]])
    for (const run of clipBelow(rows.map(r => [r.threshold, r[k]]), yl.lo)) parts.push(pathOf(run.map(([x, y]) => [P.X(x), P.Y(y)]), `${strokeOf(seriesStyle(t, si))} data-series="${k}"`));
  const items = [{ label: 'Model', sample: lineSample(t, 0) }, { label: 'Treat all', sample: lineSample(t, 1) }, { label: 'Treat none', sample: (x, y, len) => seg(x, y, x + len, y, `class="c-axis" stroke="${t.color.axis}" stroke-width="${t.line.axis}"`) }];
  return P.finish({ clipped: parts.join(''), after: y => legendRows(t, t.pad, y, P.w - 2 * t.pad, items) });
}

/** Bland–Altman plot: difference against mean, the bias solid and the limits of agreement dashed, each labelled at the right. */
export function houseBlandAltman(points, bias, loa, o = {}) {
  const { style: t, title = 'Bland–Altman plot', xLabel = 'Mean of the two measurements', yLabel = 'Difference' } = o;
  const P0 = (points || []).map(p => (Array.isArray(p) ? { mean: p[0], diff: p[1] } : p));
  const [lo, hi] = Array.isArray(loa) ? loa : [loa?.lo, loa?.hi];
  if (!P0.length || !finite(P0.map(p => [p.mean, p.diff]), bias, lo, hi)) return note(t, { ...o, title }, 'Not drawn: there are no pairs of measurements to plot.');
  const xs = P0.map(p => p.mean), ds = P0.map(p => p.diff), span = (Math.max(...xs) - Math.min(...xs)) || 1;
  const xa = niceTicks(Math.min(...xs) - span * 0.05, Math.max(...xs) + span * 0.05, 5), ya = niceTicks(Math.min(lo, bias, ...ds), Math.max(hi, bias, ...ds), 5);
  const lines = [[bias, 0, `Bias ${fmtNumber(bias)}`, 'bias'], [hi, 1, `Upper ${fmtNumber(hi)}`, 'upper'], [lo, 1, `Lower ${fmtNumber(lo)}`, 'lower']];
  const sm = t.size.small, w = widthOf(t, o.width, 'double'), labW = Math.max(...lines.map(l => measure(t, l[2]))) + t.size.label * 0.6;
  const P = xyPlot(t, { width: w, plotH: w * 0.42, xdom: [xa.lo, xa.hi], ydom: [ya.lo, ya.hi], xticks: xa.ticks, yticks: ya.ticks, xLabel, yLabel, rightPad: labW, title, source: [o.note, ...sourceOf(o.source)], desc: `Bland–Altman plot, ${P0.length} pairs`, seed: String(P0.length) });
  const parts = lines.map(([v, si, , k]) => seg(P.X(xa.lo), P.Y(v), P.X(xa.hi), P.Y(v), `${strokeOf(seriesStyle(t, si))} data-line="${k}"`));
  parts.push(...P0.map(p => dot(t, P.X(p.mean), P.Y(p.diff), t.dot * 0.8, { grey: true, inner: tip(`mean ${fmtNumber(p.mean)}, difference ${fmtNumber(p.diff)}`) })));
  // the labels sit at the line ends, pushed apart so that two close lines do not print over each other
  const at = lines.map(l => ({ l, y: P.Y(l[0]) })).sort((a, b) => a.y - b.y);
  for (let i = 1; i < at.length; i++) at[i].y = Math.max(at[i].y, at[i - 1].y + sm * 1.35);
  const labels = at.map(a => text(t, P.X(xa.hi) + t.size.label * 0.4, a.y + t.size.label * 0.35, a.l[2])).join('');
  return P.finish({ clipped: parts.join(''), over: labels });
}

/** Points on two numeric axes with an optional straight line: a scatter plot or a normal Q–Q plot. */
export function houseXy({ points, line = null, xLabel = '', yLabel = '', title = '' }, o = {}) {
  const t = o.style, pts = (points || []).filter(p => finite(p[0], p[1]));
  if (!pts.length) return noteFigure(t, { title: title || 'Scatter plot', message: 'Not drawn: there are no numeric pairs to plot.', width: o.width, source: o.source });
  const xs = pts.map(p => p[0]), ys = pts.map(p => p[1]);
  const pad = (lo, hi) => { const s = (hi - lo) || Math.abs(hi) || 1; return [lo - s * 0.04, hi + s * 0.04]; };
  const xa = niceTicks(...pad(Math.min(...xs), Math.max(...xs)), 5), ya = niceTicks(...pad(Math.min(...ys), Math.max(...ys)), 5), w = widthOf(t, o.width, 'single');
  const P = xyPlot(t, { width: w, plotH: w * 0.8, xdom: [xa.lo, xa.hi], ydom: [ya.lo, ya.hi], xticks: xa.ticks, yticks: ya.ticks, xLabel, yLabel, title: title || 'Scatter plot', source: o.source, desc: `${pts.length} points`, seed: String(pts.length) });
  const ref = line && Number.isFinite(line.slope) && Number.isFinite(line.intercept) ? seg(P.X(xa.lo), P.Y(line.intercept + line.slope * xa.lo), P.X(xa.hi), P.Y(line.intercept + line.slope * xa.hi), refAttrs(t)) : '';
  return P.finish({ clipped: ref, over: pts.map(([x, y]) => dot(t, P.X(x), P.Y(y), t.dot * 0.8, { grey: true, inner: tip(`${fmtNumber(x)}, ${fmtNumber(y)}`) })).join('') });
}

// Figures for the clinical calculators (lib/clinical-epi.mjs): ROC curve, Fagan nomogram, calibration plot, decision curve and
// Bland–Altman plot, as self-contained SVG strings. They are the house drawings of lib/clinical-plots-house.mjs (FIGURE-STYLE §2):
// one font, ink and one grey, marks told apart by weight and dash rather than hue, so a downloaded file is a publication figure
// and on screen the c-* classes take the app's theme. `opts.style` is figureTokens of lib/figure-style.mjs for the medium;
// without one the figure is the print copy (the export set). Every function is pure: data in, string out.
import { figureTokens } from './figure-style.mjs';
import { houseRoc, houseFagan, houseCalibration, houseDecisionCurve, houseBlandAltman } from './clinical-plots-house.mjs';

const styled = opts => (opts?.style ? opts : { ...opts, style: figureTokens(null, { medium: 'export' }) });

/**
 * ROC curve(s): 1 − specificity against sensitivity, one marker per threshold (data-threshold), the chance diagonal dashed.
 * `curves` is a roc() result or [{ label, result }]; `opts.cutoff` an optimalCutoff() result to ring.
 */
export const rocSvg = (curves, opts = {}) => houseRoc(curves, styled(opts));

/** Fagan nomogram: pre-test probability (left), likelihood ratio (middle), post-test probability (right); the positive-test line solid, the negative-test line dashed. */
export const faganSvg = (pretest, lrPos, lrNeg, opts = {}) => houseFagan(pretest, lrPos, lrNeg, styled(opts));

/** Calibration plot from a calibration() result: grouped observed proportions with Wilson whiskers against mean predicted risk, the ideal line dashed. */
export const calibrationSvg = (cal, opts = {}) => houseCalibration(cal, styled(opts));

/** Decision curve from a decisionCurve() result: net benefit of the model, treat all (dashed) and treat none (the zero line), against the threshold probability. */
export const decisionCurveSvg = (dc, opts = {}) => houseDecisionCurve(dc, styled(opts));

/** Bland–Altman plot: difference against mean of two measurements, the bias as a solid line and the limits of agreement dashed. points: [{ mean, diff }] or [[mean, diff]]; loa: [lo, hi] or { lo, hi }. */
export const blandAltmanSvg = (points, bias, loa, opts = {}) => houseBlandAltman(points, bias, loa, styled(opts));

/** The house drawings app/lint-figures.mjs checks: each figure of this module on small examples. */
export const __fixture = style => {
  const curve = k => { const pts = [{ threshold: Infinity, fpr: 0, se: 0, sp: 1 }, ...[0.95, 0.8, 0.6, 0.4, 0.2, 0.05].map((th, i) => ({ threshold: th, fpr: Math.min(1, (i + 1) / 7 * (k ? 1.3 : 1)), se: Math.min(1, (i + 1) / 6 * (k ? 1.0 : 1.2)), sp: 1 - (i + 1) / 7 })), { threshold: -Infinity, fpr: 1, se: 1, sp: 0 }]; return { points: pts, auc: { est: k ? 0.71 : 0.83 } }; };
  const groups = Array.from({ length: 5 }, (_, i) => { const pr = 0.1 + 0.18 * i, ob = Math.min(1, pr + (i % 2 ? 0.07 : -0.05)); return { group: i + 1, n: 20, predicted: pr, observed: ob, lo: Math.max(0, ob - 0.15), hi: Math.min(1, ob + 0.15) }; });
  const rows = Array.from({ length: 19 }, (_, i) => { const th = 0.05 + i * 0.05; return { threshold: th, model: 0.2 - th * 0.25, all: 0.3 - th * 0.55 + 0.1 * th * th }; });
  return [
    { name: 'rocSvg', svg: rocSvg(curve(0), { style, cutoff: { cutoff: true, se: 0.833, sp: 0.714, threshold: 0.4 }, source: ['12 patients'] }) },
    { name: 'rocSvgTwo', svg: rocSvg([{ label: 'Clinical score', result: curve(0) }, { label: 'Biomarker panel with a long name', result: curve(1) }], { style }) },
    { name: 'faganSvg', svg: faganSvg(0.2, 4.5, 0.125, { style }) },
    { name: 'calibrationSvg', svg: calibrationSvg({ groups, slope: { est: 0.92 }, intercept: { est: 0.03 }, oe: { est: 1.04 }, brier: 0.162 }, { style }) },
    { name: 'decisionCurveSvg', svg: decisionCurveSvg({ prevalence: 0.3, rows }, { style }) },
    { name: 'blandAltmanSvg', svg: blandAltmanSvg([[10, 0.5], [12, -0.3], [15, 1.1], [18, 0.2], [21, -0.9], [24, 0.7]], 0.22, [-1.3, 1.74], { style }) },
    { name: 'notDrawn', svg: blandAltmanSvg([], 0, [0, 0], { style }) },
  ];
};

// A researcher-defined appraisal instrument: the review team names its
// judgement levels, its domains and, under each domain, the questions that
// inform the domain judgement. toTool() gives it the APPRAISAL_TOOLS shape
// (schema.mjs) so the appraisal view, summaries and figures read it like any
// shipped instrument.
//
// {
//   id, name, design,
//   judgements: ['Low', 'Some concerns', 'High'],   // most to least favourable
//   unranked: ['No information'],                   // optional: levels outside that order
//   domains: [{ id, name, questions: [{ id, text, answers: ['Yes', 'No'] }] }],
//   overall: 'worst' | 'manual' | 'none',
// }
//
// "worst" takes the least favourable domain judgement — the order of
// `judgements` is the ranking. "manual" leaves the overall to the reviewer;
// "none" has no overall. Pure; no imports.

export const OVERALL_RULES = ['worst', 'manual', 'none'];
export const FORMAT = 'lykos-appraisal-instrument';
const ID = /^[a-z0-9][a-z0-9-]{0,47}$/;
const str = x => (typeof x === 'string' ? x.trim() : '');

const dupes = list => list.filter((x, i) => list.indexOf(x) !== i);

/**
 * Problems with an instrument definition, as sentences; `ok` when there are
 * none. `reserved` lists ids already taken (the shipped instruments).
 */
export function validate(inst, { reserved = [] } = {}) {
  const errors = [];
  if (!inst || typeof inst !== 'object') return { ok: false, errors: ['Not an instrument definition'] };
  const id = str(inst.id);
  if (!ID.test(id)) errors.push('Id must be lower-case letters, digits and hyphens');
  else if (reserved.includes(id) || reserved.includes(toolId(id))) errors.push(`Id ${id} is already in use`);
  if (!str(inst.name)) errors.push('Name is required');
  const j = Array.isArray(inst.judgements) ? inst.judgements.map(str) : [];
  if (j.length < 2) errors.push('At least two judgement levels are needed');
  if (j.some(x => !x)) errors.push('A judgement level is empty');
  if (dupes(j).length) errors.push(`Judgement level repeated: ${[...new Set(dupes(j))].join(', ')}`);
  const unranked = Array.isArray(inst.unranked) ? inst.unranked.map(str) : [];
  for (const u of unranked) if (!j.includes(u)) errors.push(`Unranked level ${u} is not a judgement level`);
  if (j.length && unranked.length >= j.length - 1) errors.push('At least two judgement levels must be ranked');
  if (!OVERALL_RULES.includes(inst.overall)) errors.push('Overall must be worst, manual or none');
  const domains = Array.isArray(inst.domains) ? inst.domains : [];
  if (!domains.length) errors.push('At least one domain is needed');
  const dids = domains.map(d => str(d?.id));
  if (dids.some(x => !ID.test(x))) errors.push('Each domain needs an id of lower-case letters, digits and hyphens');
  if (dids.includes('overall')) errors.push('A domain cannot be called overall');
  if (dupes(dids).length) errors.push(`Domain id repeated: ${[...new Set(dupes(dids))].join(', ')}`);
  domains.forEach((d, i) => {
    const at = `Domain ${i + 1}`;
    if (!str(d?.name)) errors.push(`${at} needs a name`);
    const qs = d?.questions == null ? [] : d.questions;
    if (!Array.isArray(qs)) { errors.push(`${at}: questions must be a list`); return; }
    const qids = qs.map(q => str(q?.id));
    if (qids.some(x => !ID.test(x))) errors.push(`${at}: each question needs an id of lower-case letters, digits and hyphens`);
    if (dupes(qids).length) errors.push(`${at}: question id repeated: ${[...new Set(dupes(qids))].join(', ')}`);
    qs.forEach((q, k) => {
      if (!str(q?.text)) errors.push(`${at}, question ${k + 1} needs text`);
      const a = Array.isArray(q?.answers) ? q.answers.map(str) : [];
      if (a.length < 2 || a.some(x => !x)) errors.push(`${at}, question ${k + 1} needs at least two answers`);
      else if (dupes(a).length) errors.push(`${at}, question ${k + 1} repeats an answer`);
    });
  });
  return { ok: errors.length === 0, errors };
}

/** The id the app stores assessments under: prefixed so it never meets a shipped instrument's. */
export const toolId = id => (String(id).startsWith('custom-') ? String(id) : `custom-${id}`);

/** The instrument in the APPRAISAL_TOOLS shape. Throws on an invalid definition. */
export function toTool(inst) {
  const v = validate(inst);
  if (!v.ok) throw new Error(`Invalid instrument: ${v.errors[0]}`);
  return {
    id: toolId(str(inst.id)),
    name: str(inst.name),
    design: str(inst.design) || 'Defined by the review',
    judgements: inst.judgements.map(str),
    source: { url: str(inst.source?.url), note: 'Defined by the review team' },
    overall: inst.overall !== 'none',
    overallRule: inst.overall,
    custom: true,
    unranked: (inst.unranked || []).map(str),
    domains: inst.domains.map((d, i) => ({
      id: str(d.id), short: `D${i + 1}`, label: str(d.name),
      ...(d.questions?.length ? {
        signals: d.questions.map(q => str(q.text)),
        questions: d.questions.map(q => ({ id: str(q.id), text: str(q.text), answers: q.answers.map(str) })),
      } : {}),
    })),
  };
}

/**
 * The overall judgement a rule gives. `domainJudgements` is a map
 * { domainId: level } or a list of levels; `inst` supplies the ranking and,
 * for a map, the domains that must all be judged.
 * Returns { value, rule, complete, drivers } — `value` is null for "manual"
 * (the reviewer chooses), for "none", and while any domain is unjudged.
 */
export function overallFrom(domainJudgements, rule, inst = {}) {
  const judgements = (inst.judgements || []).map(str);
  const unranked = new Set((inst.unranked || []).map(str));
  const entries = Array.isArray(domainJudgements)
    ? domainJudgements.map((v, i) => [String(i), v])
    : (inst.domains?.length ? inst.domains.map(d => [str(d.id), domainJudgements?.[str(d.id)]]) : Object.entries(domainJudgements || {}));
  const complete = entries.length > 0 && entries.every(([, v]) => str(v));
  const out = { value: null, rule, complete, drivers: [] };
  if (rule !== 'worst' || !complete) return out;
  let worst = -1;
  for (const [, v] of entries) {
    const r = judgements.indexOf(str(v));
    if (r < 0 && !unranked.has(str(v))) throw new Error(`Unknown judgement: ${v}`);
    if (!unranked.has(str(v))) worst = Math.max(worst, r);
  }
  if (worst < 0) return out;          // every domain unranked: nothing to take the worst of
  out.value = judgements[worst];
  out.drivers = entries.filter(([, v]) => str(v) === out.value).map(([k]) => k);
  return out;
}

/** The definition as a JSON file's text. */
export function exportInstrument(inst) {
  const v = validate(inst);
  if (!v.ok) throw new Error(`Invalid instrument: ${v.errors[0]}`);
  const clean = {
    id: str(inst.id), name: str(inst.name), design: str(inst.design),
    judgements: inst.judgements.map(str),
    ...(inst.unranked?.length ? { unranked: inst.unranked.map(str) } : {}),
    overall: inst.overall,
    domains: inst.domains.map(d => ({ id: str(d.id), name: str(d.name),
      questions: (d.questions || []).map(q => ({ id: str(q.id), text: str(q.text), answers: q.answers.map(str) })) })),
  };
  return JSON.stringify({ format: FORMAT, version: 1, instrument: clean }, null, 2);
}

/** A definition read back from JSON text: { ok, instrument, errors }. A bare instrument object is accepted too. */
export function importInstrument(text, opts) {
  let data;
  try { data = JSON.parse(String(text)); } catch { return { ok: false, instrument: null, errors: ['Not valid JSON'] }; }
  if (data && data.format != null && data.format !== FORMAT) return { ok: false, instrument: null, errors: [`Unknown format: ${data.format}`] };
  if (data?.format === FORMAT && data.version !== 1) return { ok: false, instrument: null, errors: [`Unsupported version: ${data.version}`] };
  const inst = data?.format === FORMAT ? data.instrument : data;
  const v = validate(inst, opts);
  return { ok: v.ok, instrument: v.ok ? inst : null, errors: v.errors };
}

// Data management for a primary study's datasets (amendment of 2026-09-29):
// column constraints, cross-field edit checks, and the change log with locks
// and source-data verification. No UI; pure over the dataset shape of
// lib/datasets.mjs and a state object the caller passes in.
//
// Column constraints live on the column:
//   column.rules = { required, min, max, allowed: [values], pattern,
//                    missingCodes: ['-99', 'NA'], unit }
// A cell holding one of its column's missing codes is missing, not wrong: it
// is never a type, range, allowed or pattern error, and it satisfies
// `required` (the value is known to be missing), reported as `missing-code`
// with severity 'info'.
//
// Edit checks are written in a small expression language, parsed here and
// evaluated by walking the tree: no eval, no new Function, no property access.
//   discharge_date >= admission_date
//   if sex == 'M' then pregnant is empty
//   bmi between 12 and 70
//   discharge_date - admission_date <= 90        (a date minus a date is days)
//   days(admission_date, discharge_date) <= 90   (the same)
//   sex in ('M', 'F') and not (age < 18)
//   if randomised == 'Yes' then coalesce(consented, 'No') == 'Yes'
// Comparisons with an empty operand are unknown, and an unknown check passes:
// "discharge_date >= admission_date" does not fire on a row with no discharge.
// `and`, `or` and `not` follow three-valued (Kleene) logic; `if A then B` is
// the implication `not A or B`.
//
// Rows are identified by index unless the dataset names a key column
// (`dataset.rowKey`, e.g. 'participant_id'); locks and verification are kept
// by that identifier.
import { cellValue } from './datasets.mjs';

// ---- values -------------------------------------------------------------------

/** Missing codes a column declares, as trimmed strings. */
export const missingCodesOf = column => (column?.rules?.missingCodes || []).map(c => String(c).trim()).filter(Boolean);
/** Codes that are often used for missing values; a cell holding one that the column does not declare gets a hint. */
export const COMMON_MISSING = ['-99', '-999', '-9', '-88', '999', '9999', 'NA', 'N/A', 'NK', 'ND', '.', 'missing', 'unknown'];

const isBlank = v => v == null || String(v).trim() === '';
/** Whether a cell holds one of its column's missing codes (case-insensitive). */
export function isMissingCode(value, column) {
  if (isBlank(value)) return false;
  const v = String(value).trim().toLowerCase();
  return missingCodesOf(column).some(c => c.toLowerCase() === v);
}
/** Empty, or a declared missing code. */
export const isMissing = (value, column) => isBlank(value) || isMissingCode(value, column);

const ISO = /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(?:\.\d+)?)?Z?)?$/;
const DMY = /^(\d{1,2})[./-](\d{1,2})[./-](\d{2}|\d{4})(?:[T ](\d{1,2}):(\d{2}))?$/;
/**
 * A date cell as UTC milliseconds, or null. ISO dates (with an optional time)
 * and day-first dates (31/12/2024, 31.12.2024); a two-digit year is 20xx.
 * An impossible date (31/02/2024) is null.
 */
export function parseDate(value) {
  const t = String(value ?? '').trim();
  let y, mo, d, h = 0, mi = 0, s = 0, m;
  if ((m = ISO.exec(t))) [y, mo, d, h, mi, s] = [m[1], m[2], m[3], m[4] || 0, m[5] || 0, m[6] || 0].map(Number);
  else if ((m = DMY.exec(t))) { [d, mo, y, h, mi] = [m[1], m[2], m[3], m[4] || 0, m[5] || 0].map(Number); if (y < 100) y += 2000; }
  else return null;
  const ms = Date.UTC(y, mo - 1, d, h, mi, s), back = new Date(ms);
  if (back.getUTCFullYear() !== y || back.getUTCMonth() !== mo - 1 || back.getUTCDate() !== d || h > 23 || mi > 59 || s > 59) return null;
  return ms;
}
const DAY = 86_400_000;
/** A UTC millisecond time as YYYY-MM-DD, with " HH:MM" when it has a time of day. */
export function formatDate(ms, { time = null } = {}) {
  const x = new Date(ms), p = n => String(n).padStart(2, '0');
  const date = `${x.getUTCFullYear()}-${p(x.getUTCMonth() + 1)}-${p(x.getUTCDate())}`;
  const withTime = time ?? (ms % DAY !== 0);
  return withTime ? `${date} ${p(x.getUTCHours())}:${p(x.getUTCMinutes())}` : date;
}

// ---- column constraints -------------------------------------------------------

const label = c => c.label || c.id;
const num = (v, type) => cellValue(v, type === 'integer' ? 'integer' : 'number');
const bound = (b, type) => type === 'date' ? parseDate(b) : (b === '' || b == null ? null : Number(b));
const safePattern = src => { try { return new RegExp(`^(?:${src})$`, 'u'); } catch { return null; } };

/** The row identifier used for locks and verification: the key column's value, else the index. */
export const rowIdOf = (dataset, index) => dataset?.rowKey ? String(dataset.rows[index]?.[dataset.rowKey] ?? index) : index;

/**
 * Every constraint breach in a dataset:
 * [{ row, rowId, column, kind, value, message, severity }], kind one of
 * required, range, allowed, pattern, type, missing-code. `row` is the index.
 */
export function checkDataset(dataset) {
  const issues = [];
  const push = (row, c, kind, value, message, severity = 'error') =>
    issues.push({ row, rowId: rowIdOf(dataset, row), column: c.id, kind, value, message, severity });
  for (const c of dataset?.columns || []) {
    const r = c.rules || {}, type = c.type || 'text';
    const lo = bound(r.min, type), hi = bound(r.max, type), unit = r.unit ? ` ${r.unit}` : '';
    const allowed = (r.allowed || []).map(a => String(a).trim().toLowerCase());
    const re = r.pattern ? safePattern(r.pattern) : null;
    (dataset.rows || []).forEach((row, i) => {
      const raw = row[c.id], v = isBlank(raw) ? '' : String(raw).trim();
      if (v === '') { if (r.required) push(i, c, 'required', raw ?? '', `${label(c)} is required`); return; }
      if (isMissingCode(v, c)) { if (r.required) push(i, c, 'missing-code', v, `${label(c)} is coded missing (${v})`, 'info'); return; }
      const hint = COMMON_MISSING.some(x => x.toLowerCase() === v.toLowerCase()) ? `; if ${v} means missing, declare it as a missing code` : '';
      let x = null;
      if (type === 'number' || type === 'integer') {
        x = num(v, type);
        if (x == null || (type === 'integer' && !Number.isInteger(x))) { push(i, c, 'type', v, `${label(c)}: ${v} is not ${type === 'integer' ? 'a whole number' : 'a number'}${hint}`); return; }
      } else if (type === 'date') {
        x = parseDate(v);
        if (x == null) { push(i, c, 'type', v, `${label(c)}: ${v} is not a date${hint}`); return; }
      }
      if (x != null && ((lo != null && x < lo) || (hi != null && x > hi))) {
        const range = lo != null && hi != null ? `between ${r.min} and ${r.max}` : lo != null ? `at least ${r.min}` : `at most ${r.max}`;
        push(i, c, 'range', v, `${label(c)}: ${v}${unit} is outside the range (${range}${unit})${hint}`);
      }
      if (allowed.length && !allowed.includes(v.toLowerCase())) push(i, c, 'allowed', v, `${label(c)}: ${v} is not one of ${r.allowed.join(', ')}${hint}`);
      if (re && !re.test(v)) push(i, c, 'pattern', v, `${label(c)}: ${v} does not match the pattern`);
    });
  }
  return issues;
}

// ---- the edit-check language ----------------------------------------------------

const KEYWORDS = new Set(['and', 'or', 'not', 'if', 'then', 'else', 'is', 'empty', 'between', 'in', 'true', 'false']);
const FUNCTIONS = {
  days: 2,      // days(from, to): to − from in days
  abs: 1,
  year: 1,
  month: 1,
  length: 1,
  date: 1,      // date('2024-01-31'): a date literal
  min: -1,
  max: -1,
  coalesce: -1, // coalesce(x, 'No'): the first operand that is not empty
};
export const RULE_FUNCTIONS = Object.keys(FUNCTIONS);

class RuleError extends Error { constructor(message, pos) { super(message); this.pos = pos; } }

function tokenize(text) {
  const out = [], s = String(text);
  let i = 0;
  while (i < s.length) {
    const c = s[i];
    if (/\s/.test(c)) { i++; continue; }
    const start = i;
    if (/\d/.test(c) || (c === '.' && /\d/.test(s[i + 1] || ''))) {
      const m = /^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?/.exec(s.slice(i));
      out.push({ t: 'num', v: Number(m[0]), pos: start }); i += m[0].length; continue;
    }
    if (c === "'" || c === '"') {
      let v = ''; i++;
      while (i < s.length && s[i] !== c) { if (s[i] === '\\' && i + 1 < s.length) i++; v += s[i++]; }
      if (i >= s.length) throw new RuleError('Unfinished text in quotes', start);
      i++; out.push({ t: 'str', v, pos: start }); continue;
    }
    if (c === '`' || c === '[') {
      const close = c === '`' ? '`' : ']', j = s.indexOf(close, i + 1);
      if (j < 0) throw new RuleError(`Unfinished column name; close it with ${close}`, start);
      out.push({ t: 'id', v: s.slice(i + 1, j).trim(), pos: start }); i = j + 1; continue;
    }
    if (/[A-Za-z_À-ɏ]/.test(c)) {
      const m = /^[\wÀ-ɏ.]+/.exec(s.slice(i));
      const w = m[0], lw = w.toLowerCase();
      out.push(KEYWORDS.has(lw) ? { t: 'kw', v: lw, pos: start } : { t: 'id', v: w, pos: start });
      i += w.length; continue;
    }
    const two = s.slice(i, i + 2);
    if (['==', '!=', '<>', '<=', '>=', '&&', '||'].includes(two)) { out.push({ t: 'op', v: two, pos: start }); i += 2; continue; }
    if ('=<>+-*/(),!'.includes(c)) { out.push({ t: 'op', v: c, pos: start }); i++; continue; }
    throw new RuleError(`Unexpected character '${c}'`, start);
  }
  out.push({ t: 'end', pos: s.length });
  return out;
}

/**
 * A rule's text as a tree. Returns { ast, error: null, pos: null }, or
 * { ast: null, error, pos } with the character position of the problem.
 */
export function parseRule(text) {
  try {
    const toks = tokenize(text);
    let k = 0;
    const peek = () => toks[k];
    const isKw = w => peek().t === 'kw' && peek().v === w;
    const isOp = (...ops) => peek().t === 'op' && ops.includes(peek().v);
    const expect = (pred, what) => { if (!pred()) throw new RuleError(`Expected ${what}${peek().t === 'end' ? ' at the end' : ''}`, peek().pos); return toks[k++]; };
    const node = (type, pos, props) => ({ type, pos, ...props });

    function expr() {
      if (isKw('if')) {
        const pos = toks[k++].pos, cond = expr();
        expect(() => isKw('then'), "'then'");
        const then = expr();
        let otherwise = null;
        if (isKw('else')) { k++; otherwise = expr(); }
        return node('if', pos, { cond, then, else: otherwise });
      }
      return or();
    }
    function or() {
      let left = and();
      while (isKw('or') || isOp('||')) { const pos = toks[k++].pos; left = node('or', pos, { left, right: and() }); }
      return left;
    }
    function and() {
      let left = not();
      while (isKw('and') || isOp('&&')) { const pos = toks[k++].pos; left = node('and', pos, { left, right: not() }); }
      return left;
    }
    function not() {
      if (isKw('not') || isOp('!')) { const pos = toks[k++].pos; return node('not', pos, { arg: not() }); }
      return comparison();
    }
    function comparison() {
      const left = additive();
      if (isOp('==', '=', '!=', '<>', '<', '<=', '>', '>=')) {
        const t = toks[k++], op = t.v === '=' ? '==' : t.v === '<>' ? '!=' : t.v;
        return node('cmp', t.pos, { op, left, right: additive() });
      }
      if (isKw('is')) {
        const pos = toks[k++].pos; let negate = false;
        if (isKw('not')) { k++; negate = true; }
        expect(() => isKw('empty'), "'empty' after 'is'");
        const n = node('empty', pos, { arg: left });
        return negate ? node('not', pos, { arg: n }) : n;
      }
      if (isKw('between')) {
        const pos = toks[k++].pos, lo = additive();
        expect(() => isKw('and'), "'and' in 'between … and …'");
        return node('between', pos, { arg: left, lo, hi: additive() });
      }
      let negate = false;
      if (isKw('not') && toks[k + 1]?.t === 'kw' && toks[k + 1].v === 'in') { k++; negate = true; }
      if (isKw('in')) {
        const pos = toks[k++].pos;
        expect(() => isOp('('), "'(' after 'in'");
        const items = [additive()];
        while (isOp(',')) { k++; items.push(additive()); }
        expect(() => isOp(')'), "')'");
        const n = node('in', pos, { arg: left, items });
        return negate ? node('not', pos, { arg: n }) : n;
      }
      return left;
    }
    function additive() {
      let left = multiplicative();
      while (isOp('+', '-')) { const t = toks[k++]; left = node('arith', t.pos, { op: t.v, left, right: multiplicative() }); }
      return left;
    }
    function multiplicative() {
      let left = unary();
      while (isOp('*', '/')) { const t = toks[k++]; left = node('arith', t.pos, { op: t.v, left, right: unary() }); }
      return left;
    }
    function unary() {
      if (isOp('-')) { const pos = toks[k++].pos; return node('neg', pos, { arg: unary() }); }
      if (isOp('+')) { k++; return unary(); }
      return primary();
    }
    function primary() {
      const t = peek();
      if (t.t === 'num') { k++; return node('lit', t.pos, { value: t.v }); }
      if (t.t === 'str') { k++; return node('lit', t.pos, { value: t.v }); }
      if (t.t === 'kw' && (t.v === 'true' || t.v === 'false')) { k++; return node('lit', t.pos, { value: t.v === 'true' }); }
      if (t.t === 'kw' && t.v === 'empty') { k++; return node('lit', t.pos, { value: null }); }
      if (isOp('(')) {
        k++; const e = expr();
        expect(() => isOp(')'), "')'");
        return e;
      }
      if (t.t === 'id') {
        k++;
        if (isOp('(')) {
          const name = t.v.toLowerCase();
          if (!(name in FUNCTIONS)) throw new RuleError(`Unknown function '${t.v}'; use one of ${RULE_FUNCTIONS.join(', ')}`, t.pos);
          k++; const args = [];
          if (!isOp(')')) { args.push(expr()); while (isOp(',')) { k++; args.push(expr()); } }
          expect(() => isOp(')'), "')' to close the function");
          const want = FUNCTIONS[name];
          if (want >= 0 && args.length !== want) throw new RuleError(`${name}() takes ${want} argument${want === 1 ? '' : 's'}`, t.pos);
          if (want < 0 && !args.length) throw new RuleError(`${name}() takes at least one argument`, t.pos);
          return node('call', t.pos, { name, args });
        }
        return node('ref', t.pos, { name: t.v });
      }
      if (t.t === 'end') throw new RuleError('The rule ends too early', t.pos);
      throw new RuleError(`Unexpected '${t.v}'`, t.pos);
    }

    const ast = expr();
    if (peek().t !== 'end') throw new RuleError(`Unexpected '${peek().v}' after a complete rule`, peek().pos);
    return { ast, error: null, pos: null };
  } catch (e) {
    if (e instanceof RuleError) return { ast: null, error: e.message, pos: e.pos };
    throw e;
  }
}

/** The column names a rule refers to. */
export function ruleColumns(ast) {
  const out = new Set();
  (function walk(n) {
    if (!n || typeof n !== 'object') return;
    if (n.type === 'ref') out.add(n.name);
    for (const v of Object.values(n)) if (Array.isArray(v)) v.forEach(walk); else if (v && typeof v === 'object') walk(v);
  })(ast);
  return [...out];
}

// Runtime values: number, string, boolean, null (empty or unknown), or a date.
const D = ms => ({ date: ms });
const isDate = v => v != null && typeof v === 'object' && 'date' in v;
const looksDate = v => typeof v === 'string' && /^\d{4}-\d{1,2}-\d{1,2}|^\d{1,2}[./-]\d{1,2}[./-]\d{2,4}$/.test(v.trim()) && parseDate(v) != null;
const looksNumber = v => typeof v === 'string' && /^\s*[-+]?(\d+\.?\d*|\.\d+)(e[-+]?\d+)?\s*$/i.test(v);

function findColumn(columns, name) {
  const n = String(name).toLowerCase();
  return (columns || []).find(c => c.id === name) || (columns || []).find(c => c.id.toLowerCase() === n || String(c.label || '').toLowerCase() === n) || null;
}

function cell(row, name, columns) {
  const c = findColumn(columns, name);
  const key = c ? c.id : name;
  const raw = row && Object.hasOwn(row, key) ? row[key] : null;
  if (isBlank(raw) || (c && isMissingCode(raw, c))) return null;
  const v = String(raw).trim();
  const type = c?.type;
  if (type === 'number' || type === 'integer') return cellValue(v, 'number');
  if (type === 'date') { const ms = parseDate(v); return ms == null ? null : D(ms); }
  if (!type || type === 'text' || type === 'category') {
    if (!type && looksNumber(v)) return Number(v);
    if (!type && looksDate(v)) return D(parseDate(v));
  }
  return v;
}

// Bring two operands to a common kind for comparison or arithmetic.
function coerce(a, b) {
  if (isDate(a) && typeof b === 'string' && parseDate(b) != null) return [a, D(parseDate(b))];
  if (isDate(b) && typeof a === 'string' && parseDate(a) != null) return [D(parseDate(a)), b];
  if (typeof a === 'number' && looksNumber(b)) return [a, Number(b)];
  if (typeof b === 'number' && looksNumber(a)) return [Number(a), b];
  return [a, b];
}
const key = v => isDate(v) ? v.date : typeof v === 'string' ? v.trim().toLowerCase() : v;
function compare(op, a, b) {
  if (a == null || b == null) return null;
  [a, b] = coerce(a, b);
  const x = key(a), y = key(b);
  if (op === '==') return x === y;
  if (op === '!=') return x !== y;
  if (typeof x !== typeof y) return null;
  return op === '<' ? x < y : op === '<=' ? x <= y : op === '>' ? x > y : x >= y;
}
const truth = v => v == null ? null : typeof v === 'boolean' ? v : typeof v === 'number' ? v !== 0 : isDate(v) ? true : String(v).trim() !== '';
const toNum = v => typeof v === 'number' ? v : looksNumber(v) ? Number(v) : null;

/**
 * A parsed rule evaluated on one row: true, false, or null when it cannot be
 * decided (an operand is empty). `columns` types the cells (dates, numbers)
 * and supplies missing codes; without them, a cell that reads as a number or
 * an ISO date is taken as one.
 */
export function evaluate(ast, row, columns = null) {
  const ev = n => {
    switch (n.type) {
      case 'lit': return n.value;
      case 'ref': return cell(row, n.name, columns);
      case 'neg': { const v = toNum(ev(n.arg)); return v == null ? null : -v; }
      case 'arith': {
        let a = ev(n.left), b = ev(n.right);
        if (a == null || b == null) return null;
        [a, b] = coerce(a, b);
        if (isDate(a) && isDate(b)) return n.op === '-' ? (a.date - b.date) / DAY : null;
        if (isDate(a) && (n.op === '+' || n.op === '-')) { const d = toNum(b); return d == null ? null : D(a.date + (n.op === '+' ? d : -d) * DAY); }
        if (isDate(b) && n.op === '+') { const d = toNum(a); return d == null ? null : D(b.date + d * DAY); }
        const x = toNum(a), y = toNum(b);
        if (x == null || y == null) return null;
        if (n.op === '/') return y === 0 ? null : x / y;
        return n.op === '+' ? x + y : n.op === '-' ? x - y : x * y;
      }
      case 'cmp': return compare(n.op, ev(n.left), ev(n.right));
      case 'empty': { const v = ev(n.arg); return v == null || (typeof v === 'string' && v.trim() === ''); }
      case 'between': {
        const v = ev(n.arg), lo = compare('>=', v, ev(n.lo)), hi = compare('<=', v, ev(n.hi));
        return lo == null || hi == null ? null : lo && hi;
      }
      case 'in': {
        const v = ev(n.arg);
        if (v == null) return null;
        return n.items.some(it => compare('==', v, ev(it)) === true);
      }
      case 'not': { const v = truth(ev(n.arg)); return v == null ? null : !v; }
      case 'and': {
        const a = truth(ev(n.left)); if (a === false) return false;
        const b = truth(ev(n.right)); if (b === false) return false;
        return a == null || b == null ? null : true;
      }
      case 'or': {
        const a = truth(ev(n.left)); if (a === true) return true;
        const b = truth(ev(n.right)); if (b === true) return true;
        return a == null || b == null ? null : false;
      }
      case 'if': {
        const c = truth(ev(n.cond));
        if (c === true) return truth(ev(n.then));
        if (c === false) return n.else ? truth(ev(n.else)) : true;
        // unknown condition: passes unless both branches fail
        const t = truth(ev(n.then)), e = n.else ? truth(ev(n.else)) : true;
        return t === true && e === true ? true : t === false && e === false ? false : null;
      }
      case 'call': {
        const args = n.args.map(ev);
        switch (n.name) {
          case 'days': {
            const [a, b] = args.map(v => isDate(v) ? v : typeof v === 'string' && parseDate(v) != null ? D(parseDate(v)) : null);
            return a && b ? (b.date - a.date) / DAY : null;
          }
          case 'abs': { const v = toNum(args[0]); return v == null ? null : Math.abs(v); }
          case 'year': case 'month': {
            const v = isDate(args[0]) ? args[0].date : typeof args[0] === 'string' ? parseDate(args[0]) : null;
            if (v == null) return null;
            return n.name === 'year' ? new Date(v).getUTCFullYear() : new Date(v).getUTCMonth() + 1;
          }
          case 'length': return args[0] == null ? 0 : String(isDate(args[0]) ? formatDate(args[0].date) : args[0]).length;
          case 'date': { const v = typeof args[0] === 'string' ? parseDate(args[0]) : null; return v == null ? null : D(v); }
          case 'coalesce': return args.find(v => v != null && !(typeof v === 'string' && v.trim() === '')) ?? null;
          case 'min': case 'max': {
            const xs = args.map(v => isDate(v) ? v.date : toNum(v));
            if (xs.some(x => x == null)) return null;
            const r = Math[n.name](...xs);
            return args.some(isDate) ? D(r) : r;
          }
        }
        return null;
      }
    }
    return null;
  };
  return truth(ev(ast));
}

/**
 * Cross-field checks on every row. `rules` are texts or
 * { id, text, message }; a rule that does not parse, or names a column the
 * dataset lacks, is one issue with row null and kind 'rule-error'. A row where
 * a rule is false gives kind 'rule'; undecided rows pass.
 */
export function checkRules(dataset, rules) {
  const issues = [], columns = dataset?.columns || [];
  (rules || []).forEach((r, n) => {
    const rule = typeof r === 'string' ? { text: r } : r || {};
    if (rule.off) return;
    const id = rule.id || `rule${n + 1}`, text = String(rule.text || '');
    const parsed = parseRule(text);
    if (parsed.error) { issues.push({ row: null, rowId: null, column: null, rule: id, kind: 'rule-error', value: text, message: `${parsed.error} (at ${parsed.pos + 1})`, pos: parsed.pos, severity: 'error' }); return; }
    const unknown = ruleColumns(parsed.ast).filter(c => !findColumn(columns, c));
    if (unknown.length) { issues.push({ row: null, rowId: null, column: null, rule: id, kind: 'rule-error', value: text, message: `No column named ${unknown.join(', ')}`, severity: 'error' }); return; }
    const cols = ruleColumns(parsed.ast).map(c => findColumn(columns, c).id);
    (dataset.rows || []).forEach((row, i) => {
      if (evaluate(parsed.ast, row, columns) === false)
        issues.push({ row: i, rowId: rowIdOf(dataset, i), column: cols[0] || null, columns: cols, rule: id, kind: 'rule', value: text, message: rule.message || `Fails: ${text}`, severity: rule.severity || 'error' });
    });
  });
  return issues;
}

/** Constraint and cross-field issues together; the rules are `dataset.rules` unless given. */
export const checkAll = (dataset, rules = dataset?.rules) => [...checkDataset(dataset), ...checkRules(dataset, rules || [])];

// ---- change log, locks and verification ------------------------------------------

const now = at => at || new Date().toISOString();
const logOf = state => (state.dataChangeLog ||= []);
const sameRow = (a, b) => String(a) === String(b);
function append(state, entry) {
  const log = logOf(state);
  const e = { id: `chg${log.length + 1}`, ...entry };
  log.push(e);
  return e;
}

/** Whether a row is locked: { by, at } or null. */
const own = (o, k) => o && Object.hasOwn(o, String(k)) ? o[String(k)] : null;
export const isLocked = (state, datasetId, rowId) => own(own(state?.dataLocks, datasetId), rowId);
/** Whether a row's source data have been verified: { by, at } or null. A later change clears it. */
export const isVerified = (state, datasetId, rowId) => own(own(state?.dataVerification, datasetId), rowId);

/**
 * Records one value change in state.dataChangeLog (mutating `state`). A change
 * to a locked row is refused; with `requireReason` (or
 * state.dataSettings.requireReason) a change without a reason is refused. A
 * change clears the row's source-data verification.
 * Returns { ok: true, entry } or { ok: false, error }.
 */
export function recordChange(state, { datasetId, row, column, from = '', to = '', reason = '', by = '', at } = {}, { requireReason = state?.dataSettings?.requireReason ?? false } = {}) {
  if (!datasetId || row == null || !column) return { ok: false, error: 'A change names its dataset, row and column' };
  if (isLocked(state, datasetId, row)) return { ok: false, error: `Row ${row} is locked` };
  const why = String(reason || '').trim();
  if (requireReason && !why) return { ok: false, error: 'A reason for the change is required' };
  if (String(from ?? '') === String(to ?? '')) return { ok: false, error: 'The value is unchanged' };
  const entry = append(state, { action: 'change', datasetId, row, column, from: String(from ?? ''), to: String(to ?? ''), reason: why, by, at: now(at) });
  const v = state.dataVerification?.[datasetId];
  if (own(v, row)) { delete v[String(row)]; entry.clearedVerification = true; }
  return { ok: true, entry };
}

/**
 * Sets a cell of a dataset held in state.datasets and records the change.
 * `rowIndex` is the position; the log keeps the row's identifier (rowIdOf).
 */
export function editCell(state, datasetId, rowIndex, column, to, meta = {}, options) {
  const d = (state.datasets || []).find(x => x.id === datasetId);
  if (!d || !d.rows[rowIndex] || !d.columns.some(c => c.id === column)) return { ok: false, error: 'No such cell' };
  const from = d.rows[rowIndex][column] ?? '';
  const r = recordChange(state, { ...meta, datasetId, row: rowIdOf(d, rowIndex), column, from, to }, options);
  if (r.ok) d.rows[rowIndex][column] = String(to ?? '').trim();
  return r;
}

/** Locks rows against change; logged. Returns the ids newly locked. */
export function lockRows(state, datasetId, rowIds, { by = '', at } = {}) {
  const locks = ((state.dataLocks ||= {})[datasetId] ||= {});
  const done = [];
  for (const id of rowIds || []) {
    if (own(locks, id)) continue;
    locks[String(id)] = { by, at: now(at) };
    append(state, { action: 'lock', datasetId, row: id, by, at: now(at) });
    done.push(id);
  }
  return done;
}

/** Unlocks rows; a reason is required and logged. */
export function unlockRows(state, datasetId, rowIds, { by = '', at, reason = '' } = {}) {
  if (!String(reason).trim()) return { ok: false, error: 'A reason for unlocking is required' };
  const locks = state.dataLocks?.[datasetId] || {}, done = [];
  for (const id of rowIds || []) {
    if (!own(locks, id)) continue;
    delete locks[String(id)];
    append(state, { action: 'unlock', datasetId, row: id, reason: String(reason).trim(), by, at: now(at) });
    done.push(id);
  }
  return { ok: true, unlocked: done };
}

/** Marks a row's source data as verified by `by`; logged. */
export function verifyRow(state, datasetId, rowId, by = '', at) {
  const when = now(at);
  ((state.dataVerification ||= {})[datasetId] ||= {})[String(rowId)] = { by, at: when };
  return append(state, { action: 'verify', datasetId, row: rowId, by, at: when });
}

/** The log for a dataset, or for one row of it, oldest first. */
export const changesFor = (state, datasetId, row = null) =>
  (state?.dataChangeLog || []).filter(e => e.datasetId === datasetId && (row == null || sameRow(e.row, row)));

/** Counts for a dataset's data-management state. */
export function managementSummary(state, dataset) {
  const ids = (dataset.rows || []).map((_, i) => String(rowIdOf(dataset, i)));
  return {
    rows: ids.length,
    locked: ids.filter(id => isLocked(state, dataset.id, id)).length,
    verified: ids.filter(id => isVerified(state, dataset.id, id)).length,
    changes: changesFor(state, dataset.id).filter(e => e.action === 'change').length,
  };
}

// What a project says about the analyses on its own data, without the statistics: the tables an analysis can read (the datasets and the patient
// table), the catalogue of analyses with their inputs and options, the hash that marks a kept result stale, and the kept results. The Overview, the
// progress counts, the checklist and the query layer read these on every start; the code that runs the analyses (lib/dataset-analysis.mjs, with
// the statistics modules, about 290 KB) loads with the Datasets, Analysis and Manuscript pages. dataset-analysis.mjs re-exports all of it.
import { get } from '../store.mjs';
import { DEFAULT_COLUMNS } from './ipd.mjs';

export const PATIENT_SOURCE = 'patients';
const IPD_TYPES = { number: 'number', category: 'category', boolean: 'category', date: 'date', text: 'text' };

/** The patient table as a dataset: its columns keep their ids, a yes/no column is a category. */
export function patientDataset(s = get()) {
  const people = s.participants || [];
  if (!people.length) return null;
  const columns = ((s.ipdColumns || []).length ? s.ipdColumns : DEFAULT_COLUMNS).map(c => ({ ...c, id: c.id, label: c.name || c.label || c.id, originalType: c.type, type: IPD_TYPES[c.type] || 'text' }));
  const rows = people.map(p => Object.fromEntries(columns.map(c => [c.id, p[c.id] == null ? '' : String(p[c.id])])));
  return { id: PATIENT_SOURCE, name: 'Patient data', columns, rows, rowIds: people.map(p => String(p.id)), virtual: true };
}
/** Every table an analysis can read: the datasets, then the patient table when there is one. */
export function analysisSources(s = get()) {
  const p = patientDataset(s);
  return [...(s.datasets || []), ...(p ? [p] : [])];
}
export const sourceById = (id, s = get()) => analysisSources(s).find(d => d.id === id) || null;

/** FNV-1a over the row count and the used columns' cells: cheap, and changes when any of them does. */
export function columnHash(d, ids) {
  let h = 0x811c9dc5;
  const feed = s => { for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } };
  const cols = [...new Set((ids || []).filter(Boolean))].sort();
  feed(`${d.rows.length}|${cols.join(',')}|`);
  for (const r of d.rows) for (const id of cols) { feed(String(r[id] ?? '')); feed('\u0001'); }
  return h.toString(16).padStart(8, '0');
}

/** Input levels and reference values are settings, never column ids. */
export function usedColumns(inputs, kind = null) {
  const spec = kind ? analysisOf(kind) : null;
  const keys = spec ? spec.inputs.filter(i => !i.levelOf).map(i => i.key)
    : ['group', 'variables', 'x', 'y', 'row', 'col', 'predictors', 'exposure', 'raters', 'items', 'test', 'reference', 'score', 'scoreA', 'scoreB', 'predicted'];
  return [...new Set(keys.flatMap(k => Array.isArray(inputs?.[k]) ? inputs[k] : [inputs?.[k]]).filter(v => typeof v === 'string' && v))];
}
const legacyColumns = inputs => [...new Set(Object.values(inputs || {}).flatMap(v => Array.isArray(v) ? v : [v]).filter(v => typeof v === 'string' && v))];
export const schemaHash = (d, ids) => columnHash({ rows: ids.map(id => ({ schema: JSON.stringify(d.columns.find(c => c.id === id) || null) })) }, ['schema']);


/** True when the dataset a kept analysis came from is gone, or the columns it used have changed. */
export function isStale(saved, s = get()) {
  const d = sourceById(saved.datasetId, s);
  if (!d) return true;
  const ids = usedColumns(saved.inputs, saved.kind);
  if (ids.some(id => !d.columns.some(c => c.id === id))) return true;
  if (saved.schemaVersion && schemaHash(d, ids) !== saved.schemaVersion) return true;
  if (saved.provenanceVersion && identityHash(d) !== saved.provenanceVersion) return true;
  const hash = columnHash(d, ids);
  // Results saved before column roles were separated from levels used the
  // legacy hash. Check it against the current rows; never change the result.
  return hash !== saved.rowsVersion && Boolean(saved.schemaVersion || columnHash(d, legacyColumns(saved.inputs)) !== saved.rowsVersion);
}

// ---- kept analyses ------------------------------------------------------------------

export const savedAnalyses = (s = get()) => s.datasetAnalyses || [];
export const savedFor = (datasetId, s = get()) => savedAnalyses(s).filter(a => a.datasetId === datasetId);
export const currentDatasetAnalyses = (s = get()) => savedAnalyses(s).filter(a => !isStale(a, s));


export const identityHash = d => columnHash({ rows: d.rows.map((r, index) => ({ identity: d.rowIds?.[index] ?? (d.rowKey ? r[d.rowKey] : index + 1) })) }, ['identity']);

// ---- the catalogue -------------------------------------------------------------------------

/**
 * The analyses, grouped as the picker shows them. `inputs` name the columns
 * each needs, with the role that filters its select; `level` inputs choose a
 * value of another input's column; `options` are the method choices.
 */
const PREDICTION_OPTIONS = [
  { key: 'split', label: 'Validation split', choices: [['random', 'Seeded holdout'], ['column', 'Partition column']] },
  { key: 'fraction', label: 'Holdout fraction', number: true, min: .1, max: .5, step: .01, default: .3 },
  { key: 'seed', label: 'Split seed', number: true, min: 0, max: 4294967295, step: 1, default: 1729 },
  { key: 'evaluation', label: 'Validation population', choices: [['held-out', 'Held-out sample'], ['external', 'External cohort']] },
];
const predictionInputs = [
  { key: 'predictors', label: 'Prespecified predictors', role: 'any', multi: true },
  { key: 'unit', label: 'Split unit (participant or site)', role: 'identity', optional: true },
  { key: 'partition', label: 'Development/validation partition', role: 'category', optional: true },
  { key: 'development', label: 'Development level', levelOf: 'partition', defaultLevel: 'first', optional: true },
  { key: 'validation', label: 'Validation level', levelOf: 'partition', optional: true },
];
export const ANALYSES = [
  { group: 'Describe', kind: 'table1', label: 'Table 1', inputs: [{ key: 'group', label: 'Group by', role: 'category', optional: true }, { key: 'variables', label: 'Variables', role: 'any', multi: true }],
    options: [{ key: 'summary', label: 'Continuous', choices: [['auto', 'By normality'], ['mean', 'Mean (SD)'], ['median', 'Median [IQR]']] }] },
