// Datasets: tables of the researcher's own, kept in the project beside the
// review's evidence tables — a registry export, a survey, a laboratory sheet.
// A dataset is columns and rows, nothing more: it is not keyed to the library's
// records, so any table can be brought in as it is, queried (lib/project-query.mjs,
// `from: dataset`), charted (Tables and figures) and read by an assistant.
//
//   { id, name, columns: [{ id, label, type }], rows: [{ [columnId]: value }],
//     source: { file, sheet, importedAt }, at }
//
// Types are read from the values on import (text, number, integer, date) and
// can be changed; a value that does not fit its column's type stays as typed
// and is reported by validate().
import { get, update } from '../store.mjs';
import { editCell, lockRows, unlockRows, verifyRow, rowIdOf, isLocked } from './data-rules.mjs';

export const COLUMN_TYPES = [['text', 'Text'], ['number', 'Number'], ['integer', 'Whole number'], ['date', 'Date'], ['category', 'Category']];
export const MAX_ROWS = 100_000;

export const datasets = (s = get()) => s.datasets || [];
export const datasetById = (id, s = get()) => datasets(s).find(d => d.id === id) || null;
/** A dataset by id or by name (case does not matter). */
export const findDataset = (ref, s = get()) => datasetById(ref, s) || datasets(s).find(d => d.name.toLowerCase() === String(ref || '').trim().toLowerCase()) || null;

export const newDatasetId = () => `ds${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
export const columnKey = label => String(label || '').toLowerCase().normalize('NFKD').replace(/[^\w\s]/g, ' ').replace(/[\s_]+/g, '_').replace(/^_|_$/g, '') || 'column';

const NUMBER = /^[-+]?(?:\d{1,3}(?:[ ,]\d{3})+|\d+)?(?:[.,]\d+)?(?:[eE][-+]?\d+)?%?$/;
const INTEGER = /^[-+]?(?:\d{1,3}(?:[ ,]\d{3})+|\d+)$/;
const DATE = /^(?:\d{4}-\d{2}-\d{2}(?:[T ][\d:.]+Z?)?|\d{1,2}[./-]\d{1,2}[./-]\d{2,4})$/;

/** The type the values of a column agree on; empty cells do not count, and an all-empty column is text. */
export function inferType(values) {
  const vs = values.map(v => String(v ?? '').trim()).filter(Boolean);
  if (!vs.length) return 'text';
  if (vs.every(v => INTEGER.test(v))) return 'integer';
  if (vs.every(v => NUMBER.test(v) && /\d/.test(v))) return 'number';
  if (vs.every(v => DATE.test(v))) return 'date';
  const distinct = new Set(vs.map(v => v.toLowerCase())).size;
  if (vs.length >= 8 && distinct <= Math.max(2, Math.min(12, Math.floor(vs.length / 4)))) return 'category';
  return 'text';
}

/** A cell as its column's type reads it: a number for number and integer columns, else the text. `null` for an empty cell. */
export function cellValue(v, type) {
  if (v == null || v === '') return null;
  if (type === 'number' || type === 'integer') {
    const t = String(v).trim().replace(/%$/, '').replace(/(\d)[ ,](?=\d{3}(?:\D|$))/g, '$1').replace(',', '.');
    const n = Number(t);
    return Number.isFinite(n) ? n : null;
  }
  return String(v);
}

/** Rows of cells (the first row the header) as a dataset; blank columns and blank rows are left out. */
export function fromRows(rows, { name, file = '', sheet = '', id = newDatasetId(), types = {} } = {}) {
  if (!Array.isArray(rows) || rows.length > MAX_ROWS + 1) throw new Error(`A dataset holds at most ${MAX_ROWS.toLocaleString()} rows`);
  let cells = 0;
  for (const row of rows) { if ((row?.length || 0) > 512 || (cells += row?.length || 0) > 2_000_000) throw new Error('The table exceeds the supported column or cell limit'); }
  const grid = (rows || []).map(r => (r || []).map(c => c == null ? '' : String(c)));
  const headerAt = grid.findIndex(r => r.filter(c => c.trim()).length >= 1);
  if (headerAt < 0) throw new Error('The sheet is empty');
  const header = grid[headerAt];
  const taken = new Set(), columns = [];
  header.forEach((label, col) => {
    const text = String(label).trim();
    const filled = grid.slice(headerAt + 1).some(r => String(r[col] ?? '').trim());
    if (!text && !filled) return;
    const base = columnKey(text || `column_${col + 1}`); let key = base, n = 1;
    while (taken.has(key)) key = `${base}_${++n}`;
    taken.add(key);
    columns.push({ id: key, label: text || `Column ${col + 1}`, type: 'text', col });
  });
  if (!columns.length) throw new Error('The sheet has no columns');
  const body = grid.slice(headerAt + 1).filter(r => r.some(c => c.trim()));
  if (body.length > MAX_ROWS) throw new Error(`The sheet has ${body.length.toLocaleString()} rows; a dataset holds at most ${MAX_ROWS.toLocaleString()}`);
  const out = body.map(r => Object.fromEntries(columns.map(c => [c.id, String(r[c.col] ?? '').trim()])));
  for (const c of columns) c.type = types[c.id] || types[c.label] || inferType(out.map(r => r[c.id]));
  return { id, name: String(name || sheet || file || 'Dataset').replace(/\.(xlsx|csv|tsv|txt)$/i, '').slice(0, 80), columns: columns.map(({ col, ...c }) => c), rows: out,
    source: { file, sheet, importedAt: new Date().toISOString() }, at: new Date().toISOString() };
}

/** The dataset as rows of cells, the header first: what a CSV export or a query reads. */
export const toRows = d => [d.columns.map(c => c.label), ...d.rows.map(r => d.columns.map(c => r[c.id] ?? ''))];

/** Cells that do not read as their column's type, by column: what to look at after an import or a type change. */
export function validate(d) {
  const out = [];
  for (const c of d.columns) {
    if (c.type !== 'number' && c.type !== 'integer' && c.type !== 'date') continue;
    const bad = d.rows.reduce((n, r) => n + (r[c.id] !== '' && r[c.id] != null && (c.type === 'date' ? !DATE.test(String(r[c.id]).trim()) : cellValue(r[c.id], c.type) == null || (c.type === 'integer' && !Number.isInteger(cellValue(r[c.id], c.type)))) ? 1 : 0), 0);
    if (bad) out.push({ column: c.id, label: c.label, type: c.type, count: bad });
  }
  return out;
}

// ---- edits, all through the store ------------------------------------------
export function addDataset(d) { update(s => { s.datasets = [...(s.datasets || []), d]; return s; }); return d.id; }
/** All sheets validate before the single live mutation. */
export function addDatasets(list) {
  if (!Array.isArray(list) || !list.length) throw new Error('The import has no datasets');
  const ids = new Set((get().datasets || []).map(d => d.id));
  for (const d of list) {
    if (!d?.id || ids.has(d.id) || !Array.isArray(d.columns) || !d.columns.length || d.columns.length > 512 || !Array.isArray(d.rows) || d.rows.length > MAX_ROWS || d.rows.length * d.columns.length > 2_000_000) throw new Error('The import contains an invalid, oversized or duplicate dataset');
    ids.add(d.id);
  }
  update(s => { s.datasets = [...(s.datasets || []), ...list]; return s; }); return list[0].id;
}
export function removeDataset(id) { update(s => { s.datasets = (s.datasets || []).filter(d => d.id !== id); return s; }); }
export function renameDataset(id, name) { update(s => { const d = (s.datasets || []).find(x => x.id === id); if (d) d.name = String(name || d.name).trim().slice(0, 80) || d.name; return s; }); }
export function setColumnType(id, columnId, type) {
  if (!COLUMN_TYPES.some(([t]) => t === type)) return;
  update(s => { const c = (s.datasets || []).find(x => x.id === id)?.columns.find(x => x.id === columnId); if (c) c.type = type; return s; });
}
/**
 * Sets one cell through the change log (lib/data-rules.mjs editCell): who,
 * when, from, to and why are recorded; a locked row is refused, and so is a
 * change without a reason when dataSettings.requireReason is on.
 * Returns { ok, error? }.
 */
export function setCell(id, rowIndex, columnId, value, meta = {}) {
  let r = { ok: false, error: 'No such cell' };
  update(s => {
    const d = (s.datasets || []).find(x => x.id === id);
    if (!d?.rows[rowIndex] || !d.columns.some(c => c.id === columnId)) return s;
    if (String(d.rows[rowIndex][columnId] ?? '') === String(value ?? '').trim()) { r = { ok: true, unchanged: true }; return s; }
    r = editCell(s, id, rowIndex, columnId, String(value ?? '').trim(), meta);
    if (r.ok) d.at = new Date().toISOString();
    return s;
  });
  return r;
}
export function addRow(id) { update(s => { const d = (s.datasets || []).find(x => x.id === id); if (d) { d.rows.push(Object.fromEntries(d.columns.map(c => [c.id, '']))); d.at = new Date().toISOString(); } return s; }); }
/**
 * Removes rows by index; a locked row is kept. Each removal is logged, and
 * locks and verification of a dataset without a key column follow their rows
 * to their new positions. Returns the number of locked rows kept.
 */
export function removeRows(id, indexes, { by = '' } = {}) {
  let kept = 0;
  update(s => {
    const d = (s.datasets || []).find(x => x.id === id); if (!d) return s;
    const gone = new Set([...indexes].filter(i => { const locked = isLocked(s, id, rowIdOf(d, i)); if (locked) kept++; return !locked; }));
    if (!gone.size) return s;
    const at = new Date().toISOString(), log = (s.dataChangeLog ||= []);
    for (const i of [...gone].sort((a, b) => a - b)) log.push({ id: `chg${log.length + 1}`, action: 'remove', datasetId: id, row: rowIdOf(d, i), by, at });
    if (!d.rowKey) {
      const moved = new Map(); let n = 0;
      d.rows.forEach((_, i) => { if (!gone.has(i)) moved.set(String(i), String(n++)); });
      for (const key of ['dataLocks', 'dataVerification']) {
        const m = s[key]?.[id]; if (!m) continue;
        s[key][id] = Object.fromEntries(Object.entries(m).filter(([k]) => moved.has(k)).map(([k, v]) => [moved.get(k), v]));
      }
    }
    d.rows = d.rows.filter((_, i) => !gone.has(i)); d.at = at;
    return s;
  });
  return kept;
}

// ---- data management: constraints, edit checks, locks and verification (lib/data-rules.mjs)
const withDataset = (id, fn) => update(s => { const d = (s.datasets || []).find(x => x.id === id); if (d) fn(d, s); return s; });
/** A column's constraints (column.rules); an empty object removes them. */
export function setColumnRules(id, columnId, rules) {
  withDataset(id, d => { const c = d.columns.find(x => x.id === columnId); if (!c) return; if (rules && Object.keys(rules).length) c.rules = rules; else delete c.rules; });
}
/** The dataset's edit checks (dataset.rules). */
export function setDatasetRules(id, rules) { withDataset(id, d => { d.rules = rules || []; }); }
/** A project-wide data-management setting (state.dataSettings). */
export function setDataSetting(key, value) { update(s => { s.dataSettings = { ...(s.dataSettings || {}), [key]: value }; return s; }); }
export function lockDatasetRows(id, rowIds, by = '') { let done = []; update(s => { done = lockRows(s, id, rowIds, { by }); return s; }); return done; }
export function unlockDatasetRows(id, rowIds, { by = '', reason = '' } = {}) { let r; update(s => { r = unlockRows(s, id, rowIds, { by, reason }); return s; }); return r; }
export function verifyDatasetRows(id, rowIds, by = '') { update(s => { for (const r of rowIds) verifyRow(s, id, r, by); return s; }); }
/** Rows added to a dataset in one step (an import of records), logged as one entry; the columns may grow. */
export function appendRows(id, rows, { columns = null, by = '', source = '' } = {}) {
  withDataset(id, (d, s) => {
    if (columns) d.columns = columns;
    d.rows = [...d.rows.map(r => Object.fromEntries(d.columns.map(c => [c.id, r[c.id] ?? '']))), ...rows.map(r => Object.fromEntries(d.columns.map(c => [c.id, r[c.id] == null ? '' : String(r[c.id])])))];
    d.at = new Date().toISOString();
    const log = (s.dataChangeLog ||= []);
    log.push({ id: `chg${log.length + 1}`, action: 'import', datasetId: id, row: null, rows: rows.length, source, by, at: d.at });
  });
}

const text = v => typeof v === 'string' ? v : v == null ? '' : String(v);
const texts = v => Array.isArray(v) ? v.map(text).map(x => x.trim()).filter(Boolean) : [];
const bound = v => typeof v === 'number' ? (Number.isFinite(v) ? v : undefined) : typeof v === 'string' && v.trim() ? v.trim() : undefined;
/** Column constraints as saved: only the known keys, each of its kind (lib/data-rules.mjs). */
export function normalizeColumnRules(r) {
  if (!r || typeof r !== 'object' || Array.isArray(r)) return null;
  const out = {};
  if (r.required) out.required = true;
  for (const k of ['min', 'max']) { const b = bound(r[k]); if (b !== undefined) out[k] = b; }
  const allowed = texts(r.allowed); if (allowed.length) out.allowed = allowed;
  const missing = texts(r.missingCodes); if (missing.length) out.missingCodes = missing;
  for (const k of ['pattern', 'unit']) if (text(r[k]).trim()) out[k] = text(r[k]).trim();
  return Object.keys(out).length ? out : null;
}
function normalizeColumn(c) {
  const out = { id: String(c.id), label: String(c.label || c.id), type: COLUMN_TYPES.some(([t]) => t === c.type) ? c.type : 'text' };
  const rules = normalizeColumnRules(c.rules); if (rules) out.rules = rules;
  if (Array.isArray(c.choices)) { const ch = c.choices.filter(x => x && typeof x === 'object').map(x => ({ code: text(x.code), label: text(x.label) })); if (ch.length) out.choices = ch; }
  if (c.redcap && typeof c.redcap === 'object' && !Array.isArray(c.redcap)) out.redcap = { ...c.redcap };
  if (c.identifier) out.identifier = true;
  if (text(c.branching).trim()) out.branching = text(c.branching);
  if (text(c.note).trim()) out.note = text(c.note);
  return out;
}
/** Edit checks as saved: { id, text, message?, severity?, off? }; a bare text is one. */
export function normalizeDatasetRules(list) {
  if (!Array.isArray(list)) return [];
  return list.flatMap((r, i) => {
    const o = typeof r === 'string' ? { text: r } : r && typeof r === 'object' ? r : null;
    if (!o || !text(o.text).trim()) return [];
    return [{ id: text(o.id) || `rule${i + 1}`, text: text(o.text), ...(text(o.message).trim() ? { message: text(o.message) } : {}),
      ...(o.severity === 'warning' || o.severity === 'info' ? { severity: o.severity } : {}), ...(o.off ? { off: true } : {}) }];
  });
}

/**
 * A saved project's datasets, put right: every column keyed, every row an
 * object of strings. Data-management fields survive: column constraints,
 * choices, REDCap field records, identifier and branching; a dataset's edit
 * checks, row key, REDCap extras and log template.
 */
export function normalizeDatasets(list) {
  if (!Array.isArray(list)) return [];
  return list.flatMap(d => {
    if (!d || typeof d !== 'object' || !Array.isArray(d.columns) || !Array.isArray(d.rows)) return [];
    const columns = d.columns.filter(c => c && c.id).map(normalizeColumn);
    const rows = d.rows.filter(r => r && typeof r === 'object').map(r => Object.fromEntries(columns.map(c => [c.id, r[c.id] == null ? '' : String(r[c.id])])));
    const { rules, rowKey, redcap, template, ...rest } = d;
    const kept = normalizeDatasetRules(rules);
    return [{ ...rest, id: String(d.id || newDatasetId()), name: String(d.name || 'Dataset'), columns, rows,
      ...(kept.length ? { rules: kept } : {}),
      ...(rowKey && columns.some(c => c.id === rowKey) ? { rowKey: String(rowKey) } : {}),
      ...(redcap && typeof redcap === 'object' && !Array.isArray(redcap) ? { redcap: { ...redcap } } : {}),
      ...(typeof template === 'string' && template ? { template } : {}) }];
  });
}

const plainObject = v => v && typeof v === 'object' && !Array.isArray(v);
/**
 * The project's data-management state put right (store normalizeProject):
 * the change log, locks and verification by dataset and row, settings, and
 * the sealed allocations with their audit log.
 */
export function normalizeDataManagement(next) {
  next.dataChangeLog = Array.isArray(next.dataChangeLog) ? next.dataChangeLog.filter(e => plainObject(e) && e.datasetId && e.action) : [];
  for (const k of ['dataLocks', 'dataVerification']) {
    next[k] = plainObject(next[k]) ? Object.fromEntries(Object.entries(next[k]).filter(([, v]) => plainObject(v))) : {};
  }
  next.dataSettings = plainObject(next.dataSettings) ? { ...next.dataSettings, requireReason: !!next.dataSettings.requireReason } : { requireReason: false };
  next.allocations = Array.isArray(next.allocations) ? next.allocations.filter(a => plainObject(a) && a.id && Array.isArray(a.entries) && plainObject(a.vault)) : [];
  next.allocationLog = Array.isArray(next.allocationLog) ? next.allocationLog.filter(e => plainObject(e) && e.allocationId && e.hash) : [];
  return next;
}

// The one place the interface formats a time, a time ago and a counted noun (roadmap S6, UI_Guidelines "Dates and counts").
//
//   when(iso)   "7 Oct, 20:22"       a moment: day, month, 24-hour time, no seconds; "7 Oct 2025, 20:22" in another year
//   day(iso)    "7 Oct"              a day; "7 Oct 2025" in another year
//   ago(iso)    "1 h ago"            "just now", "5 min ago", "1 h ago", "3 d ago"; past 30 days the day
//   monthYear / longDay / clock  "October 2026", "Monday 7 October 2026", "20:22"  a calendar's month, a day's accessible name, a time of day
//   plural(n, one, many)  "2 rows"   the count with its noun; thousands grouped with a comma
//
// Nothing here asks the host for a locale: toLocaleString and Intl follow the machine's region, so one page printed "10/7/2026, 8:22:29 PM" beside
// "7 Oct, 20:22". Month names, the 24-hour clock and the grouping are written out, so the text is the same on every machine. Times are the viewer's local time.
// Every function takes a time as an ISO string, a Date or milliseconds, and returns '' for anything else: a view never prints "Invalid Date" or "NaN".
// `now` is a parameter so a test, or a view that draws many rows, reads the clock once.

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const DATE_ONLY = /^(\d{4})-(\d{2})-(\d{2})$/;
const two = n => String(n).padStart(2, '0');

/** A Date for a time value, or null. A date with no time ("2026-10-05") is that day here, not UTC midnight, which is the previous evening west of Greenwich. */
export function toDate(value) {
  if (value == null || value === '' || typeof value === 'boolean') return null;
  let d;
  if (value instanceof Date) d = new Date(value.getTime());
  else if (typeof value === 'number') d = new Date(value);
  else if (typeof value === 'string') {
    const m = DATE_ONLY.exec(value.trim());
    d = m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]), 12) : new Date(value);
  } else return null;
  return Number.isNaN(d.getTime()) ? null : d;
}

const isDateOnly = value => typeof value === 'string' && DATE_ONLY.test(value.trim());
const nowYear = now => toDate(now)?.getFullYear() ?? new Date().getFullYear();
const dayText = (d, now) => `${d.getDate()} ${MONTHS[d.getMonth()]}${d.getFullYear() === nowYear(now) ? '' : ` ${d.getFullYear()}`}`;

/** "7 Oct" (the year only when it is not this year). */
export function day(value, now = Date.now()) {
  const d = toDate(value);
  return d ? dayText(d, now) : '';
}

/** "October 2026": the month a calendar shows. */
export function monthYear(value) {
  const d = toDate(value);
  return d ? `${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}` : '';
}

/** "Monday 7 October 2026": a day written out in full, for a control's accessible name. */
export function longDay(value) {
  const d = toDate(value);
  return d ? `${WEEKDAYS[d.getDay()]} ${d.getDate()} ${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}` : '';
}

/** "20:22": the clock time alone, 24-hour. */
export function clock(value) {
  const d = toDate(value);
  return d ? `${two(d.getHours())}:${two(d.getMinutes())}` : '';
}

/** "7 Oct, 20:22" (the year only when it is not this year). A date with no time is a day. */
export function when(value, now = Date.now()) {
  const d = toDate(value);
  if (!d) return '';
  return isDateOnly(value) ? dayText(d, now) : `${dayText(d, now)}, ${two(d.getHours())}:${two(d.getMinutes())}`;
}

/** "just now", "5 min ago", "1 h ago", "3 d ago"; thirty days and more is the day; a time more than a minute ahead is a moment ("7 Oct, 20:22"). */
export function ago(value, now = Date.now()) {
  const d = toDate(value), n = toDate(now);
  if (!d || !n) return '';
  const minutes = (n.getTime() - d.getTime()) / 60000;
  if (minutes < -1) return when(value, now);
  if (minutes < 1) return 'just now';
  if (minutes < 60) return `${Math.floor(minutes)} min ago`;
  if (minutes < 60 * 24) return `${Math.floor(minutes / 60)} h ago`;
  if (minutes < 60 * 24 * 30) return `${Math.floor(minutes / 1440)} d ago`;
  return dayText(d, now);
}

/** A number with its thousands grouped by a comma: 1234567 -> "1,234,567". A decimal keeps its own digits. '' for anything that is not a finite number. */
export function num(n) {
  if (typeof n === 'string' && n.trim() !== '') n = Number(n);
  if (typeof n !== 'number' || !Number.isFinite(n)) return '';
  const [int, frac] = String(Math.abs(n)).split('.');
  if (/e/i.test(int + (frac || ''))) return String(n);
  return `${n < 0 ? '-' : ''}${int.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}${frac ? `.${frac}` : ''}`;
}

/** The count with its noun: plural(1, 'row') "1 row", plural(2, 'row') "2 rows", plural(2, 'study', 'studies') "2 studies", plural(1234, 'record') "1,234 records". '' when n is not a number. */
export function plural(n, one, many = `${one}s`) {
  const text = num(n);
  return text === '' ? '' : `${text} ${Math.abs(Number(n)) === 1 ? one : many}`;
}

// Manuscript declarations: author contributions (CRediT), ICMJE authorship,
// competing interests, funding, ethics, consent, data availability, AI use,
// acknowledgements and registration, kept as one record at state.declarations,
// and the title page built from the paper's authors.
//
// Everything here is written from what the authors entered. Where a statement
// a journal requires has nothing behind it, the text is a [bracketed]
// placeholder for the author to replace, never a sentence the app made up.
//
// Pure: nothing here imports the store or a view.
import { newId } from './manuscript.mjs';
import { typeById } from './research-types.mjs';

// ---- CRediT ------------------------------------------------------------------
// The Contributor Roles Taxonomy (NISO Z39.104-2022), in its own order and with
// its own names; the dash in the two writing roles is an en dash.
export const CREDIT_ROLES = [
  { id: 'conceptualization', name: 'Conceptualization' },
  { id: 'data-curation', name: 'Data curation' },
  { id: 'formal-analysis', name: 'Formal analysis' },
  { id: 'funding-acquisition', name: 'Funding acquisition' },
  { id: 'investigation', name: 'Investigation' },
  { id: 'methodology', name: 'Methodology' },
  { id: 'project-administration', name: 'Project administration' },
  { id: 'resources', name: 'Resources' },
  { id: 'software', name: 'Software' },
  { id: 'supervision', name: 'Supervision' },
  { id: 'validation', name: 'Validation' },
  { id: 'visualization', name: 'Visualization' },
  { id: 'writing-original-draft', name: 'Writing – original draft' },
  { id: 'writing-review-editing', name: 'Writing – review & editing' },
];
export const CREDIT_DEGREES = ['lead', 'equal', 'supporting'];

const fold = s => String(s || '').toLowerCase().replace(/[‐-―-]/g, ' ').replace(/&/g, 'and').replace(/\s+/g, ' ').trim();
/** A CRediT role by id or by name (any dash, "&" or "and"); null for anything else. */
export function creditRole(role) {
  const f = fold(role);
  return CREDIT_ROLES.find(r => r.id === role || fold(r.name) === f || fold(r.id) === f) || null;
}

// ICMJE, "Defining the Role of Authors and Contributors": an author meets all four.
export const ICMJE_CRITERIA = [
  { id: 'c1', label: 'Substantial contributions to the conception or design of the work, or the acquisition, analysis or interpretation of data' },
  { id: 'c2', label: 'Drafting the work or reviewing it critically for important intellectual content' },
  { id: 'c3', label: 'Final approval of the version to be published' },
  { id: 'c4', label: 'Agreement to be accountable for all aspects of the work' },
];

export const CONFLICT_KINDS = ['none', 'financial', 'nonfinancial'];
export const CONSENT_TYPES = ['written', 'waived', 'not applicable'];
export const DATA_CHOICES = ['repository', 'on request', 'in paper', 'not available', 'not applicable'];

// ---- the record ----------------------------------------------------------------

/** An empty declarations record; the registration is the paper's. */
export function blankDeclarations(paper = {}) {
  return {
    contributions: {}, icmje: {}, conflicts: [], funding: [], noFunding: false,
    ethics: { committee: '', reference: '', date: '', waiver: false, text: '' },
    consent: { type: '', text: '' },
    dataAvailability: { choice: '', repository: '', doi: '', conditions: '', text: '' },
    aiUse: '', acknowledgements: '',
    trialRegistration: String(paper?.registration || ''),
  };
}

/** A stored record with every field present; the registration is always read from the paper when one is given. */
export function normalizeDeclarations(decl = {}, paper) {
  const b = blankDeclarations(paper);
  const d = decl || {};
  return {
    ...b, ...d,
    contributions: { ...(d.contributions || {}) },
    icmje: { ...(d.icmje || {}) },
    conflicts: [...(d.conflicts || [])],
    funding: [...(d.funding || [])],
    noFunding: !!d.noFunding,
    ethics: { ...b.ethics, ...(d.ethics || {}) },
    consent: { ...b.consent, ...(d.consent || {}) },
    dataAvailability: { ...b.dataAvailability, ...(d.dataAvailability || {}) },
    trialRegistration: paper ? String(paper.registration || '') : String(d.trialRegistration || ''),
  };
}

const nameOf = a => String((typeof a === 'string' ? a : a?.name) || '').trim();
const namesOf = authors => (authors || []).map(nameOf).filter(Boolean);
const has = s => !!String(s ?? '').trim();
const typeOf = t => (typeof t === 'string' ? typeById(t) : t) || null;

// Studies of people need an ethics statement and a consent statement. A guideline
// and an economic evaluation may use no participant data (a model), so for them a
// missing statement is a flag; an animal study needs approval but not consent.
const NO_PARTICIPANTS = new Set(['guideline']);
const MAYBE_PARTICIPANTS = new Set(['economic-evaluation']);
function ethicsNeed(researchType) {
  const t = typeOf(researchType);
  if (!t || !['primary', 'patients'].includes(t.kind) || NO_PARTICIPANTS.has(t.id)) return null;
  return MAYBE_PARTICIPANTS.has(t.id) ? 'warning' : 'error';
}
function consentNeed(researchType) {
  const need = ethicsNeed(researchType);
  return typeOf(researchType)?.id === 'animal-study' ? null : need;
}
const ethicsGiven = e => !!e && (has(e.text) || has(e.committee) || e.waiver);
const consentGiven = c => !!c && (has(c.type) || has(c.text));
const dataGiven = d => !!d && (has(d.choice) || has(d.text));
const fundingGiven = decl => decl.noFunding || (decl.funding || []).some(f => has(f.funder) || has(f.text));

/**
 * What is missing or doubtful, as `[{ level: 'error'|'warning', key, author?, text }]`.
 * An error is a statement a journal requires and does not have; a warning is a
 * flag for the authors to look at (an ICMJE criterion not met does not stop
 * anything — that person may belong in the acknowledgements).
 * `researchType` (an id or entry of lib/research-types.mjs) decides whether
 * ethics and consent are required.
 */
export function validate(decl, authors, { researchType = null } = {}) {
  const d = normalizeDeclarations(decl);
  const names = namesOf(authors);
  const out = [];
  const push = (level, key, text, author) => out.push({ level, key, ...(author ? { author } : {}), text });
  for (const n of names) {
    const roles = (d.contributions[n] || []).filter(r => creditRole(r?.role));
    if (!roles.length) push('error', 'contributions', `${n} has no CRediT role`, n);
  }
  for (const n of names) {
    const c = d.icmje[n] || {};
    const missing = ICMJE_CRITERIA.filter(k => !c[k.id]).map(k => Number(k.id.slice(1)));
    if (missing.length) push('warning', 'icmje', `${n} does not meet ICMJE criteri${missing.length === 1 ? 'on' : 'a'} ${missing.join(', ')}; consider the acknowledgements instead of authorship`, n);
  }
  for (const n of names) {
    const c = d.conflicts.find(x => x?.author === n);
    if (!c || !CONFLICT_KINDS.includes(c.kind)) push('error', 'conflicts', `No competing-interests statement for ${n}`, n);
    else if (c.kind !== 'none' && !has(c.text)) push('error', 'conflicts', `${n} declares ${c.kind === 'financial' ? 'a financial' : 'a non-financial'} interest without describing it`, n);
  }
  const known = new Set(names);
  const stale = new Set([...Object.keys(d.contributions), ...Object.keys(d.icmje), ...d.conflicts.map(c => c?.author)].filter(n => n && !known.has(n)));
  for (const n of stale) push('warning', 'authors', `${n} has declarations but is not an author`, n);
  if (!fundingGiven(d)) push('error', 'funding', 'Funding is neither stated nor declared as none');
  const eNeed = ethicsNeed(researchType);
  if (eNeed && !ethicsGiven(d.ethics)) push(eNeed, 'ethics', 'No ethics approval or waiver is stated');
  const cNeed = consentNeed(researchType);
  if (cNeed && !consentGiven(d.consent)) push(cNeed, 'consent', 'No consent statement');
  if (!dataGiven(d.dataAvailability)) push('error', 'dataAvailability', 'No data availability statement');
  return out;
}

// ---- statements ------------------------------------------------------------------

const initials = name => name.split(/[\s.]+/).filter(Boolean).map(w => w.split('-').map(p => p[0]?.toUpperCase() || '').join('-')).join('');
const list = xs => xs.length <= 1 ? xs.join('') : xs.length === 2 ? `${xs[0]} and ${xs[1]}` : `${xs.slice(0, -1).join(', ')}, and ${xs.at(-1)}`;
const sentence = s => { const t = String(s || '').trim(); return !t ? '' : /[.!?)\]]$/.test(t) ? t : `${t}.`; };
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
/** "2026-09-29" as "29 September 2026"; anything else as written. */
export function longDate(d) {
  const iso = d instanceof Date ? d.toISOString().slice(0, 10) : String(d || '').trim();
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso);
  return m ? `${Number(m[3])} ${MONTHS[Number(m[2]) - 1]} ${m[1]}` : iso;
}

function contributionsText(d, names, style) {
  if (!names.length) return '[Author contributions: list each author with their CRediT roles.]';
  const label = n => style === 'icmje' ? initials(n) : n;
  const lines = names.map(n => {
    const given = (d.contributions[n] || []).map(r => ({ role: creditRole(r?.role), degree: CREDIT_DEGREES.includes(r?.degree) ? r.degree : '' })).filter(r => r.role);
    const roles = CREDIT_ROLES.map(role => given.find(g => g.role === role)).filter(Boolean)
      .map(g => g.degree ? `${g.role.name} (${g.degree})` : g.role.name);
    return `${label(n)}: ${roles.length ? roles.join(', ') : `[CRediT roles for ${n}]`}.`;
  });
  // Said only when every author has recorded criteria 3 and 4.
  const allApproved = names.every(n => d.icmje[n]?.c3 && d.icmje[n]?.c4);
  if (allApproved) lines.push(names.length === 1
    ? 'The author approved the final version of the manuscript and agrees to be accountable for all aspects of the work.'
    : 'All authors approved the final version of the manuscript and agree to be accountable for all aspects of the work.');
  return lines.join(' ');
}

function conflictsText(d, names) {
  if (!names.length) return '[Competing interests statement.]';
  const by = n => d.conflicts.find(c => c?.author === n);
  if (names.every(n => by(n)?.kind === 'none'))
    return names.length === 1 ? 'The author declares no competing interests.' : 'The authors declare no competing interests.';
  const none = names.filter(n => by(n)?.kind === 'none');
  const out = [];
  for (const n of names) {
    const c = by(n);
    if (!c || !CONFLICT_KINDS.includes(c.kind)) { out.push(`[Competing interests of ${n}.]`); continue; }
    if (c.kind === 'none') continue;
    out.push(`${n} declares ${c.kind === 'financial' ? 'financial' : 'non-financial'} interests: ${has(c.text) ? sentence(c.text) : `[describe the interests of ${n}.]`}`);
  }
  if (none.length) out.push(`${list(none)} declare${none.length === 1 ? 's' : ''} no competing interests.`);
  return out.join(' ');
}

function fundingText(d) {
  if (d.noFunding) return 'This research received no specific grant from any funding agency in the public, commercial or not-for-profit sectors.';
  const rows = d.funding.filter(f => has(f.funder));
  if (!rows.length) return '[Funding: name each funder and grant number, or state that the work received no specific funding.]';
  const parts = rows.map(f => `${f.funder.trim()}${has(f.grant) ? ` (grant ${f.grant.trim()})` : ''}${has(f.recipient) ? ` to ${f.recipient.trim()}` : ''}`);
  const out = [`This work was supported by ${list(parts)}.`];
  const roles = rows.filter(f => has(f.role)).map(f => sentence(f.role));
  out.push(roles.length ? roles.join(' ') : '[State the role of the funder in study design, data collection, analysis and interpretation, writing, and the decision to submit, or that it had none.]');
  return out.join(' ');
}

function ethicsText(d, researchType) {
  const e = d.ethics;
  const t = typeOf(researchType);
  const ref = [has(e.reference) ? `reference ${e.reference.trim()}` : '', has(e.date) ? longDate(e.date) : ''].filter(Boolean).join('; ');
  const out = [];
  if (e.waiver) out.push(`${has(e.committee) ? `${e.committee.trim()} waived the requirement for ethical approval` : 'The requirement for ethical approval was waived'}${ref ? ` (${ref})` : ''}.`);
  else if (has(e.committee)) out.push(`This study was approved by ${e.committee.trim()}${ref ? ` (${ref})` : ''}.`);
  if (has(e.text)) out.push(sentence(e.text));
  if (out.length) return out.join(' ');
  if (t?.kind === 'review') return '[Ethics: state whether approval was required for this review of published studies.]';
  return '[Ethics: name the approving committee, the reference number and the date, or state why approval was not required.]';
}

function consentText(d, researchType) {
  const c = d.consent;
  const t = typeOf(researchType);
  const whom = t?.id === 'case-report' ? 'the patient for publication of this case report and any accompanying images' : 'all participants';
  const out = [];
  if (c.type === 'written') out.push(`Written informed consent was obtained from ${whom}.`);
  else if (c.type === 'waived') out.push(`The requirement for informed consent was waived${has(d.ethics.committee) ? ` by ${d.ethics.committee.trim()}` : ''}.`);
  else if (c.type === 'not applicable') out.push('Not applicable.');
  if (has(c.text)) out.push(sentence(c.text));
  if (out.length) return out.join(' ');
  return consentNeed(researchType) ? '[Consent: state how informed consent was obtained, or who waived it.]' : '';
}

// The standard templates (the forms ICMJE's data sharing statements and most
// publishers' policies give).
function dataText(d) {
  const a = d.dataAvailability;
  if (has(a.text)) return sentence(a.text);
  const cond = has(a.conditions) ? ` ${sentence(a.conditions)}` : '';
  switch (a.choice) {
    case 'repository':
      return `The data that support the findings of this study are openly available in ${has(a.repository) ? a.repository.trim() : '[repository name]'}${has(a.doi) ? ` at ${a.doi.trim()}` : ' at [DOI or accession number]'}.${cond}`;
    case 'on request':
      return `The data that support the findings of this study are available from the corresponding author upon reasonable request.${cond}`;
    case 'in paper':
      return `All data generated or analysed during this study are included in this article and its supplementary information files.${cond}`;
    case 'not available':
      return `The data that support the findings of this study are not publicly available${has(a.conditions) ? ` because ${a.conditions.trim().replace(/^because\s+/i, '').replace(/\.$/, '')}` : ' because [reason, for example participant privacy]'}.`;
    case 'not applicable':
      return 'Data sharing is not applicable to this article as no new data were created or analysed in this study.';
    default:
      return '[Data availability: state where the data can be found, on what conditions, or why they cannot be shared.]';
  }
}

function registrationText(d, researchType) {
  const reg = String(d.trialRegistration || '').trim();
  if (!reg) return '';
  const t = typeOf(researchType);
  const what = t?.id === 'rct' ? 'This trial was registered' : t?.kind === 'review' ? 'The review protocol was registered' : 'This study was registered';
  return `${what}: ${reg.replace(/\.$/, '')}.`;
}

/**
 * Ready-to-insert statements. `style: 'plain'` names authors in full;
 * 'icmje' uses their initials, as most ICMJE-journal contribution statements do.
 * A required statement with nothing entered is a [bracketed] placeholder; an
 * optional one (AI use, acknowledgements, registration) is '' when empty.
 */
export function statements(decl, authors, { style = 'plain', researchType = null } = {}) {
  const d = normalizeDeclarations(decl);
  const names = namesOf(authors);
  return {
    contributions: contributionsText(d, names, style),
    conflicts: conflictsText(d, names),
    funding: fundingText(d),
    ethics: ethicsText(d, researchType),
    consent: consentText(d, researchType),
    dataAvailability: dataText(d),
    aiUse: has(d.aiUse) ? sentence(d.aiUse) : '',
    acknowledgements: has(d.acknowledgements) ? sentence(d.acknowledgements) : '',
    registration: registrationText(d, researchType),
  };
}

// Headings the manuscript structure already recognises as back matter
// (lib/manuscript-structure.mjs), in the order most journals print them.
export const STATEMENT_HEADINGS = [
  ['acknowledgements', 'Acknowledgements'],
  ['contributions', 'Author contributions'],
  ['funding', 'Funding'],
  ['conflicts', 'Competing interests'],
  ['ethics', 'Ethics approval'],
  ['consent', 'Informed consent'],
  ['registration', 'Registration'],
  ['dataAvailability', 'Data availability'],
  ['aiUse', 'Use of artificial intelligence'],
];

const block = (type, text, runs) => ({ id: newId(), type, text, ...(runs ? { runs } : {}) });

/** The statements as manuscript blocks, an h2 and a paragraph each, for the end of the manuscript; empty optional ones are left out. */
export function statementBlocks(decl, authors, opts = {}) {
  const s = statements(decl, authors, opts);
  return STATEMENT_HEADINGS.filter(([k]) => s[k]).flatMap(([k, h]) => [block('h2', h), block('p', s[k])]);
}

// ---- title page --------------------------------------------------------------------

const SYMBOLS = ['*', '†', '‡', '§', '¶'];
const affiliationsOf = a => (Array.isArray(a?.affiliations) ? a.affiliations : String(a?.affiliation || '').split(/\s*;\s*/))
  .map(x => String(x || '').trim()).filter(Boolean);

/**
 * The title page as `{ blocks, warnings }`.
 *
 * `authors` default to `paper.authors`: `{ name, affiliation (";"-separated) or
 * affiliations[], email?, orcid?, corresponding?, equal?, address? }`.
 * `affiliations` optionally overrides them by author name ({ [name]: string[] }).
 * Affiliations are numbered in order of first appearance, so two authors at one
 * institution share its number. The corresponding author (author.corresponding,
 * else paper.correspondingAuthor) takes the first footnote symbol; equal
 * contribution the next. `correspondence` ({ name, address, email, phone })
 * overrides the corresponding author's details. `runningTitle` is warned about
 * over `runningTitleLimit` characters (default 50, counting spaces).
 * `counts` is { abstract, main, tables, figures, references } as the caller
 * measured them; `keywords` a list or a ";"-separated string.
 */
export function titlePage({ paper = {}, authors, affiliations = null, correspondence = null, runningTitle = '', runningTitleLimit = 50, keywords = [], counts = null } = {}) {
  const warnings = [];
  const people = (authors || paper.authors || []).filter(a => nameOf(a));
  const affOf = a => (affiliations?.[nameOf(a)] ? [].concat(affiliations[nameOf(a)]).map(x => String(x).trim()).filter(Boolean) : affiliationsOf(a));
  const numbers = new Map();
  for (const a of people) for (const x of affOf(a)) if (!numbers.has(x)) numbers.set(x, numbers.size + 1);

  const correspondingName = people.find(a => a.corresponding)?.name || paper.correspondingAuthor || '';
  const corresponding = people.find(a => nameOf(a) === String(correspondingName).trim()) || null;
  if (people.length && !corresponding && !correspondence?.name) warnings.push({ key: 'corresponding', text: 'No corresponding author is marked' });
  const equal = people.filter(a => a.equal || a.equalContribution);
  if (equal.length === 1) warnings.push({ key: 'equal', text: `${nameOf(equal[0])} is the only author marked as contributing equally` });
  const notes = [];
  if (corresponding || correspondence?.name) notes.push({ key: 'corresponding', text: 'Corresponding author.' });
  if (equal.length) notes.push({ key: 'equal', text: `${list(equal.map(nameOf))} contributed equally to this work.` });
  notes.forEach((n, i) => { n.symbol = SYMBOLS[i]; });
  const sym = key => notes.find(n => n.key === key)?.symbol || '';

  const blocks = [block('h1', String(paper.title || '').trim() || '[Title]')];
  if (people.length) {
    const runs = [];
    people.forEach((a, i) => {
      if (i) runs.push({ t: ', ' });
      runs.push({ t: nameOf(a) });
      const nums = affOf(a).map(x => numbers.get(x)).join(',');
      const marks = (a === corresponding ? sym('corresponding') : '') + (equal.includes(a) ? sym('equal') : '');
      const sup = nums + marks;
      if (sup) runs.push({ t: sup, sup: true });
    });
    blocks.push(block('p', runs.map(r => r.t).join(''), runs));
  } else blocks.push(block('p', '[Authors]'));
  const missingAff = people.filter(a => !affOf(a).length).map(nameOf);
  if (missingAff.length) warnings.push({ key: 'affiliations', text: `No affiliation for ${list(missingAff)}` });

  for (const [aff, n] of numbers) blocks.push(block('p', `${n} ${aff}`, [{ t: String(n), sup: true }, { t: ` ${aff}` }]));
  for (const n of notes) blocks.push(block('p', `${n.symbol} ${n.text}`, [{ t: n.symbol, sup: true }, { t: ` ${n.text}` }]));

  // Correspondence: the corresponding author's details, overridden field by field.
  const c = { name: nameOf(corresponding), address: corresponding?.address || affOf(corresponding || {})[0] || '', email: corresponding?.email || '', phone: corresponding?.phone || '', ...(correspondence || {}) };
  if (has(c.name)) {
    const parts = [`Correspondence: ${c.name.trim()}`, has(c.address) ? c.address.trim() : '[postal address]', `email: ${has(c.email) ? c.email.trim() : '[email]'}`];
    if (has(c.phone)) parts.push(`telephone: ${c.phone.trim()}`);
    blocks.push(block('p', `${parts.join(', ')}.`));
    if (!has(c.email)) warnings.push({ key: 'email', text: `No email for the corresponding author, ${c.name.trim()}` });
  }

  const rt = String(runningTitle || '').trim();
  if (rt) {
    blocks.push(block('p', `Running title: ${rt}`));
    if (runningTitleLimit && rt.length > runningTitleLimit)
      warnings.push({ key: 'runningTitle', text: `The running title is ${rt.length} characters, over the limit of ${runningTitleLimit}` });
  }

  if (counts) {
    const n = x => Number(x).toLocaleString('en-US');
    const parts = [];
    if (counts.abstract != null) parts.push(`abstract ${n(counts.abstract)}`);
    if (counts.main != null) parts.push(`main text ${n(counts.main)}`);
    const tail = [['tables', 'Tables'], ['figures', 'Figures'], ['references', 'References']].filter(([k]) => counts[k] != null).map(([k, l]) => `${l}: ${n(counts[k])}`);
    const text = [parts.length ? `Word count: ${parts.join('; ')}` : '', ...tail].filter(Boolean).join('. ');
    if (text) blocks.push(block('p', `${text}.`));
  }

  const kw = (Array.isArray(keywords) ? keywords : String(keywords || '').split(/\s*[;,]\s*/)).map(k => String(k).trim()).filter(Boolean);
  if (kw.length) blocks.push(block('p', `Keywords: ${kw.join('; ')}`));
  return { blocks, warnings };
}

// Descriptive statistics for a patient table, by group — the "Table 1/Table 2"
// of a clinical paper.
//
// Computed here rather than in R. These are exact order statistics and counts;
// sending them through WebR would mean starting an engine and waiting seconds
// for numbers a browser produces instantly. The two tests that accompany them
// (Kruskal-Wallis, Pearson chi-square) need only a chi-square upper tail, which
// is implemented below and checked against R in bench/describe.mjs.
//
// Nothing here decides significance. A p-value is reported beside the counts it
// came from, with the test named, so the reader can judge whether the test was
// appropriate (plan H4).
import { fisherExact } from './stats-tables.mjs';

// ---- distributions --------------------------------------------------------

// Lanczos approximation; accurate to ~15 significant figures for x > 0.
const LANCZOS = [
  676.5203681218851, -1259.1392167224028, 771.32342877765313,
  -176.61502916214059, 12.507343278686905, -0.13857109526572012,
  9.9843695780195716e-6, 1.5056327351493116e-7,
];
function lgamma(x) {
  if (x < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * x)) - lgamma(1 - x);
  x -= 1;
  let a = 0.99999999999980993;
  const t = x + 7.5;
  for (let i = 0; i < LANCZOS.length; i++) a += LANCZOS[i] / (x + i + 1);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}

/** Regularised lower incomplete gamma P(s, x), by series or continued fraction. */
function gammaP(s, x) {
  if (x <= 0) return 0;
  if (x < s + 1) {                       // series converges fast here
    let sum = 1 / s, term = sum;
    for (let n = 1; n < 1000; n++) {
      term *= x / (s + n);
      sum += term;
      if (Math.abs(term) < Math.abs(sum) * 1e-15) break;
    }
    return sum * Math.exp(-x + s * Math.log(x) - lgamma(s));
  }
  return 1 - gammaQcf(s, x);
}

/** Regularised upper incomplete gamma Q(s, x) by Lentz's continued fraction. */
function gammaQcf(s, x) {
  const TINY = 1e-300;
  let b = x + 1 - s, c = 1 / TINY, d = 1 / b, h = d;
  for (let i = 1; i < 1000; i++) {
    const an = -i * (i - s);
    b += 2;
    d = an * d + b; if (Math.abs(d) < TINY) d = TINY;
    c = b + an / c;  if (Math.abs(c) < TINY) c = TINY;
    d = 1 / d;
    const del = d * c;
    h *= del;
    if (Math.abs(del - 1) < 1e-15) break;
  }
  return h * Math.exp(-x + s * Math.log(x) - lgamma(s));
}

/** P(X > q) for a chi-square with `df` degrees of freedom. */
export function pchisqUpper(q, df) {
  if (!(q > 0) || !(df > 0)) return 1;
  return q < df + 1 ? 1 - gammaP(df / 2, q / 2) : gammaQcf(df / 2, q / 2);
}

// ---- order statistics -----------------------------------------------------

/** Quantile by R's default (type 7). */
export function quantile(sorted, p) {
  const n = sorted.length;
  if (!n) return NaN;
  if (n === 1) return sorted[0];
  const h = (n - 1) * p;
  const lo = Math.floor(h);
  const hi = Math.min(lo + 1, n - 1);
  return sorted[lo] + (h - lo) * (sorted[hi] - sorted[lo]);
}

const median = sorted => quantile(sorted, 0.5);

function moments(xs) {
  const n = xs.length;
  const mean = xs.reduce((a, b) => a + b, 0) / n;
  const sd = n > 1
    ? Math.sqrt(xs.reduce((a, b) => a + (b - mean) ** 2, 0) / (n - 1))
    : NaN;
  return { mean, sd };
}

// ---- tests ----------------------------------------------------------------

/**
 * Kruskal-Wallis across groups, with the standard correction for ties.
 * Returns null when fewer than two groups have data.
 */
export function kruskalWallis(groups) {
  const present = groups.filter(g => g.values.length);
  if (present.length < 2) return null;
  const all = present.flatMap(g => g.values);
  const N = all.length;
  if (N < 3) return null;

  // Mid-ranks, so tied values share the average of the ranks they span.
  const order = all.map((v, i) => [v, i]).sort((a, b) => a[0] - b[0]);
  const rank = new Array(N);
  const tieGroups = [];
  for (let i = 0; i < N;) {
    let j = i;
    while (j + 1 < N && order[j + 1][0] === order[i][0]) j++;
    const mid = (i + j) / 2 + 1;
    for (let k = i; k <= j; k++) rank[order[k][1]] = mid;
    if (j > i) tieGroups.push(j - i + 1);
    i = j + 1;
  }

  let at = 0, H = 0;
  for (const g of present) {
    const rs = rank.slice(at, at + g.values.length).reduce((a, b) => a + b, 0);
    H += rs * rs / g.values.length;
    at += g.values.length;
  }
  H = 12 / (N * (N + 1)) * H - 3 * (N + 1);
  const tieCorrection = 1 - tieGroups.reduce((a, t) => a + t ** 3 - t, 0) / (N ** 3 - N);
  if (tieCorrection > 0) H /= tieCorrection;
  const df = present.length - 1;
  return { test: 'Kruskal–Wallis', statistic: H, df, p: pchisqUpper(H, df) };
}

/**
 * Pearson chi-square on a levels x groups table. `smallExpected` reports the
 * share of cells below 5, which is when the approximation stops holding.
 */
export function chiSquare(table) {
  const rows = table.length, colsN = table[0]?.length || 0;
  if (rows < 2 || colsN < 2) return null;
  const rowSum = table.map(r => r.reduce((a, b) => a + b, 0));
  const colSum = Array.from({ length: colsN }, (_, j) =>
    table.reduce((a, r) => a + r[j], 0));
  const N = rowSum.reduce((a, b) => a + b, 0);
  if (!N) return null;

  let x2 = 0, small = 0, cells = 0;
  for (let i = 0; i < rows; i++)
    for (let j = 0; j < colsN; j++) {
      const e = rowSum[i] * colSum[j] / N;
      cells++;
      if (e < 5) small++;
      if (e > 0) x2 += (table[i][j] - e) ** 2 / e;
    }
  const df = (rows - 1) * (colsN - 1);
  return {
    test: 'Pearson χ²', statistic: x2, df, p: pchisqUpper(x2, df),
    smallExpected: small / cells,
  };
}

// ---- table ----------------------------------------------------------------

const missing = v => v == null || String(v).trim() === '';
const isNum = v => !missing(v) && Number.isFinite(Number(v));

/**
 * A column that identifies a patient is not a variable. Summarising one yields
 * a level per row ("P001, 1 (0.9%)"), which is noise, so identifiers are left
 * out: anything carrying an id role, and any categorical column whose values
 * are nearly all distinct.
 */
export function isIdentifier(col, rows) {
  if (['id', 'study', 'identifier', 'subject-id', 'participant-id'].includes(col.role)) return true;
  const namedId = /^(?:id|identifier|label|(?:patient|participant|subject|record|study|case)(?:[\s_-]*(?:id|identifier|number|code|label|no))?)$/i;
  if ([col.id, col.name, col.label].some(name => name && namedId.test(String(name).trim()))) return true;
  if (['number', 'integer', 'boolean', 'category', 'date'].includes(col.type)) return false;
  const vals = rows.map(r => String(r[col.id] ?? '').trim()).filter(Boolean);
  if (vals.length < 8) return false;
  const distinct = new Set(vals).size;
  // A characteristic has few levels. Many levels, each covering a small share
  // of the cohort, describes which record a patient came from — a source of
  // provenance, not a variable to compare across groups.
  return distinct > 12 && distinct >= vals.length * 0.9;
}

/** Default clinical descriptives omit identifiers and unsummarised date fields. */
export const baselineColumns = (rows, columns, groupCol = null) => columns.filter(col => col.id !== groupCol && col.type !== 'date' && !isIdentifier(col, rows));
const booleanLevel = value => {
  if (missing(value)) return null;
  const text = String(value).trim().toLowerCase();
  return ['yes', 'true', '1'].includes(text) ? 'Yes' : ['no', 'false', '0'].includes(text) ? 'No' : null;
};
const isBooleanColumn = (col, values) => ['boolean', 'binary'].includes(col.type) || col.originalType === 'boolean'
  || col.role === 'event' && values.length > 0 && values.every(value => booleanLevel(value) != null);
export function descriptiveKind(col, rows) {
  const values = rows.map(row => row[col.id]).filter(value => !missing(value));
  if (isBooleanColumn(col, values) || ['category', 'text', 'date'].includes(col.type) || col.levels?.length) return 'categorical';
  return ['number', 'integer'].includes(col.type) || values.length > 0 && values.every(isNum) ? 'numeric' : 'categorical';
}
export function descriptiveConverter(col, rows = []) {
  const values = rows.map(row => row[col.id]).filter(value => !missing(value));
  if (isBooleanColumn(col, values)) return booleanLevel;
  return descriptiveKind(col, rows) === 'numeric' ? value => isNum(value) ? Number(value) : null : value => missing(value) ? null : String(value).trim();
}

/**
 * One summary row per column, split by `groupCol` (omit for a single column).
 * Types follow the codebook; values are inferred only for columns without a
 * declared type. Binary events are counts. Missing numeric cells are never zero.
 *
 * Groups keep the order they first appear in the data, not alphabetical order:
 * a comparison is reported in the order the review states it.
 */
export function describe(rows, columns, groupCol) {
  const groupNames = groupCol
    ? [...new Set(rows.map(r => String(r[groupCol] ?? '').trim() || '—'))]
    : [];
  const slices = [
    { name: 'Overall', rows },
    ...groupNames.map(g => ({
      name: g,
      rows: rows.filter(r => (String(r[groupCol] ?? '').trim() || '—') === g),
    })),
  ];

  const out = [], notes = ['Percentages use nonmissing observations for each variable; missing or invalid values are excluded per variable.'];
  const omitted = columns.filter(col => col.id !== groupCol && (col.type === 'date' || isIdentifier(col, rows)));
  if (omitted.length) notes.push(`Identifier or date fields omitted: ${omitted.map(col => col.name || col.label || col.id).join(', ')}.`);
  for (const col of baselineColumns(rows, columns, groupCol)) {
    const present = rows.map(r => r[col.id]).filter(v => !missing(v));
    if (!present.length) continue;
    const numeric = descriptiveKind(col, rows) === 'numeric';

    if (numeric) {
      const per = slices.map(s => {
        const xs = s.rows.map(r => r[col.id]).filter(isNum).map(Number).sort((a, b) => a - b);
        if (!xs.length) return { name: s.name, n: 0, missing: s.rows.length };
        const { mean, sd } = moments(xs);
        return {
          name: s.name, n: xs.length, missing: s.rows.length - xs.length,
          median: median(xs), q1: quantile(xs, 0.25), q3: quantile(xs, 0.75),
          min: xs[0], max: xs[xs.length - 1], mean, sd,
        };
      });
      const invalid = present.filter(v => !isNum(v)).length;
      if (invalid) notes.push(`${col.name || col.label || col.id}: ${invalid} nonnumeric ${invalid === 1 ? 'value was' : 'values were'} excluded.`);
      out.push({
        column: col, kind: 'numeric', slices: per,
        test: groupCol ? kruskalWallis(per.slice(1).map((p, i) => ({
          values: slices[i + 1].rows.map(r => r[col.id]).filter(isNum).map(Number),
        }))) : null,
      });
    } else {
      const binary = isBooleanColumn(col, present), level = binary ? booleanLevel : value => missing(value) ? null : String(value).trim();
      const observed = [...new Set(rows.map(r => level(r[col.id])).filter(v => v != null))].sort();
      const declared = binary ? ['No', 'Yes'] : (col.levels || []).map(String);
      const levels = [...declared.filter(l => observed.includes(l)), ...observed.filter(l => !declared.includes(l))];
      const invalid = binary ? present.filter(v => booleanLevel(v) == null).length : 0;
      if (invalid) notes.push(`${col.name || col.label || col.id}: ${invalid} invalid yes/no ${invalid === 1 ? 'value was' : 'values were'} excluded.`);
      const per = slices.map(s => {
        const known = s.rows.map(r => level(r[col.id])).filter(v => v != null);
        return {
          name: s.name, n: known.length, missing: s.rows.length - known.length,
          counts: Object.fromEntries(levels.map(l =>
            [l, known.filter(value => value === l).length])),
        };
      });
      const table = levels.map(l => per.slice(1).map(p => p.counts[l] || 0));
      let test = groupCol && levels.length > 1 ? chiSquare(table) : null;
      if (test?.smallExpected > 0) {
        if (table.length === 2 && table[0].length === 2) {
          const exact = fisherExact(table);
          if (Number.isFinite(exact.p)) test = { ...exact, test: 'Fisher exact' };
        }
        if (test.test !== 'Fisher exact') notes.push(`${col.name || col.label || col.id}: Pearson χ² is approximate; ${(test.smallExpected * 100).toFixed(0)}% of expected cell counts are below 5.`);
      }
      out.push({
        column: col, kind: 'categorical', levels, slices: per,
        test,
      });
    }
  }
  if (groupCol && rows.some(r => missing(r[groupCol]))) notes.push('Rows missing the grouping variable are retained in the “—” group.');
  return { groups: ['Overall', ...groupNames], counts: Object.fromEntries(slices.map(s => [s.name, s.rows.length])), rows: out, notes };
}

// ---- formatting -----------------------------------------------------------

export const num = (v, d = 1) =>
  Number.isFinite(v) ? v.toFixed(d).replace(/\.0+$/, '') : '—';

export const pValue = p =>
  !Number.isFinite(p) ? '—' : p < 0.001 ? '<0.001' : p.toFixed(3);

/** "24 (12–48)" — median with the interquartile range, the usual clinical form. */
export const medianIQR = s =>
  s.n ? `${num(s.median)} (${num(s.q1)}–${num(s.q3)})` : '—';

export const rangeOf = s => (s.n ? `${num(s.min)}–${num(s.max)}` : '—');

export const countPct = (s, level) => {
  const c = s.counts?.[level] ?? 0;
  return s.n ? `${c} (${(100 * c / s.n).toFixed(1)}%)` : '—';
};

// Distribution functions in plain JavaScript (Numerical Recipes style series and
// continued fractions), used by the benches as an oracle independent of R.
const lgamma = x => {
  const c = [76.18009172947146, -86.50532032941677, 24.01409824083091, -1.231739572450155, 0.1208650973866179e-2, -0.5395239384953e-5];
  let y = x, tmp = x + 5.5; tmp -= (x + 0.5) * Math.log(tmp);
  let ser = 1.000000000190015; for (const cj of c) ser += cj / ++y;
  return -tmp + Math.log(2.5066282746310005 * ser / x);
};
/** Regularised lower incomplete gamma P(a, x). */
export function pgammaP(a, x) {
  if (x <= 0) return 0;
  if (x < a + 1) { let ap = a, sum = 1 / a, del = sum; for (let n = 0; n < 1000; n++) { ap++; del *= x / ap; sum += del; if (Math.abs(del) < Math.abs(sum) * 1e-16) break; } return sum * Math.exp(-x + a * Math.log(x) - lgamma(a)); }
  let b = x + 1 - a, c = 1 / 1e-300, d = 1 / b, h = d;
  for (let i = 1; i < 1000; i++) { const an = -i * (i - a); b += 2; d = an * d + b; if (Math.abs(d) < 1e-300) d = 1e-300; c = b + an / c; if (Math.abs(c) < 1e-300) c = 1e-300; d = 1 / d; const del = d * c; h *= del; if (Math.abs(del - 1) < 1e-16) break; }
  return 1 - Math.exp(-x + a * Math.log(x) - lgamma(a)) * h;
}
export const pchisq = (x, df) => pgammaP(df / 2, x / 2);
function bisect(f, lo, hi) { for (let i = 0; i < 300; i++) { const m = (lo + hi) / 2; if (f(m) < 0) lo = m; else hi = m; } return (lo + hi) / 2; }
export const qchisq = (p, df) => { let hi = Math.max(10, df * 4); while (pchisq(hi, df) < p) hi *= 2; return bisect(x => pchisq(x, df) - p, 0, hi); };
function betacf(a, b, x) {
  let qab = a + b, qap = a + 1, qam = a - 1, c = 1, d = 1 - qab * x / qap; if (Math.abs(d) < 1e-300) d = 1e-300; d = 1 / d; let h = d;
  for (let m = 1; m <= 1000; m++) { const m2 = 2 * m; let aa = m * (b - m) * x / ((qam + m2) * (a + m2)); d = 1 + aa * d; if (Math.abs(d) < 1e-300) d = 1e-300; c = 1 + aa / c; if (Math.abs(c) < 1e-300) c = 1e-300; d = 1 / d; h *= d * c;
    aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2)); d = 1 + aa * d; if (Math.abs(d) < 1e-300) d = 1e-300; c = 1 + aa / c; if (Math.abs(c) < 1e-300) c = 1e-300; d = 1 / d; const del = d * c; h *= del; if (Math.abs(del - 1) < 1e-16) break; }
  return h;
}
/** Regularised incomplete beta I_x(a, b). */
export function pbeta(x, a, b) {
  if (x <= 0) return 0; if (x >= 1) return 1;
  const bt = Math.exp(lgamma(a + b) - lgamma(a) - lgamma(b) + a * Math.log(x) + b * Math.log(1 - x));
  return x < (a + 1) / (a + b + 2) ? bt * betacf(a, b, x) / a : 1 - bt * betacf(b, a, 1 - x) / b;
}
export const pt = (t, df) => { const x = df / (df + t * t), p = 0.5 * pbeta(x, df / 2, 0.5); return t > 0 ? 1 - p : p; };
export const qt = (p, df) => { if (p === 0.5) return 0; const s = p > 0.5 ? 1 : -1, q = p > 0.5 ? p : 1 - p; let hi = 10; while (pt(hi, df) < q) hi *= 2; return s * bisect(t => pt(t, df) - q, 0, hi); };
export const pnorm = z => 0.5 * (1 + (z >= 0 ? 1 : -1) * pgammaP(0.5, z * z / 2));
export const qnorm = p => { if (p === 0.5) return 0; const s = p > 0.5 ? 1 : -1, q = p > 0.5 ? p : 1 - p; return s * bisect(z => pnorm(z) - q, 0, 40); };

// Diagnostic test accuracy (plan §1.1, I8): an index test against a reference
// standard, one selected 2×2 table per study for each synthesis. Other tests
// and thresholds remain stored; overlapping tables never count as new studies.
//
// Per study, sensitivity TP/(TP+FN) and specificity TN/(TN+FP) with a Wilson
// score or an exact (Clopper–Pearson) interval, computed here. Pooled, two
// models run through metafor (lib/r.mjs): a univariate random-effects model on
// each logit proportion (escalc "PLO", 0.5 added only to a study with a zero
// cell), and the bivariate random-effects model of Reitsma et al. (2005) as
// rma.mv on the stacked logits with an unstructured study-level random effect.
// The summary operating point, its confidence region, the SROC curve and the
// likelihood ratios and diagnostic odds ratio follow from the bivariate
// estimates here, by the formulas below; bench/dta checks both stages.
import { studies } from './screen.mjs';
import { figureTokens } from './figure-style.mjs';
import { svgRoot, text as svgText, lines, labelColumn, rowHeight, axisLine, hairLine, tick, measure, r1, esc, GAP, footBlock, emptyFigure, bottomAxis, legendRow, fullTitle, sourceOf } from './figure-kit.mjs';
import { setManualStateValue } from './fields.mjs';

export const COUNTS = ['tp', 'fp', 'fn', 'tn'];
export const Z95 = 1.959963984540054;               // qnorm(0.975)
// sqrt(qchisq(0.95, 2)): a chi-square on 2 df has quantile −2·ln(α).
export const C95 = Math.sqrt(-2 * Math.log(0.05));
export const MIN_BIVARIATE = 4;                      // three variance parameters need room
export const CI_METHODS = [['wilson', 'Wilson score'], ['exact', 'Exact (Clopper–Pearson)']];
export const ESTIMATORS = [['REML', 'REML'], ['DL', 'DerSimonian–Laird']];

export const ilogit = x => 1 / (1 + Math.exp(-x));

// ---- inputs -----------------------------------------------------------------

const count = (s, paperId, id) => {
  const v = s.values?.[`${paperId}:${id}`];
  // not reported, or blank: missing, never a zero count (plan F3)
  if (!v || v.availability === 'not_found') return null;
  const raw = v.normalized_value ?? v.reported_value;
  if (raw == null || String(raw).trim() === '') return null;
  const n = Number(raw);
  return Number.isFinite(n) ? n : NaN;
};
const text = (s, paperId, id) => String(s.values?.[`${paperId}:${id}`]?.normalized_value ?? s.values?.[`${paperId}:${id}`]?.reported_value ?? '').trim();
const META = { index: 'dta_index', reference: 'dta_reference', threshold: 'dta_threshold', population: 'dta_population', source: 'dta_source' };
export const PRIMARY_TABLE = 'primary';
export const tableSignature = r => JSON.stringify([r.index, r.reference, r.threshold]);
const rawCount = v => v == null || String(v).trim() === '' ? null : Number(v);

/** Stored alternatives and the original extraction table, whose value keys stay unchanged. */
export function dtaTables(s, paper) {
  const base = { id: paper.id, tableId: PRIMARY_TABLE, paperId: paper.id, paper, label: paper.label || paper.title || paper.id,
    ...Object.fromEntries(Object.entries(META).map(([k, f]) => [k, text(s, paper.id, f)])),
    ...Object.fromEntries(COUNTS.map(k => [k, count(s, paper.id, k)])) };
  const extras = (s.dtaTables?.[paper.id] || []).map(r => ({ ...r, id: `${paper.id}@${r.id}`, tableId: r.id,
    paperId: paper.id, paper, label: base.label,
    ...Object.fromEntries(Object.keys(META).map(k => [k, String(r[k] ?? '').trim()])),
    ...Object.fromEntries(COUNTS.map(k => [k, rawCount(r[k])])) }));
  const selected = s.dtaSelection?.[paper.id] || PRIMARY_TABLE;
  return [base, ...extras].map(r => ({ ...r, selected: r.tableId === selected, problems: tableProblems(r),
    status: COUNTS.some(k => r[k] === null) ? 'incomplete' : validTable(r) ? 'ready' : 'invalid' }));
}

/** Pure reducers: table edits are manual accepted inputs with a source and a change record. */
export function addDtaTable(s, paperId) {
  if (!(s.papers || []).some(p => p.id === paperId)) throw new Error('Unknown study');
  s.dtaTables ||= {}; const rows = s.dtaTables[paperId] ||= [];
  let n = 1; while (rows.some(r => r.id === `table${n}`) || (s.dtaTableTrash || []).some(r => r.paperId === paperId && r.table.id === `table${n}`)) n++;
  const id = `table${n}`; rows.push({ id, at: new Date().toISOString(), origin: 'manual' });
  return id;
}
export function setDtaSelection(s, paperId, tableId) {
  const p = (s.papers || []).find(p => p.id === paperId);
  if (!p || tableId !== 'none' && !dtaTables(s, p).some(r => r.tableId === tableId)) throw new Error('Unknown diagnostic table');
  s.dtaSelection ||= {}; s.dtaSelection[paperId] = tableId; return s;
}
export function removeDtaTable(s, paperId, tableId) {
  if (tableId === PRIMARY_TABLE) throw new Error('The extraction table cannot be removed here');
  const row = (s.dtaTables?.[paperId] || []).find(r => r.id === tableId); if (!row) return s;
  const wasSelected = s.dtaSelection?.[paperId] === tableId;
  s.dtaTableTrash = [...(s.dtaTableTrash || []), { id: `removed-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`, paperId, table: structuredClone(row), wasSelected, at: new Date().toISOString() }].slice(-100);
  s.dtaTables ||= {}; s.dtaTables[paperId] = (s.dtaTables[paperId] || []).filter(r => r.id !== tableId);
  if (wasSelected) delete s.dtaSelection[paperId];
  return s;
}
export function restoreDtaTable(s, removedId) {
  const entry = (s.dtaTableTrash || []).find(r => r.id === removedId);
  if (!entry || !(s.papers || []).some(p => p.id === entry.paperId)) throw new Error('The removed table or its study is unavailable');
  const rows = (s.dtaTables ||= {})[entry.paperId] ||= [];
  if (rows.some(r => r.id === entry.table.id)) throw new Error('A table with this ID already exists');
  rows.push(structuredClone(entry.table));
  if (entry.wasSelected && (!s.dtaSelection?.[entry.paperId] || s.dtaSelection[entry.paperId] === PRIMARY_TABLE)) setDtaSelection(s, entry.paperId, entry.table.id);
  s.dtaTableTrash = s.dtaTableTrash.filter(r => r.id !== removedId); return s;
}
export function setDtaTableValue(s, paperId, tableId, field, value) {
  if (![...COUNTS, ...Object.keys(META)].includes(field)) throw new Error('Unknown diagnostic field');
  const raw = String(value ?? '').trim(), at = new Date().toISOString();
  const key = `${paperId}:${tableId === PRIMARY_TABLE ? META[field] || field : `dta@${tableId}:${field}`}`;
  let previous;
  if (tableId === PRIMARY_TABLE) {
    if (!(s.papers || []).some(p => p.id === paperId)) throw new Error('Unknown study');
    const old = s.values?.[key];
    if (old?.locked) return false;
    previous = old?.reported_value ?? null;
    setManualStateValue(s, paperId, META[field] || field, raw, { type: COUNTS.includes(field) ? 'integer' : 'text', roundInteger: false });
  } else {
    const row = (s.dtaTables?.[paperId] || []).find(r => r.id === tableId);
    if (!row) throw new Error('Unknown diagnostic table');
    previous = row[field] ?? null; row[field] = raw; row.at = at; row.origin = 'manual';
  }
  s.extractionLog = [...(s.extractionLog || []), { key, action: 'manual-diagnostic-table', from: previous, value: raw, at }].slice(-2000);
  return true;
}

/** A 2×2 table is usable when every cell is a whole count and both reference groups have patients. */
export function tableProblems(r) {
  const problems = COUNTS.flatMap(k => r[k] == null ? [`${k.toUpperCase()} is missing`]
    : !Number.isInteger(r[k]) || r[k] < 0 ? [`${k.toUpperCase()} must be a nonnegative whole count`] : []);
  if (!problems.length) {
    if (r.tp + r.fn === 0) problems.push('No reference-positive participants (TP + FN = 0)');
    if (r.fp + r.tn === 0) problems.push('No reference-negative participants (FP + TN = 0)');
  }
  return problems;
}
export const validTable = r => !tableProblems(r).length;

/**
 * The included studies' 2×2 tables: ready, missing a cell, or not a valid
 * table. The snapshot is what a saved result is compared against.
 */
export function dtaInputs(s) {
  const ready = [], incomplete = [], invalid = [], tables = [], excluded = [];
  for (const p of studies(s)) {
    const all = dtaTables(s, p); tables.push(...all);
    const r = all.find(r => r.selected);
    if (!r) { excluded.push(p); continue; }
    ({ ready, incomplete, invalid })[r.status].push(r);
  }
  const snapshot = JSON.stringify({
    version: 2,
    rows: ready.map(r => [r.id, r.label, ...COUNTS.map(k => r[k]), ...Object.keys(META).map(k => r[k])]).sort((a, b) => a[0].localeCompare(b[0])),
    pending: [...incomplete, ...invalid].map(r => [r.id, r.status, ...COUNTS.map(k => r[k]), ...Object.keys(META).map(k => r[k])]).sort((a, b) => a[0].localeCompare(b[0])),
    excluded: excluded.map(p => p.id).sort(),
  });
  return { ready, incomplete, invalid, tables, excluded, snapshot };
}

/** 'current', 'stale' when the inputs changed after the saved run, or null when nothing was run. */
export function dtaStatus(s, result = s.dta) {
  if (!result) return null;
  return result.snapshot === dtaInputs(s).snapshot ? 'current' : 'stale';
}

// ---- per-study intervals ----------------------------------------------------

/** Wilson score interval for x of n. */
export function wilson(x, n, z = Z95) {
  if (!(n > 0)) return [NaN, NaN];
  const p = x / n, z2 = z * z, d = 1 + z2 / n;
  const centre = (p + z2 / (2 * n)) / d;
  const half = (z / d) * Math.sqrt(p * (1 - p) / n + z2 / (4 * n * n));
  return [Math.max(0, centre - half), Math.min(1, centre + half)];
}

// Lanczos approximation (g = 7, nine terms) to log Γ.
const LANCZOS = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
  -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
export function lgamma(x) {
  if (x < 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * x))) - lgamma(1 - x);
  x -= 1;
  let a = LANCZOS[0]; const t = x + 7.5;
  for (let i = 1; i < 9; i++) a += LANCZOS[i] / (x + i);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}
// Continued fraction for the incomplete beta (modified Lentz).
function betacf(a, b, x) {
  const TINY = 1e-300;
  const qab = a + b, qap = a + 1, qam = a - 1;
  let c = 1, d = 1 - qab * x / qap;
  if (Math.abs(d) < TINY) d = TINY;
  d = 1 / d; let h = d;
  for (let m = 1; m <= 500; m++) {
    const m2 = 2 * m;
    let aa = m * (b - m) * x / ((qam + m2) * (a + m2));
    d = 1 + aa * d; if (Math.abs(d) < TINY) d = TINY;
    c = 1 + aa / c; if (Math.abs(c) < TINY) c = TINY;
    d = 1 / d; h *= d * c;
    aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2));
    d = 1 + aa * d; if (Math.abs(d) < TINY) d = TINY;
    c = 1 + aa / c; if (Math.abs(c) < TINY) c = TINY;
    d = 1 / d; const del = d * c; h *= del;
    if (Math.abs(del - 1) < 1e-16) break;
  }
  return h;
}
/** Regularised incomplete beta I_x(a, b). */
export function ibeta(x, a, b) {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  const front = Math.exp(lgamma(a + b) - lgamma(a) - lgamma(b) + a * Math.log(x) + b * Math.log(1 - x));
  return x < (a + 1) / (a + b + 2) ? front * betacf(a, b, x) / a : 1 - front * betacf(b, a, 1 - x) / b;
}
/** Beta quantile by bisection: I_x is monotone in x, so this cannot miss. */
export function qbeta(p, a, b) {
  let lo = 0, hi = 1;
  for (let i = 0; i < 200 && hi - lo > 1e-15; i++) {
    const mid = (lo + hi) / 2;
    if (ibeta(mid, a, b) < p) lo = mid; else hi = mid;
  }
  return (lo + hi) / 2;
}
/** Exact (Clopper–Pearson) interval for x of n. */
export function clopperPearson(x, n, level = 0.95) {
  if (!(n > 0)) return [NaN, NaN];
  const a = (1 - level) / 2;
  return [x === 0 ? 0 : qbeta(a, x, n - x + 1), x === n ? 1 : qbeta(1 - a, x + 1, n - x)];
}

/** Sensitivity and specificity of one study, with the chosen interval. */
export function studyAccuracy(r, method = 'wilson') {
  const ci = method === 'exact' ? clopperPearson : wilson;
  const np = r.tp + r.fn, nn = r.fp + r.tn;
  const [sensLo, sensHi] = ci(r.tp, np), [specLo, specHi] = ci(r.tn, nn);
  return { sens: r.tp / np, sensLo, sensHi, spec: r.tn / nn, specLo, specHi, n: np + nn };
}

// ---- pooled: R, and what follows from its estimates ---------------------------

const rvec = xs => `c(${xs.map(x => String(Number(x))).join(',')})`;

/**
 * R code for both models. Ends in a flat list(...) (lib/r.mjs flattens one
 * level). The bivariate fit is attempted only with enough studies, and a fit
 * that fails to converge is reported as such rather than as a number.
 */
export function rCode(rows, { method = 'REML' } = {}) {
  const ids = rows.map(r => r.paperId || r.paper?.id || r.id).filter(Boolean);
  if (new Set(ids).size !== ids.length) throw new Error('Select one test / threshold per study; dependent tables cannot be pooled as independent studies');
  if (rows.some(r => !validTable(r))) throw new Error('Invalid diagnostic 2×2 table');
  const m = method === 'DL' ? 'DL' : 'REML';
  const col = k => rvec(rows.map(r => r[k]));
  return `
    tp <- ${col('tp')}; fp <- ${col('fp')}; fn <- ${col('fn')}; tn <- ${col('tn')}
    k <- length(tp)
    s1 <- escalc(measure="PLO", xi=tp, ni=tp+fn, add=1/2, to="only0")
    s2 <- escalc(measure="PLO", xi=tn, ni=tn+fp, add=1/2, to="only0")
    u1 <- rma(yi, vi, data=s1, method="${m}")
    u2 <- rma(yi, vi, data=s2, method="${m}")
    b <- NULL; berr <- ""
    if (k >= ${MIN_BIVARIATE}) {
      d <- data.frame(study=rep(seq_len(k), 2), what=factor(rep(c("sens","spec"), each=k), levels=c("sens","spec")),
                      yi=c(as.numeric(s1$yi), as.numeric(s2$yi)), vi=c(as.numeric(s1$vi), as.numeric(s2$vi)))
      b <- tryCatch(rma.mv(yi, vi, mods=~ what - 1, random=~ what | study, struct="UN", data=d, method="REML"),
                    error=function(e) { berr <<- conditionMessage(e); NULL })
    }
    ok <- !is.null(b)
    V <- if (ok) vcov(b) else matrix(NA_real_, 2, 2)
    list(k=k,
      yi_sens=as.numeric(s1$yi), vi_sens=as.numeric(s1$vi), yi_spec=as.numeric(s2$yi), vi_spec=as.numeric(s2$vi),
      u_sens_b=as.numeric(coef(u1)), u_sens_se=u1$se, u_sens_tau2=u1$tau2, u_sens_i2=u1$I2, u_sens_q=u1$QE, u_sens_qp=u1$QEp,
      u_spec_b=as.numeric(coef(u2)), u_spec_se=u2$se, u_spec_tau2=u2$tau2, u_spec_i2=u2$I2, u_spec_q=u2$QE, u_spec_qp=u2$QEp,
      b_ok=ok, b_err=berr,
      b_sens=if (ok) as.numeric(coef(b)[1]) else NA_real_, b_spec=if (ok) as.numeric(coef(b)[2]) else NA_real_,
      v11=V[1,1], v12=V[1,2], v22=V[2,2],
      tau2_sens=if (ok) b$tau2[1] else NA_real_, tau2_spec=if (ok) b$tau2[2] else NA_real_,
      rho=if (ok) b$rho else NA_real_, ll=if (ok) as.numeric(logLik(b)) else NA_real_)`;
}

const num = v => (v == null || Number.isNaN(Number(v)) ? null : Number(v));
const arr = v => (Array.isArray(v) ? v : Array.isArray(v?.values) ? v.values : v == null ? [] : [v]).map(Number);

/** The saved result, from R's list and the rows it was run on. */
export function fromR(out, rows, { method = 'REML', snapshot = '' } = {}) {
  const uni = key => ({ b: num(out[`u_${key}_b`]), se: num(out[`u_${key}_se`]), tau2: num(out[`u_${key}_tau2`]),
    i2: num(out[`u_${key}_i2`]), q: num(out[`u_${key}_q`]), qp: num(out[`u_${key}_qp`]) });
  const ok = out.b_ok === true || out.b_ok === 1 || out.b_ok === 'TRUE';
  return {
    at: new Date().toISOString(), method, k: rows.length, snapshot,
    ids: rows.map(r => r.id), labels: rows.map(r => r.label),
    papers: rows.map(r => r.paperId || r.paper?.id || r.id),
    tables: rows.map(r => ({ id: r.id, paperId: r.paperId || r.paper?.id || r.id, tableId: r.tableId || PRIMARY_TABLE,
      ...Object.fromEntries(Object.keys(META).map(k => [k, r[k] || ''])), ...Object.fromEntries(COUNTS.map(k => [k, r[k]])) })),
    yiSens: arr(out.yi_sens), viSens: arr(out.vi_sens), yiSpec: arr(out.yi_spec), viSpec: arr(out.vi_spec),
    uni: { sens: uni('sens'), spec: uni('spec') },
    biv: ok ? { sens: num(out.b_sens), spec: num(out.b_spec), v11: num(out.v11), v12: num(out.v12), v22: num(out.v22),
      tau2Sens: num(out.tau2_sens), tau2Spec: num(out.tau2_spec), rho: num(out.rho), ll: num(out.ll) } : null,
    bivError: ok ? '' : rows.length < MIN_BIVARIATE ? `needs ${MIN_BIVARIATE} studies` : String(out.b_err || 'did not converge'),
  };
}

/** A logit estimate and its SE as a proportion with its 95% interval. */
export const onProportion = (b, se) => ({ est: ilogit(b), lo: ilogit(b - Z95 * se), hi: ilogit(b + Z95 * se) });

/**
 * Summary sensitivity and specificity, the likelihood ratios and the
 * diagnostic odds ratio from the bivariate estimates (b = logit sens, logit
 * spec; V their covariance). DOR = exp(b1 + b2) is linear on the log scale;
 * the likelihood ratios' intervals are by the delta method on the log scale.
 */
export function summary(biv) {
  if (!biv) return null;
  const { sens: b1, spec: b2, v11, v12, v22 } = biv;
  const se = ilogit(b1), sp = ilogit(b2);
  const onLog = (est, g1, g2) => {
    const sd = Math.sqrt(g1 * g1 * v11 + 2 * g1 * g2 * v12 + g2 * g2 * v22);
    return { est, lo: est * Math.exp(-Z95 * sd), hi: est * Math.exp(Z95 * sd) };
  };
  return {
    sens: onProportion(b1, Math.sqrt(v11)), spec: onProportion(b2, Math.sqrt(v22)),
    lrPos: onLog(se / (1 - sp), 1 - se, sp),
    lrNeg: onLog((1 - se) / sp, -se, -(1 - sp)),
    dor: onLog(Math.exp(b1 + b2), 1, 1),
    rho: biv.rho, tau2Sens: biv.tau2Sens, tau2Spec: biv.tau2Spec,
  };
}

/**
 * The 95% confidence region of the summary point, in ROC space (x = 1 −
 * specificity, y = sensitivity): an ellipse in logit space, radius
 * sqrt(χ²₂(0.95)) in the metric of the estimates' covariance, mapped back.
 */
export function confidenceRegion(biv, steps = 96) {
  if (!biv) return [];
  // x = logit(1 − spec) = −b2, so its covariance with b1 changes sign.
  const sxx = biv.v22, syy = biv.v11, sxy = -biv.v12;
  const l11 = Math.sqrt(sxx), l21 = sxy / l11, l22 = Math.sqrt(Math.max(0, syy - l21 * l21));
  const out = [];
  for (let i = 0; i <= steps; i++) {
    const t = 2 * Math.PI * i / steps, u = Math.cos(t), v = Math.sin(t);
    out.push([ilogit(-biv.spec + C95 * l11 * u), ilogit(biv.sens + C95 * (l21 * u + l22 * v))]);
  }
  return out;
}

/**
 * The SROC curve implied by the bivariate model (Rutter–Gatsonis form, Harbord
 * et al. 2007): logit(sens) = μA + (σA/σB)(logit(1 − spec) + μB), drawn across
 * the studies' own range of 1 − specificity. None when a variance is zero.
 */
export function srocCurve(biv, yiSpec = [], steps = 60) {
  if (!biv || !(biv.tau2Sens > 1e-10) || !(biv.tau2Spec > 1e-10) || !yiSpec.length) return [];
  const slope = Math.sqrt(biv.tau2Sens / biv.tau2Spec);
  const xs = yiSpec.map(y => -y), x0 = Math.min(...xs), x1 = Math.max(...xs);
  const out = [];
  for (let i = 0; i <= steps; i++) {
    const x = x0 + (x1 - x0) * i / steps;
    out.push([ilogit(x), ilogit(biv.sens + slope * (x + biv.spec))]);
  }
  return out;
}

// ---- figures ------------------------------------------------------------------
// The house style (FIGURE-STYLE §2): tokens for every colour and size, study labels that wrap to two lines or become a
// key, baseline axes, the source block under the drawing. `style` is figureTokens (the export set unless given); the
// screen copy is the same drawing in px, coloured by its c-* classes.

const f2 = x => Number(x).toFixed(2);
export const withCi = (e, lo, hi) => `${f2(e)} (${f2(lo)} to ${f2(hi)})`;
const estOf = (e, lo, hi) => ([e, lo, hi].every(Number.isFinite) ? withCi(e, lo, hi) : 'Not estimable');

const readout = (r, a) => `${r.label} · TP ${r.tp}, FP ${r.fp}, FN ${r.fn}, TN ${r.tn} · ` +
  `sensitivity ${estOf(a.sens, a.sensLo, a.sensHi)} · specificity ${estOf(a.spec, a.specLo, a.specHi)}`;

/**
 * Paired forest plot: each study's counts, then sensitivity and specificity with their intervals side by side on
 * 0–1 axes, the estimate written to the left of each. With a summary, a diamond row for the pooled estimate under
 * each, under a hairline. Study names wrap to two lines or become a key.
 */
export function forestSvg(rows, { method = 'wilson', pooled = null, title = 'Paired forest plot', style = null, width = null, source = [] } = {}) {
  const t = style || figureTokens(null, { medium: 'export' });
  if (!rows?.length) return emptyFigure(t, { title, message: 'No study with a complete 2×2 table yet.', width, source });
  const P = t.pad, ls = t.size.label, gap = ls * GAP, w0 = width || t.width.double;
  const est = rows.map(r => ({ r, a: validTable(r) ? studyAccuracy(r, method) : { sens: NaN, sensLo: NaN, sensHi: NaN, spec: NaN, specLo: NaN, specHi: NaN } }));
  const overall = pooled ? { label: pooled.label || 'Summary', a: { sens: pooled.sens.est, sensLo: pooled.sens.lo, sensHi: pooled.sens.hi, spec: pooled.spec.est, specLo: pooled.spec.lo, specHi: pooled.spec.hi } } : null;
  const col = labelColumn(t, [...rows.map(r => r.label), ...(overall ? [overall.label] : [])], w0 * 0.28, { min: measure(t, 'Study') });
  const cntW = Math.max(measure(t, 'TP', 'head'), ...rows.flatMap(r => COUNTS.map(k => measure(t, String(r[k]))))) + ls * 0.8;
  const textW = key => Math.max(measure(t, `${key} (95% CI)`, 'head') * 1.08, ...est.map(({ a }) => measure(t, estOf(a[key === 'Sensitivity' ? 'sens' : 'spec'], a[key === 'Sensitivity' ? 'sensLo' : 'specLo'], a[key === 'Sensitivity' ? 'sensHi' : 'specHi'])))) + ls * 0.4;
  const tS = textW('Sensitivity'), tP = textW('Specificity');
  const fixed = P * 2 + col.w + 4 * cntW + gap + tS + gap + tP + gap * 3;
  const plotW = Math.max(ls * 8, (w0 - fixed) / 2);
  const xC = P + col.w, xTs = xC + 4 * cntW + gap + tS, xPs = xTs + gap, xTp = xPs + plotW + gap * 2 + tP, xPp = xTp + gap, w = xPp + plotW + P + ls * 0.6;
  const X = (x0, v) => x0 + plotW * Math.min(1, Math.max(0, v));
  const hy = P + ls, body = [];
  body.push(svgText(t, P, hy, 'Study', { role: 'head', cls: 'c-ink c-head' }),
    ...['TP', 'FP', 'FN', 'TN'].map((c, i) => svgText(t, xC + (i + 1) * cntW, hy, c, { role: 'head', anchor: 'end', cls: 'c-ink c-head' })),
    svgText(t, xTs, hy, 'Sensitivity (95% CI)', { role: 'head', anchor: 'end', cls: 'c-ink c-head' }),
    svgText(t, xTp, hy, 'Specificity (95% CI)', { role: 'head', anchor: 'end', cls: 'c-ink c-head' }));
  let y = hy + ls * 0.6;
  body.push(hairLine(t, P, y, w - P, y));
  const top = y, side = t.square[0] + t.square[1] * 0.5;
  const interval = (x0, cy, e, lo, hi) => ([e, lo, hi].every(Number.isFinite)
    ? `<line class="c-line" x1="${r1(X(x0, lo))}" y1="${r1(cy)}" x2="${r1(X(x0, hi))}" y2="${r1(cy)}" stroke="${t.color.ink}" stroke-width="${t.line.ci}"/>` +
      `<rect class="c-dot" x="${r1(X(x0, e) - side / 2)}" y="${r1(cy - side / 2)}" width="${r1(side)}" height="${r1(side)}" fill="${t.color.ink}"/>` : '');
  const diamond = (x0, cy, e, lo, hi) => {
    if (![e, lo, hi].every(Number.isFinite)) return '';
    const dh = t.row * t.diamond / 2;
    return `<polygon class="c-dot" points="${r1(X(x0, lo))},${r1(cy)} ${r1(X(x0, e))},${r1(cy - dh)} ${r1(X(x0, hi))},${r1(cy)} ${r1(X(x0, e))},${r1(cy + dh)}" fill="${t.color.ink}"/>`;
  };
  // each study row is one group: its <title> is the row's readout on screen (lib/figure.mjs), its band, unfilled, where it is hovered
  const row = ({ r, a }, k, pool) => {
    const ln = col.lines[k], h = rowHeight(t, ln.length), cy = y + h / 2, ty = cy + ls * 0.35, role = pool ? 'head' : 'label', cls = pool ? 'c-ink c-head' : 'c-ink';
    const say = pool ? `${r.label} · sensitivity ${estOf(a.sens, a.sensLo, a.sensHi)} · specificity ${estOf(a.spec, a.specLo, a.specHi)}` : readout(r, a);
    const g = `<g${r.paper?.id ? ` data-study="${esc(r.paper.id)}"` : ''}><title>${esc(say)}</title><rect class="fig-band" x="${r1(P)}" y="${r1(y)}" width="${r1(w - 2 * P)}" height="${r1(h)}" fill="none"/>` +
      lines(t, P, cy, ln, { role, cls, inner: fullTitle(r.label, ln) }) +
      (pool ? '' : COUNTS.map((c, j) => svgText(t, xC + (j + 1) * cntW, ty, String(r[c]), { anchor: 'end' })).join('')) +
      svgText(t, xTs, ty, estOf(a.sens, a.sensLo, a.sensHi), { anchor: 'end', role, cls }) + (pool ? diamond(xPs, cy, a.sens, a.sensLo, a.sensHi) : interval(xPs, cy, a.sens, a.sensLo, a.sensHi)) +
      svgText(t, xTp, ty, estOf(a.spec, a.specLo, a.specHi), { anchor: 'end', role, cls }) + (pool ? diamond(xPp, cy, a.spec, a.specLo, a.specHi) : interval(xPp, cy, a.spec, a.specLo, a.specHi)) + '</g>';
    y += h;
    return g;
  };
  est.forEach((e, k) => body.push(row(e, k, false)));
  if (overall) { body.push(hairLine(t, P, y, w - P, y)); body.push(row({ r: { label: overall.label }, a: overall.a }, rows.length, true)); }
  const parts = [...body];
  y += ls * 0.4;
  const ticks = [0, 0.2, 0.4, 0.6, 0.8, 1], fmt = v => (v === 0 || v === 1 ? String(v) : v.toFixed(1));
  const ay = bottomAxis(t, parts, v => xPs + plotW * v, ticks, xPs, xPs + plotW, y, fmt);
  bottomAxis(t, parts, v => xPp + plotW * v, ticks, xPp, xPp + plotW, y, fmt);
  const sm = t.size.small, ty = ay + sm * 1.5;
  parts.push(svgText(t, xPs + plotW / 2, ty, 'Sensitivity', { anchor: 'middle', role: 'small', cls: 'c-mute' }), svgText(t, xPp + plotW / 2, ty, 'Specificity', { anchor: 'middle', role: 'small', cls: 'c-mute' }));
  const note = `${rows.length} ${rows.length === 1 ? 'study' : 'studies'} · ${method === 'exact' ? 'Exact (Clopper–Pearson)' : 'Wilson score'} intervals`;
  const h = footBlock(t, parts, ty, w, { source: [note, ...sourceOf(source)], keys: col.keys });
  void top;
  return svgRoot(t, w, h, parts.join(''), { title, desc: note });
}

/**
 * SROC plot in ROC space: the studies (area by size), the bivariate summary point, its 95% confidence region and the
 * SROC curve, on L-shaped axes with ticks. The marks are named in a legend under the plot.
 */
export function srocSvg(rows, result, { title = 'Summary ROC plot', style = null, width = null, source = [] } = {}) {
  const t = style || figureTokens(null, { medium: 'export' });
  const pts = (rows || []).filter(validTable).map(r => ({ r, a: studyAccuracy(r) })).filter(({ a }) => Number.isFinite(a.sens) && Number.isFinite(a.spec));
  if (!pts.length) return emptyFigure(t, { title, message: 'No study with a complete 2×2 table yet.', width, source });
  const P = t.pad, ls = t.size.label, sm = t.size.small, k = t.row / 22, S = Math.round(300 * k);
  const L = Math.max(...[0, 0.2, 0.4, 0.6, 0.8, 1].map(v => measure(t, v === 0 || v === 1 ? String(v) : v.toFixed(1), 'small'))) + sm * 0.9, top = P + sm * 1.9;
  const w = Math.max(P + L + S + P + ls, Math.min(t.width.single, t.width.single * 0.9)), x0 = P + L, y1 = top + S;
  const X = v => x0 + S * v, Y = v => y1 - S * v;
  const parts = [];
  parts.push(svgText(t, P, P + sm, 'Sensitivity', { role: 'small', cls: 'c-mute' }), axisLine(t, x0, top, x0, y1), axisLine(t, x0, y1, x0 + S, y1));
  parts.push(hairLine(t, X(0), Y(0), X(1), Y(1)));
  const label = v => (v === 0 || v === 1 ? String(v) : v.toFixed(1));
  for (const v of [0, 0.2, 0.4, 0.6, 0.8, 1]) {
    parts.push(tick(t, X(v), y1), svgText(t, X(v), y1 + sm * 1.45, label(v), { anchor: v === 1 ? 'end' : 'middle', role: 'small', cls: 'c-ink', color: t.color.ink }),
      tick(t, x0, Y(v), 'left'), svgText(t, x0 - sm * 0.5, Y(v) + sm * 0.35, label(v), { anchor: 'end', role: 'small', cls: 'c-ink', color: t.color.ink }));
  }
  parts.push(svgText(t, X(0.5), y1 + sm * 3, '1 − specificity', { anchor: 'middle', role: 'small', cls: 'c-mute' }));
  const nMax = Math.max(1, ...pts.map(({ r }) => r.tp + r.fp + r.fn + r.tn));
  const dots = pts.map(({ r, a }) => {
    const rad = (3 + 6 * Math.sqrt((r.tp + r.fp + r.fn + r.tn) / nMax)) * k;
    return `<circle class="c-line" cx="${r1(X(1 - a.spec))}" cy="${r1(Y(a.sens))}" r="${r1(rad)}" fill="none" stroke="${t.color.ink}" stroke-width="${t.line.ci}"${r.paper?.id ? ` data-study="${esc(r.paper.id)}"` : ''}><title>${esc(readout(r, a))}</title></circle>`;
  }).join('');
  const path = ps => ps.map(([x, y], i) => `${i ? 'L' : 'M'}${r1(X(x))},${r1(Y(y))}`).join(' ');
  const biv = result?.biv, curve = srocCurve(biv, result?.yiSpec || []), region = confidenceRegion(biv), dash = `${r1(4 * k)} ${r1(3 * k)}`;
  const sq = 8 * k;
  parts.push((curve.length ? `<path class="c-line" d="${path(curve)}" fill="none" stroke="${t.color.ink}" stroke-width="${t.line.ci * 1.6}"/>` : '') +
    (region.length ? `<path class="c-line" d="${path(region)} Z" fill="none" stroke="${t.color.ink}" stroke-width="${t.line.ci}" stroke-dasharray="${dash}"/>` : '') + dots +
    (biv ? `<rect class="c-dot" x="${r1(X(1 - ilogit(biv.spec)) - sq / 2)}" y="${r1(Y(ilogit(biv.sens)) - sq / 2)}" width="${r1(sq)}" height="${r1(sq)}" fill="${t.color.ink}"><title>Summary point</title></rect>` : ''));
  const items = [{ label: 'Study', markW: 10 * k, mark: (x, y) => `<circle class="c-line" cx="${r1(x + 5 * k)}" cy="${r1(y)}" r="${r1(4 * k)}" fill="none" stroke="${t.color.ink}" stroke-width="${t.line.ci}"/>` }];
  if (biv) items.push({ label: 'Summary point', markW: sq, mark: (x, y) => `<rect class="c-dot" x="${r1(x)}" y="${r1(y - sq / 2)}" width="${r1(sq)}" height="${r1(sq)}" fill="${t.color.ink}"/>` });
  if (region.length) items.push({ label: '95% confidence region', markW: 14 * k, mark: (x, y) => `<line class="c-line" x1="${r1(x)}" y1="${r1(y)}" x2="${r1(x + 14 * k)}" y2="${r1(y)}" stroke="${t.color.ink}" stroke-width="${t.line.ci}" stroke-dasharray="${dash}"/>` });
  if (curve.length) items.push({ label: 'SROC curve', markW: 14 * k, mark: (x, y) => `<line class="c-line" x1="${r1(x)}" y1="${r1(y)}" x2="${r1(x + 14 * k)}" y2="${r1(y)}" stroke="${t.color.ink}" stroke-width="${t.line.ci * 1.6}"/>` });
  const ky = legendRow(t, parts, y1 + sm * 3, w, items);
  const note = `${pts.length} ${pts.length === 1 ? 'study' : 'studies'} · marker area follows study size`;
  const h = footBlock(t, parts, ky, w, { source: [note, ...sourceOf(source)] });
  return svgRoot(t, w, h, parts.join(''), { title, desc: note });
}

/** The drawings app/lint-figures.mjs checks: a paired forest with a long study name and a summary, the SROC plot with every mark, a bare one, and the empty forest. */
export const __fixture = style => {
  const rows = [{ label: 'Aldermere 2012', tp: 45, fp: 12, fn: 5, tn: 88 }, { label: 'Ibarra-Montoya, Kowalczyk and Nowak 2019: a multicentre cohort in emergency departments', tp: 30, fp: 3, fn: 10, tn: 40 },
    { label: 'Bo 2020', tp: 18, fp: 0, fn: 2, tn: 61 }, { label: 'Cole 2021', tp: 70, fp: 20, fn: 14, tn: 150 }];
  const biv = { sens: 1.6, spec: 2.1, v11: 0.04, v12: -0.01, v22: 0.09, tau2Sens: 0.5, tau2Spec: 0.8, rho: -0.4 };
  const sm = summary(biv), yiSpec = [1.4, 2.6, 4.1, 1.9];
  return [{ name: 'forestSvg', svg: forestSvg(rows, { style, pooled: { label: 'Summary (bivariate)', sens: sm.sens, spec: sm.spec } }) },
    { name: 'srocSvg', svg: srocSvg(rows, { biv, yiSpec }, { style }) }, { name: 'srocSvg-points', svg: srocSvg(rows.slice(0, 1), null, { style }) },
    { name: 'forestSvg-empty', svg: forestSvg([], { style }) }];
};

/** Rows for a CSV: the 2×2 table and both proportions with their intervals. */
export function csvRows(rows, method = 'wilson') {
  return [['Study', 'Index test', 'Reference standard', 'Threshold', 'TP', 'FP', 'FN', 'TN',
    'Sensitivity', 'Sensitivity lower', 'Sensitivity upper', 'Specificity', 'Specificity lower', 'Specificity upper', 'Population', 'Source', 'Table ID', 'Selected', 'Status'],
  ...rows.map(r => { const a = validTable(r) ? studyAccuracy(r, method) : {};
    return [r.label, r.index, r.reference, r.threshold, r.tp, r.fp, r.fn, r.tn, a.sens, a.sensLo, a.sensHi, a.spec, a.specLo, a.specHi,
      r.population || '', r.source || '', r.tableId || PRIMARY_TABLE, r.selected === false ? 'no' : 'yes', r.status || (validTable(r) ? 'ready' : 'invalid')]; })];
}

/** For the assistant and the manuscript: the saved result in one line. */
export function resultLine(result) {
  const sm = summary(result?.biv);
  if (!sm) return result ? `Accuracy (k = ${result.k}): bivariate model ${result.bivError}` : 'Accuracy: not run';
  return `Bivariate (k = ${result.k}): sensitivity ${withCi(sm.sens.est, sm.sens.lo, sm.sens.hi)}, specificity ${withCi(sm.spec.est, sm.spec.lo, sm.spec.hi)}, ` +
    `LR+ ${withCi(sm.lrPos.est, sm.lrPos.lo, sm.lrPos.hi)}, LR− ${withCi(sm.lrNeg.est, sm.lrNeg.lo, sm.lrNeg.hi)}, DOR ${withCi(sm.dor.est, sm.dor.lo, sm.dor.hi)}, ρ ${f2(sm.rho)}`;
}

// Effect measures a pooled analysis can estimate, and the extracted inputs
// each needs. Binary outcomes pool 2×2 counts; continuous outcomes pool
// arm means, SDs and sizes. metafor's escalc computes the effect sizes: "SMD"
// there is Hedges' g, bias-corrected (Viechtbauer 2010, metafor manual).
export const MEASURES = [
  { id: 'RR',  label: 'Risk ratio',                  family: 'binary',     ratio: true },
  { id: 'OR',  label: 'Odds ratio',                  family: 'binary',     ratio: true },
  { id: 'RD',  label: 'Risk difference',             family: 'binary',     ratio: false },
  { id: 'MD',  label: 'Mean difference',             family: 'continuous', ratio: false },
  { id: 'SMD', label: "Standardised mean difference (Hedges' g)", family: 'continuous', ratio: false },
  // Reported as a ratio with its 95% CI; pooled on the log scale by generic
  // inverse variance: yi = log(HR), SE = (log upper − log lower) / (2 · 1.96).
  { id: 'HR',  label: 'Hazard ratio',                family: 'generic',    ratio: true, escalc: 'GEN' },
  // Estimates from a fitted model, rather than reconstructed arm counts.
  ...[
    ['OR-report', 'Odds ratio', true, 'OR'], ['RR-report', 'Risk ratio', true, 'RR'],
    ['HR-report', 'Hazard ratio', true, 'HR'], ['MD-report', 'Mean difference', false, 'MD'],
    ['SMD-report', 'Standardised mean difference', false, 'SMD'],
    ['BETA', 'Regression coefficient', false, 'coefficient'],
  ].map(([id, label, ratio, short]) => ({ id, label: `${label} · reported estimate`, family: 'reported', ratio, short, escalc: 'GEN' })),
  { id: 'IRR', label: 'Incidence rate ratio',        family: 'rate',       ratio: true },
  // Single-group and association measures: pooled on a transformed scale
  // (logit proportion, Fisher's z) and shown back on the natural one.
  { id: 'PR',  label: 'Proportion (single group)',   family: 'proportion', ratio: false, escalc: 'PLO', back: 'transf.ilogit' },
  // Freeman–Tukey double arcsine: offered with its warning (lib/heterogeneity.mjs FT_WARNING). The back-transformation
  // ipft_hm is defined by the model's R (lib/pooled-model.mjs) with the harmonic mean of the rows' sample sizes.
  { id: 'PFT', label: 'Proportion (single group, Freeman–Tukey)', family: 'proportion', ratio: false, escalc: 'PFT', back: 'ipft_hm', warning: 'freeman-tukey' },
  { id: 'MN',  label: 'Mean (single group)',         family: 'single-mean', ratio: false },
  { id: 'COR', label: 'Correlation (r)',             family: 'correlation', ratio: false, escalc: 'ZCOR', back: 'transf.ztor' },
];

// Extraction field ids per family, in escalc's argument order.
export const INPUTS = {
  binary:     [['events_t', 'ai'], ['n_t', 'n1i'], ['events_c', 'ci'], ['n_c', 'n2i']],
  continuous: [['mean_t', 'm1i'], ['sd_t', 'sd1i'], ['n_t', 'n1i'], ['mean_c', 'm2i'], ['sd_c', 'sd2i'], ['n_c', 'n2i']],
  generic:    [['hr', 'est'], ['hr_lo', 'lo'], ['hr_hi', 'hi']],
  reported:   [['effect_estimate', 'yi'], ['effect_se', 'sei']],
  rate:       [['events_t', 'x1i'], ['time_t', 't1i'], ['events_c', 'x2i'], ['time_c', 't2i']],
  proportion: [['events', 'xi'], ['n', 'ni']],
  'single-mean': [['mean', 'mi'], ['sd', 'sdi'], ['n', 'ni']],
  correlation: [['r', 'ri'], ['n', 'ni']],
};

export const measureOf = id => MEASURES.find(m => m.id === id) || MEASURES[0];
export const inputFields = id => INPUTS[measureOf(id).family].map(([f]) => f);
export const REPORTED_FIELDS = ['effect_estimate', 'effect_se', 'effect_lo', 'effect_hi', 'effect_confidence', 'effect_df',
  'effect_uncertainty', 'effect_population', 'effect_contrast', 'effect_adjustment_type', 'effect_adjustment', 'effect_source'];
/** Extraction retains the original uncertainty and the identity of a reported model. */
export const extractionFields = id => measureOf(id).family === 'reported' ? REPORTED_FIELDS : inputFields(id);
export const effectName = id => measureOf(id).short || measureOf(id).id;
/** Ratios are pooled on the log scale and shown back-transformed; differences are not. */
export const isRatio = id => measureOf(id).ratio;
/** The value meaning "no difference between arms"; a single-group proportion or mean has none. */
export const noEffect = id => (isRatio(id) ? 1 : ['proportion', 'single-mean'].includes(measureOf(id).family) ? null : 0);
/** The R function taking a pooled value back to the scale it is reported on: exp for ratios, and the measure's own otherwise. */
export const backTransform = id => (isRatio(id) ? 'exp' : measureOf(id).back || null);
/** escalc's name for the measure. */
export const escalcName = id => measureOf(id).escalc || measureOf(id).id;

// The evidence features' project state, brought to the current shape when a
// project is opened (called from normalizeProject in store.mjs). Pure.
//   robReview        — risk of bias per outcome, two reviewers (lib/rob-review.mjs)
//   multiArm         — studies with several treated arms (lib/multi-arm.mjs)
//   doubleExtraction — two extractors' entries (lib/double-extraction.mjs)
//   extractionLog    — locks and amendments of accepted values (lib/fields.mjs)
import { allTools } from '../schema.mjs';
import { migrateAssessments } from './rob-review.mjs';

const obj = v => (v && typeof v === 'object' && !Array.isArray(v) ? v : null);

export function normalizeEvidence(next) {
  // the project's own instruments count as instruments: their answers are not RoB 2's flat keys
  migrateAssessments(next, allTools(next).map(t => t.id));
  next.multiArm = obj(next.multiArm) || {};
  for (const [id, m] of Object.entries(next.multiArm)) if (!obj(m) || !Array.isArray(m.arms)) delete next.multiArm[id];
  if (next.doubleExtraction != null) {
    const d = obj(next.doubleExtraction) || {};
    next.doubleExtraction = { ...d, on: Boolean(d.on), entries: obj(d.entries) || {} };
  }
  if (next.extractionLog != null && !Array.isArray(next.extractionLog)) next.extractionLog = [];
  return next;
}

// Evidence: where a value came from, as a list. A cell such as "ODI 68 → 10;
// VAS 7 → 1" is drawn from two places, so one locator per value (the first
// contract) is replaced by a list, each item one of four kinds; an abstract
// quote has no page, only the record it was read from.
export const KINDS = ['text', 'image', 'file', 'abstract'];

export function migrateValue(v) {
  if (!v || Array.isArray(v.evidence)) return v;
  const loc = v.source_locator;
  const evidence = loc && loc.page ? [{ kind: 'text', document_version: loc.document_version, page: loc.page, quote: v.reported_value, rects: loc.rects || [] }] : [];
  return { ...v, evidence };
}

const base = p => String(p || '').split('/').pop();
export function evidenceLabel(e) {
  if (!e) return '';
  if (e.kind === 'text') return `p. ${e.page}${e.ocr ? ' (recognised text)' : ''}`;
  if (e.kind === 'abstract') return 'abstract';
  if (e.kind === 'image') return e.caption ? `p. ${e.page}, ${e.caption}` : `p. ${e.page}, figure`;
  if (e.kind === 'file') {
    const l = e.locator || {};
    if (l.sheet != null && l.cell) return `${base(e.path)} ${l.sheet}!${l.cell}`;
    if (l.paragraph != null) return `${base(e.path)} ¶${l.paragraph}`;
    if (l.line != null) return `${base(e.path)} line ${l.line}`;
    return base(e.path);
  }
  return '';
}

/** The first anchor a reader can jump to. */
export function firstLocator(v) {
  const e = (v?.evidence || []).find(x => x.kind === 'text' || x.kind === 'image');
  return e ? { page: e.page, rects: e.rects || [], kind: e.kind, region: e.region || null } : null;
}

// The project state behind the extraction data summary (design note 2026-10-13 §2): what a person approved about how a field's texts count.
// Pure and free of the store, so the project normaliser (store.mjs normalizeProject) and the node tests load it. The thin store wrappers are
// in ./extraction-summary-store.mjs.
//
//   project.extractionSummary = { version: 1, fields, cache, review, runs, columns }   (absent until used; null in the empty project)
//
// Nothing here touches a value, a proposal or a study's text. Counts are never stored: they are recomputed from `values` on demand.
import { evictionPlan } from './cache-budget.mjs';

export const STATE_VERSION = 1;
export const CACHE_LIMIT_BYTES = 1048576;   // the answer cache: 1 MB, least recently used first
export const RUNS_KEPT = 20;
export const REVIEW_NOTES_PER_CELL = 20;

const obj = v => (v && typeof v === 'object' && !Array.isArray(v) ? v : null);
const str = v => (typeof v === 'string' ? v : '');
const KINDS = ['multi', 'categorical', 'free'];
const NOTE_STATES = ['open', 'dismissed', 'applied'];
const ts = at => { const t = Date.parse(at); return Number.isFinite(t) ? t : 0; };
const size = v => { try { return JSON.stringify(v)?.length || 0; } catch { return 0; } };

/** One field's approved decisions in the shape the summary reads; null when nothing usable is left. */
function cleanField(m) {
  const f = obj(m); if (!f) return null;
  const out = { states: {}, markers: {}, categories: {}, cells: {} };
  if (KINDS.includes(f.kind)) out.kind = f.kind;
  if (f.parse === 'plain') out.parse = 'plain';
  for (const [k, v] of Object.entries(obj(f.states) || {})) if (k && str(v).trim()) out.states[k] = v.trim();
  for (const [k, v] of Object.entries(obj(f.markers) || {})) if (k && str(v).trim()) out.markers[k] = v.trim();
  for (const [id, c] of Object.entries(obj(f.categories) || {})) {
    const label = str(obj(c)?.label).trim(); if (!id || !label) continue;
    out.categories[id] = { label, from: c.from === 'model' ? 'model' : 'person' };
  }
  for (const [k, list] of Object.entries(obj(f.cells) || {})) {
    if (!Array.isArray(list)) continue;
    const kept = list.filter(x => obj(x) && out.categories[x.category]).map(x => ({ category: x.category, ...(str(x.status).trim() ? { status: x.status.trim() } : {}) }));
    if (kept.length) out.cells[k] = kept;   // a text pointing at an unknown category is dropped
  }
  if (str(f.definitionHash)) out.definitionHash = f.definitionHash;
  if (str(f.approvedAt)) out.approvedAt = f.approvedAt;
  if (str(f.model)) out.model = f.model;
  const empty = !out.kind && !out.parse && ['states', 'markers', 'categories', 'cells'].every(k => !Object.keys(out[k]).length);
  return empty ? null : out;
}

function cleanNote(n) {
  const x = obj(n); if (!x || !str(x.id) || !str(x.text)) return null;
  return { ...x, state: NOTE_STATES.includes(x.state) ? x.state : 'open', kind: str(x.kind), runId: str(x.runId), valueHash: str(x.valueHash), at: str(x.at) };
}

/**
 * The summary state as this version holds it. Absent or not an object: null. A version this build does not know is returned untouched, so a
 * newer file is carried through and written back as it was. Otherwise: unknown shapes dropped, `cells` pointing at an unknown category
 * dropped, the answer cache trimmed to its byte limit (least recently used first), the review notes capped, the last RUNS_KEPT runs kept.
 * Notes whose value changed are not rewritten here: a reader retires them when it sees a different `valueHash`.
 */
export function normalizeExtractionSummary(next, { cacheLimit = CACHE_LIMIT_BYTES } = {}) {
  const s = obj(next); if (!s) return null;
  if (s.version !== STATE_VERSION) return s.version > STATE_VERSION ? s : null;
  const fields = {};
  for (const [id, m] of Object.entries(obj(s.fields) || {})) { const c = cleanField(m); if (c) fields[id] = c; }
  const cache = {};
  const entries = Object.entries(obj(s.cache) || {}).filter(([k, e]) => k && obj(e) && 'out' in e).map(([k, e]) => [k, { out: e.out, at: str(e.at), bytes: Number(e.bytes) > 0 ? Number(e.bytes) : size(e.out) }]);
  const drop = new Set(evictionPlan(entries.map(([k, e]) => [k, { bytes: e.bytes, at: ts(e.at) }]), cacheLimit));
  for (const [k, e] of entries) if (!drop.has(k)) cache[k] = e;
  const review = {};
  for (const [cell, list] of Object.entries(obj(s.review) || {})) {
    if (!Array.isArray(list)) continue;
    const kept = list.map(cleanNote).filter(Boolean).slice(-REVIEW_NOTES_PER_CELL);
    if (kept.length) review[cell] = kept;
  }
  const runs = (Array.isArray(s.runs) ? s.runs : []).filter(r => obj(r) && str(r.id)).slice(-RUNS_KEPT);
  const columns = {};
  for (const [t, c] of Object.entries(obj(s.columns) || {})) if (Array.isArray(obj(c)?.hidden)) columns[t] = { hidden: [...new Set(c.hidden.filter(x => typeof x === 'string' && x))] };
  return { version: STATE_VERSION, fields, cache, review, runs, columns };
}

// ---- writers: pure on a project state object (the setManualStateValue / setManualValue split) -------------------------------------------

/** The state to write into: created on first use. */
export function base(s) {
  s.extractionSummary = normalizeExtractionSummary(s.extractionSummary) ?? { version: STATE_VERSION, fields: {}, cache: {}, review: {}, runs: [], columns: {} };
  return s.extractionSummary;
}
const fieldOf = (s, id) => (base(s).fields[id] ||= { states: {}, markers: {}, categories: {}, cells: {} });
export const prune = (s, id) => { const f = s.extractionSummary.fields[id]; if (f && !cleanField(f)) delete s.extractionSummary.fields[id]; };

/** Approves a mapping for a field: `mapping` is { categories, cells, markers?, states?, kind?, parse?, definitionHash?, model? }; it replaces the field's earlier one. */
export function approveMapping(s, fieldId, mapping, now = new Date().toISOString()) {
  const c = cleanField({ ...mapping, approvedAt: now }); const st = base(s);
  if (c) st.fields[fieldId] = c; else delete st.fields[fieldId];
  return s;
}
/** Merges categories into one named `label` (the first id is kept); every text that pointed at a merged id points at the kept one. */
export function mergeCategories(s, fieldId, ids, label) {
  const f = fieldOf(s, fieldId), [keep, ...gone] = ids.filter(id => f.categories[id]); if (!keep || !str(label).trim()) return s;
  f.categories[keep] = { label: label.trim(), from: 'person' };
  for (const id of gone) delete f.categories[id];
  for (const [k, list] of Object.entries(f.cells)) {
    const seen = new Set();
    f.cells[k] = list.map(x => (gone.includes(x.category) ? { ...x, category: keep } : x)).filter(x => { const key = `${x.category}|${x.status || ''}`; if (seen.has(key)) return false; seen.add(key); return true; });
  }
  return s;
}
export function renameCategory(s, fieldId, id, label) {
  const f = fieldOf(s, fieldId); if (f.categories[id] && str(label).trim()) f.categories[id] = { label: label.trim(), from: 'person' };
  return s;
}
export function dropMapping(s, fieldId) { delete base(s).fields[fieldId]; return s; }
/** Marks texts (already folded with `valueKey`) as meaning "no value" for a field, by the label the person chose; an empty role clears them. */
export function markStatesFor(s, fieldId, keys, role) {
  const f = fieldOf(s, fieldId);
  for (const k of keys) if (str(role).trim()) f.states[k] = role.trim(); else delete f.states[k];
  prune(s, fieldId); return s;
}
/**
 * A short token for the value a review note was written for: the note is current only while the cell still holds that value. FNV-1a over the
 * state and the text, with the length, so a different value of the same length collides only by a 32-bit chance, and the worst a collision
 * does is leave a stale note on view until the next review.
 */
export function valueHash(v) {
  const t = v ? `${v.availability || ''}|${v.reported_value ?? v.normalized_value ?? ''}` : '';
  let h = 0x811c9dc5;
  for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
