 *   fallback     the family is absent: the tail of the font stack draws
 *
 * The result's `metrics` is what a clip check should measure against; layout
 * itself uses the profile's table (tokensFor), so coordinates do not depend on
 * which of these three it is.
 */
export function resolveFonts(profile, available = null) {
  const fonts = profile?.fonts || {};
  const family = fonts.family || null;
  const base = { widths: profile?.metrics?.widths || null, scale: profile?.metrics?.scale ?? 1 };
  if (!family) return { family: null, fidelity: 'exact', faces: {}, record: {}, notice: '', metrics: { ...base, source: 'profile' } };
  const list = (Array.isArray(available) ? available : available?.faces || [])
    .filter(f => isObj(f) && String(f.family || '').toLowerCase() === family.toLowerCase() && (!f.style || f.style === 'normal') && isNum(Number(f.weight)));
  const have = [...new Set(list.map(f => Number(f.weight)))].sort((a, b) => a - b);
  const tail = String(fonts.stack || '').split(',').map(s => s.trim().replace(/^["']|["']$/g, '')).filter(s => s && s.toLowerCase() !== family.toLowerCase() && !GENERIC.test(s))[0] || 'a system font';
  const faces = {}, record = {};
  for (const [role, asked] of Object.entries(fonts.roles || {})) {
    const wanted = fonts.weights?.[asked] ?? asked;
    let fidelity = 'fallback', got = null;
    if (have.includes(wanted)) { fidelity = 'exact'; got = wanted; }
    else if (have.length) { fidelity = 'approximate'; got = have.reduce((best, w) => (Math.abs(w - wanted) < Math.abs(best - wanted) ? w : best), have[0]); }
    faces[role] = { family, asked, wanted, got, fidelity };
    record[role] = fidelity === 'exact' ? `${family} ${wanted}` : fidelity === 'approximate' ? `${family} ${wanted} -> ${got}` : `${family} ${wanted} -> ${tail}`;
  }
  const levels = Object.values(faces).map(f => f.fidelity);
  const fidelity = levels.length ? levels.reduce((a, b) => (RANK[b] > RANK[a] ? b : a), 'exact') : (have.length ? 'exact' : 'fallback');
  const regular = list.find(f => Number(f.weight) === 400 && f.widths) || null;
  const labelFace = list.find(f => Number(f.weight) === faces.label?.got && f.widths) || null;
  let metrics;
  if (fidelity === 'exact') metrics = labelFace ? { widths: labelFace.widths, scale: 1, source: 'font file' } : { ...base, source: 'profile' };
  else if (fidelity === 'approximate') {
    const m = regular ? { widths: regular.widths, scale: 1 } : base;
    metrics = { widths: m.widths, scale: round(m.scale * MISSING_WEIGHT_SLACK), source: regular ? 'regular file with slack' : 'profile with slack' };
  } else metrics = { widths: base.widths, scale: base.widths ? base.scale : ABSENT_FAMILY_SCALE, source: base.widths ? 'profile table' : 'Helvetica table, largest measured ratio' };
  const names = have.map(w => WEIGHT_NAME[w] || String(w)).join(', ');
  const notice = fidelity === 'exact' ? '' : fidelity === 'fallback' ? `${family} not found` : `${family} ${names} only`;
  return { family, fidelity, faces, record, notice, metrics };
}

/** The `style` stamp a render carries in outputs.json and in the SVG `<desc>`: `{ id, version, hash, fonts, fidelity }`. */
export const styleStamp = (profile, resolved) => ({
  id: profile.id, version: profile.version ?? 1, hash: canonicalHash(profile),
  fonts: { ...(resolved?.record || {}) }, fidelity: resolved?.fidelity || 'exact',
});

// Rendered figures, kept beside the project rather than in it (plan §4.15b).
//
// An analysis result used to carry its R-drawn SVGs inline (`a.svg`,
// `a.funnel`, the sensitivity plots): about 2 MB of a 6.1 MB
// project file, serialised again on every save. The project now keeps
// only the numbers, inputs and results; each figure is stored once under the
// SHA-256 of its text and the result names it in `a.figures`:
//
//   { estimate, lo, hi, ..., figures: { svg: '<sha-256>', funnel: '<sha-256>' } }
//
// The name is the hash of the drawing, which is what the result and its render
// options produce, so a reader can check the file it got is the figure the
// result names, a figure is never stored twice, and a stored file is never
// rewritten. Where figures live depends on where the project does:
//   - a folder project: `.lykos/figures/<hash>.svg`, beside project.json;
//   - the app's own storage: the `lykos-figures` IndexedDB database, keyed by
//     the project's save channel and the hash.
// A figure is removed only by clean-up (store.mjs figureCleanup), when nothing
// that can still be opened names it and it is more than an hour old.
//
// Results written by code that still puts the SVG inline keep working: every
// reader goes through figureFor / figureNow / hasFigure, which answer for an
// inline figure and a stored one alike, and the store moves inline figures out
// on the next save (externalizeFigures). A figure that is named but cannot be
// found is not redrawn silently — R would have to run again — so readers get
// null and the view says the result needs a Run.

/** The result fields that hold a drawn figure. */
export const FIGURE_KEYS = ['svg', 'funnel', 'tf_svg', 'cumul_svg', 'baujat_svg', 'contour_svg'];
export const FIGURE_DIR = '.lykos/figures';
const HASH = /^[0-9a-f]{64}$/;
export const isFigureHash = h => typeof h === 'string' && HASH.test(h);

/** The analysis results a project holds: the primary's and each other outcome's. */
export function figureResults(st) {
  const out = [];
  if (st?.analysis && typeof st.analysis === 'object') out.push(st.analysis);
  if (st?.analyses && typeof st.analyses === 'object') for (const a of Object.values(st.analyses)) if (a && typeof a === 'object') out.push(a);
  return out;
}

/** Every figure hash a project names, for backups and checks. */
export function figureRefs(st) {
  const refs = new Set();
  for (const a of figureResults(st)) for (const h of Object.values(a.figures || {})) if (isFigureHash(h)) refs.add(h);
  return [...refs];
}

const enc = new TextEncoder(), dec = new TextDecoder();
/** SHA-256 of the text, as 64 hex digits; null where the runtime has no Web Crypto. */
export async function figureHash(text) {
  const subtle = globalThis.crypto?.subtle;
  if (!subtle) return null;
  const d = new Uint8Array(await subtle.digest('SHA-256', enc.encode(String(text))));
  let hex = '';
  for (const b of d) hex += b.toString(16).padStart(2, '0');
  return hex;
}

// ---- stores ----------------------------------------------------------------
// A store answers get(hash) → text or null, and put(hash, text). It is not
// trusted to hand back what was put: every read is checked against its hash.

/** Figures in a project folder (lib/fsys.mjs shape), one file per figure. */
export function folderFigureStore(f) {
  const rel = h => `${FIGURE_DIR}/${h}.svg`;
  return {
    kind: 'folder',
    async get(h) {
      const st = await f.stat(rel(h)).catch(() => null);
      if (!st?.exists || st.dir) return null;
      return dec.decode(await f.read(rel(h)));
    },
    // Written even when the file is there (the same bytes): its time is then
    // this write's, so clean-up's grace period covers a figure a save names again.
    async put(h, text) { await f.writeText(rel(h), text); },
    /** Every stored figure: `{ hash, bytes, at }`. */
    async list() {
      const st = await f.stat(FIGURE_DIR).catch(() => null);
      if (!st?.exists) return [];
      return (await f.list(FIGURE_DIR)).filter(e => !e.dir && /^[0-9a-f]{64}\.svg$/.test(e.name))
        .map(e => ({ hash: e.name.slice(0, 64), bytes: e.size || 0, at: e.mtime || null }));
    },
    // Removed to the system Trash, not deleted: one rename, all or nothing,
    // and the person can still take it back. Where the folder has no Trash (a
    // browser folder), figures are not removed at all.
    canRemove: Boolean(f.can?.trash && f.trash),
    remove: h => f.trash(rel(h)),
  };
}

// The app's own storage: a database of its own, so the project database's
// version (and older builds that open it) are untouched.
const FIG_DB = 'lykos-figures';
let figDb = null;
function openFigDb() {
  if (figDb) return figDb;
  const opening = figDb = new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') { reject(new Error('no IndexedDB')); return; }
    const req = indexedDB.open(FIG_DB, 1);
    req.onupgradeneeded = () => req.result.createObjectStore('figures');
    req.onsuccess = () => { req.result.onclose = () => { if (figDb === opening) figDb = null; }; resolve(req.result); };
    req.onerror = () => reject(req.error);
  });
  opening.catch(() => { if (figDb === opening) figDb = null; });
  return figDb;
}
const figOp = (mode, fn) => openFigDb().then(d => new Promise((resolve, reject) => {
  const t = d.transaction('figures', mode);
  const r = fn(t.objectStore('figures'));
  t.oncomplete = () => resolve(r?.result);
  t.onerror = () => reject(t.error);
}));

/** Figures of the project saved on `owner` (the store's save channel), in IndexedDB. */
export function idbFigureStore(owner) {
  const key = h => `${owner}|${h}`;
  return {
    kind: 'app',
    owner,
    // Kept as { svg, at }: when it was written, for clean-up's grace period.
    // A bare string is a figure from before that; its age is not known.
    get: async h => { const v = await figOp('readonly', s => s.get(key(h))); return typeof v === 'string' ? v : v?.svg ?? null; },
    put: (h, text) => figOp('readwrite', s => s.put({ svg: text, at: Date.now() }, key(h))).then(() => {}),
    async list() {
      const d = await openFigDb();
      return new Promise((resolve, reject) => {
        const t = d.transaction('figures', 'readonly'), st = t.objectStore('figures'), out = [];
        const keys = st.getAllKeys();
        keys.onsuccess = () => {
          for (const k of keys.result.filter(k => String(k).startsWith(`${owner}|`))) {
            const r = st.get(k);
            r.onsuccess = () => { const v = r.result; out.push({ hash: String(k).slice(owner.length + 1), bytes: (typeof v === 'string' ? v : v?.svg || '').length, at: typeof v === 'string' ? null : v?.at ?? null }); };
          }
        };
        t.oncomplete = () => resolve(out);
        t.onerror = () => reject(t.error);
      });
    },
    canRemove: true,
    remove: h => figOp('readwrite', s => s.delete(key(h))).then(() => {}),
    /** Gives a figure of unknown age the time now, so a later clean-up can judge it. */
    stamp: h => figOp('readwrite', s => { const r = s.get(key(h)); r.onsuccess = () => { if (typeof r.result === 'string') s.put({ svg: r.result, at: Date.now() }, key(h)); }; }).then(() => {}),
  };
}

/** A store in memory, for tests and for runtimes without storage. */
export function memoryFigureStore() {
  const m = new Map(), times = new Map();
  return { kind: 'memory', map: m, times, get: async h => m.get(h) ?? null, put: async (h, text) => { m.set(h, text); times.set(h, Date.now()); },
    list: async () => [...m].map(([hash, t]) => ({ hash, bytes: t.length, at: times.get(hash) ?? null })),
    canRemove: true, remove: async h => { m.delete(h); times.delete(h); } };
}

// ---- clean-up ----------------------------------------------------------------------
/** Every figure hash named anywhere in a text (a project, a backup, a log): cheap, and it can only keep more. */
export function hashesIn(text, into = new Set()) {
  for (const m of String(text).matchAll(/(?<![0-9a-f])[0-9a-f]{64}(?![0-9a-f])/g)) into.add(m[0]);
  return into;
}
/**
 * Which of `hashes` a text names, added to `into`. A clean-up only asks about
 * the figures actually stored, so a substring test per stored figure replaces a
 * regular-expression pass over the whole text: on a project of 50,000 values
 * the pass held the window for over a second (review of 2026-09-29).
 */
export function namedIn(text, hashes, into = new Set()) {
  const t = String(text);
  for (const h of hashes) if (!into.has(h) && t.includes(h)) into.add(h);
  return into;
}
export const FIGURE_GRACE_MS = 3_600_000;
/**
 * Which stored figures may go: named by nothing in `refs`, and written more
 * than FIGURE_GRACE_MS ago (another window may have just written one it is
 * about to name). A figure whose age is not known is kept.
 */
export function figureGarbage(stored, refs, now = Date.now(), grace = FIGURE_GRACE_MS) {
  const remove = [], young = [], unknown = [];
  let kept = 0;
  for (const f of stored) {
    if (refs.has(f.hash)) { kept++; continue; }
    if (f.at == null) unknown.push(f);
    else if (now - f.at < grace) young.push(f);
    else remove.push(f);
  }
  return { remove, young, unknown, kept, bytes: remove.reduce((n, f) => n + f.bytes, 0) };
}

// ---- the open project's figures ----------------------------------------------
let active = null;
// Figures read or moved out in this window, by hash. Content-addressed, so an
// entry is right for any project; bounded so a long session does not hold
// every figure it ever drew.
const cache = new Map();
const CACHE_MAX = 48;
function remember(h, text) {
  cache.delete(h); cache.set(h, text);
  while (cache.size > CACHE_MAX) cache.delete(cache.keys().next().value);
}

/** Where the open project's figures are kept (store.mjs sets it with the backend). */
export function useFigureStore(store) { active = store || null; }
export const figureStore = () => active;

/** Whether the result has this figure, inline or stored. */
export const hasFigure = (a, key) => Boolean(a && ((typeof a[key] === 'string' && a[key]) || isFigureHash(a.figures?.[key])));

/** The figure now, without waiting: inline, or stored and already read in this window; else null. */
export function figureNow(a, key) {
  if (!a) return null;
  if (typeof a[key] === 'string' && a[key]) return a[key];
  const h = a.figures?.[key];
  return isFigureHash(h) ? cache.get(h) ?? null : null;
}

/** Reads a stored figure by hash and checks it is the one named; null when missing or altered. */
export async function readFigure(h, store = active) {
  if (!isFigureHash(h)) return null;
  if (cache.has(h)) return cache.get(h);
  if (!store) return null;
  let text = null;
  try { text = await store.get(h); } catch { return null; }
  if (typeof text !== 'string' || await figureHash(text) !== h) return null;
  remember(h, text);
  return text;
}

/**
 * The accessor every reader uses: the figure's SVG text, inline or stored, or
 * null when the result has none or its stored copy cannot be found (the result
 * then needs a Run to draw it again; see figureState).
 */
export async function figureFor(a, key, store = active) {
  const now = figureNow(a, key);
  if (now) return now;
  return readFigure(a?.figures?.[key], store);
}

/** 'none' (not drawn), 'ready' (inline or read), 'stored' (named, not read yet). */
export function figureState(a, key) {
  if (!hasFigure(a, key)) return 'none';
  return figureNow(a, key) ? 'ready' : 'stored';
}

/**
 * Draws a figure with `draw(svg)`: at once when it is at hand, else once it is
 * read. `missing()` runs when the result names a figure that cannot be found.
 * Answers whether the result has the figure at all.
 */
export function withFigure(a, key, draw, missing = () => {}) {
  if (!hasFigure(a, key)) return false;
  const now = figureNow(a, key);
  if (now) { draw(now); return true; }
  figureFor(a, key).then(svg => (svg ? draw(svg) : missing()), () => missing());
  return true;
}

/** The text a figure panel shows in place of a figure that cannot be found. */
export const MISSING_FIGURE = 'Figure not found on this computer. Run the analysis again to draw it.';
/** Puts that text in a figure host (`#id` under `root`), if it is still on screen. */
export function figureMissing(root, id) {
  const host = root?.querySelector?.('#' + id);
  if (host && host.isConnected !== false) host.textContent = MISSING_FIGURE;
}

// ---- moving figures out, and back in ---------------------------------------------

/**
 * Moves every inline figure of the project's results into the store, and puts
 * its hash in the result's `figures`. A figure leaves the result only after
 * the store has taken it; a figure the store refuses stays inline, and so
 * does everything when the runtime cannot hash. Mutates `st`'s results.
 * Answers what moved: `{ moved, bytes }`.
 */
export async function externalizeFigures(st, store = active) {
  let moved = 0, bytes = 0;
  if (!store) return { moved, bytes };
  for (const a of figureResults(st)) {
    for (const key of FIGURE_KEYS) {
      const text = a[key];
      if (typeof text !== 'string' || !text) continue;
      const h = await figureHash(text);
      if (!h) return { moved, bytes };
      try { await store.put(h, text); } catch { continue; }
      remember(h, text);
      // The result may have been given a new drawing while the store wrote.
      if (a[key] !== text) continue;
      a.figures = { ...(a.figures || {}), [key]: h };
      delete a[key];
      moved++; bytes += text.length;
    }
  }
  return { moved, bytes };
}

/**
 * A copy of the project with its stored figures back inline, for a file that
 * has to stand on its own (an export, a backup file, a move into a folder).
 * Results whose figures cannot be found keep the hash. Results are copied;
 * nothing else is.
 */
export async function inlineFigures(st, store = active) {
  // Every result is copied, so moving the copy's figures elsewhere
  // (externalizeFigures into another store) never changes the open project.
  const fill = async a => {
    if (!a?.figures) return { ...a };
    const copy = { ...a }, left = {};
    for (const [key, h] of Object.entries(a.figures)) {
      const text = typeof copy[key] === 'string' && copy[key] ? copy[key] : await readFigure(h, store);
      if (text) copy[key] = text; else left[key] = h;
    }
    if (Object.keys(left).length) copy.figures = left; else delete copy.figures;
    return copy;
  };
  const out = { ...st };
  if (st.analysis && typeof st.analysis === 'object') out.analysis = await fill(st.analysis);
  if (st.analyses && typeof st.analyses === 'object') {
    out.analyses = {};
    for (const [k, a] of Object.entries(st.analyses)) out.analyses[k] = a && typeof a === 'object' ? await fill(a) : a;
  }
  return out;
}

/** For tests: forget what this window has read. */
export const clearFigureCache = () => cache.clear();

// The stored study-governance records and what the shell reads of them on every load: the ethics record and its deadlines, the registration, the statistical
// analysis plan rows and the checklist choice, normalised; the Overview's ethics attention. store.mjs and lib/progress.mjs import these; the drafting
// (lib/governance.mjs), the registration forms (lib/registration.mjs) and the checklist catalogues (lib/checklists-extra.mjs) load with the pages that use
// them, and re-export what moved here.

const has = v => !!String(v ?? '').trim();
const trim = v => String(v ?? '').trim();
const obj = v => v && typeof v === 'object' && !Array.isArray(v) ? v : null;
const day = d => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(d instanceof Date ? d.toISOString() : String(d ?? '')); return m ? `${m[1]}-${m[2]}-${m[3]}` : null; };
const daysBetween = (a, b) => Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 864e5);
export const DATE_KEYS = ['registeredAt', 'firstEnrolmentAt', 'primaryCompletionAt'];

/** An ISO day plus whole months, the day clamped to the month's end. */
export function addMonths(iso, months) {
  const d = day(iso); if (!d) return null;
  const [y, m, dd] = d.split('-').map(Number);
  const tm = m - 1 + months, ty = y + Math.floor(tm / 12), mm = ((tm % 12) + 12) % 12;
  const last = new Date(Date.UTC(ty, mm + 1, 0)).getUTCDate();
  return `${ty}-${String(mm + 1).padStart(2, '0')}-${String(Math.min(dd, last)).padStart(2, '0')}`;
}

// ---- ethics ---

/** An empty ethics record. Dates are ISO days. */
export function blankEthics() {
  return { committee: '', reference: '', approvedAt: '', expiresAt: '', amendments: [], annualReportDue: '', conditions: '' };
}
/** A stored record with every field present. */
export function normalizeEthics(r = {}) {
  const b = blankEthics(), x = r || {};
  return { ...b, ...x, amendments: (Array.isArray(x.amendments) ? x.amendments : []).map(a => ({ at: '', text: '', approvedAt: '', ...a })) };
}

/**
 * Upcoming and overdue items for the to-do list, soonest first:
 * `[{ kind: 'expiry'|'annual-report'|'amendment', due, text, overdue, hint? }]`.
 * Items further than `within` days away are left out. With no annual report
 * date recorded, the next anniversary of approval is offered as a hint to check.
 */
export function deadlines(record, today = new Date(), { within = 90 } = {}) {
  const r = normalizeEthics(record), now = day(today), out = [];
  const who = has(r.committee) ? ` (${trim(r.committee)})` : '';
  const push = (kind, due, text, extra = {}) => {
    if (!due) { out.push({ kind, due: null, text, overdue: false, ...extra }); return; }
    const d = daysBetween(now, due);
    if (d <= within) out.push({ kind, due, text, overdue: d < 0, ...extra });
  };
  if (day(r.expiresAt)) push('expiry', day(r.expiresAt), `Ethics approval expires${who}: renew or close the study`);
  if (day(r.annualReportDue)) push('annual-report', day(r.annualReportDue), `Annual progress report to the ethics committee${who}`);
  else if (day(r.approvedAt)) {
    let due = addMonths(r.approvedAt, 12);
    while (due && daysBetween(now, due) < 0 && (!day(r.expiresAt) || due < day(r.expiresAt))) due = addMonths(due, 12);
    if (due && (!day(r.expiresAt) || due <= day(r.expiresAt)))
      push('annual-report', due, `Annual progress report to the ethics committee${who}`, { hint: 'Anniversary of approval; check the committee’s own reporting rule.' });
  }
  r.amendments.forEach(a => { if (has(a.text) && !has(a.approvedAt)) push('amendment', null, `Amendment awaiting approval: ${trim(a.text)}${day(a.at) ? ` (submitted ${day(a.at)})` : ''}`); });
  return out.sort((a, b) => (a.due || '9999') < (b.due || '9999') ? -1 : 1);
}

// ---- registration, plan and checklist choice ---

/** The stored registration with every part present. Other keys (sponsor, countries…) are kept. */
export function normalizeRegistration(r) {
  const x = obj(r) || {};
  const values = Object.fromEntries(Object.entries(obj(x.values) || {}).filter(([, v]) => obj(v))
    .map(([form, v]) => [form, Object.fromEntries(Object.entries(v).filter(([, t]) => typeof t === 'string'))]));
  const dates = Object.fromEntries(DATE_KEYS.map(k => [k, String(obj(x.dates)?.[k] ?? x[k] ?? '')]));
  return { ...x, form: typeof x.form === 'string' ? x.form : '', values, dates };
}

/** The stored plan's rows, `[{ outcome, method }]`. */
export function sapRows(state) {
  return (Array.isArray(state?.sap?.analyses) ? state.sap.analyses : [])
    .filter(obj).map(a => ({ ...a, outcome: String(a.outcome ?? ''), method: String(a.method ?? '') }));
}

/** The stored choice with every part present; `abstract` and `protocol` say whether those checklists are reported too. */
export function normalizeChecklistChoice(c) {
  const x = obj(c) || {};
  const ids = v => [...new Set((Array.isArray(v) ? v : []).filter(id => typeof id === 'string'))];
  return { checklist: typeof x.checklist === 'string' ? x.checklist : '', extensions: ids(x.extensions), addons: ids(x.addons), abstract: !!x.abstract, protocol: !!x.protocol };
}

// ---- ethics attention ---

/**
 * Ethics deadlines within `within` days (and overdue ones) as Overview rows:
 * `[{ severity, view: 'protocol', go: 'protocol:ethics', text, due }]`. An
 * overdue item blocks; an amendment awaiting approval has no date and is a gap.
 */
export function ethicsAttention(state, today = new Date(), { within = 90 } = {}) {
  if (!obj(state?.ethics)) return [];
  return deadlines(state.ethics, today, { within }).map(d => ({
    severity: d.overdue ? 'block' : 'gap', view: 'protocol', go: 'protocol:ethics',
    text: d.due ? `${d.text} · ${d.overdue ? 'overdue since' : 'due'} ${d.due}` : d.text, due: d.due,
  }));
}

/** Brings the stored governance records forward in place; absent ones stay absent. */
export function normalizeGovernance(next) {
  if (next.registration != null) next.registration = normalizeRegistration(next.registration);
  if (next.ethics != null) next.ethics = normalizeEthics(obj(next.ethics) || {});
  if (next.sap != null) next.sap = { ...(obj(next.sap) || {}), analyses: sapRows(next) };
  if (next.spiritSchedule != null && !obj(next.spiritSchedule)) next.spiritSchedule = null;
  if (next.checklistChoice != null) next.checklistChoice = normalizeChecklistChoice(next.checklistChoice);
  return next;
}

// gzip for backups and recovery copies: CompressionStream is in WebKit, Chromium and Node 22; nothing is vendored.
export async function gzipText(text) { return new Response(new Blob([text]).stream().pipeThrough(new CompressionStream('gzip'))).blob(); }
export async function gunzipBlob(blob) { return new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text(); }
/** Whether bytes start with the gzip magic number (a `.json.gz` copy, whatever its name says). */
export const isGzip = bytes => bytes?.length >= 2 && bytes[0] === 0x1f && bytes[1] === 0x8b;
/** The text of a file that may be gzip or plain UTF-8; a gzip that does not inflate throws, so it is reported, never taken for empty. */
export async function textOf(bytes) {
  if (!isGzip(bytes)) return new TextDecoder().decode(bytes);
  try { return await gunzipBlob(new Blob([bytes])); } catch (err) { throw new Error(`the compressed copy could not be read (${err?.message || err})`); }
}

// Individual participant data.
//
// A review of a rare condition pools patients, not studies: a few patients
// drawn from many case reports, or hundreds across several treatment
// strategies. The unit of analysis is the patient, and each one keeps the study
// it came from, so a result can always be traced back to its report (plan G3,
// and PRISMA-IPD).
//
// Columns are editable because no fixed schema survives contact with a second
// review; these defaults are what a comparative time-to-event pooled analysis
// needs.
import { get, update } from '../store.mjs';

export const COLUMN_TYPES = ['text', 'number', 'category', 'date', 'boolean'];

export const DEFAULT_COLUMNS = [
  { id: 'label',      name: 'Patient',        type: 'text' },
  { id: 'age',        name: 'Age',            type: 'number' },
  { id: 'sex',        name: 'Sex',            type: 'category', levels: ['Female', 'Male'] },
  { id: 'strategy',   name: 'Strategy',       type: 'category',
    levels: ['GTR alone', 'Incomplete resection alone', 'Incomplete + RT', 'Incomplete + SRS'],
    role: 'group' },
  { id: 'dose',       name: 'Marginal dose (Gy)', type: 'number' },
  { id: 'volume',     name: 'Volume (cm³)',   type: 'number' },
  { id: 'time',       name: 'Follow-up (months)', type: 'number', role: 'time' },
  { id: 'event',      name: 'Progression',    type: 'boolean', role: 'event' },
  { id: 'outcome',    name: 'Outcome',        type: 'text' },
];

export const columns = () => get().ipdColumns || DEFAULT_COLUMNS;
export const participants = () => get().participants || [];

/** The column carrying a role, so an analysis knows which is time and which is event. */
export const roleColumn = role => columns().find(c => c.role === role);

export function setColumns(cols) {
  update(s => { s.ipdColumns = cols; return s; });
}

/**
 * `extra` is for a row a model read from a report: `evidence` ({ column id:
 * [{ quote, page, ... }] }, the report's own words for each cell), `extractor`
 * ('model:<name>') and `run_id`. A row typed or imported has none of them.
 */
export function addParticipant(studyId, values = {}, extra = null) {
  const id = `ipd${Date.now().toString(36)}${Math.random().toString(36).slice(2, 5)}`;
  const own = extra ? Object.fromEntries(['evidence', 'extractor', 'run_id'].filter(k => extra[k] != null).map(k => [k, extra[k]])) : {};
  update(s => {
    s.participants = [...(s.participants || []), { id, study_id: studyId, ...values, ...own, updatedAt: new Date().toISOString() }];
    return s;
  });
  return id;
}

// ---- rows a model extracted, waiting for a person ----------------------------------
// A patient a model read from a report is not yet data: survival tables and
// pooled analyses read `participants`. Rows wait here with the quote behind each
// cell and what the rule check found, and join the participants only when a
// person accepts them (lib/extract-batch.mjs writes them).
export const participantProposals = () => get().ipdProposals || [];

/** Adds proposed rows: [{ cells, evidence, qa?, case_no? }]. Returns their ids. */
export function proposeParticipants(studyId, rows, { model = null, run_id = null } = {}) {
  const at = new Date().toISOString(), ids = [];
  update(s => {
    s.ipdProposals = s.ipdProposals || [];
    for (const r of rows) {
      const id = `ipp${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`; ids.push(id);
      s.ipdProposals.push({ id, study_id: studyId, cells: { ...(r.cells || {}) }, evidence: r.evidence || {}, qa: r.qa || null, model, run_id, at });
    }
    return s;
  });
  return ids;
}

/** Replaces the record of a proposed row (a stamp from the rule check, a re-check by a stronger model). */
export function patchParticipantProposal(id, fn) {
  update(s => { const p = (s.ipdProposals || []).find(x => x.id === id); if (p) fn(p); return s; });
}

/** A proposed row becomes a participant, with its quotes; `editedCells` are a person's corrections. Returns the participant id. */
export function acceptParticipantProposal(id, { editedCells = null } = {}) {
  const p = participantProposals().find(x => x.id === id); if (!p) return null;
  const pid = addParticipant(p.study_id, { ...p.cells, ...(editedCells || {}) },
    { evidence: p.evidence, extractor: `model:${p.model || 'unknown'}${editedCells ? ' (edited)' : ''}`, run_id: p.run_id });
  update(s => { s.ipdProposals = (s.ipdProposals || []).filter(x => x.id !== id); return s; });
  return pid;
}

export function rejectParticipantProposal(id) {
  update(s => { s.ipdProposals = (s.ipdProposals || []).filter(x => x.id !== id); return s; });
}

export function setValue(participantId, columnId, value) {
  update(s => {
    s.participants = (s.participants || []).map(p =>
      p.id === participantId ? { ...p, [columnId]: value, updatedAt: new Date().toISOString() } : p);
    return s;
  });
}

export function removeParticipant(id) {
  update(s => {
    s.participants = (s.participants || []).filter(p => p.id !== id);
    return s;
  });
}

/** Reads a numeric cell without discarding text or silently converting an unknown value to zero. */
export function numeric(p, columnId) {
  const raw = p[columnId];
  if (raw == null || typeof raw === 'boolean') return null;
  const text = String(raw).trim();
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(text)) return null;
  const n = Number(text);
  return Number.isFinite(n) ? n : null;
}

export function boolish(p, columnId) {
  const raw = String(p[columnId] ?? '').trim().toLowerCase();
  if (['1', 'yes', 'y', 'true', 'progressed', 'event'].includes(raw)) return 1;
  if (['0', 'no', 'n', 'false', 'censored'].includes(raw)) return 0;
  return null;
}

/**
 * Cut points into labelled intervals, lower bound included: "< 40", "40–<60",
 * "≥ 60". The label list is the order groups are shown in.
 */
export function binLabels(cuts) {
  const c = [...new Set(cuts.map(Number).filter(Number.isFinite))].sort((a, b) => a - b);
  if (!c.length) return [];
  return [`< ${c[0]}`, ...c.slice(1).map((x, i) => `${c[i]}–<${x}`), `≥ ${c[c.length - 1]}`];
}

/** The interval label a value falls in. */
export function binOf(value, cuts) {
  const c = [...new Set(cuts.map(Number).filter(Number.isFinite))].sort((a, b) => a - b);
  const labels = binLabels(c);
  let i = 0;
  while (i < c.length && value >= c[i]) i++;
  return labels[i];
}

const blank = v => v == null || String(v).trim() === '';

/**
 * Rows ready for a time-to-event analysis, and the ones that could not be used,
 * from participants and columns alone (no store), so a test or a bench can call it.
 *
 * opts: group (a column id; null for one group; default the column with role
 * "group"), time, event (column ids; default their roles), bins (cut points for
 * a number column used as the group), cluster (column id, default study_id;
 * a patient without one is a cluster of its own), strata (column id),
 * covariates (column ids, complete cases), subset (a predicate on the
 * participant, or a list of participant ids), landmark and landmarkMode
 * ("reset", the default, restarts the clock at the landmark; "filter" keeps
 * the original times).
 *
 * A patient missing a follow-up time or an event status is reported, not
 * silently dropped: how many were excluded is part of the result.
 */
export function survivalRowsFrom(people, cols, opts = {}) {
  const find = id => {
    const c = cols.find(x => x.id === id);
    if (!c) throw new Error(`no column "${id}"`);
    return c;
  };
  const role = r => cols.find(c => c.role === r);
  const time = opts.time ? find(opts.time) : role('time');
  const event = opts.event ? find(opts.event) : role('event');
  const group = opts.group === undefined ? role('group') : opts.group === null ? null : find(opts.group);
  const strata = opts.strata === 'study_id' ? { id: 'study_id', name: 'source report', type: 'text' } : opts.strata ? find(opts.strata) : null;
  const covs = (opts.covariates || []).map(find);
  const bins = Array.isArray(opts.bins) && opts.bins.length ? opts.bins : null;
  const clusterId = opts.cluster === undefined ? 'study_id' : opts.cluster;
  const keep = typeof opts.subset === 'function' ? opts.subset
    : Array.isArray(opts.subset) ? (p => opts.subset.includes(p.id)) : null;
  const t0 = Number(opts.landmark) > 0 ? Number(opts.landmark) : 0;

  const label = (p, c) => {
    const raw = p[c.id];
    if (blank(raw)) return null;
    if (c.type === 'boolean') { const b = boolish(p, c.id); return b == null ? null : b ? 'Yes' : 'No'; }
    if (c.type === 'number' && c === group && bins) { const n = numeric(p, c.id); return n == null ? null : binOf(n, bins); }
    return String(raw).trim();
  };

  const rows = [], excluded = [];
  for (const p of people) {
    const t = time ? numeric(p, time.id) : null;
    const e = event ? boolish(p, event.id) : null;
    const g = group ? label(p, group) : 'All';
    if (t == null || t < 0) { excluded.push({ p, why: time && !blank(p[time.id]) ? 'invalid follow-up time' : 'no follow-up time' }); continue; }
    if (e == null) { excluded.push({ p, why: event && !blank(p[event.id]) ? 'unrecognised event status' : 'no event status' }); continue; }
    if (group && !g) { excluded.push({ p, why: 'no group' }); continue; }
    if (keep && !keep(p)) { excluded.push({ p, why: 'outside the subset' }); continue; }
    const row = { id: p.id, study_id: p.study_id, time: t, event: e, group: g || 'All',
      cluster: String((clusterId && !blank(p[clusterId]) ? p[clusterId] : null) ?? p.id) };
    if (strata) {
      const s = label(p, strata);
      if (!s) { excluded.push({ p, why: `no ${strata.name || strata.id}` }); continue; }
      row.strata = s;
    }
    if (covs.length) {
      const x = {};
      let missing = null;
      for (const c of covs) {
        const v = c.type === 'number' ? numeric(p, c.id) : label(p, c);
        if (v == null) { missing = c; break; }
        x[c.id] = v;
      }
      if (missing) { excluded.push({ p, why: `no ${missing.name || missing.id}` }); continue; }
      row.x = x;
    }
    rows.push(row);
  }

  let out = rows;
  if (t0) {
    out = landmarkRows(rows, t0, { reset: opts.landmarkMode !== 'filter' });
    const kept = new Set(out.map(r => r.id));
    for (const r of rows) if (!kept.has(r.id)) excluded.push({ p: people.find(p => p.id === r.id), why: 'follow-up ends by the landmark' });
  }

  // The group order a table is read in: the column's own levels, then the rest.
  const present = [...new Set(out.map(r => r.group))];
  let levels;
  if (group && bins) levels = binLabels(bins).filter(l => present.includes(l));
  else if (group?.type === 'boolean') levels = ['No', 'Yes'].filter(l => present.includes(l));
  else {
    const own = (group?.levels || []).filter(l => present.includes(l));
    levels = [...own, ...present.filter(l => !own.includes(l)).sort()];
  }
  return { rows: out, excluded, levels, groupName: group ? group.name || group.id : null };
}

/** The participants and columns held by the open project. */
export function survivalRows(opts = {}) {
  return survivalRowsFrom(participants(), columns(), opts);
}

/**
 * A landmark analysis: patients still under follow-up beyond t0, the clock
 * restarted at t0 (unless reset is false). Someone whose event or censoring
 * falls at t0 or earlier is not in the risk set at t0 and is left out.
 */
export function landmarkRows(rows, t0, { reset = true } = {}) {
  return rows.filter(r => r.time > t0).map(r => (reset ? { ...r, time: r.time - t0 } : { ...r }));
}

/** Rows kept by a predicate on the row, or by a list of participant ids. */
export function subsetRows(rows, subset) {
  if (Array.isArray(subset)) { const ids = new Set(subset); return rows.filter(r => ids.has(r.id)); }
  if (typeof subset === 'function') return rows.filter(r => subset(r));
  return rows;
}

// ---- CSV ----------------------------------------------------------------
export function toCsv() {
  const cols = columns();
  const head = ['study', ...cols.map(c => c.name)];
  const body = participants().map(p => [
    get().papers.find(x => x.id === p.study_id)?.label ?? p.study_id,
    ...cols.map(c => p[c.id] ?? ''),
  ]);
  return [head, ...body];
}

/**
 * Reads a table where each row is a patient. Columns are matched by name; a
 * column the schema does not know is added rather than discarded, because a
 * dropped variable is a silent change to the dataset.
 */
export function fromCsv(text) {
  const rows = parseCsv(text);
  if (rows.length < 2) return { added: 0, columns: 0 };
  const header = rows[0].map(h => h.trim());
  const cols = [...columns()];
  const byName = new Map(cols.map(c => [c.name.toLowerCase(), c]));
  const mapping = header.map(h => {
    if (/^stud(y|ies)$/i.test(h)) return { study: true };
    const known = byName.get(h.toLowerCase());
    if (known) return { col: known };
    const id = h.toLowerCase().replace(/[^a-z0-9]+/g, '_').slice(0, 32) || `c${cols.length}`;
    const created = { id, name: h, type: 'text' };
    cols.push(created);
    return { col: created, created: true };
  });
  const madeCols = mapping.filter(m => m.created).length;
  if (madeCols) setColumns(cols);

  const papers = get().papers;
  let added = 0;
  for (const row of rows.slice(1)) {
    if (!row.some(v => String(v).trim())) continue;
    const values = {};
    let studyId = null;
    row.forEach((v, i) => {
      const m = mapping[i];
      if (!m) return;
      if (m.study) {
        const label = String(v).trim();
        studyId = papers.find(p => p.label === label || p.title === label)?.id ?? label;
      } else values[m.col.id] = String(v).trim();
    });
    addParticipant(studyId, values);
    added++;
  }
  return { added, columns: madeCols };
}

/** Quote-aware, so a value containing a comma survives the round trip. */
function parseCsv(text) {
  const rows = [];
  let row = [], field = '', quoted = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') quoted = false;
      else field += c;
    } else if (c === '"') quoted = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c !== '\r') field += c;
  }
  if (field || row.length) { row.push(field); rows.push(row); }
  return rows;
}

// The stored journal profile and the review rounds as the store keeps them: the part of lib/manuscript-submission.mjs that store.mjs normalises on every
// load. The submission checks, the declarations and the decision-letter parser stay in lib/manuscript-submission.mjs, which re-exports these.
import { profileById, validateProfile } from './journal-profiles.mjs';
import { newId } from './manuscript.mjs';

export const VARIETIES = ['us', 'uk'];

// ---- the stored journal profile ----------------------------------------------

/**
 * state.journalProfile as this version keeps it: null, or { id, variety,
 * custom, from? }. `from` is 'target' when the profile was set because the
 * target journal names it (lib/journal-context.mjs; a target change may then
 * replace it) and 'manual' when the author chose it; absent in a project saved
 * before it was recorded, which is treated as chosen by hand. `id` is a built-in profile's id, 'custom' for the author's own
 * profile (kept in `custom` whole, also while a generic one is chosen), or
 * null; `variety` is the spelling the consistency check expects ('us', 'uk'
 * or null). A custom profile that no longer validates is kept as the author
 * left it; `activeProfile` then gives null.
 */
export function normalizeJournalProfile(jp) {
  if (!jp || typeof jp !== 'object' || Array.isArray(jp)) return null;
  const custom = jp.custom && typeof jp.custom === 'object' && !Array.isArray(jp.custom) ? { ...jp.custom } : null;
  const id = profileById(jp.id) ? jp.id : jp.id === 'custom' && custom ? 'custom' : null;
  const variety = VARIETIES.includes(jp.variety) ? jp.variety : null;
  // 'target' only describes a profile that is set; a chosen None (id null, from 'manual') keeps the target from setting one
  const from = jp.from === 'manual' || (jp.from === 'target' && id) ? jp.from : null;
  return id || custom || variety || from ? { id, variety, custom, ...(from ? { from } : {}) } : null;
}

/** The profile the checks run against, or null when none is chosen or the custom one is invalid. */
export function activeProfile(jp) {
  const n = normalizeJournalProfile(jp);
  if (!n?.id) return null;
  if (n.id !== 'custom') return profileById(n.id);
  return validateProfile(n.custom).length ? null : n.custom;
}

// ---- review rounds -------------------------------------------------------------

const STATUSES = ['done', 'proposed'];
export function normalizePoint(p) {
  return {
    id: String(p?.id || newId()),
    reviewer: String(p?.reviewer || 'Reviewer 1'),
    n: Number.isInteger(p?.n) ? p.n : 1,
    text: String(p?.text || ''),
    ...(p?.section ? { section: String(p.section) } : {}),
    response: String(p?.response || ''),
    change: String(p?.change || ''),
    location: String(p?.location || ''),
    status: STATUSES.includes(p?.status) ? p.status : 'done',
  };
}

/** state.reviewRounds: [{ id, at, journal, manuscriptId, points }], anything else dropped. */
export function normalizeReviewRounds(rounds) {
  if (!Array.isArray(rounds)) return [];
  return rounds.filter(r => r && typeof r === 'object' && Array.isArray(r.points)).map(r => ({
    id: String(r.id || newId()),
    at: String(r.at || ''),
    journal: String(r.journal || ''),
    manuscriptId: String(r.manuscriptId || ''),
    points: r.points.map(normalizePoint),
  }));
}

// Journal profiles: the limits and requirements a manuscript is checked
// against before submission (lib/submission-checks.mjs).
//
// No named journal's limits are stored here. A journal's instructions for
// authors change without notice, and nothing in this app can verify them, so
// a profile for a named journal is built by the author: typed in
// (`customProfile`) or read from instructions pasted from the journal's site
// (`profileFromText`), with the sentence each value came from kept beside it.
// The generic profiles below are defined by reporting conventions, not by any
// journal: they carry the abstract headings and statements the convention
// asks for, and no word, reference or figure limits, because a convention
// does not set them. `source.checked` is null on every built-in profile: the
// URL names where the convention is published, not a page read on a date.
//
// Pure data and text: nothing here imports the store or a view.

import { blankBlock } from './manuscript.mjs';

export const REFERENCE_STYLES = ['vancouver', 'ama', 'apa', 'harvard', 'nlm'];

/** Statements a journal may require, by key, with the headings they go under. */
export const REQUIREMENTS = [
  { id: 'coi', label: 'Conflicts of interest' },
  { id: 'funding', label: 'Funding' },
  { id: 'dataAvailability', label: 'Data availability' },
  { id: 'ethics', label: 'Ethics approval' },
  { id: 'consent', label: 'Patient consent' },
  { id: 'registration', label: 'Registration' },
  { id: 'credit', label: 'Author contributions' },
  { id: 'orcid', label: 'ORCID iDs' },
];
const REQUIREMENT_IDS = new Set(REQUIREMENTS.map(r => r.id));

// ---- structured abstracts --------------------------------------------------
//
// Each set lists the headings an abstract is written under and, where the
// convention itemises more than it heads, what each heading covers. The
// headings are the ones the convention names; `aliases` are the other names
// journals commonly print for the same part, used when checking an abstract.

export const STRUCTURED_ABSTRACTS = {
  imrad: {
    id: 'imrad', label: 'IMRaD',
    headings: ['Background', 'Methods', 'Results', 'Conclusions'],
    aliases: { Background: ['Introduction', 'Objective', 'Objectives', 'Aim', 'Aims', 'Purpose', 'Context'], Methods: ['Materials and methods', 'Patients and methods', 'Design'], Results: ['Findings'], Conclusions: ['Conclusion', 'Interpretation'] },
    source: { name: 'Common four-heading form', url: null },
  },
  haynes: {
    id: 'haynes', label: 'Eight-heading (Haynes et al. 1990)',
    // The classic 1990 form ("More informative abstracts revisited", Ann Intern
    // Med 1990). Journals that still use it have often adapted it since.
    classic: true,
    headings: ['Objective', 'Design', 'Setting', 'Participants', 'Interventions', 'Measurements', 'Results', 'Conclusion'],
    aliases: { Objective: ['Objectives'], Participants: ['Patients', 'Subjects'], Interventions: ['Intervention'], Measurements: ['Main outcome measures', 'Main outcomes and measures', 'Outcome measures'], Conclusion: ['Conclusions'] },
    source: { name: 'Haynes RB, Mulrow CD, Huth EJ, Altman DG, Gardner MJ. More informative abstracts revisited. Ann Intern Med. 1990', url: null },
  },
  consort: {
    id: 'consort', label: 'CONSORT for Abstracts',
    // CONSORT for Abstracts itemises rather than prescribes headings; these are
    // its groups, with the items each covers.
    headings: ['Trial design', 'Methods', 'Results', 'Conclusions', 'Trial registration', 'Funding'],
    covers: {
      Methods: ['Participants', 'Interventions', 'Objective', 'Outcome', 'Randomisation', 'Blinding'],
      Results: ['Numbers randomised', 'Recruitment', 'Numbers analysed', 'Outcome', 'Harms'],
    },
    aliases: { 'Trial design': ['Design', 'Background'], Conclusions: ['Conclusion', 'Interpretation'], 'Trial registration': ['Registration'] },
    source: { name: 'CONSORT for Abstracts (Hopewell et al. 2008); CONSORT 2025 revised the main checklist, so check the items against the current version', url: 'https://www.equator-network.org/' },
  },
  prisma: {
    id: 'prisma', label: 'PRISMA 2020 for Abstracts',
    headings: ['Background', 'Methods', 'Results', 'Discussion', 'Funding', 'Registration'],
    covers: {
      Background: ['Objectives'],
      Methods: ['Eligibility criteria', 'Information sources', 'Risk of bias', 'Synthesis of results'],
      Results: ['Included studies', 'Synthesis of results'],
      Discussion: ['Limitations of evidence', 'Interpretation'],
    },
    aliases: { Background: ['Objective', 'Objectives', 'Introduction'], Discussion: ['Conclusions', 'Conclusion', 'Interpretation'], Registration: ['Protocol registration', 'Systematic review registration', 'PROSPERO registration'] },
    source: { name: 'PRISMA 2020 for Abstracts (Page et al. 2021)', url: 'https://www.prisma-statement.org/' },
  },
  care: {
    id: 'care', label: 'CARE',
    // CARE item 3: what is unique, the main symptoms and findings, the main
    // diagnoses, interventions and outcomes, and the take-away lesson. The
    // headings match the case report starter in lib/manuscript.mjs.
    headings: ['Introduction', 'Case presentation', 'Conclusions'],
    covers: {
      Introduction: ['What is unique about the case'],
      'Case presentation': ['Main symptoms and clinical findings', 'Main diagnoses, interventions and outcomes'],
      Conclusions: ['The main take-away lesson'],
    },
    aliases: { Introduction: ['Background'], 'Case presentation': ['Case report', 'Case description', 'Case summary'], Conclusions: ['Conclusion'] },
    source: { name: 'CARE guidelines (Gagnier et al. 2013)', url: 'https://www.care-statement.org/' },
  },
};

/** Every name an abstract heading goes by in the sets above, lower-cased, keyed by the heading. */
export function headingNames(heading) {
  const out = new Set([String(heading).toLowerCase()]);
  for (const set of Object.values(STRUCTURED_ABSTRACTS))
    for (const [h, as] of Object.entries(set.aliases || {}))
      if (h.toLowerCase() === String(heading).toLowerCase()) for (const a of as) out.add(a.toLowerCase());
  return [...out];
}

/**
 * The blocks to insert for a profile's structured abstract: an Abstract
 * heading, then a subheading and an empty paragraph per abstract heading.
 * An unstructured abstract is the heading and one paragraph.
 */
export function abstractTemplate(profile, { withHeading = true } = {}) {
  const heads = profile?.abstractStructured && profile.abstractHeadings?.length ? profile.abstractHeadings : [];
  return [
    ...(withHeading ? [blankBlock('h2', 'Abstract')] : []),
    ...(heads.length ? heads.flatMap(h => [blankBlock('h3', h), blankBlock('p', '')]) : [blankBlock('p', '')]),
  ];
}

// ---- profiles --------------------------------------------------------------

const DEFAULT_NOTE = 'Set word, abstract, reference and figure limits from the journal’s instructions for authors.';

/** Profiles defined by reporting conventions, not by a journal. No limits are set. */
export const GENERIC_PROFILES = [
  { id: 'imrad-original', name: 'Original article (IMRaD)', abstractStructured: true, abstractHeadings: [...STRUCTURED_ABSTRACTS.imrad.headings],
    referenceStyle: 'vancouver', requires: ['coi', 'funding', 'ethics', 'dataAvailability', 'credit'],
    notes: `A structured Background, Methods, Results, Conclusions abstract. The statements are those ICMJE recommends disclosing; the reference style is a default. ${DEFAULT_NOTE}`,
    source: { url: 'https://www.icmje.org/recommendations/', checked: null } },
  { id: 'consort-abstract', name: 'Randomised trial (CONSORT abstract)', abstractStructured: true, abstractHeadings: [...STRUCTURED_ABSTRACTS.consort.headings],
    referenceStyle: 'vancouver', requires: ['registration', 'funding', 'coi', 'ethics', 'dataAvailability', 'credit'],
    notes: `Abstract grouped as CONSORT for Abstracts itemises it; CONSORT asks for trial registration and funding. ${DEFAULT_NOTE}`,
    source: { url: STRUCTURED_ABSTRACTS.consort.source.url, checked: null } },
  { id: 'prisma-abstract', name: 'Systematic review (PRISMA 2020 abstract)', abstractStructured: true, abstractHeadings: [...STRUCTURED_ABSTRACTS.prisma.headings],
    referenceStyle: 'vancouver', requires: ['registration', 'funding', 'coi', 'dataAvailability', 'credit'],
    notes: `Abstract as PRISMA 2020 for Abstracts groups it; PRISMA 2020 asks for registration, support, competing interests and data availability. ${DEFAULT_NOTE}`,
    source: { url: STRUCTURED_ABSTRACTS.prisma.source.url, checked: null } },
  { id: 'case-report', name: 'Case report (CARE abstract)', abstractStructured: true, abstractHeadings: [...STRUCTURED_ABSTRACTS.care.headings],
    referenceStyle: 'vancouver', requires: ['consent', 'coi', 'funding', 'credit'],
    notes: `Abstract in the three parts of CARE item 3; CARE asks for the patient’s informed consent. ${DEFAULT_NOTE}`,
    source: { url: STRUCTURED_ABSTRACTS.care.source.url, checked: null } },
  { id: 'letter', name: 'Letter', abstractStructured: false, abstractHeadings: null,
    referenceStyle: 'vancouver', requires: ['coi'],
    notes: `Many journals publish letters without an abstract. ${DEFAULT_NOTE}`,
    source: { url: null, checked: null } },
];

/**
 * Profiles for a named journal, with the limits its instructions for authors
 * state. Empty on purpose: an entry is added only from instructions that were
 * read, with `source: { url, checked }` naming the page and the date (and
 * validateProfile holds it to that). A preset (lib/journal-presets.mjs) may
 * name one by `profile`.
 */
export const JOURNAL_PROFILES = [];

export const profileById = id => GENERIC_PROFILES.find(p => p.id === id) || JOURNAL_PROFILES.find(p => p.id === id) || null;

const slug = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
const LIMITS = ['wordLimit', 'abstractLimit', 'referenceLimit', 'figureTableLimit', 'titleLimitChars', 'runningTitleChars'];
const isCount = v => Number.isInteger(v) && v > 0;
const isDate = v => /^\d{4}-\d{2}-\d{2}$/.test(v) && !Number.isNaN(Date.parse(`${v}T00:00:00Z`)) && new Date(`${v}T00:00:00Z`).toISOString().slice(0, 10) === v;

/** What is wrong with a profile, as sentences; empty when it is valid. */
export function validateProfile(p) {
  const out = [];
  if (!p || typeof p !== 'object') return ['A profile is an object'];
  if (!String(p.id || '').trim()) out.push('A profile needs an id');
  if (!String(p.name || '').trim()) out.push('A profile needs a name');
  for (const k of LIMITS) if (p[k] != null && !isCount(p[k])) out.push(`${k} must be a whole number above zero`);
  if (!REFERENCE_STYLES.includes(p.referenceStyle)) out.push(`referenceStyle must be one of ${REFERENCE_STYLES.join(', ')}`);
  if (typeof p.abstractStructured !== 'boolean') out.push('abstractStructured must be true or false');
  if (p.abstractHeadings != null) {
    if (!Array.isArray(p.abstractHeadings) || p.abstractHeadings.some(h => typeof h !== 'string' || !h.trim())) out.push('abstractHeadings must be a list of headings');
    else if (new Set(p.abstractHeadings.map(h => h.trim().toLowerCase())).size !== p.abstractHeadings.length) out.push('abstractHeadings repeats a heading');
  }
  if (p.abstractStructured && !p.abstractHeadings?.length) out.push('A structured abstract needs its headings');
  if (p.keywords != null) {
    const { min, max } = p.keywords;
    if (min != null && !(Number.isInteger(min) && min >= 0)) out.push('keywords.min must be a whole number');
    if (max != null && !isCount(max)) out.push('keywords.max must be a whole number above zero');
    if (min != null && max != null && min > max) out.push('keywords.min is above keywords.max');
  }
  if (!Array.isArray(p.requires)) out.push('requires must be a list');
  else for (const r of p.requires) if (!REQUIREMENT_IDS.has(r)) out.push(`Unknown requirement '${r}'`);
  if (p.source != null) {
    if (p.source.url != null && !/^https?:\/\/\S+$/.test(p.source.url)) out.push('source.url must be a web address');
    if (p.source.checked != null && !isDate(p.source.checked)) out.push('source.checked must be a date as YYYY-MM-DD');
  }
  return out;
}

/**
 * A profile from the author's own fields, with defaults for what they leave
 * out. Throws with every problem listed (`err.problems`) when it is invalid.
 */
export function customProfile(fields = {}) {
  const f = { ...fields };
  const headings = Array.isArray(f.abstractHeadings) ? f.abstractHeadings.map(h => String(h).trim()).filter(Boolean)
    : typeof f.abstractHeadings === 'string' ? splitHeadings(f.abstractHeadings) : null;
  const p = {
    id: f.id || (f.name ? `custom-${slug(f.name)}` : ''),
    name: String(f.name || '').trim(),
    ...(f.publisher ? { publisher: String(f.publisher).trim() } : {}),
    ...Object.fromEntries(LIMITS.filter(k => f[k] != null && f[k] !== '').map(k => [k, typeof f[k] === 'string' ? Number(f[k].replace(/[,\s]/g, '')) : f[k]])),
    abstractHeadings: headings?.length ? headings : null,
    abstractStructured: f.abstractStructured ?? Boolean(headings?.length),
    referenceStyle: String(f.referenceStyle || 'vancouver').toLowerCase(),
    ...(f.keywords ? { keywords: { min: f.keywords.min ?? null, max: f.keywords.max ?? null } } : {}),
    requires: [...new Set(f.requires || [])],
    notes: String(f.notes || ''),
    source: { url: f.source?.url || null, checked: f.source?.checked || null },
  };
  const problems = validateProfile(p);
  if (problems.length) { const e = new Error(`Invalid journal profile: ${problems.join('; ')}`); e.problems = problems; throw e; }
  return p;
}

// ---- reading instructions for authors --------------------------------------

const SMALL = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12, thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17, eighteen: 18, nineteen: 19, twenty: 20, thirty: 30, forty: 40, fifty: 50, sixty: 60, seventy: 70, eighty: 80, ninety: 90 };
const NUM = String.raw`(\d{1,3}(?:[,   ]\d{3})+|\d+|(?:${Object.keys(SMALL).join('|')})(?:[- ](?:one|two|three|four|five|six|seven|eight|nine))?)`;
function toNumber(s) {
  const t = String(s).toLowerCase().trim();
  if (/^\d/.test(t)) return Number(t.replace(/[,   ]/g, ''));
  const [a, b] = t.split(/[- ]/);
  return (SMALL[a] || 0) + (SMALL[b] || 0) || null;
}
// "not exceed", "no more than", "a maximum of", "up to", "limited to", "at most", "should be under"
const CAP = String.raw`(?:(?:should|must|may|shall|will|cannot|can)\s+not\s+exceed|not\s+(?:to\s+)?exceed(?:ing)?|do(?:es)?\s+not\s+exceed|no\s+(?:more|longer)\s+than|not\s+more\s+than|(?:a\s+|the\s+)?max(?:imum|\.)?(?:\s+(?:length|of))*|up\s+to|limited\s+to|(?:is\s+)?limit(?:ed)?\s+(?:of|to)|at\s+most|fewer\s+than|less\s+than|under|within)`;

/** Split pasted text into sentences, keeping "e.g." and decimal points whole. */
export function sentencesOf(text) {
  return String(text || '').replace(/\r/g, '').split(/\n\s*\n|\n(?=\s*[-•*\d]+[.)]?\s)|(?<!\b(?:e\.g|i\.e|approx|incl|max|min|no|vs|Fig|etc)\.)(?<=[.!?])\s+(?=[A-Z(“"])/)
    .map(s => s.replace(/\s+/g, ' ').trim()).filter(Boolean);
}

function splitHeadings(list) {
  return String(list).replace(/[“”"']/g, '').replace(/\.$/, '')
    .split(/\s*(?:,|;|\band\b|•)\s*/i).map(s => s.replace(/^(?:and|or)\s+/i, '').replace(/^[:\s(]+|[)\s]+$/g, '').trim()).filter(s => s && s.length <= 40)
    .map(s => s[0].toUpperCase() + s.slice(1));
}

const EXCLUDING = /\b(?:exclud\w*|not\s+includ\w*|without|except|apart\s+from|besides)\b/i;

/** Which counted thing a number-with-unit belongs to, from the words around it. */
function subjectOf(before, after, unit) {
  const clause = before.split(/[;:]|,\s|\.\s|\b(?:and|while|whereas|with)\s+(?=an?\s|the\s)/i).pop();
  const near = clause.slice(-80);
  const mentions = (re) => { const m = near.match(re); if (!m) return false; const pre = near.slice(0, m.index).split(/\s+/).slice(-3).join(' '); return !EXCLUDING.test(pre); };
  if (unit === 'char') {
    if (/\b(running|short)\s+(title|head)|\brunning\s+head/i.test(near) || /^\s*(?:\(?including spaces\)?\s*)?(?:for\s+the\s+)?(?:running|short)\s+(?:title|head)/i.test(after)) return 'runningTitleChars';
    if (/\btitle\b/i.test(near) || /^\s*(?:\(?including spaces\)?\s*)?(?:for\s+the\s+)?title/i.test(after)) return 'titleLimitChars';
    return null;
  }
  if (/^\s*(?:\)|\s)?(?:structured\s+|unstructured\s+)?(abstract|summary)\b/i.test(after)) return 'abstractLimit';
  if (mentions(/\b(abstract|summary)\b/i)) return 'abstractLimit';
  // "Abstract: unstructured, maximum 200 words" names its subject as a label
  if (/^\s*(?:the\s+)?(abstract|summary)\s*[:\u2013\u2014-]/i.test(before) && !/\b(manuscript|main\s+text|text|article|paper|body)\b/i.test(near)) return 'abstractLimit';
  // "The abstract must be structured ..., and no more than 250 words": the
  // clause names nothing counted, so the sentence's subject is what is limited
  if (/^\s*(?:the\s+|an?\s+|your\s+)?(?:structured\s+|unstructured\s+)?(abstract|summary)\b/i.test(before)
    && !/\b(abstract|summary|title|manuscript|main\s+text|text|article|paper|body|word\s+count)\b/i.test(clause)) return 'abstractLimit';
  if (mentions(/\b(title)\b/i) && !/\b(manuscript|text|article|paper)\b/i.test(near)) return null;
  return 'wordLimit';
}

/**
 * Limits and requirements read from pasted instructions for authors.
 * Returns `{ profile, evidence, conflicts }`: a partial profile, the sentence
 * each value came from (`[{ field, value, sentence }]`), and the fields for
 * which the text gave more than one value (instructions often list several
 * article types). The first value found is used; the author confirms.
 */
export function profileFromText(text) {
  const evidence = [];
  const add = (field, value, sentence) => { if (value != null && !evidence.some(e => e.field === field && JSON.stringify(e.value) === JSON.stringify(value) && e.sentence === sentence)) evidence.push({ field, value, sentence }); };
  for (const s of sentencesOf(text)) {
    // words and characters: find each "N words" and decide what it limits
    for (const m of s.matchAll(new RegExp(String.raw`${NUM}(?:\s*|-)(words?|characters?|chars?)\b`, 'gi'))) {
      const n = toNumber(m[1]); if (!n) continue;
      const before = s.slice(0, m.index), after = s.slice(m.index + m[0].length);
      const unit = /^char/i.test(m[2]) ? 'char' : 'word';
      // a number must be stated as a limit ("up to", "no more than", "N-word limit", "maximum")
      const capped = new RegExp(`${CAP}\\s*(?:of\\s+|about\\s+|\\(\\s*)?$`, 'i').test(before)
        || /^\s*(?:or\s+(?:less|fewer)|\(?\s*max(?:imum)?\b|limit)/i.test(after)
        || /^-?\s*words?\s+(?:limit|maximum)/i.test(m[0].slice(m[1].length) + after)
        || /^-words?$/i.test(m[0].slice(m[1].length)) && /^\s*(?:structured\s+|unstructured\s+)?(?:abstract|summary)\b/i.test(after)
        || /\b(?:limit|maximum|length)\b[^.]{0,25}$/i.test(before);
      if (!capped || /\b(at\s+least|minimum\s+of|min\.)\s*$/i.test(before)) continue;
      const field = subjectOf(before, after, unit);
      if (field) add(field, n, s);
    }
    // references
    for (const m of s.matchAll(new RegExp(String.raw`${NUM}\s+(?:references|citations|refs\b)`, 'gi'))) {
      const n = toNumber(m[1]); const before = s.slice(0, m.index);
      if (n && (new RegExp(`${CAP}\\s*$`, 'i').test(before) || /^\s*(?:or\s+fewer|max)/i.test(s.slice(m.index + m[0].length)))) add('referenceLimit', n, s);
    }
    const refCap = s.match(new RegExp(String.raw`\b(?:references?|reference\s+list|citations)\b[^.]{0,40}?${CAP}\s*${NUM}(?!\s*(?:words?|characters?|figures?|tables?))`, 'i'));
    if (refCap) add('referenceLimit', toNumber(refCap[1]), s);
    // figures and tables, together
    const ft = s.match(new RegExp(String.raw`${CAP}\s*(?:a\s+(?:total|combined\s+total)\s+of\s+)?${NUM}\s+(?:(?:figures?|illustrations?)\s*(?:and\/or|and|\/|or|plus|\+)\s*tables?|tables?\s*(?:and\/or|and|\/|or|plus|\+)\s*(?:figures?|illustrations?)|display\s+items|figures?\s+(?:or|and)\s+tables?\s+combined)`, 'i'))
      || s.match(new RegExp(String.raw`\b(?:figures?\s*(?:and\/or|and|\/|or)\s*tables?|tables?\s*(?:and\/or|and|\/|or)\s*figures?|display\s+items)\b[^.]{0,30}?${CAP}\s*${NUM}`, 'i'));
    if (ft) add('figureTableLimit', toNumber(ft[1]), s);
    // keywords: "3 to 6 keywords", "between 3 and 6 key words", "up to 6 keywords"
    const kr = s.match(new RegExp(String.raw`(?:between\s+)?${NUM}\s*(?:to|-|–|and)\s*${NUM}\s+key\s?words?`, 'i'));
    if (kr) add('keywords', { min: toNumber(kr[1]), max: toNumber(kr[2]) }, s);
    else {
      const kmax = s.match(new RegExp(String.raw`${CAP}\s*${NUM}\s+key\s?words?`, 'i')) || s.match(new RegExp(String.raw`key\s?words?[^.]{0,30}?${CAP}\s*${NUM}`, 'i'));
      if (kmax) add('keywords', { min: null, max: toNumber(kmax[1]) }, s);
      const kmin = s.match(new RegExp(String.raw`(?:at\s+least|a\s+minimum\s+of)\s*${NUM}\s+key\s?words?`, 'i'));
      if (kmin) add('keywords', { min: toNumber(kmin[1]), max: null }, s);
    }
    // abstract form
    if (/\bunstructured\s+abstract|\babstract\b[^.]{0,20}\bunstructured\b|\babstract\b[^.]{0,40}\bshould\s+not\s+be\s+structured|\bnon-structured\s+abstract/i.test(s)) add('abstractStructured', false, s);
    else if (/\bstructured\s+(?:abstract|summary)|\babstract\b[^.]{0,40}\bstructured\b/i.test(s)) add('abstractStructured', true, s);
    const hl = s.match(/\b(?:sub)?headings?\s*(?:of|:|as\s+follows:?|such\s+as|including)?\s*[:(]?\s*((?:[“"']?[A-Z][A-Za-z/ -]{1,38}[”"']?\s*(?:,|;|\band\b|•)\s*){2,}[“"']?[A-Z][A-Za-z/ -]{1,38}[”"']?)/)
      || (/\bstructured\s+(?:abstract|summary)/i.test(s) && s.match(/\bstructured\s+(?:abstract|summary)[^(]{0,30}\(\s*([^)]+)\)/i));
    if (hl) { const heads = splitHeadings(hl[1]); if (heads.length >= 2) add('abstractHeadings', heads, s); }
    // reference style, named
    const style = s.match(/\b(Vancouver|AMA|American Medical Association|APA|American Psychological Association|Harvard|NLM|National Library of Medicine)\b[^.]{0,40}\b(?:style|format|system|manual)|\b(?:style|format)\b[^.]{0,30}\b(Vancouver|AMA|APA|Harvard|NLM)\b/i);
    if (style && /\breferenc|\bcitation|\bbibliograph/i.test(s)) {
      const name = (style[1] || style[2]).toLowerCase();
      add('referenceStyle', name.startsWith('american medical') ? 'ama' : name.startsWith('american psych') ? 'apa' : name.startsWith('national library') ? 'nlm' : name, s);
    }
    // statements the instructions mention
    const req = [
      ['coi', /\b(conflicts?\s+of\s+interests?|competing\s+interests?|declarations?\s+of\s+interests?|ICMJE\s+disclosure)/i],
      ['funding', /\b(funding|financial\s+support|sources?\s+of\s+support)\b/i],
      ['dataAvailability', /\b(data\s+availability|data\s+sharing|availability\s+of\s+data)\b/i],
      ['ethics', /\b(ethics\s+(?:committee|approval|statement)|ethical\s+approval|institutional\s+review\s+board|\bIRB\b|research\s+ethics)/i],
      ['consent', /\b(informed\s+consent|patient\s+consent|consent\s+(?:for|to)\s+publication)\b/i],
      ['registration', /\b(trial\s+registration|registered\s+in\s+a\s+(?:public\s+)?(?:trial\s+)?registry|prospectively\s+registered|registration\s+number|PROSPERO)\b/i],
      ['credit', /\b(CRediT|author(?:s'|s)?\s+contributions?|contributorship)\b/i],
      ['orcid', /\bORCID\b/i],
    ];
    for (const [id, re] of req) if (re.test(s)) add(`requires:${id}`, true, s);
  }
  const conflicts = [];
  const profile = {};
  for (const e of evidence) {
    if (e.field.startsWith('requires:')) { (profile.requires ||= []).includes(e.field.slice(9)) || profile.requires.push(e.field.slice(9)); continue; }
    if (!(e.field in profile)) profile[e.field] = e.value;
    else if (JSON.stringify(profile[e.field]) !== JSON.stringify(e.value) && !conflicts.includes(e.field)) conflicts.push(e.field);
  }
  if (profile.abstractHeadings && profile.abstractStructured == null) profile.abstractStructured = true;
  return { profile, evidence, conflicts };
}

// The project journal: dated entries, one a day unless several are allowed,
// listed by ISO week (amendment "Workspace: backup, dashboard, tasks,
// timeline and translation").
//
//   state.journal       [{ id, date, text, at, updated }]
//   state.journalMany   true when a day may hold more than one entry
//
// Kept in the project itself, so a project in the app's storage and one in a
// folder keep it alike and a backup carries it. Pure.

const DAY = /^\d{4}-\d{2}-\d{2}$/;
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const utc = iso => new Date(`${iso}T00:00:00Z`);
const iso = d => d.toISOString().slice(0, 10);

/** ISO 8601 week of a day: `{ year, week, key: '2026-W40' }` (weeks start Monday; week 1 holds the first Thursday). */
export function isoWeek(date) {
  const d = utc(date);
  const dow = (d.getUTCDay() + 6) % 7;             // Monday 0
  d.setUTCDate(d.getUTCDate() - dow + 3);           // the Thursday of this week
  const year = d.getUTCFullYear();
  const first = new Date(Date.UTC(year, 0, 4));
  const week = 1 + Math.round(((d - first) / 864e5 - 3 + ((first.getUTCDay() + 6) % 7)) / 7);
  return { year, week, key: `${year}-W${String(week).padStart(2, '0')}` };
}

/** The Monday and Sunday of the week a day falls in. */
export function weekBounds(date) {
  const d = utc(date), dow = (d.getUTCDay() + 6) % 7;
  const from = new Date(d); from.setUTCDate(d.getUTCDate() - dow);
  const to = new Date(from); to.setUTCDate(from.getUTCDate() + 6);
  return { from: iso(from), to: iso(to) };
}

const short = (x, year) => { const d = utc(x); return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}${year ? ` ${d.getUTCFullYear()}` : ''}`; };
/** "Week 40 · 28 Sep – 4 Oct 2026". */
export function weekLabel(date) {
  const { week } = isoWeek(date), { from, to } = weekBounds(date);
  return `Week ${week} · ${short(from, from.slice(0, 4) !== to.slice(0, 4))} – ${short(to, true)}`;
}

export function normaliseJournal(list) {
  return (Array.isArray(list) ? list : []).filter(e => e && typeof e === 'object' && DAY.test(String(e.date || '')) && typeof e.text === 'string')
    .map(e => ({ id: String(e.id || `j${e.date}`), date: e.date, text: e.text, at: String(e.at || ''), updated: String(e.updated || e.at || '') }));
}

/**
 * The entry to write in for a day: that day's existing entry, unless several
 * a day are allowed or none exists, when a new one is added. Mutates
 * `state.journal`; answers `{ entry, created }`. Opening the same day twice
 * never makes a second entry by default.
 */
export function entryFor(state, date, { many = Boolean(state.journalMany), text = '', now = new Date() } = {}) {
  if (!DAY.test(String(date))) throw new Error('A journal entry needs a date');
  if (!Array.isArray(state.journal)) state.journal = [];
  if (!many) {
    const found = state.journal.find(e => e && e.date === date);
    if (found) return { entry: found, created: false };
  }
  const at = now.toISOString();
  const entry = { id: `j${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, date, text, at, updated: at };
  state.journal.push(entry);
  return { entry, created: true };
}

/** Entries grouped by ISO week, newest week first; within a week newest day first. */
export function byWeek(list) {
  const groups = new Map();
  for (const e of normaliseJournal(list)) {
    const k = isoWeek(e.date).key;
    if (!groups.has(k)) groups.set(k, { key: k, label: weekLabel(e.date), entries: [] });
    groups.get(k).entries.push(e);
  }
  return [...groups.values()].sort((a, b) => b.key.localeCompare(a.key))
    .map(g => ({ ...g, entries: g.entries.sort((a, b) => b.date.localeCompare(a.date) || b.at.localeCompare(a.at)) }));
}

// The manuscript document: blocks, citations, and linked results.
//
// Plan J1 specifies Tiptap/ProseMirror. Measured, a Tiptap editor is 42 npm
// packages and 8.0 MiB unpacked, for what J1 itself scopes as "selection-based
// suggestions, not a full word-processor clone". What this module actually
// needs is a block list with stable ids, two inline node types, and a content
// hash per block — so it is built here, the same trade §4.6 makes for the
// PRISMA diagram. See §4.11.
//
// The document is plain text per block. Citations and results are inline tokens
// in that text, so the document is its own export format and nothing is lost in
// a round trip:
//
//   [@paperId]            a citation, resolved against the library
//   [@paperId p. 4]       with a locator
//   {{result.key}}        a value from a saved analysis
//
// A block's hash covers its text. A suggestion or a review note records the
// hash it was made against; when the text changes the hash changes and anything
// anchored to it is stale rather than silently applied to different words
// (plan J5).

import { parseMarkdown, toMarkdown as mdOut } from './markdown.mjs';

export const BLOCK_TYPES = [
  { id: 'h1', label: 'Title' },
  { id: 'h2', label: 'Heading' },
  { id: 'h3', label: 'Subheading' },
  { id: 'p', label: 'Paragraph' },
  { id: 'quote', label: 'Quote' },
];

// IMRaD, which is the shape of the paper this tool exists to write.
export const STARTER = [
  { type: 'h1', text: '' },
  { type: 'h2', text: 'Abstract' },
  { type: 'p', text: '' },
  { type: 'h2', text: 'Introduction' },
  { type: 'p', text: '' },
  { type: 'h2', text: 'Methods' },
  { type: 'p', text: '' },
  { type: 'h2', text: 'Results' },
  { type: 'p', text: '' },
  { type: 'h2', text: 'Discussion' },
  { type: 'p', text: '' },
];

let seq = 0;
export const newId = () => `b${Date.now().toString(36)}${(seq++).toString(36)}${
  Math.random().toString(36).slice(2, 5)}`;

export const blankBlock = (type = 'p', text = '') => ({ id: newId(), type, text });

// A case report follows CARE (lib/checklist.mjs): the title names it, the
// abstract has its three parts, and the case is presented in CARE order.
export const CASE_REPORT_STARTER = [
