  { type: 'h2', text: 'Informed consent' }, { type: 'p', text: '' },
];

/** A new document in the shape of the project's paper: IMRaD, or a CARE case report. */
// `title` fills the empty title line: a new manuscript starts under the project's working title, not a blank heading
export const starterDocument = (type = '', title = '') => (type === 'case-report' ? CASE_REPORT_STARTER : STARTER).map((b, i) => blankBlock(b.type, i === 0 && b.type === 'h1' && !b.text ? String(title || '').trim() : b.text));

// Word imports often use a body style for section labels. Recognize only
// standalone, conventional labels so prose such as "Results: We found..."
// cannot become a heading by accident. The Word style and runs stay intact.
const SECTION_LABEL = /^(?:(?:\d+(?:\.\d+)*[.)]?|[IVX]+[.)])\s+)?(?:abstract|summary|keywords?|introduction|background|aims?|objectives?|patients? and methods|materials? and methods|methods?|study design|results?|findings|discussion|conclusions?|limitations?|references|bibliography|acknowledg(?:e)?ments?|funding|ethics(?: approval)?|conflicts? of interest|author contributions?|figure legends?|supplementary (?:materials?|information|methods?))$/i;
export function recognizedSection(text) {
  const label = String(text || '').trim().replace(/\s+/g, ' ');
  return label.length <= 80 && SECTION_LABEL.test(label) ? label : null;
}

export function recognizeSections(blocks) {
  let changed = false;
  for (const b of blocks || []) {
    if (b.type !== 'p' || !recognizedSection(b.text)) continue;
    b.type = 'h2';
    b.semanticHeading = true;
    changed = true;
  }
  return changed;
}

/**
 * A stable 32-bit hash of a block's text.
 *
 * Not a cryptographic digest: its job is to notice that text changed between
 * when a suggestion was made and when it would be applied. FNV-1a over UTF-16
 * code units is enough for that and needs no async crypto call on every
 * keystroke.
 */
export function hashText(text) {
  let h = 0x811c9dc5;
  const s = String(text ?? '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(36);
}

// ---- inline tokens --------------------------------------------------------

// A record key can be `doi-10.1002/ccr3.73436`, so the key runs to the first
// space or bracket rather than to a fixed character class — a DOI suffix may
// contain almost anything.
const CITE = /\[@([^\s\]]+)((?:\s+[^\]]*)?)\]/g;
const RESULT = /\{\{([A-Za-z0-9._:-]+)\}\}/g;

/** Every citation in a block, with its locator and character range. */
export function citations(text) {
  const out = [];
  CITE.lastIndex = 0;
  for (const m of String(text ?? '').matchAll(CITE))
    out.push({ key: m[1], locator: (m[2] || '').trim(), start: m.index, end: m.index + m[0].length });
  return out;
}

/** Every linked result in a block. */
export function resultTokens(text) {
  const out = [];
  RESULT.lastIndex = 0;
  for (const m of String(text ?? '').matchAll(RESULT))
    out.push({ key: m[1], start: m.index, end: m.index + m[0].length });
  return out;
}

export const citeToken = (id, locator = '') =>
  `[@${id}${locator ? ` ${locator}` : ''}]`;
export const resultToken = key => `{{${key}}}`;

/**
 * Split a block's text into runs for rendering.
 * Returns plain text runs and resolved token runs; nothing here produces HTML,
 * so escaping stays the caller's job and cannot be forgotten by accident.
 */
export function runs(text) {
  const marks = [
    ...citations(text).map(c => ({ ...c, kind: 'cite' })),
    ...resultTokens(text).map(r => ({ ...r, kind: 'result' })),
  ].sort((a, b) => a.start - b.start);

  const out = [];
  let at = 0;
  for (const m of marks) {
    if (m.start > at) out.push({ kind: 'text', text: text.slice(at, m.start) });
    out.push(m);
    at = m.end;
  }
  if (at < text.length) out.push({ kind: 'text', text: text.slice(at) });
  return out;
}

// ---- document-level -------------------------------------------------------

export const wordCount = text =>
  String(text ?? '').replace(CITE, ' ').replace(RESULT, ' ')
    .split(/\s+/).filter(Boolean).length;

/** Sections, in order: a heading and the blocks under it. */
export function sections(blocks) {
  const out = [];
  let cur = { heading: null, blocks: [] };
  for (const b of blocks) {
    if (b.type === 'h2') {
      if (cur.heading || cur.blocks.length) out.push(cur);
      cur = { heading: b, blocks: [] };
    } else cur.blocks.push(b);
  }
  if (cur.heading || cur.blocks.length) out.push(cur);
  return out;
}

// ---- Markdown -------------------------------------------------------------
// Reading and writing live in lib/markdown.mjs (headings, emphasis, lists,
// tables, quotes, code); these keep the older names for their callers.

const PREFIX = { h1: '# ', h2: '## ', h3: '### ', quote: '> ', p: '' };

/** The document as Markdown, tokens intact, so a round trip loses nothing. */
export function toMarkdown(blocks, opts = {}) {
  return mdOut(blocks, opts);
}

/** Markdown as blocks only; `parseMarkdown` also gives the list definitions the blocks use. */
export function fromMarkdown(text) {
  return parseMarkdown(text).blocks;
}

/**
 * Citation numbers by first appearance, which is what a numbered (Vancouver)
 * style means: the first work cited is 1, wherever it is cited again. Runs
 * are authoritative when present; table cells follow their displayed row
 * order. A used note is visited at its first body anchor, not by storage order.
 * Header/footer-only works follow the body in section-definition order, so
 * pagination and repeated running headers cannot change body numbering.
 * Editing the document renumbers the next render — nothing is stored.
 */
export function citationContext(blocks, { notes = {}, section = null } = {}) {
  const map = new Map(), usedNotes = new Set();
  const add = key => { if (!map.has(key)) map.set(key, map.size + 1); };
  const visitText = (text, noteAnchors) => {
    const marks = citations(text).map(c => ({ at: c.start, key: c.key }));
    if (noteAnchors) for (const m of String(text ?? '').matchAll(/\{\{fn:([A-Za-z0-9._-]+)\}\}/g)) marks.push({ at: m.index, note: m[1] });
    marks.sort((a, b) => a.at - b.at);
    for (const mark of marks) {
      if (mark.key != null) add(mark.key);
      else if (notes[mark.note] && !usedNotes.has(mark.note)) {
        usedNotes.add(mark.note);
        // Word does not support nested notes; only body-anchored notes are exported.
        visitContent(notes[mark.note], false);
      }
    }
  };
  const visitContent = (content, noteAnchors) => {
    if (content.runs?.length) for (const run of content.runs) {
      if (run.del) continue;
      if (run.cite) run.cite.forEach(add);
      else visitText(run.t, noteAnchors);
    }
    else visitText(content.text, noteAnchors);
  };
  const visitBlock = (block, noteAnchors) => {
    if (['figure', 'toc', 'bib'].includes(block.type)) return;
    if (block.type === 'table' && block.grid) for (const row of block.grid.rows || []) for (const cell of row.cells || []) {
      if (!row.del && !cell.cellDel && !cell.merged) visitContent(cell, noteAnchors);
    }
    else if (block.type === 'table' && Array.isArray(block.rows)) for (const row of block.rows) for (const cell of row) visitText(String(cell ?? ''), noteAnchors);
    else visitContent(block, noteAnchors);
  };
  for (const block of blocks || []) visitBlock(block, true);
  for (const sec of [...(blocks || []).filter(b => b.props?.section).map(b => b.props.section), section || {}]) {
    for (const kind of ['header', 'footer']) for (const suffix of ['', 'First', 'Even']) {
      const part = sec?.[kind + suffix];
      if (!part) continue;
      if (part.blocks?.length) part.blocks.forEach(b => visitBlock(b, false));
      else visitText(part.text, false);
    }
  }
  return { numbers: map, usedNotes: [...usedNotes].map(id => ({ id, note: notes[id] })) };
}

/** Citation numbers only; older block-only callers retain the same signature. */
export const numbering = (blocks, options = {}) => citationContext(blocks, options).numbers;

/** "1,2,3,5" as "1–3,5". */
export function compactNumbers(nums) {
  const a = [...new Set(nums)].sort((x, y) => x - y);
  const out = [];
  for (let i = 0; i < a.length; i++) {
    let j = i;
    while (j + 1 < a.length && a[j + 1] === a[j] + 1) j++;
    out.push(j - i >= 2 ? `${a[i]}\u2013${a[j]}` : a.slice(i, j + 1).join(','));
    i = j;
  }
  return out.join(',');
}

/**
 * The document with every token replaced by its current text, for an export
 * that is read rather than edited.
 *
 * Adjacent citations are one group: "[@a][@b]" renders as "[1,2]", not
 * "[1][2]". `cite` is called once per group with all its citations. An unresolved token is left visible instead
 * of being dropped: a reader must be able to see that something is missing
 * (plan J2 — an unresolved reference is a search lead, not bibliography).
 */
export function render(blocks, { cite, result }) {
  return blocks.map(b => `${PREFIX[b.type] ?? ''}${renderText(b.text, { cite, result })}`).join('\n\n').trim() + '\n';
}

/** One block's text with its tokens replaced, as `render` does for a document. */
export function renderText(text, { cite, result }) {
  const rs = runs(text);
  let out = '';
  for (let i = 0; i < rs.length; i++) {
    const r = rs[i];
    if (r.kind === 'text') { out += r.text; continue; }
    if (r.kind === 'result') { out += result(r) ?? `{{${r.key}?}}`; continue; }
    const group = [r];
    while (i + 1 < rs.length) {
      const nx = rs[i + 1], gap = rs[i + 2];
      if (nx.kind === 'cite') { group.push(nx); i++; continue; }
      if (nx.kind === 'text' && !nx.text.trim() && gap?.kind === 'cite') { group.push(gap); i += 2; continue; }
      break;
    }
    out += cite(group) ?? group.map(c => `[@${c.key}?]`).join('');
  }
  return out;
}

// Markdown in and out of the manuscript (document formats amendment of
// 2026-09-29). Reading keeps the structure a Word document would: headings,
// paragraphs with bold, italic, strikethrough, code, super- and subscript,
// block quotes, bulleted, numbered and task lists with nesting, fenced code,
// pipe tables with a header row, and the app's own citation ([@key]) and result
// ({{key}}) tokens untouched. Writing is the inverse, so a manuscript that came
// from Word leaves as Markdown with its lists and tables intact.
//
// Blocks are the manuscript's (lib/manuscript.mjs): { id, type, text, runs?,
// props?, grid? }, and lists the numbering definitions the page renderer and
// the Word writer read (lib/pages.mjs, lib/docx-write-doc.mjs).

let seq = 0;
const newId = () => `b${Date.now().toString(36)}${(seq++).toString(36)}${Math.random().toString(36).slice(2, 5)}`;
const CODE_FONT = 'Courier New';

/** The list definitions Markdown lists use: one bulleted, one numbered, nine levels each. */
export const MD_LISTS = {
  'md-bullet': { levels: Array.from({ length: 9 }, (_, i) => ({ fmt: 'bullet', text: ['•', '◦', '▪'][i % 3], start: 1, indLeft: 36 * (i + 1), indHanging: 18 })) },
  'md-number': { levels: Array.from({ length: 9 }, (_, i) => ({ fmt: ['decimal', 'lowerLetter', 'lowerRoman'][i % 3], text: `%${i + 1}.`, start: 1, indLeft: 36 * (i + 1), indHanging: 18 })) },
};

// ---- inline ------------------------------------------------------------------
// Tokens the manuscript owns are lifted out first so their brackets and braces
// never read as links or emphasis; code spans next, for the same reason.
const TOKEN = /\[@[^\]]+\]|\{\{[^}]+\}\}/g;
const MARKS = [
  [/\*\*(?=\S)([\s\S]*?\S)\*\*/, { b: true }], [/__(?=\S)([\s\S]*?\S)__/, { b: true }],
  [/~~(?=\S)([\s\S]*?\S)~~/, { strike: true }],
  [/(?<![\w*])\*(?![\s*])([^*]*?[^\s*])\*(?![\w*])/, { i: true }], [/(?<![\w_])_(?![\s_])([^_]*?[^\s_])_(?![\w_])/, { i: true }],
  [/\^(?=\S)([^^\s]*?\S)\^/, { sup: true }], [/~(?=\S)([^~\s]*?\S)~/, { sub: true }],
];

/** Runs `[{ t, b?, i?, strike?, sup?, sub?, font? }]` for a line of Markdown; plain text stays one run. */
export function inlineRuns(text, base = {}) {
  const out = [];
  const push = (t, fmt) => { if (!t) return; const last = out.at(-1); const f = { ...base, ...fmt }; if (last && same(last, f)) last.t += t; else out.push({ t, ...f }); };
  const parts = String(text).split(/(`[^`\n]+`|\[@[^\]]+\]|\{\{[^}]+\}\})/g);
  for (const part of parts) {
    if (!part) continue;
    if (part.startsWith('`') && part.endsWith('`') && part.length > 2) { push(part.slice(1, -1), { font: CODE_FONT }); continue; }
    if (TOKEN.test(part) && part.match(TOKEN)?.[0] === part) { push(part, {}); continue; }
    // an escaped character is hidden from the marker search and restored in the run
    emphasis(part.replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/\[([^\]]+)\]\((?:[^()\s]|\([^()]*\))+\)/g, '$1').replace(/\\([\\`*_{}[\]()#+\-.!~^])/g, (_, c) => String.fromCharCode(0xE000 + c.charCodeAt(0))), {}, (t, fmt) => push(t.replace(/[\uE000-\uE0FF]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xE000)), fmt));
  }
  return out.length ? out : [{ t: '', ...base }];
}
const same = (a, f) => ['b', 'i', 'strike', 'sup', 'sub', 'font', 'u'].every(k => (a[k] ?? undefined) === (f[k] ?? undefined));
function emphasis(text, fmt, push) {
  let best = null;
  for (const [re, add] of MARKS) { const m = re.exec(text); if (m && (!best || m.index < best.m.index)) best = { m, add }; }
  if (!best) { push(text, fmt); return; }
  const { m, add } = best;
  push(text.slice(0, m.index), fmt);
  emphasis(m[1], { ...fmt, ...add }, push);
  emphasis(text.slice(m.index + m[0].length), fmt, push);
}
const plain = runs => runs.map(r => r.t).join('');

// ---- blocks ------------------------------------------------------------------
const block = (type, runs, extra = {}) => {
  const formatted = runs.some(r => r.b || r.i || r.strike || r.sup || r.sub || r.font || r.u);
  return { id: newId(), type, text: plain(runs), ...(formatted ? { runs } : {}), ...extra };
};
const isTableRow = l => /^\s*\|.*\|\s*$/.test(l);
const isDelimiter = l => /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/.test(l);
const cellsOf = l => { const inner = l.trim().replace(/^\|/, '').replace(/\|$/, ''); const out = []; let cur = ''; for (let i = 0; i < inner.length; i++) { const c = inner[i]; if (c === '\\' && inner[i + 1] === '|') { cur += '|'; i++; } else if (c === '|') { out.push(cur.trim()); cur = ''; } else cur += c; } out.push(cur.trim()); return out; };
const LIST = /^(\s*)([-*+]|\d{1,3}[.)])\s+(\[[ xX]\]\s+)?(.*)$/;

/**
 * Markdown as manuscript blocks and the list definitions they use.
 * `{ blocks, lists }`.
 */
export function parseMarkdown(text) {
  const lines = String(text ?? '').replace(/\r\n?/g, '\n').split('\n');
  const blocks = [];
  let usedLists = false;
  let i = 0;
  const para = [];
  const flushPara = () => { if (!para.length) return; blocks.push(block('p', inlineRuns(para.join(' ').replace(/\s{2,}$/, '')))); para.length = 0; };
  while (i < lines.length) {
    const line = lines[i];
    // fenced code
    let m = /^\s*(`{3,}|~{3,})\s*\w*\s*$/.exec(line);
    if (m) {
      flushPara();
      const fence = m[1][0]; const body = [];
      i++;
      while (i < lines.length && !new RegExp(`^\\s*${fence}{3,}\\s*$`).test(lines[i])) body.push(lines[i++]);
      i++;
      blocks.push(block('p', [{ t: body.join('\n'), font: CODE_FONT }]));
      continue;
    }
    // headings
    m = /^(#{1,6})\s+(.*?)\s*#*\s*$/.exec(line);
    if (m) { flushPara(); blocks.push(block(['h1', 'h2', 'h3'][Math.min(2, m[1].length - 1)], inlineRuns(m[2]))); i++; continue; }
    if (para.length && /^\s*(=+|-+)\s*$/.test(line) && !isTableRow(para.at(-1))) {
      const t = para.join(' '); para.length = 0;
      blocks.push(block(line.trim()[0] === '=' ? 'h1' : 'h2', inlineRuns(t))); i++; continue;
    }
    // rules and blank lines
    if (/^\s*([-*_]\s*){3,}$/.test(line) || !line.trim()) { flushPara(); i++; continue; }
    // block quote
    if (/^\s*>/.test(line)) {
      flushPara(); const q = [];
      while (i < lines.length && /^\s*>/.test(lines[i])) q.push(lines[i++].replace(/^\s*>\s?/, ''));
      blocks.push(block('quote', inlineRuns(q.join(' ')))); continue;
    }
    // tables
    if (isTableRow(line) && i + 1 < lines.length && isDelimiter(lines[i + 1])) {
      flushPara();
      const header = cellsOf(line); i += 2;
      const rows = [];
      while (i < lines.length && isTableRow(lines[i])) rows.push(cellsOf(lines[i++]));
      const cols = Math.max(header.length, ...rows.map(r => r.length));
      const cell = t => { const runs = inlineRuns(t || ''); return { runs, text: plain(runs) }; };
      const grid = { cols: Array(cols).fill(Math.round(468 / cols)), borders: 'all',
        rows: [{ header: true, cells: Array.from({ length: cols }, (_, c) => cell(header[c])) }, ...rows.map(r => ({ cells: Array.from({ length: cols }, (_, c) => cell(r[c])) }))] };
      blocks.push({ id: newId(), type: 'table', styleId: 'Table', grid, text: grid.rows.map(r => r.cells.map(c => c.text).join('\t')).join('\n') });
      continue;
    }
    // lists, nested by indentation; an item's continuation lines are indented under it
    m = LIST.exec(line);
    if (m) {
      flushPara(); usedLists = true;
      while (i < lines.length && (m = LIST.exec(lines[i]))) {
        const level = Math.min(8, Math.floor(m[1].replace(/\t/g, '  ').length / 2));
        const numbered = /\d/.test(m[2]);
        const parts = [m[4]]; i++;
        while (i < lines.length && lines[i].trim() && !LIST.test(lines[i]) && /^\s{2,}/.test(lines[i])) parts.push(lines[i++].trim());
        const task = m[3] ? (/x/i.test(m[3]) ? '☑ ' : '☐ ') : '';
        blocks.push(block('p', inlineRuns(task + parts.join(' ')), { props: { list: { id: numbered ? 'md-number' : 'md-bullet', level } } }));
      }
      continue;
    }
    para.push(line.trim()); i++;
  }
  flushPara();
  return { blocks, lists: usedLists ? structuredClone(MD_LISTS) : {} };
}

// ---- out ---------------------------------------------------------------------
const wrap = (t, r) => {
  if (!t) return '';
  let s = t;
  if (r.font === CODE_FONT) return `\`${s}\``;
  if (r.sup) s = `^${s}^`; if (r.sub) s = `~${s}~`;
  if (r.strike) s = `~~${s}~~`; if (r.i) s = `*${s}*`; if (r.b) s = `**${s}**`;
  return s;
};
/** A block's inline Markdown from its runs (formatting) or its text; `token(run)` renders a citation or result run when given. */
export function inlineMarkdown(b, token = null) {
  const runs = b.runs?.length ? b.runs : [{ t: b.text || '' }];
  return runs.map(r => {
    if (r.del) return '';
    const text = token ? token(r) : (r.cite ? r.cite.map(k => `[@${k}]`).join('') : r.t ?? '');
    // whitespace at a run's edge stays outside the marker, as Markdown requires
    const m = /^(\s*)([\s\S]*?)(\s*)$/.exec(text);
    return m[1] + wrap(m[2], r) + m[3];
  }).join('');
}
const escCell = t => String(t ?? '').replace(/\|/g, '\\|').replace(/\n/g, ' ');
const marker = (lists, id, level, count) => {
  const l = lists?.[id]?.levels?.[level] || (id === 'md-number' ? { fmt: 'decimal' } : { fmt: 'bullet' });
  if (l.fmt === 'bullet') return '-';
  return `${count}.`;
};

/**
 * The document as Markdown. `text(b)` gives a block's inline Markdown (by
 * default from its runs, tokens intact); lists and tables are written from
 * the blocks' own structure.
 */
export function toMarkdown(blocks, { lists = {}, text = b => inlineMarkdown(b) } = {}) {
  const out = [];
  const counts = new Map();
  let prevList = null;
  for (const b of blocks) {
    const li = b.props?.list;
    if (!li) { counts.clear(); prevList = null; }
    if (b.type === 'table' && (b.grid || Array.isArray(b.rows))) {
      const rows = b.grid ? b.grid.rows.filter(r => !r.del).map(r => r.cells.filter(c => !c.merged).map(c => escCell(c.cellDel ? '' : text(c))))
        : b.rows.map(row => row.map(cell => escCell(text({ text: String(cell ?? '') }))));
      if (!rows.length) continue;
      const cols = Math.max(...rows.map(r => r.length));
      const line = r => `| ${Array.from({ length: cols }, (_, c) => r[c] ?? '').join(' | ')} |`;
      out.push([line(rows[0] || []), `| ${Array(cols).fill('---').join(' | ')} |`, ...rows.slice(1).map(line)].join('\n'));
      continue;
    }
    if (b.type === 'toc' || b.type === 'figure' && !b.text) continue;
    if (b.type === 'bib') { out.push((b.lines || []).join('\n')); continue; }
    const body = text(b);
    if (li) {
      const key = `${li.id}:${li.level}`;
      for (const k of [...counts.keys()]) if (k.startsWith(`${li.id}:`) && Number(k.split(':')[1]) > li.level) counts.delete(k);
      counts.set(key, (counts.get(key) || 0) + 1);
      const line = `${'  '.repeat(li.level || 0)}${marker(lists, li.id, li.level || 0, counts.get(key))} ${body}`;
      // items of one list stay on consecutive lines
      if (prevList) out[out.length - 1] += `\n${line}`; else out.push(line);
      prevList = li.id;
      continue;
    }
    const prefix = { h1: '# ', h2: '## ', h3: '### ', quote: '> ' }[b.type] ?? '';
    out.push(b.type === 'quote' ? body.split('\n').map(l => `> ${l}`).join('\n') : prefix + body);
  }
  return out.join('\n\n').trim() + '\n';
}

// Capability-gated reasoning controls. Unknown endpoints keep their defaults.
export const EFFORTS = Object.freeze(['none', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max', 'ultra']);
export function reportedEfforts(reasoning) {
  if (!reasoning || !Object.hasOwn(reasoning, 'supported_efforts')) return [];
  const values = reasoning.supported_efforts === null ? EFFORTS.filter(e => e !== 'ultra') : reasoning.supported_efforts;
  return Array.isArray(values) ? EFFORTS.filter(e => values.includes(e) && !(e === 'none' && reasoning.mandatory)) : [];
}
export function effortLevels(cfg, info = {}) {
  if (!['chatgpt', 'openrouter', 'anthropic'].includes(cfg?.provider)) return [];
  if (Array.isArray(info.efforts)) return EFFORTS.filter(e => info.efforts.includes(e));
  // Exact documented Responses models, not a guess for future model families.
  if (cfg.provider === 'chatgpt' && ['gpt-5.6', 'gpt-5.6-sol', 'gpt-6-sol'].includes(cfg.model))
    return ['none', 'low', 'medium', 'high', 'xhigh', 'max'];
  return [];
}
export function reasoningOptions(cfg, info) {
  return cfg?.effort && effortLevels(cfg, info).includes(cfg.effort) ? { effort: cfg.effort } : null;
}
export const effortLabel = value => ({ none: 'None', minimal: 'Minimal', low: 'Low', medium: 'Medium', high: 'High', xhigh: 'Extra high', max: 'Max', ultra: 'Ultra' }[value] || 'Automatic');

// Studies with more than two arms in a pairwise analysis (plan G3, I4;
// Cochrane Handbook 23.3.4).
//
// A pairwise analysis compares one treated group with one control. A study
// with two treated arms and one shared control (two doses against placebo)
// cannot enter twice with the same control: its participants would be counted
// twice and the two comparisons are correlated. Per study the reviewer either
// chooses the comparison that fits the review question, or splits the shared
// control group between the comparisons (Handbook 23.3.4: its events and total
// are divided for a dichotomous outcome, its total for a continuous one, the
// mean and SD unchanged). The choice and its reason are recorded with the
// study and with every result it produced.
//
// `s.multiArm[paperId] = { arms: [{ id: 'arm1', label }, { id: 'arm2', label }, …],
//   control: 'Placebo', handling: 'arm1' | 'arm2' | … | 'split', reason }`.
// The first treated arm keeps the plain input keys (`events_t`, `mean_t__o2`),
// so a study's values from before it had arms are its first arm; a further
// arm's inputs carry `@armN` ("events_t@arm2", "mean_t__o2#t2@arm2").
// The control inputs (events_c, n_c, …) are shared and keep the plain keys.
//
// Pure: the analysis view, the extraction fields and the tests share it.
import { measureOf } from './effect-measures.mjs';

// The inputs that belong to a treated arm, per family; the rest are the
// shared control's. A reported ratio (HR) is itself a contrast: all three of
// its inputs are per arm, and it cannot be split.
export const TREATED = {
  binary: ['events_t', 'n_t'],
  continuous: ['mean_t', 'sd_t', 'n_t'],
  rate: ['events_t', 'time_t'],
  generic: ['hr', 'hr_lo', 'hr_hi'],
};
// What a split divides: a count or a size of the shared control, never a mean or an SD.
const SPLIT = { binary: ['events_c', 'n_c'], continuous: ['n_c'], rate: ['events_c', 'time_c'] };

/** Whether a measure's studies can have several treated arms here (two-group measures). */
export const armsApply = measure => measureOf(measure).family in TREATED;
/** Whether a split of the shared control is defined for the measure (not for a reported ratio). */
export const canSplit = measure => measureOf(measure).family in SPLIT;

/** A study's multi-arm record, when it has two treated arms or more; else null. */
export function multiArmOf(s, paperId) {
  const m = s.multiArm?.[paperId];
  return m && Array.isArray(m.arms) && m.arms.length > 1 ? m : null;
}
/** The most treated arms any study has (1 when none has several). */
export const maxArms = s => Math.max(1, ...Object.keys(s.multiArm || {}).map(id => multiArmOf(s, id)?.arms.length || 1));

/** The value key of an input for an arm: the plain key for the first arm and for control inputs. */
export const armFieldId = (fieldId, arm) => (!arm || arm === 'arm1' ? fieldId : `${fieldId}@${arm}`);

/** The handling a study's rows follow for this measure: a chosen arm, or 'split'. */
export function handlingOf(m, measure) {
  if (!m) return null;
  if (m.handling === 'split' && canSplit(measure)) return 'split';
  return m.arms.some(a => a.id === m.handling) ? m.handling : m.arms[0].id;
}

/** The label of a study's row for one comparison: "Trial 2018 · High dose vs Placebo". */
export function contrastLabel(paper, m, armId, split = false) {
  const arm = m.arms.find(a => a.id === armId);
  const name = arm?.label || armId;
  return `${paper.label || paper.id} · ${name}${m.control ? ` vs ${m.control}` : ''}${split ? ' (control split)' : ''}`;
}

/**
 * The comparisons a study contributes: `read(fieldId)` reads an accepted
 * input (null missing, NaN unreadable); `fields` are the measure's input
 * field ids in its order (already for the outcome and timepoint). Returns
 * [{ contrast, split, values }], one row for a two-arm study or a chosen
 * comparison, one per arm with inputs when the control is split (divided by
 * the number of arms that enter).
 */
export function contrastRows(s, paperId, measure, fields, bases, read) {
  const m = multiArmOf(s, paperId);
  const family = measureOf(measure).family;
  const own = arm => fields.map((f, i) => read(TREATED[family]?.includes(bases[i]) ? armFieldId(f, arm) : f));
  const how = armsApply(measure) ? handlingOf(m, measure) : null;
  if (!how) return [{ contrast: null, split: false, values: fields.map(read) }];
  if (how !== 'split') return [{ contrast: how, split: false, values: own(how) }];
  // arms without any treated input stay out of the split; one with part of its inputs is kept, so it shows as incomplete
  const treatedIdx = bases.map((b, i) => (TREATED[family].includes(b) ? i : -1)).filter(i => i >= 0);
  const entering = m.arms.map(a => ({ arm: a.id, values: own(a.id) })).filter(r => treatedIdx.some(i => r.values[i] != null));
  const k = entering.length || 1;
  const divide = SPLIT[family] || [];
  return entering.map(r => ({ contrast: r.arm, split: k > 1,
    values: r.values.map((v, i) => (k > 1 && divide.includes(bases[i]) && Number.isFinite(v) ? v / k : v)) }));
}

/** The sentence a result records for its multi-arm studies; '' when none. */
export function multiArmText(s, papers, measure) {
  const out = [];
  for (const p of papers) {
    const m = multiArmOf(s, p.id); if (!m) continue;
    const how = handlingOf(m, measure);
    const arm = m.arms.find(a => a.id === how);
    const control = m.control || 'the control arm';
    const text = how === 'split'
      ? `${p.label}: ${m.arms.map(a => a.label || a.id).join(' and ')} each compared with ${control}, the shared ${control} group split between the comparisons${measureOf(measure).family === 'continuous' ? ' (its total divided; mean and SD unchanged)' : ' (its events and total divided)'}`
      : `${p.label}: ${arm?.label || how} compared with ${control}; ${m.arms.filter(a => a.id !== how).map(a => a.label || a.id).join(', ')} not used`;
    out.push(`${text}${m.reason ? ` (${m.reason})` : ''}`);
  }
  return out.join('; ');
}

