    }
    if(reason) { excluded.push({id:identifiers[i],row:i+1,reason});return; }
    prepared.push({id:identifiers[i],row:i+1,source,treatment:String(r[settings.treatment]).trim()===settings.treatedLevel?1:0});
  });
  if(!prepared.some(r=>r.treatment===1) || !prepared.some(r=>r.treatment===0)) throw new Error('Complete cases must contain both treatment groups');
  let model=null;
  if(!settings.scoreColumn) {
    model=logisticRegression(prepared.map(r=>r.source),settings.treatment,specs,{event:settings.treatedLevel,profile:false});
    if(!model.converged || model.warnings.some(w=>w.code==='separation' || w.code==='not-converged')) throw new Error('The propensity logistic model is separated or did not converge; revise the covariates or supply reviewed scores');
    if(model.nUsed!==prepared.length) throw new Error('Propensity model excluded unexpected rows');
  }
  const covariateLevels=Object.fromEntries(specs.filter(c=>c.type==='categorical').map(c=>[c.column,[...new Set(prepared.map(r=>String(r.source[c.column])))].sort()]));
  const scored=prepared.map((r,i)=>({...r,ps:settings.scoreColumn?Number(r.source[settings.scoreColumn]):model.fitted[i],covariates:Object.fromEntries(specs.flatMap(c=>c.type==='numeric'?[[covariateName(c.column),r.source[c.column]]]:
    covariateLevels[c.column].map(level=>[`${covariateName(c.column)} = ${level}`,String(r.source[c.column])===level?1:0])))}));
  const interior=scored.filter(r=>{
    if(!(Number.isFinite(r.ps) && r.ps>0 && r.ps<1)) { excluded.push({id:r.id,row:r.row,reason:'Propensity score outside (0, 1): positivity'});return false; }
    return true;
  });
  const t=interior.filter(r=>r.treatment===1),c=interior.filter(r=>r.treatment===0);
  if(!t.length || !c.length) throw new Error('Positivity exclusions removed a treatment group');
  const tr=range(t.map(r=>r.ps)),cr=range(c.map(r=>r.ps)),overlap=[Math.max(tr[0],cr[0]),Math.min(tr[1],cr[1])];
  const eligible=interior.filter(r=>{
    const reason=r.ps<settings.trimLower || r.ps>settings.trimUpper?'Propensity trimming':
      settings.commonSupport==='overlap' && (r.ps<overlap[0] || r.ps>overlap[1])?'Outside common support':'';
    if(reason) excluded.push({id:r.id,row:r.row,reason});return !reason;
  });
  if(!eligible.some(r=>r.treatment===1) || !eligible.some(r=>r.treatment===0)) throw new Error('Trimming/support restrictions removed a treatment group');
  let adjusted,pairs=[],cost=null,absoluteCaliper=null;
  if(settings.method==='match') {
    absoluteCaliper=settings.caliper==null?Infinity:settings.caliper*(settings.caliperUnits==='sd'?Math.sqrt(variance(interior.map(r=>logit(r.ps)))):1);
    const matched=matchScores(eligible,{ratio:settings.ratio,caliper:absoluteCaliper,algorithm:settings.algorithm});
    adjusted=matched.rows;pairs=matched.pairs;cost=matched.cost;
    adjusted.filter(r=>r.weight===0).forEach(r=>excluded.push({id:r.id,row:r.row,reason:r.treatment?'Unmatched treated row: no unused control within the caliper':'Unmatched control'}));
  } else adjusted=iptwWeights(eligible,{estimand:settings.estimand,stabilized:settings.stabilized,treatedPrevalence:mean(interior.map(r=>r.treatment))});
  const balance=balanceTable(interior,adjusted,{estimand:settings.estimand});
  const used=new Map(adjusted.map(r=>[r.id,r]));
  const exclusions=new Map(excluded.map(e=>[e.id,e.reason]));
  const output=interior.map(r=>({...r,...(used.get(r.id)||{weight:0,set:''}),reason:exclusions.get(r.id) || ''}));
  const groupStats=group=>{const rows=adjusted.filter(r=>r.treatment===group && r.weight>0),weights=rows.map(r=>r.weight);return {n:rows.length,ess:effectiveSampleSize(weights),weightSum:sum(weights),maxWeight:weights.length?range(weights)[1]:null};};
  const frozen=JSON.parse(snapshot);
  return {version:PROPENSITY_VERSION,at:new Date().toISOString(),datasetId:d.id,datasetName:d.name,settings,inputSnapshot:snapshot,
    frozenData:{id:d.id,name:d.name,rowKey:frozen.rowKey,rowIds:frozen.rowIds,columns:frozen.columns,rows:frozen.rows},
    rows:output.map(({source,...r})=>r),excluded,pairs,totalDistance:cost,absoluteCaliper:Number.isFinite(absoluteCaliper)?absoluteCaliper:null,
    balance,overlap:{treated:tr,control:cr,common:overlap,empty:overlap[0]>overlap[1]},groups:{treated:groupStats(1),control:groupStats(0)},
    nInput:d.rows.length,nComplete:prepared.length,nScored:interior.length,nRetained:adjusted.filter(r=>r.weight>0).length,
    model:model?{coefficients:model.coefficients,converged:model.converged,iterations:model.iterations,warnings:model.warnings}:null,
    deterministic:true,seed:null,method:settings.method==='match'?(settings.algorithm==='nearest-neighbor'?'Greedy 1:1 nearest-neighbor matching on absolute propensity-logit distance, without replacement; ascending treated Row ID; equal-distance controls use ascending Row ID; ATT preprocessing weights for retained treated rows':`Complete 1:${settings.ratio} minimum-cost assignment on absolute propensity-logit distance, without replacement; ATT preprocessing weights`):
      `${settings.estimand} inverse-probability weights${settings.stabilized?' stabilized by the complete-case treatment prevalence':''}`,
    balanceMethod:`Standardized differences use fixed baseline ${settings.estimand==='ATT'?'treated':'pooled'} SDs; categorical levels use Bernoulli variances. No outcome inference.`,
    target:settings.method==='match'?(settings.algorithm==='nearest-neighbor'?'Treated complete cases satisfying the score restrictions and obtaining a nearest-neighbor match':'Treated complete cases satisfying the declared score restrictions'):'Complete cases satisfying the declared score restrictions',
    references:['https://kosukeimai.github.io/MatchIt/articles/matching-methods.html','https://kosukeimai.github.io/MatchIt/reference/method_nearest.html','https://ngreifer.github.io/WeightIt/reference/get_w_from_ps.html','https://ngreifer.github.io/cobalt/articles/cobalt.html']};
}

export function propensityStatus(saved,d) {
  if(!saved) return 'none';if(!d) return 'stale';
  try { return propensitySnapshot(d,saved.settings)===saved.inputSnapshot?'current':'stale'; } catch { return 'stale'; }
}
export function replayPropensity(saved) {
  if(saved?.version!==PROPENSITY_VERSION || !saved.frozenData) throw new Error('Unsupported propensity replay record');
  if(propensitySnapshot(saved.frozenData,saved.settings)!==saved.inputSnapshot) throw new Error('Frozen propensity inputs differ from the saved snapshot');
  return runPropensity(saved.frozenData,saved.settings);
}
export function propensityRows(saved) {
  const ids=new Set(saved.rows.map(r=>r.id));
  return [['Row ID','Source row','Treatment','Propensity score','Weight','Matched set','Exclusion reason'],
    ...saved.rows.map(r=>[r.id,r.row,r.treatment,r.ps,r.weight,r.set,r.reason]),
    ...saved.excluded.filter(e=>!ids.has(e.id)).map(e=>[e.id,e.row,'','','','',e.reason])];
}
export function propensityBalanceRows(saved) {
  return [['Variable','Treated before','Control before','Treated after','Control after','SD denominator','SMD before','SMD after'],
    ...saved.balance.map(r=>[r.variable,r.treatedBefore,r.controlBefore,r.treatedAfter,r.controlAfter,r.denominator,r.smdBefore,r.smdAfter])];
}

// Thematic synthesis for a qualitative evidence synthesis (Thomas & Harden
// 2008): line-by-line codes on quoted findings, descriptive themes that group
// codes, and analytical themes built from descriptive themes.
//
// State lives in `s.qes`:
//   codes:       [{ id, label }]
//   quotes:      [{ id, code, paper, text, page, rects, document_version, at }]
//   descriptive: [{ id, label, codes: [codeId] }]
//   analytical:  [{ id, label, statement, themes: [descriptiveId], cerqual }]
// A quote carries the reader's anchor (page, rectangles, document hash), the
// same shape a quotation note has, so a code opens at the passage it came from.
//
// Every mutator here takes the state and changes it in place, for use inside
// store.update(). None leaves a reference to something that no longer exists:
// deleting or merging a code rewrites the themes that held it, and so on up.
import { studies } from './screen.mjs';
import { figureTokens } from './figure-style.mjs';
import { svgRoot, text, lines, r1, esc, axisLine, matrixFrame, drawHeads, rowLabel, footBlock, emptyFigure, sourceOf } from './figure-kit.mjs';

const uid = p => `${p}${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const clean = t => String(t ?? '').replace(/\s+/g, ' ').trim();
const LEVEL = { descriptive: 'descriptive', analytical: 'analytical' };
const memberKey = level => (level === 'analytical' ? 'themes' : 'codes');

/** The synthesis, with every list present. Creates it on a state being updated. */
export function qesOf(s) {
  s.qes ||= {};
  for (const k of ['codes', 'quotes', 'descriptive', 'analytical']) s.qes[k] ||= [];
  return s.qes;
}
/** Read-only view for rendering: never writes to the state. */
export const readQes = s => ({ codes: [], quotes: [], descriptive: [], analytical: [], ...(s?.qes || {}) });

// ---- codes ----------------------------------------------------------------
/** A code by label, reusing one already named the same (ignoring case). Returns its id. */
export function ensureCode(s, label) {
  const q = qesOf(s), name = clean(label);
  if (!name) return null;
  const found = q.codes.find(c => c.label.toLowerCase() === name.toLowerCase());
  if (found) return found.id;
  const c = { id: uid('c'), label: name };
  q.codes.push(c);
  return c.id;
}

/**
 * A quoted finding coded with a label. `locator` is the reader's anchor
 * ({ page, rects, document_version }) or null for a quote typed in by hand.
 */
export function addQuote(s, { code, paper, text, locator = null }) {
  const body = String(text ?? '').trim();
  if (!body || !paper) return null;
  const codeId = qesOf(s).codes.some(c => c.id === code) ? code : ensureCode(s, code);
  if (!codeId) return null;
  const quote = { id: uid('q'), code: codeId, paper, text: body,
    page: locator?.page ?? null, rects: locator?.rects ?? null, document_version: locator?.document_version ?? null,
    at: new Date().toISOString() };
  s.qes.quotes.push(quote);
  return quote.id;
}

export function deleteQuote(s, id) {
  const q = qesOf(s);
  q.quotes = q.quotes.filter(x => x.id !== id);
}

// ---- themes and codes alike -------------------------------------------------
const listOf = (s, kind) => qesOf(s)[kind === 'code' ? 'codes' : kind];

/** Renames a code or a theme. A code renamed to another code's name merges into it. */
export function rename(s, kind, id, label) {
  const name = clean(label), item = listOf(s, kind).find(x => x.id === id);
  if (!name || !item) return;
  if (kind === 'code') {
    const twin = qesOf(s).codes.find(c => c.id !== id && c.label.toLowerCase() === name.toLowerCase());
    if (twin) { merge(s, 'code', [id], twin.id); return; }
  }
  item.label = name;
}

/** Folds `fromIds` into `intoId`: their members move to it and the parents that held them hold it instead. */
export function merge(s, kind, fromIds, intoId) {
  const q = qesOf(s), from = new Set(fromIds.filter(x => x !== intoId));
  if (!from.size || !listOf(s, kind).some(x => x.id === intoId)) return;
  if (kind === 'code') {
    for (const x of q.quotes) if (from.has(x.code)) x.code = intoId;
    q.codes = q.codes.filter(c => !from.has(c.id));
    replaceMembers(q.descriptive, 'codes', from, intoId);
    return;
  }
  const list = q[kind], into = list.find(t => t.id === intoId), key = memberKey(kind);
  for (const t of list) if (from.has(t.id)) into[key] = union(into[key], t[key]);
  if (kind === 'analytical') into.statement = [into.statement, ...list.filter(t => from.has(t.id)).map(t => t.statement)].filter(Boolean).join('\n\n');
  q[kind] = list.filter(t => !from.has(t.id));
  if (kind === 'descriptive') replaceMembers(q.analytical, 'themes', from, intoId);
}

/** Deletes codes or themes. A code takes its quotes with it; themes lose it as a member. */
export function remove(s, kind, ids) {
  const q = qesOf(s), gone = new Set(ids);
  if (kind === 'code') {
    q.codes = q.codes.filter(c => !gone.has(c.id));
    q.quotes = q.quotes.filter(x => !gone.has(x.code));
    for (const t of q.descriptive) t.codes = t.codes.filter(c => !gone.has(c));
    return;
  }
  q[kind] = q[kind].filter(t => !gone.has(t.id));
  if (kind === 'descriptive') for (const t of q.analytical) t.themes = t.themes.filter(d => !gone.has(d));
}

const union = (a = [], b = []) => [...new Set([...a, ...b])];
function replaceMembers(parents, key, from, intoId) {
  for (const p of parents) {
    if (!p[key].some(m => from.has(m))) continue;
    p[key] = union(p[key].map(m => (from.has(m) ? intoId : m)));
  }
}

/** A new theme at a level holding `members` (code ids, or descriptive-theme ids). Returns its id. */
export function addTheme(s, level, label, members = []) {
  const name = clean(label); if (!name || !LEVEL[level]) return null;
  const q = qesOf(s), valid = new Set((level === 'analytical' ? q.descriptive : q.codes).map(x => x.id));
  const t = { id: uid(level === 'analytical' ? 'a' : 'd'), label: name, [memberKey(level)]: union(members.filter(m => valid.has(m))) };
  if (level === 'analytical') t.statement = '';
  q[level].push(t);
  return t.id;
}

/** Adds members to a theme, or takes them out. */
export function setMembers(s, level, themeId, members, on = true) {
  const q = qesOf(s), t = q[level]?.find(x => x.id === themeId); if (!t) return;
  const key = memberKey(level), valid = new Set((level === 'analytical' ? q.descriptive : q.codes).map(x => x.id));
  t[key] = on ? union(t[key], members.filter(m => valid.has(m))) : t[key].filter(m => !members.includes(m));
}

export function setStatement(s, id, text) {
  const t = qesOf(s).analytical.find(x => x.id === id); if (t) t.statement = String(text ?? '');
}

// ---- reading it back ------------------------------------------------------
/** Code ids beneath a theme at either level. */
export function codesUnder(s, level, id) {
  const q = readQes(s);
  if (level === 'code') return [id];
  if (level === 'descriptive') return q.descriptive.find(t => t.id === id)?.codes || [];
  const d = q.analytical.find(t => t.id === id)?.themes || [];
  return [...new Set(d.flatMap(x => q.descriptive.find(t => t.id === x)?.codes || []))];
}
/** Quotes supporting a code or theme. */
export const quotesUnder = (s, level, id) => { const set = new Set(codesUnder(s, level, id)); return readQes(s).quotes.filter(x => set.has(x.code)); };
/** Paper ids of the sources contributing to a code or theme, in first-quoted order. */
export const sourcesOf = (s, level, id) => [...new Set(quotesUnder(s, level, id).map(x => x.paper))];

/** Codes not yet in any descriptive theme; descriptive themes not yet in an analytical one. */
export function ungrouped(s) {
  const q = readQes(s);
  const inD = new Set(q.descriptive.flatMap(t => t.codes)), inA = new Set(q.analytical.flatMap(t => t.themes));
  return { codes: q.codes.filter(c => !inD.has(c.id)).map(c => c.id), descriptive: q.descriptive.filter(t => !inA.has(t.id)).map(t => t.id) };
}

/** The sources a matrix lists: the included studies, then any other quoted source. */
function sourcePapers(s) {
  const inc = studies(s), have = new Set(inc.map(p => p.id));
  const extra = [...new Set(readQes(s).quotes.map(x => x.paper))].filter(id => !have.has(id))
    .map(id => (s.papers || []).find(p => p.id === id)).filter(Boolean);
  return [...inc, ...extra];
}

/**
 * Sources × themes: which studies support which theme, and with how many
 * quotes. { level, rows: papers, cols: themes, cells[r][c] = quote count,
 * support[c] = sources contributing to the theme }.
 */
export function themeMatrix(s, level = 'analytical') {
  const q = readQes(s), rows = sourcePapers(s), cols = q[level] || [];
  const quotes = cols.map(t => quotesUnder(s, level, t.id));
  const cells = rows.map(p => quotes.map(list => list.filter(x => x.paper === p.id).length));
  const support = cols.map((_, j) => cells.filter(r => r[j] > 0).length);
  return { level, rows, cols, cells, support };
}

export const labelOf = (s, id) => (s.papers || []).find(p => p.id === id)?.label || id;

/** The matrix as CSV rows: one row per source, a quote count per theme, sources per theme last. */
export function matrixRows(m) {
  return [['Source', ...m.cols.map(t => t.label)],
    ...m.rows.map((p, i) => [p.label || p.id, ...m.cells[i]]),
    ['Sources contributing', ...m.support]];
}

/**
 * The matrix as a self-contained SVG in the house style: a grey square where a source supports a theme, with its
 * quote count, and the sources contributing to each theme under a rule. Source labels wrap to two lines or become a
 * key; theme heads never rotate. `style` is figureTokens (the export set unless given).
 */
export function matrixSvg(m, { style = null, width = null, source = [] } = {}) {
  const t = style || figureTokens(null, { medium: 'export' }), lv = m?.level || 'thematic', title = `Sources by ${lv} themes`;
  if (!m?.rows?.length || !m?.cols?.length)
    return emptyFigure(t, { title, message: m?.cols?.length ? 'No source is included yet.' : `No ${lv} theme has been built yet.`, width, source });
  const rows = m.rows.map(p => p.label || p.id), cols = m.cols.map(c => c.label);
  const f = matrixFrame(t, { rows, cols, width, cell: t.row * 2 }), { P, ls } = f, inset = t.unit === 'pt' ? 0.5 : 1;
  const parts = [], body = [];
  let y = drawHeads(t, parts, f, cols);
  m.rows.forEach((p, i) => {
    const h = f.rowH(i), cy = y + h / 2;
    body.push(rowLabel(t, f, i, cy, rows[i]));
    m.cells[i].forEach((n, j) => {
      if (!n) return;
      body.push(`<rect class="c-seq1" x="${r1(f.cx[j] + inset)}" y="${r1(y + inset)}" width="${r1(f.cw[j] - 2 * inset)}" height="${r1(h - 2 * inset)}" fill="${t.seq[1]}"><title>${esc(`${rows[i]} · ${cols[j]}: ${n} ${n === 1 ? 'quote' : 'quotes'}`)}</title></rect>`,
        text(t, f.cx[j] + f.cw[j] / 2, cy + ls * 0.35, String(n), { anchor: 'middle', attrs: 'pointer-events="none"' }));
    });
    y += h;
  });
  parts.push(...body, axisLine(t, P, y, f.right, y));
  const cy = y + Math.max(t.row, f.step * 1.2) / 2;
  parts.push(lines(t, f.x0 - ls * 0.6, cy, ['Sources'], { anchor: 'end', role: 'head', cls: 'c-ink c-head' }));
  (m.support || []).forEach((n, j) => parts.push(text(t, f.cx[j] + f.cw[j] / 2, cy + ls * 0.35, String(n), { anchor: 'middle' })));
  const line = `${m.rows.length} sources · ${m.cols.length} ${m.level} themes · quotes per cell`;
  const h = footBlock(t, parts, y + Math.max(t.row, f.step * 1.2), f.w, { source: [line, ...sourceOf(source)], keys: f.keys });
  return svgRoot(t, f.w, h, parts.join(''), { title, desc: line });
}

/** The drawings app/lint-figures.mjs checks: three sources by three themes, one with a long label, and a matrix without themes. */
export const __fixture = style => {
  const rows = [{ id: 'p1', label: 'Ames 2019' }, { id: 'p2', label: 'Cole, Hartmann and Ito 2021: older adults after a fall' }, { id: 'p3', label: 'Delgado 2020' }];
  const cols = [{ id: 'd1', label: 'Restricted life' }, { id: 'd2', label: 'Fear of falling again' }, { id: 'd3', label: 'Relationship with family and carers' }];
  const m = { level: 'descriptive', rows, cols, cells: [[2, 0, 1], [1, 3, 0], [0, 0, 0]], support: [2, 1, 1] };
  return [{ name: 'matrixSvg', svg: matrixSvg(m, { style }) }, { name: 'matrixSvg-empty', svg: matrixSvg({ level: 'analytical', rows, cols: [], cells: [], support: [] }, { style }) }];
};

// ---- exports ----------------------------------------------------------------
const locatorText = x => (x.page ? `p. ${x.page}` : 'typed');

/** One row per coded quote: source, locator, quote, code, the themes it sits under. */
export function codesCsvRows(s) {
  const q = readQes(s), code = new Map(q.codes.map(c => [c.id, c]));
  const dOf = id => q.descriptive.filter(t => t.codes.includes(id));
  const aOf = ds => q.analytical.filter(t => t.themes.some(d => ds.some(x => x.id === d)));
  return [['source', 'locator', 'quote', 'code', 'descriptive_themes', 'analytical_themes', 'document_version'],
    ...q.quotes.map(x => { const ds = dOf(x.code);
      return [labelOf(s, x.paper), locatorText(x), x.text, code.get(x.code)?.label || '',
        ds.map(t => t.label).join('; '), aOf(ds).map(t => t.label).join('; '), x.document_version || ''];
    })];
}

/** One row per theme: level, label, members, sources contributing, and an analytical theme's statement. */
export function themesCsvRows(s) {
  const q = readQes(s), code = new Map(q.codes.map(c => [c.id, c.label])), desc = new Map(q.descriptive.map(t => [t.id, t.label]));
  return [['level', 'theme', 'members', 'sources', 'source_count', 'statement'],
    ...q.descriptive.map(t => { const src = sourcesOf(s, 'descriptive', t.id);
      return ['descriptive', t.label, t.codes.map(c => code.get(c)).join('; '), src.map(id => labelOf(s, id)).join('; '), src.length, '']; }),
    ...q.analytical.map(t => { const src = sourcesOf(s, 'analytical', t.id);
      return ['analytical', t.label, t.themes.map(d => desc.get(d)).join('; '), src.map(id => labelOf(s, id)).join('; '), src.length, t.statement || '']; })];
}

// The text side of the qualitative coding workspace (views/coding.mjs): a
// document is plain text with character offsets, and everything structural is
// read from that text rather than stored beside it, so an edit can never leave
// structure and text disagreeing. Paragraphs are lines; a transcript's speaker
// turns begin at a paragraph that opens with "Name:" (optionally after or
// before a timestamp such as [00:12:34]) and run until the next such paragraph.
//
// Pure: nothing here reads the store or the DOM.

/** Paragraphs as offsets: one per line, the newline not included. */
export function paragraphs(text) {
  const out = []; let at = 0;
  for (const line of String(text ?? '').split('\n')) { out.push({ start: at, end: at + line.length }); at += line.length + 1; }
  return out;
}

const TIME = String.raw`\[(\d{1,2}:\d{2}(?::\d{2})?(?:[.,]\d+)?)\]`;
// A label is a name of up to four words, or an interviewer shorthand (I, R, P3);
// "10:30" never qualifies because a label starts with a letter.
const LABEL = String.raw`(\p{Lu}[\p{L}\d'’.-]*(?:\s+[\p{Lu}\d][\p{L}\d'’.-]*){0,3})`;
const TURN = new RegExp(String.raw`^(\s*(?:${TIME}\s*)?)${LABEL}(\s*(?:${TIME})?\s*):(?=\s|$)`, 'u');
const STAMP = new RegExp(TIME, 'g');
// Words that open ordinary prose with a colon and are not speakers.
const NOT_SPEAKER = new Set(['note', 'notes', 'example', 'question', 'answer', 'q', 'a', 'http', 'https', 'mailto', 'see', 'nb', 'ps', 'topic', 'theme']);

/**
 * Speaker turns: [{ speaker, start, end, labelStart, labelEnd, time }]. `start`
 * is the paragraph where the label is, `end` the end of the last paragraph
 * before the next label; `labelStart..labelEnd` covers "Name:".
 */
export function parseTurns(text) {
  const t = String(text ?? ''), turns = [];
  for (const p of paragraphs(t)) {
    const line = t.slice(p.start, p.end), m = TURN.exec(line);
    if (!m || NOT_SPEAKER.has(m[3].toLowerCase())) { if (turns.length && line.trim()) turns[turns.length - 1].end = p.end; continue; }
    const labelStart = p.start + m[1].length;
    turns.push({ speaker: m[3].trim(), start: p.start, end: p.end, labelStart, labelEnd: p.start + m[0].length, time: m[2] || m[5] || null });
  }
  return turns;
}

/** Distinct speakers in first-appearance order, merged ignoring case. */
export function speakersOf(text) {
  const seen = new Map();
  for (const t of parseTurns(text)) if (!seen.has(t.speaker.toLowerCase())) seen.set(t.speaker.toLowerCase(), t.speaker);
  return [...seen.values()];
}

/** The turn covering an offset, or null. */
export const turnAt = (turns, offset) => turns.find(t => offset >= t.start && offset <= t.end) || null;

/** Timestamps written in the text: [{ start, end, time }]. */
export const timestamps = text => [...String(text ?? '').matchAll(STAMP)].map(m => ({ start: m.index, end: m.index + m[0].length, time: m[1] }));

// A sentence ends at . ! or ? followed by space and a capital, a quote or a
// digit; common abbreviations do not end one.
const ABBR = /\b(?:Dr|Mr|Mrs|Ms|Prof|Mx|St|vs|etc|e\.g|i\.e|approx|No)\.$/i;
/** Sentences inside [from, to) as offsets, trimmed of surrounding space. */
export function sentences(text, from = 0, to = String(text ?? '').length) {
  const t = String(text ?? ''), out = [];
  let s = from;
  const push = (a, b) => { while (a < b && /\s/.test(t[a])) a++; while (b > a && /\s/.test(t[b - 1])) b--; if (b > a) out.push({ start: a, end: b }); };
  const re = /[.!?]+["'’”)]*(?=\s+["'‘“(]?[\p{Lu}\d])/gu;
  re.lastIndex = from;
  const body = t.slice(0, to);
  for (let m; (m = re.exec(body));) {
    const end = m.index + m[0].length;
    if (ABBR.test(body.slice(Math.max(s, m.index - 8), m.index + 1))) continue;
    push(s, end); s = end;
  }
  push(s, to);
  return out;
}

/**
 * The unit around a match: the match itself, its sentence, its paragraph or
 * its speaker turn (without the "Name:" label). Returns { start, end }.
 */
export function unitAround(text, start, end, unit, turns = null) {
  const t = String(text ?? '');
  if (unit === 'match') return { start, end };
  const para = paragraphs(t).find(p => start >= p.start && start <= p.end) || { start: 0, end: t.length };
  if (unit === 'paragraph') return { start: para.start, end: Math.max(para.end, Math.min(end, t.length)) };
  if (unit === 'turn') {
    const turn = turnAt(turns || parseTurns(t), start);
    if (turn) return { start: turn.labelEnd + (/\s/.test(t[turn.labelEnd] || '') ? 1 : 0), end: turn.end };
    return { start: para.start, end: para.end };
  }
  const list = sentences(t, para.start, para.end);
  const a = list.find(x => start >= x.start && start < x.end) || list.find(x => x.start >= start) || { start, end };
  const b = list.find(x => end > x.start && end <= x.end) || a;
  return { start: Math.min(a.start, start), end: Math.max(b.end, end) };
}

export const UNITS = [['match', 'Match'], ['sentence', 'Sentence'], ['paragraph', 'Paragraph'], ['turn', 'Speaker turn']];
export const HIT_CAP = 5000;
const escRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** The search as a regular expression, or { error } for one that does not compile. */
export function compileSearch({ pattern, regex = false, caseSensitive = false, wholeWord = false }) {
  const p = String(pattern ?? '');
  if (!p.trim()) return { error: 'Nothing to find' };
  let src = regex ? p : escRe(p);
  if (wholeWord) src = String.raw`(?<![\p{L}\p{N}_])(?:${src})(?![\p{L}\p{N}_])`;
  try { return { re: new RegExp(src, `gu${caseSensitive ? '' : 'i'}`) }; }
  catch (e) { return { error: `Not a valid pattern: ${String(e.message || e).replace(/^Invalid regular expression: /, '')}` }; }
}

/**
 * Finds a pattern across documents ([{ id, name, text }]) and widens each
 * match to the chosen unit. Matches landing in the same unit make one hit.
 * Returns { hits: [{ docId, start, end, text, match }], error, truncated }.
 */
export function findHits(docs, opts = {}) {
  const { re, error } = compileSearch(opts);
  if (error) return { hits: [], error, truncated: false };
  const unit = opts.unit || 'match', cap = opts.cap || HIT_CAP, hits = [];
  for (const d of docs) {
    const t = String(d.text ?? ''), turns = unit === 'turn' ? parseTurns(t) : null, seen = new Set();
    re.lastIndex = 0;
    for (let m; (m = re.exec(t));) {
      if (!m[0].length) { re.lastIndex++; continue; }
      const u = unitAround(t, m.index, m.index + m[0].length, unit, turns), key = `${u.start}:${u.end}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (hits.length >= cap) return { hits, error: null, truncated: true };
      hits.push({ docId: d.id, start: u.start, end: u.end, text: t.slice(u.start, u.end), match: m[0] });
    }
  }
  return { hits, error: null, truncated: false };
}

// ---- layering coded ranges for display -------------------------------------
/**
 * Cuts [from, to) at every range boundary: [{ start, end, ids }] where ids are
 * the ranges covering that piece. Pieces without a range are included with
 * ids = [], so the pieces tile [from, to) exactly.
 */
export function segments(ranges, from, to) {
  const cuts = new Set([from, to]);
  for (const r of ranges) { if (r.end <= from || r.start >= to) continue; cuts.add(Math.max(from, r.start)); cuts.add(Math.min(to, r.end)); }
  const xs = [...cuts].sort((a, b) => a - b), out = [];
  for (let i = 0; i < xs.length - 1; i++) {
    const a = xs[i], b = xs[i + 1];
    if (b <= a) continue;
    out.push({ start: a, end: b, ids: ranges.filter(r => r.start < b && r.end > a).map(r => r.id) });
  }
  return out;
}

/**
 * Margin lanes for ranges, so overlapping ones sit side by side: the first
 * lane free when a range starts (greedy interval partitioning, longest first
 * among equal starts). Returns Map id -> lane and the lane count.
 */
export function lanes(ranges) {
  const order = [...ranges].sort((a, b) => a.start - b.start || (b.end - b.start) - (a.end - a.start));
  const ends = [], lane = new Map();
  for (const r of order) {
    let i = ends.findIndex(e => e <= r.start);
    if (i < 0) { i = ends.length; ends.push(r.end); } else ends[i] = r.end;
    lane.set(r.id, i);
  }
  return { lane, count: ends.length };
}

// The qualitative coding workspace for a study's own data (views/coding.mjs):
// interview and focus-group transcripts, documents and survey free text coded
// with a hierarchical codebook. A review's thematic synthesis keeps `s.qes`
// (lib/qes.mjs); a primary study's corpus lives in `s.qual`:
//
//   documents:   [{ id, name, kind: 'transcript'|'document'|'survey', text, source, caseId, speakers: { name: caseId }, version, at }]
//   codes:       [{ id, label, short, parent, description, guid?, at }]
//   codings:     [{ id, docId, start, end, codeIds, coder, at, exemplar, weight }]
//   cases:       [{ id, label, attributes: { attrId: value } }]
//   attributes:  [{ id, label, type: 'text'|'number'|'category' }]
//   memos:       [{ id, kind: 'code'|'document'|'case'|'coding', target, text, by, at }]
//   descriptive, analytical: themes in the shape of lib/qes.mjs, whose theme
//                functions are reused here unchanged (themes group codes)
//   framework:   { cells: { 'row|col': text } }
//   codebookVersion: a counter raised by every change to the codebook
//   coder:       who is coding on this machine, stamped on new codings
//
// A coding is a character range [start, end) in its document's text. Every
// edit to a document's text goes through editText/replaceRanges, which move
// codings with the text (shiftRange), so offsets stay right after an edit or
// pseudonymisation. Mutators change the state in place, for store.update().
import { addTheme, setMembers, merge as qesMerge, remove as qesRemove, setStatement, rename as qesRename } from './qes.mjs';
import { parseTurns, turnAt } from './qual-text.mjs';

export const uid = p => `${p}${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
const clean = t => String(t ?? '').replace(/\s+/g, ' ').trim();
const now = () => new Date().toISOString();
const LISTS = ['documents', 'codes', 'codings', 'cases', 'attributes', 'memos', 'descriptive', 'analytical'];

/** The workspace, with every list present. Creates it on a state being updated. */
export function qualOf(s) {
  s.qual ||= {};
  for (const k of LISTS) if (!Array.isArray(s.qual[k])) s.qual[k] = [];
  s.qual.framework ||= { cells: {} };
  s.qual.framework.cells ||= {};
  s.qual.codebookVersion ||= 0;
  return s.qual;
}
const EMPTY = () => ({ documents: [], codes: [], codings: [], cases: [], attributes: [], memos: [], descriptive: [], analytical: [], framework: { cells: {} }, codebookVersion: 0, coder: '' });
/** Read-only view for rendering: never writes to the state. */
export const readQual = s => ({ ...EMPTY(), ...(s?.qual || {}) });

/** A saved workspace brought to the current shape; anything malformed is dropped rather than trusted. */
export function normalizeQual(q) {
  if (!q || typeof q !== 'object' || Array.isArray(q)) return null;
  const out = { ...EMPTY(), ...q };
  for (const k of LISTS) out[k] = Array.isArray(q[k]) ? q[k].filter(x => x && typeof x === 'object' && x.id) : [];
  out.documents = out.documents.filter(d => typeof d.text === 'string').map(d => ({ kind: 'document', speakers: {}, caseId: null, version: 1, ...d }));
  out.codes = out.codes.filter(c => typeof c.label === 'string').map(c => ({ parent: null, description: '', ...c }));
  const docs = new Map(out.documents.map(d => [d.id, d])), codes = new Set(out.codes.map(c => c.id));
  for (const c of out.codes) if (c.parent && (!codes.has(c.parent) || c.parent === c.id)) c.parent = null;
  out.codings = out.codings.filter(x => docs.has(x.docId) && Number.isInteger(x.start) && Number.isInteger(x.end) && x.start < x.end && x.end <= docs.get(x.docId).text.length)
    .map(x => ({ coder: '', exemplar: false, weight: null, ...x, codeIds: (Array.isArray(x.codeIds) ? x.codeIds : []).filter(id => codes.has(id)) }))
    .filter(x => x.codeIds.length);
  out.cases = out.cases.map(c => ({ attributes: {}, ...c }));
  out.framework = q.framework && typeof q.framework === 'object' ? { cells: { ...(q.framework.cells || {}) } } : { cells: {} };
  out.codebookVersion = Number.isInteger(q.codebookVersion) ? q.codebookVersion : 0;
  return out;
}
const bump = q => { q.codebookVersion = (q.codebookVersion || 0) + 1; };

// ---- documents --------------------------------------------------------------
/** A new document. `text` is kept with Unix line ends; returns its id. */
export function addDocument(s, { name, text, kind = 'document', source = null, caseId = null }) {
  const q = qualOf(s), body = String(text ?? '').replace(/\r\n?/g, '\n');
  const d = { id: uid('d'), name: clean(name) || 'Untitled', kind, text: body, source, caseId, speakers: {}, version: 1, at: now() };
  if (kind === 'document' && parseTurns(body).length >= 2) d.kind = 'transcript';
  q.documents.push(d);
  return d.id;
}
export const docById = (s, id) => readQual(s).documents.find(d => d.id === id) || null;

/** Removes documents with their codings and the memos on them and on their codings. */
export function removeDocuments(s, ids) {
  const q = qualOf(s), gone = new Set(ids);
  const lost = new Set(q.codings.filter(x => gone.has(x.docId)).map(x => x.id));
  q.documents = q.documents.filter(d => !gone.has(d.id));
  q.codings = q.codings.filter(x => !gone.has(x.docId));
  q.memos = q.memos.filter(m => !(m.kind === 'document' && gone.has(m.target)) && !(m.kind === 'coding' && lost.has(m.target)));
  pruneFramework(q);
}
export function renameDocument(s, id, name) { const d = qualOf(s).documents.find(x => x.id === id); if (d && clean(name)) d.name = clean(name); }

// ---- the edit model ---------------------------------------------------------
/**
 * Where a range lands after the text in [at, at + removed) is replaced by
 * `inserted` characters. Text inserted exactly at a range's start or end stays
 * outside it; a replacement inside or at the edge of a range stays inside it.
 * Returns [start, end], or null when the range's text was deleted entirely.
 */
export function shiftRange(start, end, at, removed, inserted) {
  const delta = inserted - removed, stop = at + removed;
  const mapStart = p => (p <= at ? p : p >= stop ? p + delta : at);
  const mapEnd = p => (p <= at ? p : p >= stop ? p + delta : at + inserted);
  let a = mapStart(start), b = mapEnd(end);
  if (removed === 0 && start === at) a = start + delta;   // an insertion at the start is outside
  if (removed === 0 && end === at) b = end;
  return b > a ? [a, b] : null;
}

/** The one edited region between two texts: { at, removed, inserted }, or null when equal. */
export function diffText(before, after) {
  const a = String(before ?? ''), b = String(after ?? '');
  if (a === b) return null;
  let p = 0; const max = Math.min(a.length, b.length);
  while (p < max && a[p] === b[p]) p++;
  let e = 0;
  while (e < max - p && a[a.length - 1 - e] === b[b.length - 1 - e]) e++;
  return { at: p, removed: a.length - p - e, inserted: b.length - p - e };
}

function shiftCodings(q, docId, at, removed, inserted) {
  const drop = new Set();
  for (const x of q.codings) {
    if (x.docId !== docId) continue;
    const r = shiftRange(x.start, x.end, at, removed, inserted);
    if (r) [x.start, x.end] = r; else drop.add(x.id);
  }
  if (drop.size) { q.codings = q.codings.filter(x => !drop.has(x.id)); q.memos = q.memos.filter(m => !(m.kind === 'coding' && drop.has(m.target))); }
  return drop.size;
}

/** Replaces a document's text, moving its codings with the edit. Returns { dropped } codings whose text was deleted. */
export function editText(s, docId, text) {
  const q = qualOf(s), d = q.documents.find(x => x.id === docId); if (!d) return { dropped: 0 };
  const next = String(text ?? '').replace(/\r\n?/g, '\n'), e = diffText(d.text, next);
  if (!e) return { dropped: 0 };
  const dropped = shiftCodings(q, docId, e.at, e.removed, e.inserted);
  d.text = next; d.version = (d.version || 1) + 1; d.editedAt = now();
  return { dropped };
}

/** Several replacements [{ start, end, text }] (not overlapping) applied at once, codings moved through each. */
export function replaceRanges(s, docId, reps) {
  const q = qualOf(s), d = q.documents.find(x => x.id === docId); if (!d) return { dropped: 0 };
  let text = d.text, dropped = 0;
  for (const r of [...reps].sort((a, b) => b.start - a.start)) {
    text = text.slice(0, r.start) + r.text + text.slice(r.end);
    dropped += shiftCodings(q, docId, r.start, r.end - r.start, r.text.length);
  }
  d.text = text; d.version = (d.version || 1) + 1; d.editedAt = now();
  return { dropped };
}

// ---- codes ----------------------------------------------------------------
/** A short label for a code: its initials, or its first letters, unique among `taken` (lower case). */
export function shortFor(label, taken = new Set()) {
  const words = clean(label).split(' ').filter(w => /[\p{L}\d]/u.test(w));
  let base = words.length > 1 ? words.slice(0, 3).map(w => w.match(/[\p{L}\d]/u)[0]).join('') : (words[0] || 'C').replace(/[^\p{L}\d]/gu, '').slice(0, 3);
  base = base.toUpperCase() || 'C';
  if (!taken.has(base.toLowerCase())) return base;
  for (let i = 2; ; i++) if (!taken.has(`${base}${i}`.toLowerCase())) return `${base}${i}`;
}
const takenShorts = (q, except) => new Set(q.codes.filter(c => c.id !== except).map(c => String(c.short || '').toLowerCase()));

/** A code by label, reusing one already named the same (ignoring case). Returns its id. */
export function ensureCode(s, label, { parent = null, description = '' } = {}) {
  const q = qualOf(s), name = clean(label).slice(0, 120);
  if (!name) return null;
  const found = q.codes.find(c => c.label.toLowerCase() === name.toLowerCase());
  if (found) return found.id;
  const c = { id: uid('k'), label: name, short: shortFor(name, takenShorts(q)), parent: q.codes.some(x => x.id === parent) ? parent : null, description: String(description || ''), at: now() };
  q.codes.push(c); bump(q);
  return c.id;
}

/** An in-vivo code: the participant's own words, collapsed and cut to 60 characters. */
export const inVivoLabel = text => { const t = clean(text).replace(/^["'“‘]+|["'”’]+$/g, ''); return t.length > 60 ? `${t.slice(0, 59).replace(/\s+\S*$/, '')}…` : t; };

/** Renames a code. A code renamed to another code's name merges into it. */
export function renameCode(s, id, label) {
  const q = qualOf(s), name = clean(label).slice(0, 120), c = q.codes.find(x => x.id === id);
  if (!name || !c) return;
  const twin = q.codes.find(x => x.id !== id && x.label.toLowerCase() === name.toLowerCase());
  if (twin) { mergeCodes(s, [id], twin.id); return; }
  c.label = name; bump(q);
}
export function setShort(s, id, short) {
  const q = qualOf(s), c = q.codes.find(x => x.id === id), v = clean(short).slice(0, 6);
  if (!c || !v || takenShorts(q, id).has(v.toLowerCase())) return false;
  c.short = v; bump(q); return true;
}
export function setDescription(s, id, text) { const q = qualOf(s), c = q.codes.find(x => x.id === id); if (c) { c.description = String(text ?? ''); bump(q); } }

export const childrenOf = (s, id) => readQual(s).codes.filter(c => (c.parent || null) === (id || null));
/** Ids of every code beneath `id`, depth first. */
export function descendants(s, id) {
  const out = [], walk = p => { for (const c of childrenOf(s, p)) { out.push(c.id); walk(c.id); } };
  walk(id); return out;
}
/** 'Parent › Child' */
export function pathOf(s, id) {
  const q = readQual(s), byId = new Map(q.codes.map(c => [c.id, c])), parts = [];
  for (let c = byId.get(id), n = 0; c && n < 64; c = byId.get(c.parent), n++) parts.unshift(c.label);
  return parts.join(' › ');
}
/** The codebook depth first: [{ code, depth }], siblings in their stored order. */
export function codeTree(s) {
  const q = readQual(s), ids = new Set(q.codes.map(c => c.id)), out = [];
  const walk = (p, depth) => { for (const c of q.codes.filter(x => (ids.has(x.parent) ? x.parent : null) === p)) { out.push({ code: c, depth }); if (depth < 32) walk(c.id, depth + 1); } };
  walk(null, 0); return out;
}

/** Moves a code under another (or to the top with null). Refuses itself and its own descendants. */
export function setParent(s, id, parentId) {
  const q = qualOf(s), c = q.codes.find(x => x.id === id);
  if (!c) return false;
  const p = parentId || null;
  if (p === id || (p && !q.codes.some(x => x.id === p)) || (p && descendants(s, id).includes(p))) return false;
  c.parent = p;
  // it goes last among its new siblings
  q.codes = [...q.codes.filter(x => x.id !== id), c];
  bump(q); return true;
}
/** Indent: under the sibling just above it. Outdent: beside its parent, just after it. */
export function indent(s, id) {
  const q = readQual(s), c = q.codes.find(x => x.id === id); if (!c) return false;
  const sibs = q.codes.filter(x => (x.parent || null) === (c.parent || null)), i = sibs.findIndex(x => x.id === id);
  return i > 0 ? setParent(s, id, sibs[i - 1].id) : false;
}
export function outdent(s, id) {
  const q = qualOf(s), c = q.codes.find(x => x.id === id); if (!c?.parent) return false;
  const parent = q.codes.find(x => x.id === c.parent);
  c.parent = parent?.parent || null;
  const rest = q.codes.filter(x => x.id !== id), at = rest.findIndex(x => x.id === parent?.id);
  rest.splice(at + 1, 0, c); q.codes = rest; bump(q);
  return true;
}

/** Folds codes into one: codings, children, theme membership, memos and framework cells move to it. */
export function mergeCodes(s, fromIds, intoId) {
  const q = qualOf(s), from = new Set(fromIds.filter(x => x !== intoId));
  const into = q.codes.find(c => c.id === intoId);
  if (!from.size || !into) return;
  // children of the merged codes move under the target; the target itself,
  // and any code above it, move up past the codes that are going away
  const byId = new Map(q.codes.map(c => [c.id, c]));
  const up = p => { for (let n = 0; p && from.has(p) && n < 64; n++) p = byId.get(p)?.parent || null; return p; };
  into.parent = up(into.parent);
  const above = new Set();
  for (let p = into.parent, n = 0; p && n < 64; p = byId.get(p)?.parent, n++) above.add(p);
  for (const c of q.codes) if (c.id !== intoId && from.has(c.parent)) c.parent = above.has(c.id) ? up(c.parent) : intoId;
  for (const x of q.codings) if (x.codeIds.some(id => from.has(id))) x.codeIds = [...new Set(x.codeIds.map(id => (from.has(id) ? intoId : id)))];
  const memo = [memoOf(s, 'code', intoId), ...[...from].map(id => memoOf(s, 'code', id))].filter(Boolean).join('\n\n');
  q.memos = q.memos.filter(m => !(m.kind === 'code' && from.has(m.target)));
  if (memo) setMemo(s, 'code', intoId, memo);
  into.description = [into.description, ...q.codes.filter(c => from.has(c.id)).map(c => c.description)].filter(Boolean).join('\n\n');
  const cells = q.framework.cells;
  for (const k of Object.keys(cells)) {
    const [row, col] = k.split('|');
    if (!from.has(col)) continue;
    const to = `${row}|${intoId}`;
    cells[to] = [cells[to], cells[k]].filter(Boolean).join('\n\n');
    delete cells[k];
  }
  q.codes = q.codes.filter(c => !from.has(c.id));
  viaQes(s, x => { x.qes.codes.push(...[...from].map(id => ({ id }))); qesMerge(x, 'code', [...from], intoId); });
  bump(q);
}

/** A new code beside `id` taking the chosen codings from it. Returns the new code's id. */
export function splitCode(s, id, codingIds, label) {
  const q = qualOf(s), c = q.codes.find(x => x.id === id), name = clean(label);
  if (!c || !name || q.codes.some(x => x.label.toLowerCase() === name.toLowerCase())) return null;
  const nid = ensureCode(s, name, { parent: c.parent });
  const move = new Set(codingIds);
  for (const x of q.codings) if (move.has(x.id) && x.codeIds.includes(id)) x.codeIds = [...new Set(x.codeIds.map(k => (k === id ? nid : k)))];
  return nid;
}

/** Deletes codes. Their children move up to the nearest surviving ancestor; codings left without a code go. */
export function deleteCodes(s, ids) {
  const q = qualOf(s), gone = new Set(ids), byId = new Map(q.codes.map(c => [c.id, c]));
  const up = p => { while (p && gone.has(p)) p = byId.get(p)?.parent || null; return p; };
  for (const c of q.codes) if (!gone.has(c.id) && gone.has(c.parent)) c.parent = up(c.parent);
  q.codes = q.codes.filter(c => !gone.has(c.id));
  for (const x of q.codings) x.codeIds = x.codeIds.filter(id => !gone.has(id));
  const empty = new Set(q.codings.filter(x => !x.codeIds.length).map(x => x.id));
  q.codings = q.codings.filter(x => !empty.has(x.id));
  q.memos = q.memos.filter(m => !(m.kind === 'code' && gone.has(m.target)) && !(m.kind === 'coding' && empty.has(m.target)));
  viaQes(s, x => { x.qes.codes.push(...[...gone].map(id => ({ id }))); qesRemove(x, 'code', [...gone]); });
  pruneFramework(q);
  bump(q);
}

// ---- codings ----------------------------------------------------------------
/**
 * Codes a range. A range the same coder already coded exactly gains the codes
 * instead of a second coding. Returns the coding's id, or null when invalid.
 */
export function addCoding(s, { docId, start, end, codeIds, coder = null, exemplar = false, weight = null }) {
  const q = qualOf(s), d = q.documents.find(x => x.id === docId);
  const codes = [...new Set(codeIds || [])].filter(id => q.codes.some(c => c.id === id));
  if (!d || !codes.length || !Number.isInteger(start) || !Number.isInteger(end)) return null;
  // trim surrounding space: a selection that ran past a word is the word
  while (start < end && /\s/.test(d.text[start])) start++;
  while (end > start && /\s/.test(d.text[end - 1])) end--;
  if (start < 0 || end > d.text.length || start >= end) return null;
  const who = coder ?? (q.coder || '');
  const same = q.codings.find(x => x.docId === docId && x.start === start && x.end === end && (x.coder || '') === who);
  if (same) { same.codeIds = [...new Set([...same.codeIds, ...codes])]; same.at = now(); return same.id; }
  const x = { id: uid('g'), docId, start, end, codeIds: codes, coder: who, at: now(), exemplar: !!exemplar, weight: validWeight(weight) };
  q.codings.push(x);
  return x.id;
}
const validWeight = w => (w === null || w === '' || w === undefined ? null : Number.isFinite(Number(w)) ? Number(w) : null);
/** Takes codes off a coding; a coding left with none is deleted. */
export function uncode(s, codingId, codeIds) {
  const q = qualOf(s), x = q.codings.find(c => c.id === codingId); if (!x) return;
  x.codeIds = x.codeIds.filter(id => !codeIds.includes(id));
  if (!x.codeIds.length) deleteCodings(s, [codingId]);
}
export function deleteCodings(s, ids) {
  const q = qualOf(s), gone = new Set(ids);
  q.codings = q.codings.filter(x => !gone.has(x.id));
  q.memos = q.memos.filter(m => !(m.kind === 'coding' && gone.has(m.target)));
}
export function setExemplar(s, id, on) { const x = qualOf(s).codings.find(c => c.id === id); if (x) x.exemplar = !!on; }
export function setWeight(s, id, w) { const x = qualOf(s).codings.find(c => c.id === id); if (!x) return false; const v = validWeight(w); if (w !== null && w !== '' && v === null) return false; x.weight = v; return true; }
export const textOf = (s, x) => (docById(s, x.docId)?.text || '').slice(x.start, x.end);

/** The most recently applied codes, newest first, at most `n`. */
export function recentCodes(s, n = 9) {
  const q = readQual(s), ids = new Set(q.codes.map(c => c.id)), out = [];
  for (const x of [...q.codings].sort((a, b) => String(b.at).localeCompare(String(a.at))))
    for (const id of x.codeIds) if (ids.has(id) && !out.includes(id)) { out.push(id); if (out.length >= n) return out; }
  return out;
}

// ---- memos ------------------------------------------------------------------
export const MEMO_KINDS = ['code', 'document', 'case', 'coding'];
export const memoOf = (s, kind, target) => readQual(s).memos.find(m => m.kind === kind && m.target === target)?.text || '';
/** Sets the memo on a code, document, case or coding; empty text removes it. */
export function setMemo(s, kind, target, text, by = '') {
  if (!MEMO_KINDS.includes(kind)) return;
  const q = qualOf(s), body = String(text ?? '').trim(), m = q.memos.find(x => x.kind === kind && x.target === target);
  if (!body) { q.memos = q.memos.filter(x => x !== m); return; }
  if (m) { m.text = body; m.at = now(); if (by) m.by = by; } else q.memos.push({ id: uid('m'), kind, target, text: body, by, at: now() });
}

// ---- cases of a coding --------------------------------------------------------
/** The case a coding belongs to: its speaker's case in a transcript, else its document's case, else null. */
export function caseOfCoding(s, x, turnsCache = new Map()) {
  const d = docById(s, x.docId); if (!d) return null;
  const map = d.speakers || {};
  if (Object.keys(map).length) {
    if (!turnsCache.has(d.id)) turnsCache.set(d.id, parseTurns(d.text));
    const t = turnAt(turnsCache.get(d.id), x.start);
    const hit = t && Object.entries(map).find(([k]) => k.toLowerCase() === t.speaker.toLowerCase());
    if (hit?.[1]) return hit[1];
  }
  return d.caseId || null;
}
/** Cases whose data a document holds: its own and its speakers'. */
export const casesOfDocument = d => [...new Set([d.caseId, ...Object.values(d.speakers || {})].filter(Boolean))];

// ---- themes: the synthesis theme model (lib/qes.mjs) over this codebook ------
// qes.mjs keeps themes in s.qes; here they live in s.qual, so its functions run
// on a stand-in whose lists are this workspace's and are written back after.
function viaQes(s, fn) {
  const q = qualOf(s);
  const shim = { qes: { codes: q.codes.map(c => ({ id: c.id, label: c.label })), quotes: [], descriptive: q.descriptive, analytical: q.analytical } };
  const r = fn(shim);
  q.descriptive = shim.qes.descriptive; q.analytical = shim.qes.analytical;
  return r;
}
export const addQualTheme = (s, level, label, members = []) => viaQes(s, x => addTheme(x, level, label, members));
export const setQualMembers = (s, level, id, members, on = true) => viaQes(s, x => setMembers(x, level, id, members, on));
export const mergeQualThemes = (s, level, ids, into) => viaQes(s, x => qesMerge(x, level, ids, into));
export const removeQualThemes = (s, level, ids) => viaQes(s, x => qesRemove(x, level, ids));
export const renameQualTheme = (s, level, id, label) => viaQes(s, x => qesRename(x, level, id, label));
export const setQualStatement = (s, id, text) => viaQes(s, x => setStatement(x, id, text));
/** Code ids a theme gathers, with every code beneath them in the tree. */
export function codesOfTheme(s, level, id) {
  const q = readQual(s);
  const direct = level === 'code' ? [id] : level === 'descriptive' ? q.descriptive.find(t => t.id === id)?.codes || []
    : (q.analytical.find(t => t.id === id)?.themes || []).flatMap(d => q.descriptive.find(t => t.id === d)?.codes || []);
  return [...new Set(direct.flatMap(c => [c, ...descendants(s, c)]))];
}

function pruneFramework(q) {
  const rows = new Set([...q.cases.map(c => c.id), ...q.documents.map(d => d.id)]);
  const cols = new Set([...q.codes.map(c => c.id), ...q.descriptive.map(t => t.id), ...q.analytical.map(t => t.id)]);
  for (const k of Object.keys(q.framework.cells)) { const [r, c] = k.split('|'); if (!rows.has(r) || !cols.has(c)) delete q.framework.cells[k]; }
}
export { pruneFramework };

// The project's reading list: which papers to read, which are being read,
// which are read, with a priority and a short reason (amendment "Workspace:
// backup, dashboard, tasks, timeline and translation").
//
//   state.reading  { [paperId]: { status: 'to-read'|'reading'|'read', priority: 'none'|'low'|'high', reason, at } }
//
// A paper is on the list when it has an entry; clearing its status takes it
// off. It is set from the Library (a row's Reading menu, the paper's details)
// and listed, filtered, in Notes › Reading list. Pure.

export const READING_STATUSES = [['to-read', 'To read'], ['reading', 'Reading'], ['read', 'Read']];
export const READING_PRIORITIES = [['none', 'No priority'], ['low', 'Low'], ['high', 'High']];
const STATUS = new Set(READING_STATUSES.map(([k]) => k)), PRIORITY = new Set(READING_PRIORITIES.map(([k]) => k));
export const statusLabel = k => READING_STATUSES.find(([id]) => id === k)?.[1] || '';

const clean = e => ({ status: e.status, priority: PRIORITY.has(e.priority) ? e.priority : 'none', reason: String(e.reason || '').slice(0, 280), at: String(e.at || '') });

/** The stored list, with every entry valid; an entry without a known status is dropped. */
export function normaliseReading(r) {
  if (!r || typeof r !== 'object' || Array.isArray(r)) return {};
  return Object.fromEntries(Object.entries(r).filter(([id, e]) => id && e && STATUS.has(e.status)).map(([id, e]) => [id, clean(e)]));
}

/** A paper's entry, or null when it is not on the list. */
export const readingOf = (state, paperId) => {
  const e = state?.reading?.[paperId];
  return e && STATUS.has(e.status) ? clean(e) : null;
};

/**
 * Sets part of a paper's entry in place: `{ status, priority, reason }`.
 * A status of '' removes the paper from the list; a priority or reason for a
 * paper not yet on it puts it on as To read.
 */
export function setReading(state, paperId, patch, at = new Date().toISOString()) {
  if (!paperId) return null;
  const was = readingOf(state, paperId);
  if ('status' in patch && !patch.status) {
    if (state.reading) delete state.reading[paperId];
    return null;
  }
  const next = clean({ ...(was || { status: 'to-read' }), ...patch, at });
  if (!STATUS.has(next.status)) return was;
  state.reading = { ...(state.reading || {}), [paperId]: next };
  return next;
}

const RANK = { high: 0, low: 1, none: 2 }, ORDER = { reading: 0, 'to-read': 1, read: 2 };
/**
 * The list as rows `{ paper, entry }` for papers still in the library,
 * filtered by `{ status: 'all'|'open'|<status>, priority: 'any'|<priority>, text }`
 * and ordered: reading, then to read, then read; high priority first; then
 * most recently set.
 */
export function readingRows(state, { status = 'open', priority = 'any', text = '' } = {}) {
  const papers = new Map((state?.papers || []).map(p => [p.id, p]));
  const q = String(text || '').trim().toLowerCase();
  return Object.entries(normaliseReading(state?.reading))
    .filter(([id]) => papers.has(id))
    .map(([id, entry]) => ({ paper: papers.get(id), entry }))
    .filter(({ paper, entry }) => (status === 'all' || (status === 'open' ? entry.status !== 'read' : entry.status === status))
      && (priority === 'any' || entry.priority === priority)
      && (!q || [paper.title, paper.label, entry.reason, ...(paper.authors || []).map(a => typeof a === 'string' ? a : a?.name || '')].join(' ').toLowerCase().includes(q)))
    .sort((a, b) => ORDER[a.entry.status] - ORDER[b.entry.status] || RANK[a.entry.priority] - RANK[b.entry.priority] || b.entry.at.localeCompare(a.entry.at));
}

/** How many papers are in each status (papers still in the library only). */
export function readingCounts(state) {
  const out = { 'to-read': 0, reading: 0, read: 0 };
  for (const { entry } of readingRows(state, { status: 'all' })) out[entry.status]++;
  return out;
}

