/** The types a new project offers first (the researcher's own: reviews and case reports); the rest are one disclosure away (A21). */
export const DEFAULT_TYPES = ['systematic-review', 'meta-analysis', 'scoping-review', 'case-series', 'case-report'];
export const typeById = id => RESEARCH_TYPES.find(t => t.id === id) || null;
/** The start screen's groups, in registry order. */
export const TYPE_GROUPS = [...new Set(RESEARCH_TYPES.map(t => t.group))].map(g => [g, RESEARCH_TYPES.filter(t => t.group === g).map(t => t.id)]);
export const isPrimaryType = t => (typeof t === 'string' ? typeById(t) : t)?.kind === 'primary';
export const isReviewType = t => (typeof t === 'string' ? typeById(t) : t)?.kind === 'review';
export const questionFrameOf = t => (typeof t === 'string' ? typeById(t) : t)?.question || PICO;
export const questionLabelOf = t => (typeof t === 'string' ? typeById(t) : t)?.questionLabel || 'Research question';
export const layoutOf = id => typeById(id)?.layout || typeById('other').layout;

/** The type's name where a line is short (the title bar's status: 24 characters at most): its brief name, else its label. */
export const typeBrief = type => type?.brief || type?.label || '';

// Risk-of-bias assessments per outcome, by two reviewers, reconciled (plan H3).
//
// RoB 2 judges a result and ROBINS-I an outcome, so an assessment is kept per
// study and level: 'study' (the default, and every assessment made before
// levels existed) or an outcome id. A study assessed only at study level uses
// that assessment for every outcome; an outcome assessed on its own uses its
// own.
//
// With a second reviewer, reviewer A and reviewer B answer independently; a
// domain on which they differ is a discrepancy until a resolved value is
// recorded with its reason; the final judgement of a domain is the agreed or
// resolved one. When every domain has a final judgement and none is open, the
// consensus can be confirmed; any later change clears the confirmation.
//
//   s.robReview = { second: false, records: { [paperId]: { [toolId]: { [level]: {
//     a: { d1: 'Low', … }, b: { … }, resolved: { d1: { value, reason, at } }, consensus: { at } | null } } } } }
//
// `s.assessments[paperId][toolId]` keeps the final study-level judgements,
// the shape every other reader (figures, results, bundle, certainty) knows;
// it is rewritten from these records on every change. With one reviewer it is
// reviewer A's answers, exactly as before.
//
// Pure (no store import): the view, the migration in normalizeProject and the
// tests call it with the state.
export const STUDY = 'study';
export const OVERALL = 'overall';

// Instruments judged per result or outcome; the others appraise a study as a whole.
export const PER_OUTCOME = new Set(['rob2', 'robins-i', 'robins-e', 'rob-me']);

const isInstrument = (k, toolIds) => toolIds.includes(k);
/** A study's answers as stored before reviewers and levels: per instrument, or the flat RoB 2 shape. */
export function legacyAnswers(rec, toolId, toolIds) {
  if (!rec) return {};
  if (rec[toolId]) return { ...rec[toolId] };
  return toolId === 'rob2' ? Object.fromEntries(Object.entries(rec).filter(([k]) => !isInstrument(k, toolIds))) : {};
}

export const secondOn = s => Boolean(s.robReview?.second);
export const recordOf = (s, paperId, toolId, level = STUDY) => s.robReview?.records?.[paperId]?.[toolId]?.[level] || null;
const has = o => o && Object.keys(o).length > 0;

/** The domain ids an instrument asks, with its overall when it has one. */
export const domainIds = tool => [...tool.domains.map(d => d.id), ...(tool.overall ? [OVERALL] : [])];

/** Reviewer A's or B's answers at a level. */
export const answersBy = (s, paperId, toolId, level, who) => ({ ...(recordOf(s, paperId, toolId, level)?.[who === 'b' ? 'b' : 'a'] || {}) });

/**
 * The final judgements at a level: reviewer A's with one reviewer; with two,
 * each domain the reviewers agree on or that has a resolved value.
 */
export function finalAnswers(s, paperId, toolId, level = STUDY) {
  const r = recordOf(s, paperId, toolId, level);
  if (!r) return {};
  if (!secondOn(s)) return { ...(r.a || {}) };
  const out = {}, a = r.a || {}, b = r.b || {}, res = r.resolved || {};
  for (const d of new Set([...Object.keys(a), ...Object.keys(b), ...Object.keys(res)])) {
    if (res[d]?.value) out[d] = res[d].value;
    else if (a[d] && a[d] === b[d]) out[d] = a[d];
  }
  return out;
}

/** Whether a level has an assessment of its own (made its own, or any answer by either reviewer). */
export const assessedAt = (s, paperId, toolId, level) => { const r = recordOf(s, paperId, toolId, level); return Boolean(r?.own) || has(r?.a) || has(r?.b); };

/**
 * The judgements that apply to a study for an outcome: the outcome's own
 * assessment when it has one, else the study-level one. `level` 'study'
 * gives the study level.
 */
export function effectiveAnswers(s, paperId, toolId, level = STUDY) {
  if (level !== STUDY && assessedAt(s, paperId, toolId, level)) return { level, answers: finalAnswers(s, paperId, toolId, level) };
  return { level: STUDY, answers: finalAnswers(s, paperId, toolId, STUDY) };
}

/**
 * The domains the reviewers judged differently at a level:
 * [{ domain, a, b, resolved: { value, reason } | null, state: 'open' | 'resolved' }],
 * and the ones only one reviewer has judged (state 'waiting').
 */
export function discrepancies(s, paperId, tool, level = STUDY) {
  const r = recordOf(s, paperId, tool.id, level) || {}, a = r.a || {}, b = r.b || {}, res = r.resolved || {};
  const out = [];
  for (const d of domainIds(tool)) {
    if (!a[d] && !b[d]) continue;
    if (a[d] && b[d] && a[d] === b[d]) continue;
    const resolved = res[d]?.value ? res[d] : null;
    out.push({ domain: d, a: a[d] || '', b: b[d] || '', resolved, state: a[d] && b[d] ? (resolved ? 'resolved' : 'open') : 'waiting' });
  }
  return out;
}

/**
 * Where a level's reconciliation stands: 'single' (one reviewer), 'empty',
 * 'waiting' (a domain judged by one reviewer only), 'open' (a discrepancy
 * without a resolved value), 'ready' (every domain final, not confirmed),
 * 'agreed' (consensus confirmed).
 */
export function consensusState(s, paperId, tool, level = STUDY) {
  if (!secondOn(s)) return { state: 'single', open: 0 };
  const r = recordOf(s, paperId, tool.id, level);
  if (!has(r?.a) && !has(r?.b)) return { state: 'empty', open: 0 };
  const list = discrepancies(s, paperId, tool, level);
  const open = list.filter(x => x.state === 'open').length, waiting = list.filter(x => x.state === 'waiting').length;
  const final = finalAnswers(s, paperId, tool.id, level);
  const complete = domainIds(tool).every(d => final[d]);
  if (open) return { state: 'open', open };
  if (waiting || !complete) return { state: 'waiting', open: 0, waiting };
  return { state: r.consensus ? 'agreed' : 'ready', open: 0, at: r.consensus?.at || null };
}

// ---- writing (reducers: they change the state passed in and return it) ----------

function ensure(st, paperId, toolId, level) {
  st.robReview = { second: false, records: {}, ...(st.robReview || {}) };
  const rec = st.robReview.records = { ...(st.robReview.records || {}) };
  rec[paperId] = { ...(rec[paperId] || {}) };
  rec[paperId][toolId] = { ...(rec[paperId][toolId] || {}) };
  return rec[paperId][toolId][level] = { a: {}, b: {}, resolved: {}, consensus: null, ...(rec[paperId][toolId][level] || {}) };
}
function tidy(st, paperId, toolId, level) {
  const t = st.robReview.records[paperId]?.[toolId];
  const r = t?.[level];
  if (r && !r.own && !has(r.a) && !has(r.b) && !has(r.resolved) && !r.context) delete t[level];
  if (t && !has(t)) delete st.robReview.records[paperId][toolId];
  if (st.robReview.records[paperId] && !has(st.robReview.records[paperId])) delete st.robReview.records[paperId];
}

/**
 * Keeps `assessments[paperId][toolId]` equal to the final study-level
 * judgements, dropping the flat pre-instrument keys as the view always did.
 */
export function mirror(st, paperId, toolId, toolIds) {
  st.assessments = st.assessments || {};
  const rec = st.assessments[paperId] ? { ...st.assessments[paperId] } : {};
  for (const k of Object.keys(rec)) if (!isInstrument(k, toolIds)) delete rec[k];
  const final = finalAnswers(st, paperId, toolId, STUDY);
  if (has(final)) rec[toolId] = final; else delete rec[toolId];
  if (has(rec)) st.assessments[paperId] = rec; else delete st.assessments[paperId];
  return st;
}

/** One reviewer's judgement of one domain; '' clears it. Clears a confirmed consensus. */
export function setAnswer(st, { paperId, toolId, level = STUDY, who = 'a', domain, value, toolIds }) {
  const r = ensure(st, paperId, toolId, level), side = who === 'b' ? 'b' : 'a';
  r[side] = { ...r[side] };
  if (value) r[side][domain] = value; else delete r[side][domain];
  // a resolution stays only while it settles a difference that still exists
  const other = r[side === 'a' ? 'b' : 'a'][domain];
  if (r.resolved?.[domain] && (!value || !other || value === other)) { r.resolved = { ...r.resolved }; delete r.resolved[domain]; }
  r.consensus = null;
  tidy(st, paperId, toolId, level);
  if (level === STUDY) mirror(st, paperId, toolId, toolIds);
  return st;
}

/** The resolved value of a discrepant domain, with its reason (both required); '' removes it. */
export function resolveDomain(st, { paperId, toolId, level = STUDY, domain, value, reason = '', toolIds }) {
  const why = String(reason || '').trim();
  if (value && !why) return st;
  const r = ensure(st, paperId, toolId, level);
  r.resolved = { ...(r.resolved || {}) };
  if (value) r.resolved[domain] = { value, reason: why, at: new Date().toISOString() };
  else delete r.resolved[domain];
  r.consensus = null;
  tidy(st, paperId, toolId, level);
  if (level === STUDY) mirror(st, paperId, toolId, toolIds);
  return st;
}

/** Confirms (or withdraws) the consensus of a level; only a level whose state is 'ready' can be confirmed. */
/** A level's assessment context: `{ target, scope }`, the result assessed and the scope of the appraisal, as the decision log prints them. */
export const contextOf = (s, paperId, toolId, level = STUDY) => ({ target: '', scope: '', ...(recordOf(s, paperId, toolId, level)?.context || {}) });
/** Sets the context of a level; both blank removes it. */
export function setContext(st, { paperId, toolId, level = STUDY, target = '', scope = '' }) {
  const r = ensure(st, paperId, toolId, level);
  const t = String(target || '').trim(), sc = String(scope || '').trim();
  if (t || sc) r.context = { target: t, scope: sc }; else delete r.context;
  tidy(st, paperId, toolId, level);
  return st;
}

export function confirmConsensus(st, { paperId, tool, level = STUDY, on = true }) {
  if (on && consensusState(st, paperId, tool, level).state !== 'ready') return st;
  const r = ensure(st, paperId, tool.id, level);
  r.consensus = on ? { at: new Date().toISOString() } : null;
  return st;
}

/** Turns the second reviewer on or off; answers are kept, and the study-level mirror follows. */
export function setSecond(st, on, toolIds) {
  st.robReview = { records: {}, ...(st.robReview || {}), second: Boolean(on) };
  for (const [paperId, byTool] of Object.entries(st.robReview.records)) for (const toolId of Object.keys(byTool)) mirror(st, paperId, toolId, toolIds);
  return st;
}

/**
 * Gives an outcome its own assessment, starting from each reviewer's
 * study-level answers (a reviewer then changes what differs for it).
 */
export function startLevel(st, { paperId, toolId, level, toolIds }) {
  if (level === STUDY) return st;
  const start = { a: answersBy(st, paperId, toolId, STUDY, 'a'), b: answersBy(st, paperId, toolId, STUDY, 'b') };
  const r = ensure(st, paperId, toolId, level);
  r.a = { ...start.a, ...r.a }; r.b = { ...start.b, ...r.b }; r.own = true; r.consensus = null;
  return st;
}

/** Removes an outcome-level assessment, so the study level applies again. */
export function clearLevel(st, { paperId, toolId, level }) {
  if (level === STUDY || !st.robReview?.records?.[paperId]?.[toolId]?.[level]) return st;
  delete st.robReview.records[paperId][toolId][level];
  tidy(st, paperId, toolId, STUDY);
  return st;
}

// ---- migration -------------------------------------------------------------------

/**
 * Brings a project to this shape: every study-level judgement in
 * `assessments` becomes reviewer A's answers at study level. With one
 * reviewer, `assessments` is what a person last saw and wins over a stale
 * record (it may have been written by a build before this one); with two,
 * the records are the source and `assessments` is rebuilt from them.
 */
export function migrateAssessments(st, toolIds) {
  const review = st.robReview && typeof st.robReview === 'object' ? st.robReview : {};
  st.robReview = { second: Boolean(review.second), records: review.records && typeof review.records === 'object' ? review.records : {} };
  for (const [paperId, rec] of Object.entries(st.assessments || {})) {
    if (!rec || typeof rec !== 'object') continue;
    for (const toolId of toolIds) {
      const answers = legacyAnswers(rec, toolId, toolIds);
      if (!has(answers)) continue;
      const cur = st.robReview.records[paperId]?.[toolId]?.[STUDY];
      if (cur && (st.robReview.second || JSON.stringify(cur.a || {}) === JSON.stringify(answers))) continue;
      const r = ensure(st, paperId, toolId, STUDY);
      r.a = answers;
    }
  }
  // with two reviewers the records rebuild the mirror; with one, a record the mirror lacks is shown there again
  for (const [paperId, byTool] of Object.entries(st.robReview.records)) for (const toolId of Object.keys(byTool || {})) {
    if (!toolIds.includes(toolId)) continue;
    if (st.robReview.second || !has(legacyAnswers(st.assessments?.[paperId], toolId, toolIds))) mirror(st, paperId, toolId, toolIds);
  }
  return st;
}

// ---- agreement ---------------------------------------------------------------------

/**
 * Cohen's kappa (unweighted) for one domain across studies at one level,
 * from the pairs where both reviewers answered: po the observed agreement,
 * pe the agreement expected from each reviewer's marginal proportions,
 * κ = (po − pe) / (1 − pe). Null with fewer than two pairs; κ is undefined
 * (null) when pe is 1.
 */
export function kappa(pairs) {
  const n = pairs.length;
  if (n < 2) return { n, kappa: null, po: null, pe: null };
  const cats = [...new Set(pairs.flat())];
  const po = pairs.filter(([x, y]) => x === y).length / n;
  const pe = cats.reduce((t, c) => t + (pairs.filter(p => p[0] === c).length / n) * (pairs.filter(p => p[1] === c).length / n), 0);
  return { n, po, pe, kappa: pe === 1 ? null : (po - pe) / (1 - pe) };
}

/** The reviewers' paired answers for a domain across studies at a level. */
export function pairsFor(s, paperIds, toolId, level, domain) {
  const out = [];
  for (const id of paperIds) {
    const r = recordOf(s, id, toolId, level);
    const x = r?.a?.[domain], y = r?.b?.[domain];
    if (x && y) out.push([x, y]);
  }
  return out;
}

// Which version of the screening rules a proposal was made under. The rules
// were stored whole on every proposal (12.6 KB each, 461 identical copies in
// the review's project) and whole again in every run's snapshot of the
// proposals it replaced — 50 MB of a project whose records are 2 MB. The only
// question ever asked of them is "are these the rules now in force?", so a
// proposal keeps a fingerprint and a run keeps one full copy for the record.
// A stored value may still be the old JSON text; both compare the same way.

// FNV-1a over the text, twice with different offsets: 16 hex digits.
function fnv(text, h) {
  for (let i = 0; i < text.length; i++) { h ^= text.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}
const hash = text => `rk:${fnv(text, 0x811c9dc5)}${fnv(text, 0x050c5d1f)}`;

/** The fingerprint of rules given as the rule list, its JSON text, or a fingerprint already. */
export function rulesKey(rules) {
  if (typeof rules === 'string') return rules.startsWith('rk:') ? rules : hash(rules);
  return hash(JSON.stringify(rules || []));
}
/** Whether two stored or current rule sets are the same rules. */
export const sameRules = (a, b) => rulesKey(a) === rulesKey(b);

/**
 * Shrinks what an older project carried: proposals keep a fingerprint, runs
 * keep one copy of their rules, and only the latest run and the latest batch
 * keep the snapshot they replaced. Returns the state, changed in place.
 */
export function compactScreening(s) {
  const fp = p => { if (p && typeof p.rulesSnapshot === 'string' && !p.rulesSnapshot.startsWith('rk:')) p.rulesSnapshot = rulesKey(p.rulesSnapshot); };
  const eachProposal = (map, fn) => { for (const stage of Object.values(map || {})) if (stage && typeof stage === 'object') for (const p of Object.values(stage)) { fn(p); fn(p?.jev); } };
  eachProposal(s.proposals, fp);
  const runs = s.jevRuns || [];
  runs.forEach((r, i) => {
    if (typeof r.rulesSnapshot === 'string' && !r.rulesSnapshot.startsWith('rk:')) { r.rules = r.rules || r.rulesSnapshot; r.rulesSnapshot = rulesKey(r.rulesSnapshot); }
    if (i < runs.length - 1) delete r.before;
    else if (r.before) for (const p of Object.values(r.before)) { fp(p); fp(p?.jev); }
  });
  const batches = s.screeningBatches || [];
  batches.forEach((b, i) => { if (i < batches.length - 1) delete b.before; });
  return s;
}

// Assignments and calibration batches (plan E4).
//
// A batch is a set of record ids, the reviewers who screen them and the stage
// they are screened at. A calibration batch is drawn at random (or stratified
// by source database) and screened by everyone; the rest can then be split
// between reviewers, with an optional overlap screened by two. Under dual
// screening, once a stage has batches a reviewer's queue is the records
// assigned to them, and a record's consensus needs the reviewers assigned to
// it (one for a record split to one person, two for calibration) rather than
// "any two". Reassigning a batch keeps its history; every change is logged.
//
// State: `screeningAssignments = [{ id, name, stage, kind, ids, reviewers,
// seed, strata, at, by, history: [{ at, by, action, from, to }] }]`.
// Batch state per reviewer (not started, in progress, complete) is read from
// the decisions, never stored, so it cannot drift from them.
import { update, persist } from '../store.mjs';

export const batchesOf = (s, stage = null) => (Array.isArray(s.screeningAssignments) ? s.screeningAssignments : []).filter(b => !stage || b.stage === stage);
// A random check sample (kind 'check', for the stopping estimate) is kept with
// the batches but assigns nothing: it never narrows a queue.
const assigning = (s, stage) => batchesOf(s, stage).filter(b => b.kind !== 'check');
/** The stage's random check sample, the latest drawn, or null. */
export const checkSample = (s, stage) => batchesOf(s, stage).filter(b => b.kind === 'check').at(-1) || null;

/** Normalised for storage (normalizeProject calls this). */
export function normalizeAssignments(v) {
  if (!Array.isArray(v)) return [];
  return v.filter(b => b && typeof b.id === 'string' && Array.isArray(b.ids) && Array.isArray(b.reviewers))
    .map(b => ({ ...b, stage: b.stage === 'ft' ? 'ft' : 'ta', ids: b.ids.map(String), reviewers: b.reviewers.map(r => String(r).trim()).filter(Boolean), history: Array.isArray(b.history) ? b.history : [] }));
}

/** The records assigned to a reviewer at a stage; null when the stage has no batches (everyone screens everything). */
export function assignedTo(s, stage, by) {
  const bs = assigning(s, stage); if (!bs.length) return null;
  const out = new Set();
  for (const b of bs) if (b.reviewers.includes(by)) for (const id of b.ids) out.add(id);
  return out;
}

/** The reviewers a record needs at a stage, from its batches; null when none assigns it. */
export function requiredFor(s, stage, id) {
  let out = null;
  for (const b of assigning(s, stage)) if (b.ids.includes(id)) { out ||= new Set(); for (const r of b.reviewers) out.add(r); }
  return out ? [...out] : null;
}

/** Record ids no batch of the stage holds, among `pool`. */
export function unassigned(s, stage, pool) {
  const held = new Set(assigning(s, stage).flatMap(b => b.ids));
  return pool.filter(id => !held.has(id));
}

// ---- random draws ----------------------------------------------------------
/** mulberry32: a small seeded generator, so a draw can be repeated from its seed. */
export function rng(seed) {
  let a = seed >>> 0;
  return () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
export function shuffle(list, rand) {
  const a = list.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

/**
 * n ids drawn from `pool` (ids), at random or stratified: `strataOf(id)`
 * names each record's stratum and every stratum gives its share (largest
 * remainders), so a 40-record sample of a 70/30 PubMed/Scopus pool has 28
 * and 12. Deterministic for a seed.
 */
export function drawSample(pool, n, { seed = 1, strataOf = null } = {}) {
  const rand = rng(seed); n = Math.min(n, pool.length);
  if (!strataOf) return shuffle(pool, rand).slice(0, n);
  const groups = new Map();
  for (const id of pool) { const k = strataOf(id) || ''; if (!groups.has(k)) groups.set(k, []); groups.get(k).push(id); }
  const keys = [...groups.keys()].sort();
  const exact = keys.map(k => groups.get(k).length * n / pool.length);
  const take = exact.map(Math.floor);
  let left = n - take.reduce((a, b) => a + b, 0);
  for (const i of exact.map((x, i) => [x - Math.floor(x), i]).sort((a, b) => b[0] - a[0] || a[1] - b[1]).map(x => x[1])) { if (left <= 0) break; take[i]++; left--; }
  return shuffle(keys.flatMap((k, i) => shuffle(groups.get(k), rand).slice(0, take[i])), rand);
}

/**
 * The records left after the calibration batch split between reviewers:
 * shuffled, dealt in turn, and a share `overlap` (0–1) of them also given to
 * the next reviewer, so some records are screened twice outside calibration.
 * Returns one batch per reviewer: `[{ reviewer, ids, overlap }]`.
 */
export function splitIds(ids, reviewers, { seed = 1, overlap = 0 } = {}) {
  const rand = rng(seed), order = shuffle(ids, rand), k = reviewers.length;
  const out = reviewers.map(r => ({ reviewer: r, ids: [], overlap: [] }));
  const twice = k > 1 ? Math.round(order.length * Math.max(0, Math.min(1, overlap))) : 0;
  order.forEach((id, i) => {
    out[i % k].ids.push(id);
    if (i < twice) { const second = out[(i + 1) % k]; second.ids.push(id); second.overlap.push(id); }
  });
  return out;
}

// ---- changes -----------------------------------------------------------------
const newId = () => `b-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const log = (s, entry) => { s.screeningLog = s.screeningLog || []; s.screeningLog.push({ ...entry, at: new Date().toISOString() }); };

/** Adds batches; each is logged. Returns their ids. */
export function addBatches(list, { by = '' } = {}) {
  const ids = [];
  update(s => {
    s.screeningAssignments = normalizeAssignments(s.screeningAssignments);
    for (const b of list) {
      const batch = { id: newId() + ids.length, name: b.name, stage: b.stage || 'ta', kind: b.kind || 'manual', ids: [...new Set(b.ids)], reviewers: [...new Set(b.reviewers)],
        ...(b.seed != null ? { seed: b.seed } : {}), ...(b.strata ? { strata: b.strata } : {}), ...(b.pool != null ? { pool: b.pool } : {}), at: new Date().toISOString(), by, history: [] };
      s.screeningAssignments.push(batch); ids.push(batch.id);
      log(s, { action: 'assign', stage: batch.stage, batch: batch.name, kind: batch.kind, count: batch.ids.length, reviewers: batch.reviewers.join(', '), by });
    }
    return s;
  });
  persist();
  return ids;
}

/** A batch handed from one reviewer to another; the change is kept in the batch's history and the log. */
export function reassign(batchId, from, to, { by = '' } = {}) {
  to = String(to || '').trim();
  if (!to) return;
  update(s => {
    const b = batchesOf(s).find(x => x.id === batchId); if (!b || !b.reviewers.includes(from) || from === to) return s;
    b.reviewers = [...new Set(b.reviewers.map(r => r === from ? to : r))];
    b.history = [...(b.history || []), { at: new Date().toISOString(), by, action: 'reassign', from, to }];
    log(s, { action: 'reassign', stage: b.stage, batch: b.name, from, to, by });
    return s;
  });
  persist();
}

/** A batch removed; decisions made in it stay. */
export function removeBatch(batchId, { by = '' } = {}) {
  update(s => {
    const b = batchesOf(s).find(x => x.id === batchId); if (!b) return s;
    s.screeningAssignments = batchesOf(s).filter(x => x.id !== batchId);
    log(s, { action: 'unassign', stage: b.stage, batch: b.name, count: b.ids.length, by });
    return s;
  });
  persist();
}

// ---- progress and agreement --------------------------------------------------
const own = (s, stage, id) => s.dual?.[stage]?.[id] || {};

/** Per reviewer of a batch: assigned, decided, and the state that follows. */
export function batchProgress(s, b) {
  return b.reviewers.map(r => {
    let decided = 0;
    for (const id of b.ids) { const d = own(s, b.stage, id)[r]; if (d && d.decision !== 'uncertain') decided++; }
    return { reviewer: r, assigned: b.ids.length, decided, state: !decided ? 'Not started' : decided >= b.ids.length ? 'Complete' : 'In progress' };
  });
}

/**
 * Cohen's kappa from paired ratings: `pairs` is `[[a, b], …]`, `cats` the
 * categories. Returns `{ n, po, pe, kappa }`; kappa is null with no pairs,
 * and 1 when both raters used a single identical category throughout.
 */
export function cohenKappa(pairs, cats = ['include', 'exclude', 'uncertain']) {
  const n = pairs.length; if (!n) return { n: 0, po: null, pe: null, kappa: null };
  const ma = Object.fromEntries(cats.map(c => [c, 0])), mb = { ...ma };
  let agree = 0;
  for (const [a, b] of pairs) { if (a === b) agree++; ma[a] = (ma[a] || 0) + 1; mb[b] = (mb[b] || 0) + 1; }
  const po = agree / n;
  const pe = Object.keys({ ...ma, ...mb }).reduce((acc, c) => acc + ((ma[c] || 0) / n) * ((mb[c] || 0) / n), 0);
  return { n, po, pe, kappa: pe === 1 ? (po === 1 ? 1 : 0) : (po - pe) / (1 - pe) };
}

/** Kappa between two reviewers over a set of records (those both decided). */
export function pairKappa(s, stage, ids, a, b) {
  const pairs = [];
  for (const id of ids) { const d = own(s, stage, id); if (d[a] && d[b]) pairs.push([d[a].decision, d[b].decision]); }
  return cohenKappa(pairs);
}

/**
 * Per reviewer, for the stage: records assigned and decided across batches,
 * and agreement on the calibration batches with each other reviewer.
 */
export function reviewerSummary(s, stage) {
  const bs = assigning(s, stage);
  const people = [...new Set(bs.flatMap(b => b.reviewers))].sort();
  const calib = bs.filter(b => b.kind === 'calibration').flatMap(b => b.ids);
  return people.map(r => {
    const ids = new Set(bs.filter(b => b.reviewers.includes(r)).flatMap(b => b.ids));
    let decided = 0; for (const id of ids) { const d = own(s, stage, id)[r]; if (d && d.decision !== 'uncertain') decided++; }
    const agreement = people.filter(o => o !== r).map(o => ({ with: o, ...pairKappa(s, stage, calib, r, o) }));
    return { reviewer: r, assigned: ids.size, decided, agreement };
  });
}

// Screening labels (plan E1, as Rayyan has them): words a review team puts on
// records ("Conference abstract", "Ask the second reviewer", "Paediatric subgroup"), several
// per record, that are not decisions. They filter the screening list and the
// Library, are listed in the decision log and exported with it.
//
// State: `screeningLabels = { list: [{ id, name }], of: { paperId: { labelId: by } } }`.
// Who put a label on is kept with it, so under blind dual screening a
// reviewer sees only their own (plan E3: labels are reviewer-specific and
// concealed too). Every change is appended to the screening log.
import { update, persist } from '../store.mjs';

const empty = () => ({ list: [], of: {} });
export const labelState = s => s.screeningLabels || empty();
export const labelList = s => labelState(s).list;

/** Normalised for storage (normalizeProject calls this). */
export function normalizeLabels(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return empty();
  const list = Array.isArray(v.list) ? v.list.filter(l => l && typeof l.id === 'string' && typeof l.name === 'string') : [];
  const ids = new Set(list.map(l => l.id));
  const of = {};
  for (const [pid, m] of Object.entries(v.of && typeof v.of === 'object' ? v.of : {})) {
    const keep = Object.fromEntries(Object.entries(m || {}).filter(([id]) => ids.has(id)).map(([id, by]) => [id, String(by || '')]));
    if (Object.keys(keep).length) of[pid] = keep;
  }
  return { list, of };
}

/**
 * Labels on a record, as `[{ id, name, by }]`. `by` limits them to one
 * reviewer's (blind dual screening); '' shows every label.
 */
export function labelsOf(s, paperId, by = '') {
  const st = labelState(s), on = st.of[paperId] || {};
  return st.list.filter(l => l.id in on && (!by || on[l.id] === by)).map(l => ({ ...l, by: on[l.id] }));
}
export const labelNames = (s, paperId, by = '') => labelsOf(s, paperId, by).map(l => l.name);

/** Records carrying each label (all reviewers'), for counts and filters. */
export function labelCounts(s, ids = null) {
  const st = labelState(s), n = Object.fromEntries(st.list.map(l => [l.id, 0]));
  for (const [pid, m] of Object.entries(st.of)) { if (ids && !ids.has(pid)) continue; for (const id in m) if (id in n) n[id]++; }
  return n;
}

const slug = name => `l-${String(name).toLowerCase().normalize('NFKD').replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-|-$/g, '').slice(0, 40) || 'label'}`;
const log = (s, entry) => { s.screeningLog = s.screeningLog || []; s.screeningLog.push({ ...entry, at: new Date().toISOString() }); };

/** A new project label; an existing name (ignoring case) is returned instead of doubled. */
export function addLabel(name, { by = '' } = {}) {
  const n = String(name || '').trim().replace(/\s+/g, ' ').slice(0, 60);
  if (!n) return null;
  let made = null;
  update(s => {
    const st = s.screeningLabels = normalizeLabels(s.screeningLabels);
    const had = st.list.find(l => l.name.toLowerCase() === n.toLowerCase());
    if (had) { made = had; return s; }
    let id = slug(n), k = 2; while (st.list.some(l => l.id === id)) id = `${slug(n)}-${k++}`;
    made = { id, name: n }; st.list.push(made);
    log(s, { action: 'label-create', label: n, by });
    return s;
  });
  persist();
  return made;
}

export function renameLabel(id, name, { by = '' } = {}) {
  const n = String(name || '').trim().replace(/\s+/g, ' ').slice(0, 60);
  if (!n) return;
  update(s => {
    const l = labelState(s).list.find(x => x.id === id); if (!l || l.name === n) return s;
    log(s, { action: 'label-rename', label: n, prior: l.name, by }); l.name = n; return s;
  });
  persist();
}

/** A label removed from the project and from every record; logged with how many records carried it. */
export function removeLabel(id, { by = '' } = {}) {
  update(s => {
    const st = s.screeningLabels = normalizeLabels(s.screeningLabels);
    const l = st.list.find(x => x.id === id); if (!l) return s;
    let n = 0;
    for (const m of Object.values(st.of)) if (id in m) { delete m[id]; n++; }
    for (const [pid, m] of Object.entries(st.of)) if (!Object.keys(m).length) delete st.of[pid];
    st.list = st.list.filter(x => x.id !== id);
    log(s, { action: 'label-delete', label: l.name, count: n, by });
    return s;
  });
  persist();
}

/** A label put on a record or taken off it. */
export function setLabel(paperId, labelId, on, { by = '' } = {}) {
  update(s => {
    const st = s.screeningLabels = normalizeLabels(s.screeningLabels);
    const l = st.list.find(x => x.id === labelId); if (!l) return s;
    const m = st.of[paperId] || {};
    if (on === (labelId in m)) return s;
    if (on) m[labelId] = by; else delete m[labelId];
    if (Object.keys(m).length) st.of[paperId] = m; else delete st.of[paperId];
    log(s, { action: on ? 'label' : 'unlabel', id: paperId, label: l.name, by });
    return s;
  });
  return persist();
}

// Screening decisions: two stages, one log.
//
// A title/abstract decision lives in `screening`, a full-text decision in
// `fulltext`, both keyed by record id. Every change — a decision, an undo, a
// reset — is appended to `screeningLog` and never edited, so what the review
// concluded and how it got there are two different questions with two
// different answers (plan E1, E5). A decision follows the store's short save
// debounce and is flushed when the window hides or closes: a run of quick
// decisions is one write, not a clone of the whole project per keystroke.
import { update, whenSaved } from '../store.mjs';
import { assignedTo, requiredFor } from './screen-assign.mjs';

export const STAGES = [
  { id: 'ta', label: 'Title and abstract', key: 'screening' },
  { id: 'ft', label: 'Full text',          key: 'fulltext' },
];
export const stageOf = id => STAGES.find(s => s.id === id) || STAGES[0];

export const decisionAt = (s, stage, id) => s[stageOf(stage).key]?.[id] || null;

// ---- two reviewers -----------------------------------------------------------
// With dual screening on, each reviewer's decision goes to `dual[stage][id]`
// under their initials, unseen by the other. The consensus — what the rest of
// the review reads from `screening`/`fulltext` — is written only when two
// reviewers agree, or when a conflict is resolved by hand.
export const isDual = s => Boolean(s.settings?.dualScreening);
const own = (s, stage, id) => s.dual?.[stage]?.[id] || {};
export const ownDecision = (s, stage, id, by) => (by && own(s, stage, id)[by]) || null;
export const reviewersOf = (s, stage) => {
  const set = new Set();
  for (const d of Object.values(s.dual?.[stage] || {})) for (const r of Object.keys(d)) set.add(r);
  return [...set].sort();
};

/**
 * Both decided and not the same: the records a pair has to talk about. With
 * `{ resolved: true }` the settled ones follow the open ones, each with the
 * resolution, so a settlement can be read back and reopened (plan E5).
 */
export function conflicts(s, stage, { resolved = false } = {}) {
  const key = stageOf(stage).key; const open = [], settled = [];
  for (const p of s.papers || []) {
    const d = own(s, stage, p.id); const who = Object.keys(d);
    if (who.length < 2) continue;
    const kinds = new Set(who.map(r => d[r].decision));
    if (kinds.size < 2) continue;
    const c = s[key]?.[p.id];
    const item = { paper: p, decisions: who.sort().map(r => ({ by: r, ...d[r] })) };
    if (!c) open.push(item);
    else if (resolved && c.resolved) settled.push({ ...item, resolution: c });
  }
  return resolved ? [...open, ...settled] : open;
}

/**
 * The consensus a record's own decisions make, or null. Without assignments
 * two reviewers must agree; with them, the reviewers assigned to the record
 * must all have decided alike (one, for a record split to one person). An
 * uncertain decision is never a consensus.
 */
export function consensusOf(s, stage, id) {
  const d = own(s, stage, id); const all = Object.entries(d);
  const need = requiredFor(s, stage, id);
  const needed = need ? Math.max(1, need.filter(r => r).length) : 2;
  if (need && !need.every(r => d[r])) return null;
  if (all.length < needed) return null;
  const kinds = new Set(all.map(([, x]) => x.decision));
  if (kinds.size !== 1 || kinds.has('uncertain')) return null;
  const decision = all[0][1].decision;
  return { decision, reason: all.find(([, x]) => x.reason)?.[1].reason || '', note: all.map(([r, x]) => x.note ? `${r}: ${x.note}` : '').filter(Boolean).join(' · '),
    at: new Date().toISOString(), by: all.map(([r]) => r).sort().join('+') };
}

/** Cohen's κ over the records two reviewers both decided (three categories). */
export function agreement(s, stage) {
  const rs = reviewersOf(s, stage); if (rs.length < 2) return { n: 0, kappa: null };
  const [a, b] = rs; const cats = ['include', 'exclude', 'uncertain'];
  let n = 0, agree = 0; const ma = {}, mb = {};
  for (const d of Object.values(s.dual?.[stage] || {})) {
    if (!d[a] || !d[b]) continue; n++;
    if (d[a].decision === d[b].decision) agree++;
    ma[d[a].decision] = (ma[d[a].decision] || 0) + 1; mb[d[b].decision] = (mb[d[b].decision] || 0) + 1;
  }
  if (!n) return { n: 0, kappa: null };
  const po = agree / n; const pe = cats.reduce((acc, c) => acc + ((ma[c] || 0) / n) * ((mb[c] || 0) / n), 0);
  return { n, kappa: pe === 1 ? 1 : (po - pe) / (1 - pe), reviewers: rs };
}

/** What the review concluded about a record: full text if decided, else title/abstract. */
export const finalDecision = (s, id) => s.fulltext?.[id] || s.screening?.[id] || null;
export const isIncluded = (s, id) => finalDecision(s, id)?.decision === 'include';

/**
 * The studies the later stages work on. Once screening has a decision in it,
 * that is the included studies and nothing else: extracting from or
 * appraising a record screening has not let through contradicts the review's
 * own flow. Before any decision the whole library is in scope, because the
 * plan keeps screening optional (§1.1): an ordinary research workspace can
 * compare and appraise papers without a formal eligibility stage.
 */
export const screeningStarted = s => (s.papers || []).some(p => finalDecision(s, p.id));
export const studies = s => screeningStarted(s) ? (s.papers || []).filter(p => isIncluded(s, p.id)) : (s.papers || []);

/** Records a stage still has to decide: undecided or uncertain. */
export function queue(s, stage, by = '') {
  const papers = s.papers || [];
  const pool = stage === 'ft' ? papers.filter(p => s.screening?.[p.id]?.decision === 'include') : papers;
  // dual: what this reviewer has not decided, whatever the other did; with
  // assignments at this stage, only the records assigned to them (plan E4)
  if (isDual(s) && by) {
    const mine = assignedTo(s, stage, by);
    const own = mine ? pool.filter(p => mine.has(p.id)) : pool;
    return { pool: own, open: own.filter(p => { const d = ownDecision(s, stage, p.id, by); return !d || d.decision === 'uncertain' || d.needsCriteriaReview === true; }) };
  }
  return { pool, open: pool.filter(p => { const d = decisionAt(s, stage, p.id); return !d || d.decision === 'uncertain' || d.needsCriteriaReview === true; }) };
}

function log(s, entry) {
  s.screeningLog = s.screeningLog || [];
  s.screeningLog.push({ ...entry, at: new Date().toISOString() });
}

// What a decision carries besides its verdict: the reviewer's note (plan E1)
// and the time the record was on screen before it (E8), in milliseconds.
const extras = ({ via = '', note = '', ms = 0 } = {}) => ({
  ...(via ? { via } : {}), ...(String(note || '').trim() ? { note: String(note).trim().slice(0, 2000) } : {}),
  ...(Number.isFinite(ms) && ms > 0 ? { ms: Math.round(ms) } : {}) });

// One decision applied to the live state (inside an update).
function applyDecision(s, stage, id, decision, { reason = '', by = '', via = '', note = '', ms = 0 } = {}) {
  if (decision === 'exclude' && !reason) throw new Error('An exclusion needs a reason');
  const key = stageOf(stage).key;
  const more = extras({ via, note, ms });
  if (isDual(s)) {
    if (!by) throw new Error('Dual screening needs reviewer initials');
    s.dual = s.dual || {}; s.dual[stage] = s.dual[stage] || {}; s.dual[stage][id] = s.dual[stage][id] || {};
    const prior = s.dual[stage][id][by];
    s.dual[stage][id][by] = { decision, reason: decision === 'exclude' ? reason : '', at: new Date().toISOString(), ...more };
    log(s, { action: prior ? 'change' : 'decide', stage, id, decision, reason: decision === 'exclude' ? reason : '', by, prior: prior?.decision, ...more });
    settleConsensus(s, stage, id);
    return;
  }
  s[key] = s[key] || {};
  const prior = s[key][id];
  s[key][id] = { decision, reason: decision === 'exclude' ? reason : '', at: new Date().toISOString(), by, ...more };
  log(s, { action: prior ? 'change' : 'decide', stage, id, decision, reason: s[key][id].reason, by, prior: prior?.decision, ...more });
}

// The reviewers agree (as assigned): that is the consensus; otherwise it
// waits, in conflicts when they differ. A hand resolution is left alone.
export function settleConsensus(s, stage, id, { quiet = false } = {}) {
  const key = stageOf(stage).key;
  if (s[key]?.[id]?.resolved) return;
  const c = consensusOf(s, stage, id);
  if (c) {
    const had = s[key]?.[id];
    s[key] = s[key] || {}; s[key][id] = c;
    if (!quiet && had?.decision !== c.decision) log(s, { action: 'agree', stage, id, decision: c.decision, by: c.by });
  } else if (s[key]?.[id]) delete s[key][id];
}

export function decide(stage, id, decision, { reason = '', by = '', via = '', note = '', ms = 0 } = {}) {
  if (decision === 'exclude' && !reason) throw new Error('An exclusion needs a reason');
  update(s => { applyDecision(s, stage, id, decision, { reason, by, via, note, ms }); return s; });
  return whenSaved();
}

/**
 * Several decisions as one change and one write: accepting a batch of
 * proposals used to make one store update (and one repaint signal) per
 * record. Every decision is still logged on its own.
 */
export function decideMany(stage, list, { by = '' } = {}) {
  for (const d of list) if (d.decision === 'exclude' && !d.reason) throw new Error('An exclusion needs a reason');
  if (!list.length) return Promise.resolve();
  update(s => { for (const d of list) applyDecision(s, stage, d.id, d.decision, { reason: d.reason || '', by, via: d.via || '' }); return s; });
  return whenSaved();
}

/** What a reviewer's decision on a record is now, to put back with revert(). */
export function priorOf(s, stage, id, by = '') {
  const d = isDual(s) && by ? s.dual?.[stage]?.[id]?.[by] : s[stageOf(stage).key]?.[id];
  return d ? structuredClone(d) : null;
}

/**
 * Takes back the last decision on a record: the decision it replaced comes
 * back as it was (reason, reviewer, time), or the record is undecided again.
 * Logged as an undo, like the inspector's Undo.
 */
export function revert(stage, id, prior, { by = '' } = {}) {
  if (!prior) return undo(stage, id, { by });
  const key = stageOf(stage).key;
  update(s => {
    if (isDual(s) && by) {
      const now = s.dual?.[stage]?.[id]?.[by];
      s.dual = s.dual || {}; s.dual[stage] = s.dual[stage] || {}; s.dual[stage][id] = s.dual[stage][id] || {};
      s.dual[stage][id][by] = prior;
      settleConsensus(s, stage, id, { quiet: true });
      log(s, { action: 'undo', stage, id, prior: now?.decision, decision: prior.decision, by });
      return s;
    }
    const now = s[key]?.[id];
    s[key] = s[key] || {};
    s[key][id] = prior;
    log(s, { action: 'undo', stage, id, prior: now?.decision, decision: prior.decision, by });
    return s;
  });
  return whenSaved();
}

/**
 * A conflict settled (plan E5): the consensus is written and the settlement
 * logged with the reviewers' decisions it settled, whose call was taken
 * (`picked`, or none for a third decision) and why (`why`). The reviewers'
 * own decisions are never changed.
 */
export function resolve(stage, id, decision, { reason = '', by = '', why = '', picked = '', note = '' } = {}) {
  if (decision === 'exclude' && !reason) throw new Error('An exclusion needs a reason');
  const key = stageOf(stage).key;
  update(s => {
    const settled = Object.entries(own(s, stage, id)).map(([r, d]) => `${r} ${d.decision}`).join(', ');
    s[key] = s[key] || {};
    s[key][id] = { decision, reason: decision === 'exclude' ? reason : '', at: new Date().toISOString(), by, resolved: true,
      ...(picked ? { picked } : {}), ...(String(why || '').trim() ? { why: String(why).trim() } : {}), ...(String(note || '').trim() ? { note: String(note).trim() } : {}) };
    log(s, { action: 'resolve', stage, id, decision, reason: s[key][id].reason, by, settled, ...(picked ? { picked } : {}), ...(s[key][id].why ? { why: s[key][id].why } : {}) });
    return s;
  });
  return whenSaved();
}

/**
 * A resolution taken back: logged with who reopened it and why, and the
 * record is a conflict again. It is never removed quietly.
 */
export function reopen(stage, id, { by = '', why = '' } = {}) {
  const key = stageOf(stage).key;
  update(s => {
    const c = s[key]?.[id]; if (!c?.resolved) return s;
    delete s[key][id];
    if (stage === 'ta' && s.fulltext?.[id]) log(s, { action: 'note', stage: 'ft', id, text: 'Title/abstract resolution reopened; full-text decision kept' });
    log(s, { action: 'reopen', stage, id, prior: c.decision, by, ...(String(why || '').trim() ? { why: String(why).trim() } : {}) });
    return s;
  });
  return whenSaved();
}

export function undo(stage, id, { by = '' } = {}) {
  const key = stageOf(stage).key;
  update(s => {
    if (isDual(s) && by) {
      const mine = s.dual?.[stage]?.[id]?.[by]; if (!mine) return s;
      delete s.dual[stage][id][by];
      settleConsensus(s, stage, id, { quiet: true });   // an agreement one side withdrew
      log(s, { action: 'undo', stage, id, prior: mine.decision, by });
      return s;
    }
    const prior = s[key]?.[id]; if (!prior) return s;
    delete s[key][id];
    log(s, { action: 'undo', stage, id, prior: prior.decision, by });
    return s;
  });
  return whenSaved();
}

export function reset(stage, { by = '' } = {}) {
  const key = stageOf(stage).key;
  update(s => {
    const n = Object.keys(s[key] || {}).length;
    s[key] = {};
    if (s.dual?.[stage]) s.dual[stage] = {};
    if (stage === 'ta') { s.fulltext = {}; if (s.dual?.ft) s.dual.ft = {}; }   // a full-text decision presumes a title/abstract inclusion
    log(s, { action: 'reset', stage, count: n, by });
    return s;
  });
  return whenSaved();
}

/** Every decision on record, newest first, for the log table. */
export function decisions(s, { by = '' } = {}) {
  const out = [];
  if (isDual(s) && by) {
    // blinded: a reviewer's log is their own decisions, not the other's
    for (const st of STAGES)
      for (const [id, d] of Object.entries(s.dual?.[st.id] || {})) if (d[by]) out.push({ id, stage: st.id, by, ...d[by] });
  } else {
    for (const st of STAGES)
      for (const [id, d] of Object.entries(s[st.key] || {})) out.push({ id, stage: st.id, ...d });
  }
  return out.sort((a, b) => (b.at || '').localeCompare(a.at || ''));
}

// Agreement and reliability statistics in plain JavaScript: intraclass
// correlation, Bland–Altman limits of agreement, Cohen's (weighted) kappa,
// Fleiss' kappa, Gwet's AC1, Krippendorff's alpha, percent agreement and
// Cronbach's alpha.
//
// Every function is pure and returns a plain object with its estimates, a
// confidence interval at `conf` (default 0.95) and an R-style `method` string.
// Formulas follow the R functions named in each block (irr::icc, irr::kappa2,
// irr::kappam.fleiss, irr::kripp.alpha, irr::agree); where irr has no
// counterpart the source paper is named. Nothing here has been benchmarked
// against native R; the unit tests check hand-computed cases and published
// worked examples only.
//
// Data layout, throughout: a matrix is an array of rows, one row per subject
// (unit), one column per rater (or item, for Cronbach's alpha). Missing values
// are null, undefined or NaN.
//
// Unweighted Cohen's kappa gives the same po, pe and κ as the risk-of-bias
// reviewers' kappa in lib/rob-review.mjs (checked there against irr::kappa2);
// the version here adds weights, levels and standard errors, so it keeps the
// full contingency table rather than the pair list.
import { pnorm, qnorm, pt, qt, pbeta } from './dist.mjs';

// ---- helpers ------------------------------------------------------------------------

const isMissing = v => v == null || (typeof v === 'number' && Number.isNaN(v));
const sum = a => a.reduce((t, v) => t + v, 0);
const mean = a => sum(a) / a.length;
/** Sample variance (divisor n − 1), as R's var. */
const variance = a => { const m = mean(a); return sum(a.map(v => (v - m) ** 2)) / (a.length - 1); };
const cor = (x, y) => {
  const mx = mean(x), my = mean(y);
  let sxy = 0, sxx = 0, syy = 0;
  for (let i = 0; i < x.length; i++) { sxy += (x[i] - mx) * (y[i] - my); sxx += (x[i] - mx) ** 2; syy += (y[i] - my) ** 2; }
  return sxy / Math.sqrt(sxx * syy);
};
const zOf = conf => qnorm(1 - (1 - conf) / 2);
const check = (ok, msg) => { if (!ok) throw new Error(msg); };

function bisect(f, lo, hi) {
  let flo = f(lo);
  for (let i = 0; i < 300; i++) {
    const mid = (lo + hi) / 2, fm = f(mid);
    if ((fm < 0) === (flo < 0)) { lo = mid; flo = fm; } else hi = mid;
    if (hi - lo <= 1e-15 * Math.max(1, Math.abs(mid))) break;
  }
  return (lo + hi) / 2;
}

/** F distribution function P(F ≤ f) with d1, d2 degrees of freedom (d2 may be fractional). */
export function pf(f, d1, d2, lowerTail = true) {
  if (!(f > 0)) return lowerTail ? 0 : 1;
  if (f === Infinity) return lowerTail ? 1 : 0;
  // compute the smaller tail directly for precision
  const x = d1 * f / (d1 * f + d2);
  return lowerTail ? pbeta(x, d1 / 2, d2 / 2) : pbeta(d2 / (d2 + d1 * f), d2 / 2, d1 / 2);
}

/** F quantile: the f with P(F ≤ f) = p. */
export function qf(p, d1, d2) {
  if (p <= 0) return 0; if (p >= 1) return Infinity;
  let hi = 2; while (pf(hi, d1, d2) < p) hi *= 2;
  return bisect(t => pf(t, d1, d2) - p, 0, hi);
}

/** Complete rows only (listwise deletion, as irr's na.omit). */
function completeRows(matrix) {
  check(Array.isArray(matrix) && matrix.length, 'a matrix of rows is required');
  return matrix.filter(r => r.every(v => !isMissing(v))).map(r => r.map(Number));
}

// ---- intraclass correlation (irr::icc) ----------------------------------------------

const ICC_FORMS = [
  ['oneway', 'agreement', 'single'], ['oneway', 'agreement', 'average'],
  ['twoway', 'consistency', 'single'], ['twoway', 'consistency', 'average'],
  ['twoway', 'agreement', 'single'], ['twoway', 'agreement', 'average'],
];

/** Mean squares of the subjects × raters layout, as irr::icc computes them. */
function iccMeanSquares(ratings) {
  const ns = ratings.length, nr = ratings[0].length, all = ratings.flat();
  const SStotal = variance(all) * (ns * nr - 1);
  const MSr = variance(ratings.map(mean)) * nr;
  const MSw = sum(ratings.map(variance)) / ns;
  const colMeans = Array.from({ length: nr }, (_, j) => mean(ratings.map(r => r[j])));
  const MSc = variance(colMeans) * ns;
  const MSe = (SStotal - MSr * (ns - 1) - MSc * (nr - 1)) / ((ns - 1) * (nr - 1));
  return { ns, nr, MSr, MSw, MSc, MSe };
}

/**
 * Intraclass correlation, one of the six Shrout–Fleiss / McGraw–Wong forms,
 * with the F test of H0: ICC = r0 and the confidence interval exactly as
 * irr::icc (which follows McGraw & Wong 1996). `matrix` has subjects in rows
 * and raters in columns; incomplete rows are dropped. The one-way model has
 * no separate consistency form (type is ignored there, as in irr).
 */
export function icc(matrix, { model = 'oneway', type = 'consistency', unit = 'single', r0 = 0, conf = 0.95 } = {}) {
  check(['oneway', 'twoway'].includes(model), `model must be 'oneway' or 'twoway'`);
  check(['agreement', 'consistency'].includes(type), `type must be 'agreement' or 'consistency'`);
  check(['single', 'average'].includes(unit), `unit must be 'single' or 'average'`);
  const ratings = completeRows(matrix);
  check(ratings.length >= 2 && ratings[0].length >= 2, 'icc needs at least two complete subjects and two raters');
  const { ns, nr, MSr, MSw, MSc, MSe } = iccMeanSquares(ratings);
  const alpha = 1 - conf;
  let value, F, df1 = ns - 1, df2, lower, upper;
  const agreementDf = c => {
    const a = (nr * c) / (ns * (1 - c)), b = 1 + (nr * c * (ns - 1)) / (ns * (1 - c));
    return (a * MSc + b * MSe) ** 2 / ((a * MSc) ** 2 / (nr - 1) + (b * MSe) ** 2 / ((ns - 1) * (nr - 1)));
  };
  const agreementBounds = v => {
    const FL = qf(1 - alpha / 2, ns - 1, v), FU = qf(1 - alpha / 2, v, ns - 1);
    return [
      (ns * (MSr - FL * MSe)) / (FL * (nr * MSc + (nr * ns - nr - ns) * MSe) + ns * MSr),
      (ns * (FU * MSr - MSe)) / (nr * MSc + (nr * ns - nr - ns) * MSe + ns * FU * MSr),
    ];
  };
  if (model === 'oneway') {
    df2 = ns * (nr - 1);
    const FL = (MSr / MSw) / qf(1 - alpha / 2, df1, df2), FU = (MSr / MSw) * qf(1 - alpha / 2, df2, df1);
    if (unit === 'single') {
      value = (MSr - MSw) / (MSr + (nr - 1) * MSw);
      F = MSr / MSw * ((1 - r0) / (1 + (nr - 1) * r0));
      lower = (FL - 1) / (FL + (nr - 1)); upper = (FU - 1) / (FU + (nr - 1));
    } else {
      value = (MSr - MSw) / MSr;
      F = MSr / MSw * (1 - r0);
      lower = 1 - 1 / FL; upper = 1 - 1 / FU;
    }
  } else if (type === 'consistency') {
    df2 = (ns - 1) * (nr - 1);
    const FL = (MSr / MSe) / qf(1 - alpha / 2, df1, df2), FU = (MSr / MSe) * qf(1 - alpha / 2, df2, df1);
    if (unit === 'single') {
      value = (MSr - MSe) / (MSr + (nr - 1) * MSe);
      F = MSr / MSe * ((1 - r0) / (1 + (nr - 1) * r0));
      lower = (FL - 1) / (FL + (nr - 1)); upper = (FU - 1) / (FU + (nr - 1));
    } else {
      value = (MSr - MSe) / MSr;
      F = MSr / MSe * (1 - r0);
      lower = 1 - 1 / FL; upper = 1 - 1 / FU;
    }
  } else if (unit === 'single') {
    value = (MSr - MSe) / (MSr + (nr - 1) * MSe + (nr / ns) * (MSc - MSe));
    const a = (nr * r0) / (ns * (1 - r0)), b = 1 + (nr * r0 * (ns - 1)) / (ns * (1 - r0));
    F = MSr / (a * MSc + b * MSe);
    df2 = agreementDf(value);
    [lower, upper] = agreementBounds(df2);
  } else {
    value = (MSr - MSe) / (MSr + (MSc - MSe) / ns);
    const a = r0 / (ns * (1 - r0)), b = 1 + (r0 * (ns - 1)) / (ns * (1 - r0));
    F = MSr / (a * MSc + b * MSe);
    // irr derives the df and the interval from the single-rater coefficient, then steps both bounds up
    const single = (MSr - MSe) / (MSr + (nr - 1) * MSe + (nr / ns) * (MSc - MSe));
    df2 = agreementDf(single);
    const [lb, ub] = agreementBounds(df2);
    lower = lb * nr / (1 + lb * (nr - 1)); upper = ub * nr / (1 + ub * (nr - 1));
  }
  const pValue = pf(F, df1, df2, false);
  const label = model === 'oneway' ? '' : type === 'agreement' ? 'A,' : 'C,';
  const shape = model === 'oneway' ? `ICC(1,${unit === 'single' ? 1 : 'k'})` : `ICC(${label}${unit === 'single' ? 1 : 'k'})`;
  return {
    method: `${unit === 'single' ? 'Single Score' : 'Average Score'} Intraclass Correlation`,
    model, type: model === 'oneway' ? 'agreement' : type, unit, form: shape,
    subjects: ns, raters: nr, value, r0, F, df1, df2, pValue, conf, lower, upper,
    meanSquares: { rows: MSr, within: MSw, columns: MSc, error: MSe },
  };
}

/** Every ICC form for one matrix, as a table (one row per form). */
export function iccAll(matrix, { r0 = 0, conf = 0.95 } = {}) {
  const rows = ICC_FORMS.map(([model, type, unit]) => icc(matrix, { model, type, unit, r0, conf }));
  return {
    method: 'Intraclass correlations, all forms (McGraw & Wong 1996)',
    subjects: rows[0].subjects, raters: rows[0].raters, conf,
    rows: rows.map(r => ({ form: r.form, model: r.model, type: r.type, unit: r.unit, value: r.value, F: r.F, df1: r.df1, df2: r.df2, pValue: r.pValue, lower: r.lower, upper: r.upper })),
  };
}

// ---- noncentral t, for the exact limits-of-agreement interval ----------------------

/**
 * P(T ≤ t) for a noncentral t with `df` degrees of freedom and noncentrality
 * `ncp`, by integrating Φ(t·√(V/df) − ncp) over V ~ χ²(df) on a log grid
 * (composite Simpson). Accurate to about 1e-10 for the df used here.
 */
function ptnc(t, df, ncp) {
  // V = e^y; density of y is f_χ²(e^y)·e^y
  const logConst = -(df / 2) * Math.LN2 - lgammaHalf(df);
  const g = y => { const v = Math.exp(y); return Math.exp(logConst + (df / 2) * y - v / 2) * pnorm(t * Math.sqrt(v / df) - ncp); };
  const lo = Math.log(df) - 40 / Math.sqrt(df) - 20, hi = Math.log(df + 40 * Math.sqrt(2 * df) + 60);
  const m = 4000, h = (hi - lo) / m;
  let s = g(lo) + g(hi);
  for (let i = 1; i < m; i++) s += (i % 2 ? 4 : 2) * g(lo + i * h);
  return s * h / 3;
}
/** log Γ(df/2), exact recursion for half-integers and integers. */
function lgammaHalf(df) {
  // Γ(n/2): Γ(1) = 1, Γ(1/2) = √π, Γ(x + 1) = x Γ(x)
  let x = df / 2, acc = 0;
  if (Number.isInteger(df)) {
    while (x > 1) { x -= 1; acc += Math.log(x); }
    return acc + (x === 0.5 ? 0.5 * Math.log(Math.PI) : 0);
  }
  // fractional df: Stirling series (not reached by the callers here)
  x = df / 2;
  let shift = 0; while (x < 8) { shift += Math.log(x); x += 1; }
  return (x - 0.5) * Math.log(x) - x + 0.5 * Math.log(2 * Math.PI) + 1 / (12 * x) - 1 / (360 * x ** 3) + 1 / (1260 * x ** 5) - shift;
}
function qtnc(p, df, ncp) {
  let lo = ncp - 10, hi = ncp + 10;
  while (ptnc(lo, df, ncp) > p) lo -= Math.max(10, Math.abs(lo));
  while (ptnc(hi, df, ncp) < p) hi += Math.max(10, Math.abs(hi));
  return bisect(t => ptnc(t, df, ncp) - p, lo, hi);
}

// ---- Bland–Altman -------------------------------------------------------------------

function slr(x, y) {
  const n = x.length, mx = mean(x), my = mean(y);
  let sxx = 0, sxy = 0; for (let i = 0; i < n; i++) { sxx += (x[i] - mx) ** 2; sxy += (x[i] - mx) * (y[i] - my); }
  const slope = sxy / sxx, intercept = my - slope * mx;
  const rss = sum(y.map((v, i) => (v - intercept - slope * x[i]) ** 2));
  const df = n - 2, se = df > 0 ? Math.sqrt(rss / df / sxx) : NaN, t = slope / se;
  return { intercept, slope, se, t, df, pValue: df > 0 ? 2 * pt(-Math.abs(t), df) : NaN };
}

/**
 * Bland–Altman analysis of two methods measured once on the same subjects.
 * Differences are x − y. The limits of agreement are bias ± z·s with z =
 * qnorm(1 − (1 − `coverage`)/2) (1.959964 for 95%; pass `z: 1.96` for the
 * rounded multiplier). The bias interval is the exact t interval. Two
 * intervals are returned for each limit: 'approximate', Bland & Altman's
 * (1986, 1999) SE = √(3s²/n) with a t quantile, and 'exact', the
 * tolerance-factor interval from noncentral t quantiles (Carkeet 2015);
 * `loaMethod` picks which one fills lowerCI/upperCI and defaults to 'exact'.
 * With `ratio: true` the analysis runs on log(x) − log(y) and every estimate
 * is back-transformed to a ratio x / y. Proportional bias is the regression
 * of the difference on the mean of the pair.
 */
export function blandAltman(x, y, { ratio = false, conf = 0.95, coverage = 0.95, z = null, loaMethod = 'exact' } = {}) {
  check(Array.isArray(x) && Array.isArray(y) && x.length === y.length, 'x and y must be arrays of equal length');
  check(['exact', 'approximate'].includes(loaMethod), `loaMethod must be 'exact' or 'approximate'`);
  const pairs = x.map((v, i) => [v, y[i]]).filter(([a, b]) => !isMissing(a) && !isMissing(b)).map(([a, b]) => [Number(a), Number(b)]);
  const n = pairs.length;
  check(n >= 3, 'Bland–Altman needs at least three complete pairs');
  if (ratio) check(pairs.every(([a, b]) => a > 0 && b > 0), 'ratio analysis needs positive values');
  const t = ratio ? Math.log : v => v;
  const d = pairs.map(([a, b]) => t(a) - t(b));
  const m = pairs.map(([a, b]) => (t(a) + t(b)) / 2);
  const bias = mean(d), sd = Math.sqrt(variance(d)), df = n - 1;
  const zz = z ?? zOf(coverage);
  const tq = qt(1 - (1 - conf) / 2, df);
  const seBias = sd / Math.sqrt(n);
  const lower = bias - zz * sd, upper = bias + zz * sd;
  // approximate: SE of a limit ≈ √(3 s² / n)
  const seLoa = Math.sqrt(3 * sd * sd / n);
  const approximate = { se: seLoa, lower: [lower - tq * seLoa, lower + tq * seLoa], upper: [upper - tq * seLoa, upper + tq * seLoa] };
  // exact: the limit bias + zz·s is a normal quantile; its CI uses noncentral t with ncp zz·√n
  const ncp = zz * Math.sqrt(n), a = 1 - conf;
  const kLo = qtnc(a / 2, df, ncp) / Math.sqrt(n), kHi = qtnc(1 - a / 2, df, ncp) / Math.sqrt(n);
  const exact = { lower: [bias - kHi * sd, bias - kLo * sd], upper: [bias + kLo * sd, bias + kHi * sd] };
  const chosen = loaMethod === 'exact' ? exact : approximate;
  const back = ratio ? Math.exp : v => v;
  const backPair = p => p.map(back);
  const reg = slr(m, d);
  return {
    method: `Bland-Altman limits of agreement${ratio ? ' (ratio, log scale)' : ''}`,
    n, ratio, conf, coverage, z: zz, loaMethod,
    bias: back(bias), biasCI: backPair([bias - tq * seBias, bias + tq * seBias]), seBias,
    sd, lower: back(lower), upper: back(upper),
    lowerCI: backPair(chosen.lower), upperCI: backPair(chosen.upper),
    loaCI: {
      approximate: { se: seLoa, lower: backPair(approximate.lower), upper: backPair(approximate.upper) },
      exact: { lower: backPair(exact.lower), upper: backPair(exact.upper), factors: [kLo, kHi] },
    },
    biasTest: { t: bias / seBias, df, pValue: 2 * pt(-Math.abs(bias / seBias), df) },
    proportionalBias: reg,
    scale: ratio ? 'log' : 'identity',
    points: pairs.map((p, i) => ({ x: p[0], y: p[1], mean: ratio ? (p[0] + p[1]) / 2 : m[i], diff: ratio ? p[0] / p[1] : d[i] })),
  };
}

/**
 * Bland–Altman limits with several paired observations per subject, where
 * the true value may change between a subject's observations (Bland &
 * Altman 2007, §3). A one-way ANOVA of the differences on subject gives the
 * within-subject mean square MSw and between-subject MSb; the between-subject
 * variance of differences is (MSb − MSw) / λ with λ = (N² − Σmᵢ²) / ((n − 1)N),
 * set to 0 when negative, and the total variance is that plus MSw. Bias is the
 * mean of all N differences. No interval is given for the limits (see Zou
 * 2013 for a MOVER interval, not built).
 */
export function blandAltmanRepeated(subjects, x, y, { coverage = 0.95, z = null } = {}) {
  check(subjects.length === x.length && x.length === y.length, 'subjects, x and y must have equal length');
  const groups = new Map();
  const points = [];
  for (let i = 0; i < x.length; i++) {
    if (isMissing(x[i]) || isMissing(y[i]) || subjects[i] == null) continue;
    const d = Number(x[i]) - Number(y[i]);
    if (!groups.has(subjects[i])) groups.set(subjects[i], []);
    groups.get(subjects[i]).push(d);
    points.push({ subject: subjects[i], x: Number(x[i]), y: Number(y[i]), mean: (Number(x[i]) + Number(y[i])) / 2, diff: d });
  }
  const g = [...groups.values()], n = g.length, N = sum(g.map(a => a.length));
  check(n >= 2 && N > n, 'repeated Bland–Altman needs at least two subjects and some subject with two or more pairs');
  const all = g.flat(), bias = mean(all);
  const ssb = sum(g.map(a => a.length * (mean(a) - bias) ** 2));
  const ssw = sum(g.map(a => { const ma = mean(a); return sum(a.map(v => (v - ma) ** 2)); }));
  const MSb = ssb / (n - 1), MSw = ssw / (N - n);
  const lambda = (N * N - sum(g.map(a => a.length ** 2))) / ((n - 1) * N);
  const betweenVar = Math.max(0, (MSb - MSw) / lambda);
  const totalVar = betweenVar + MSw, sd = Math.sqrt(totalVar);
  const zz = z ?? zOf(coverage);
  return {
    method: 'Bland-Altman limits of agreement, multiple observations per subject (Bland & Altman 2007)',
    subjects: n, n: N, coverage, z: zz, bias, sd,
    lower: bias - zz * sd, upper: bias + zz * sd,
    variance: { between: betweenVar, within: MSw, total: totalVar, MSb, MSw, lambda },
    points,
  };
}

// ---- Cohen's kappa (irr::kappa2) ----------------------------------------------------

function levelsOf(values, levels) {
  if (levels) return levels.slice();
  const u = [...new Set(values)];
  return u.every(v => typeof v === 'number') ? u.sort((a, b) => a - b) : u.map(String).sort();
}

function weightMatrix(k, weights) {
  return Array.from({ length: k }, (_, i) => Array.from({ length: k }, (_, j) => {
    if (!weights) return i === j ? 1 : 0;
    if (k === 1) return 1;
    const r = Math.abs(i - j) / (k - 1);
    return weights === 'linear' ? 1 - r : 1 - r * r;
  }));
}

/**
 * Cohen's kappa for two raters, unweighted or with 'linear' (irr "equal") or
 * 'quadratic' (irr "squared") agreement weights on the order of `levels`
 * (default: the sorted distinct values). Pairs with a missing rating are
 * dropped. `se` is the Fleiss–Cohen–Everitt (1969) large-sample SE of κ̂, used
 * for the Wald interval; `se0` is the SE under H0: κ = 0, used for z and its
 * two-sided p, as irr::kappa2 reports.
 */
export function cohenKappa(r1, r2, { weights = null, levels = null, conf = 0.95 } = {}) {
  check(r1.length === r2.length, 'r1 and r2 must have equal length');
  check([null, 'linear', 'quadratic'].includes(weights), `weights must be null, 'linear' or 'quadratic'`);
  const pairs = r1.map((v, i) => [v, r2[i]]).filter(([a, b]) => !isMissing(a) && !isMissing(b));
  const n = pairs.length;
  check(n > 0, 'no complete pairs');
  const lev = levelsOf(pairs.flat(), levels), k = lev.length;
  const idx = new Map(lev.map((l, i) => [l, i]));
  const at = v => { const i = idx.has(v) ? idx.get(v) : idx.get(String(v)); check(i != null, `rating ${v} is not among the levels`); return i; };
  const table = Array.from({ length: k }, () => new Array(k).fill(0));
  for (const [a, b] of pairs) table[at(a)][at(b)]++;
  const w = weightMatrix(k, weights);
  const p = table.map(r => r.map(c => c / n));
  const pr = p.map(sum), pc = lev.map((_, j) => sum(p.map(r => r[j])));
  let po = 0, pe = 0;
  for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) { po += w[i][j] * p[i][j]; pe += w[i][j] * pr[i] * pc[j]; }
  const kappa = pe === 1 ? null : (po - pe) / (1 - pe);
  // w̄ᵢ. = Σⱼ p.ⱼ wᵢⱼ ; w̄.ⱼ = Σᵢ pᵢ. wᵢⱼ
  const wi = lev.map((_, i) => sum(lev.map((__, j) => pc[j] * w[i][j])));
  const wj = lev.map((_, j) => sum(lev.map((__, i) => pr[i] * w[i][j])));
  let se = null, se0 = null;
  if (kappa != null) {
    let a = 0, b = 0;
    for (let i = 0; i < k; i++) for (let j = 0; j < k; j++) {
      a += p[i][j] * (w[i][j] - (wi[i] + wj[j]) * (1 - kappa)) ** 2;
      b += pr[i] * pc[j] * (w[i][j] - (wi[i] + wj[j])) ** 2;
    }
    const d = n * (1 - pe) ** 2;
    se = Math.sqrt(Math.max(0, (a - (kappa - pe * (1 - kappa)) ** 2) / d));
    se0 = Math.sqrt(Math.max(0, (b - pe * pe) / d));
  }
  const zc = zOf(conf);
  const zv = kappa != null && se0 > 0 ? kappa / se0 : null;
  return {
    method: `Cohen's Kappa for 2 Raters (Weights: ${weights === 'linear' ? 'equal' : weights === 'quadratic' ? 'squared' : 'unweighted'})`,
    subjects: n, raters: 2, levels: lev, weights, table,
    po, pe, kappa, se, se0, conf,
    lower: kappa != null && se != null ? kappa - zc * se : null,
    upper: kappa != null && se != null ? kappa + zc * se : null,
    z: zv, pValue: zv == null ? null : 2 * pnorm(-Math.abs(zv)),
  };
}

// ---- Fleiss' kappa (irr::kappam.fleiss) ---------------------------------------------

/**
 * Fleiss' kappa for m raters. `data` is either subject × category counts
 * (`{ counts: [[…], …] }` or a matrix with `counts: true`) with the same row
 * total for every subject, or raw ratings (subjects × raters, complete rows
 * only). SEs are Fleiss, Nee & Landis (1979) under H0: κ = 0, as irr reports;
 * the interval uses that SE and is only a guide away from 0.
 */
export function fleissKappa(data, { counts = false, levels = null, conf = 0.95 } = {}) {
  let cats, n;
  if (counts) {
    n = data.map(r => r.map(Number));
    cats = levels || n[0].map((_, j) => j);
  } else {
    const rows = data.filter(r => r.every(v => !isMissing(v)));
    cats = levelsOf(rows.flat(), levels);
    const idx = new Map(cats.map((c, i) => [c, i]));
    n = rows.map(r => { const c = new Array(cats.length).fill(0); for (const v of r) { const i = idx.has(v) ? idx.get(v) : idx.get(String(v)); check(i != null, `rating ${v} is not among the levels`); c[i]++; } return c; });
  }
  const N = n.length, m = sum(n[0]), k = cats.length;
  check(N >= 1 && m >= 2, 'Fleiss kappa needs at least two ratings per subject');
  check(n.every(r => sum(r) === m), 'every subject must have the same number of ratings');
  const pj = cats.map((_, j) => sum(n.map(r => r[j])) / (N * m));
  const Pi = n.map(r => (sum(r.map(c => c * c)) - m) / (m * (m - 1)));
  const Pbar = mean(Pi), Pe = sum(pj.map(v => v * v));
  const kappa = (Pbar - Pe) / (1 - Pe);
  const pq = pj.map(p => p * (1 - p)), spq = sum(pq);
  const se = Math.sqrt(2) / (spq * Math.sqrt(N * m * (m - 1))) * Math.sqrt(spq ** 2 - sum(pj.map((p, j) => pq[j] * (1 - 2 * p))));
  const seJ = Math.sqrt(2 / (N * m * (m - 1)));
  const zc = zOf(conf), zv = kappa / se;
  const byCategory = cats.map((c, j) => {
    const kj = 1 - sum(n.map(r => r[j] * (m - r[j]))) / (N * m * (m - 1) * pq[j]);
    const zj = kj / seJ;
    return { category: c, p: pj[j], kappa: kj, se: seJ, z: zj, pValue: 2 * pnorm(-Math.abs(zj)) };
  });
  return {
    method: `Fleiss' Kappa for m Raters`,
    subjects: N, raters: m, categories: cats, po: Pbar, pe: Pe, kappa, se, conf,
    lower: kappa - zc * se, upper: kappa + zc * se, z: zv, pValue: 2 * pnorm(-Math.abs(zv)),
    byCategory,
  };
}

// ---- Gwet's AC1 ---------------------------------------------------------------------

/**
 * Gwet's AC1 for two raters (Gwet 2008): chance agreement is
 * Σ πₖ(1 − πₖ) / (q − 1), πₖ the mean of the two raters' marginal shares.
 * The SE is Gwet's (2008, eq. 28) with no finite-population correction.
 */
export function gwetAC1(r1, r2, { levels = null, conf = 0.95 } = {}) {
  const ck = cohenKappa(r1, r2, { levels });
  const { table, subjects: n, levels: lev } = ck, q = lev.length;
  check(q >= 2, 'AC1 needs at least two categories');
  const p = table.map(r => r.map(c => c / n));
  const pr = p.map(sum), pc = lev.map((_, j) => sum(p.map(r => r[j])));
  const pi = lev.map((_, k) => (pr[k] + pc[k]) / 2);
  const pa = sum(lev.map((_, k) => p[k][k]));
  const pe = sum(pi.map(v => v * (1 - v))) / (q - 1);
  const ac1 = (pa - pe) / (1 - pe);
  let s1 = 0, s2 = 0;
  for (let k = 0; k < q; k++) {
    s1 += p[k][k] * (1 - pi[k]);
    for (let l = 0; l < q; l++) s2 += p[k][l] * (1 - (pi[k] + pi[l]) / 2) ** 2;
  }
  s1 /= q - 1; s2 /= (q - 1) ** 2;
  const v = (pa * (1 - pa) - 4 * (1 - ac1) * (s1 - pa * pe) + 4 * (1 - ac1) ** 2 * (s2 - pe * pe)) / (n * (1 - pe) ** 2);
  const se = Math.sqrt(Math.max(0, v)), zc = zOf(conf), zv = se > 0 ? ac1 / se : null;
  return {
    method: "Gwet's AC1 for 2 Raters", subjects: n, raters: 2, levels: lev,
    po: pa, pe, ac1, se, conf, lower: ac1 - zc * se, upper: ac1 + zc * se,
    z: zv, pValue: zv == null ? null : 2 * pnorm(-Math.abs(zv)),
  };
}

// ---- Krippendorff's alpha (irr::kripp.alpha) ----------------------------------------

/**
 * Krippendorff's alpha from a coincidence matrix. `data` has units in rows
 * and coders in columns (the transpose of irr::kripp.alpha's layout, to
 * match the rest of this module); missing values are allowed and units with
 * fewer than two values are not pairable and are left out. Levels: 'nominal',
 * 'ordinal' (rank distance on the pooled value frequencies), 'interval',
 * 'ratio'. No interval (Krippendorff's bootstrap is not built).
 */
export function krippendorffAlpha(data, level = 'nominal') {
  check(['nominal', 'ordinal', 'interval', 'ratio'].includes(level), `level must be nominal, ordinal, interval or ratio`);
  const units = data.map(r => r.filter(v => !isMissing(v))).filter(r => r.length >= 2);
  check(units.length, 'no pairable units');
  const vals = levelsOf(units.flat(), null), k = vals.length;
  const idx = new Map(vals.map((v, i) => [v, i]));
  const o = Array.from({ length: k }, () => new Array(k).fill(0));
  for (const u of units) {
    const mu = u.length;
    for (let i = 0; i < mu; i++) for (let j = 0; j < mu; j++) if (i !== j) o[idx.get(u[i])][idx.get(u[j])] += 1 / (mu - 1);
  }
  const nc = o.map(sum), n = sum(nc);
  const num = v => Number(v);
  const delta2 = (c, kk) => {
    if (c === kk) return 0;
    if (level === 'nominal') return 1;
    if (level === 'interval') return (num(vals[c]) - num(vals[kk])) ** 2;
    if (level === 'ratio') { const a = num(vals[c]), b = num(vals[kk]); return ((a - b) / (a + b)) ** 2; }
    const [lo, hi] = c < kk ? [c, kk] : [kk, c];
    let s = 0; for (let g = lo; g <= hi; g++) s += nc[g];
    return (s - (nc[c] + nc[kk]) / 2) ** 2;
  };
  let Do = 0, De = 0;
  for (let c = 0; c < k; c++) for (let kk = 0; kk < k; kk++) { const d = delta2(c, kk); Do += o[c][kk] * d; De += nc[c] * nc[kk] * d; }
  const alpha = De === 0 ? null : 1 - (n - 1) * Do / De;
  return {
    method: `Krippendorff's alpha`, level, units: units.length, pairableValues: n,
    values: vals, coincidence: o, observedDisagreement: Do / n, expectedDisagreement: De / (n * (n - 1)), alpha,
  };
}

// ---- percent agreement (irr::agree) -------------------------------------------------

/**
 * Share of subjects on which every rater gave the same value (numeric values
 * within `tolerance` of each other count as the same, as irr::agree).
 * Incomplete rows are dropped.
 */
export function percentAgreement(matrix, { tolerance = 0 } = {}) {
  const rows = matrix.filter(r => r.every(v => !isMissing(v)));
  check(rows.length, 'no complete subjects');
  const same = rows.filter(r => tolerance > 0
    ? Math.max(...r.map(Number)) - Math.min(...r.map(Number)) <= tolerance
    : r.every(v => v === r[0])).length;
  return {
    method: `Percentage agreement (Tolerance=${tolerance})`,
    subjects: rows.length, raters: rows[0].length, agreed: same, proportion: same / rows.length, percent: 100 * same / rows.length,
  };
}

// ---- Cronbach's alpha ---------------------------------------------------------------

function alphaOf(items) {
  const k = items[0].length;
  const itemVar = sum(Array.from({ length: k }, (_, j) => variance(items.map(r => r[j]))));
  const totalVar = variance(items.map(sum));
  return k / (k - 1) * (1 - itemVar / totalVar);
}

/**
 * Cronbach's alpha for a subjects × items matrix (complete rows only), with
 * Feldt's (1965) F-based interval: [1 − (1 − α̂)F(1 − γ/2), 1 − (1 − α̂)F(γ/2)]
 * on n − 1 and (n − 1)(k − 1) df. Alpha if each item is deleted and the
 * corrected item–total correlation (item against the sum of the others).
 * McDonald's omega is not built: it needs a factor analysis.
 */
export function cronbachAlpha(matrix, { conf = 0.95 } = {}) {
  const items = completeRows(matrix);
  const n = items.length, k = items[0]?.length || 0;
  check(n >= 2 && k >= 2, 'Cronbach alpha needs at least two subjects and two items');
  const alpha = alphaOf(items);
  const df1 = n - 1, df2 = (n - 1) * (k - 1), g = 1 - conf;
  const lower = 1 - (1 - alpha) * qf(1 - g / 2, df1, df2);
  const upper = 1 - (1 - alpha) * qf(g / 2, df1, df2);
  const itemStats = Array.from({ length: k }, (_, j) => {
    const col = items.map(r => r[j]), rest = items.map(r => sum(r) - r[j]);
    const others = items.map(r => r.filter((_, c) => c !== j));
    return {
      item: j, mean: mean(col), sd: Math.sqrt(variance(col)),
      correctedItemTotal: cor(col, rest),
      alphaIfDeleted: k > 2 ? alphaOf(others) : null,
    };
  });
  return {
    method: "Cronbach's alpha (Feldt interval)", subjects: n, items: k,
    alpha, conf, lower, upper, df1, df2, itemStats,
  };
}

// Regression for a patient table: linear, logistic and Poisson models, the
// univariable screen and the side-by-side publication table.
//
// Computed here in plain JavaScript rather than in R so that a model is fitted
// without starting the WebR engine. The linear algebra is small and dense:
// Householder QR with R's limited column pivoting (dqrdc2, tolerance 1e-7), so
// a column that is a linear combination of earlier ones is reported as aliased
// (R's NA coefficient) rather than crashing. Generalised linear models are
// fitted by iteratively reweighted least squares as glm.fit does: the same
// starting values, convergence rule (relative deviance change < 1e-8, at most
// 25 iterations) and logit clamping.
//
// Data are complete-case: a row missing the outcome, any predictor or the
// offset is dropped and counted (nUsed, nDropped). Categorical predictors are
// treatment (dummy) coded against a reference level, the first level unless
// one is named. Levels are ordered by the spec's `levels` when given, otherwise
// sorted with numeric awareness ("2" before "10"), which differs from R's plain
// string sort only for numeric-looking labels.
//
// Checked by unit tests against published R output for mtcars (lm, glm) and
// hand-computable cases; not benchmarked against a native R installation, so
// this module is not among the plan's measured components (status line).
//
// Nothing here decides significance. Each estimate is reported with its
// interval and test, and warnings (aliased terms, separation, overdispersion)
// travel with the result for the view to show.

import { qt, qnorm, pnorm, pchisq, pbeta } from './dist.mjs';

const DBL_EPS = 2.220446049250313e-16;
const QR_TOL = 1e-7;

// ---- data -------------------------------------------------------------------

const isMissing = v => v === null || v === undefined || (typeof v === 'string' && v.trim() === '') ||
  (typeof v === 'number' && !Number.isFinite(v));

function toNumber(v) {
  if (isMissing(v)) return null;
  if (typeof v === 'boolean') return v ? 1 : 0;
  const x = typeof v === 'number' ? v : Number(String(v).trim());
  return Number.isFinite(x) ? x : null;
}
const toLevel = v => isMissing(v) ? null : String(v).trim();
const levelSort = (a, b) => a.localeCompare(b, undefined, { numeric: true });

function normalizeSpecs(predictors) {
  return (predictors || []).map(p => typeof p === 'string' ? { column: p, type: 'numeric' } : {
    column: p.column, type: p.type === 'categorical' ? 'categorical' : 'numeric',
    reference: p.reference == null ? undefined : String(p.reference),
    levels: Array.isArray(p.levels) ? p.levels.map(String) : undefined,
  });
}

/**
 * Build the model matrix. Always includes an intercept.
 * @param {object[]} rows
 * @param {string} outcome column name
 * @param {{column:string,type:'numeric'|'categorical',reference?:string,levels?:string[]}[]} predictors
 * @param {{outcomeValue?:(v:any)=>number|null, offset?:string, exposure?:string}} [opts]
 *   outcomeValue codes the raw outcome (default: numeric); offset names a column already
 *   on the linear-predictor scale; exposure names a positive column whose log is the offset.
 * @returns {{X:number[][], y:number[], names:string[], columns:{name:string,term:string|null,level:string|null}[],
 *   levels:Object<string,{levels:string[],reference:string}>, nUsed:number, nDropped:number,
 *   rowIndex:number[], offset:number[]|null}}
 */
export function designMatrix(rows, outcome, predictors, opts = {}) {
  const specs = normalizeSpecs(predictors);
  const code = opts.outcomeValue || toNumber;
  const offCol = opts.offset || opts.exposure || null;
  const kept = [];
  (rows || []).forEach((r, i) => {
    const y = code(r?.[outcome]);
    if (y === null || y === undefined || !Number.isFinite(y)) return;
    const vals = [];
    for (const s of specs) {
      const v = s.type === 'categorical' ? toLevel(r[s.column]) : toNumber(r[s.column]);
      if (v === null) return;
      vals.push(v);
    }
    let off = 0;
    if (offCol) {
      const o = toNumber(r[offCol]);
      if (o === null) return;
      if (opts.exposure) { if (!(o > 0)) return; off = Math.log(o); } else off = o;
    }
    kept.push({ i, y, vals, off });
  });

  const levels = {};
  specs.forEach((s, k) => {
    if (s.type !== 'categorical') return;
    const present = new Set(kept.map(r => r.vals[k]));
    const order = s.levels ? s.levels.filter(l => present.has(l)).concat([...present].filter(l => !s.levels.includes(l)).sort(levelSort))
      : [...present].sort(levelSort);
    const reference = s.reference ?? order[0];
    if (order.length && !order.includes(reference))
      throw new Error(`Reference level '${reference}' of ${s.column} is not among the complete cases`);
    levels[s.column] = { levels: order, reference };
  });

  const columns = [{ name: '(Intercept)', term: null, level: null }];
  specs.forEach(s => {
    if (s.type === 'numeric') columns.push({ name: s.column, term: s.column, level: null });
    else for (const l of levels[s.column].levels) if (l !== levels[s.column].reference)
      columns.push({ name: `${s.column}: ${l}`, term: s.column, level: l });
  });

  const X = kept.map(r => {
    const x = [1];
    specs.forEach((s, k) => {
      if (s.type === 'numeric') x.push(r.vals[k]);
      else for (const l of levels[s.column].levels) if (l !== levels[s.column].reference) x.push(r.vals[k] === l ? 1 : 0);
    });
    return x;
  });
  return {
    X, y: kept.map(r => r.y), names: columns.map(c => c.name), columns, levels,
    nUsed: kept.length, nDropped: (rows || []).length - kept.length, rowIndex: kept.map(r => r.i),
    offset: offCol ? kept.map(r => r.off) : null, specs,
  };
}

// ---- linear algebra -----------------------------------------------------------

/**
 * Householder QR of sqrt(w)·X with dqrdc2-style limited pivoting: a column whose
 * remaining norm falls below QR_TOL of its original norm is aliased and skipped.
 */
function qrFit(X, z, w) {
  const n = X.length, p = n ? X[0].length : 0;
  const cols = Array.from({ length: p }, (_, j) => Float64Array.from(X, (r, i) => r[j] * (w ? Math.sqrt(w[i]) : 1)));
  const qty = Float64Array.from(z, (v, i) => v * (w ? Math.sqrt(w[i]) : 1));
  const orig = cols.map(c => Math.hypot(...c));
  const keep = [], aliased = [];
  let k = 0;
  for (let j = 0; j < p; j++) {
    const c = cols[j];
    let s = 0; for (let i = k; i < n; i++) s += c[i] * c[i];
    const norm = Math.sqrt(s);
    if (k >= n || !(orig[j] > 0) || norm <= QR_TOL * orig[j]) { aliased.push(j); continue; }
    const alpha = c[k] > 0 ? -norm : norm;
    const v = new Float64Array(n); for (let i = k; i < n; i++) v[i] = c[i]; v[k] -= alpha;
    let vv = 0; for (let i = k; i < n; i++) vv += v[i] * v[i];
    const reflect = a => { let d = 0; for (let i = k; i < n; i++) d += v[i] * a[i]; d = 2 * d / vv; for (let i = k; i < n; i++) a[i] -= d * v[i]; };
    for (let jj = j + 1; jj < p; jj++) reflect(cols[jj]);
    reflect(qty);
    c[k] = alpha; for (let i = k + 1; i < n; i++) c[i] = 0;
    keep.push(j); k++;
  }
  const R = Array.from({ length: k }, (_, r) => Array.from({ length: k }, (_, cc) => r <= cc ? cols[keep[cc]][r] : 0));
  const b = new Array(k).fill(0);
  for (let r = k - 1; r >= 0; r--) { let s = qty[r]; for (let cc = r + 1; cc < k; cc++) s -= R[r][cc] * b[cc]; b[r] = s / R[r][r]; }
  const Rinv = Array.from({ length: k }, () => new Array(k).fill(0));
  for (let cc = 0; cc < k; cc++) {
    Rinv[cc][cc] = 1 / R[cc][cc];
    for (let r = cc - 1; r >= 0; r--) { let s = 0; for (let m = r + 1; m <= cc; m++) s += R[r][m] * Rinv[m][cc]; Rinv[r][cc] = -s / R[r][r]; }
  }
  const XtXinv = Array.from({ length: k }, (_, a) => Array.from({ length: k }, (_, bb) => {
    let s = 0; for (let m = Math.max(a, bb); m < k; m++) s += Rinv[a][m] * Rinv[bb][m]; return s;
  }));
  return { coef: b, keep, aliased, rank: k, XtXinv };
}

/** Cholesky determinant of a symmetric positive-definite matrix. */
function detSPD(A) {
  const n = A.length, L = Array.from({ length: n }, () => new Array(n).fill(0));
  let det = 1;
  for (let j = 0; j < n; j++) {
    let s = A[j][j]; for (let m = 0; m < j; m++) s -= L[j][m] * L[j][m];
    if (!(s > 0)) return 0;
    L[j][j] = Math.sqrt(s); det *= s;
    for (let i = j + 1; i < n; i++) { let t = A[i][j]; for (let m = 0; m < j; m++) t -= L[i][m] * L[j][m]; L[i][j] = t / L[j][j]; }
  }
  return det;
}
const sub = (A, idx) => idx.map(i => idx.map(j => A[i][j]));
const dot = (a, b) => { let s = 0; for (let i = 0; i < a.length; i++) s += a[i] * b[i]; return s; };
const quad = (x, M) => { let s = 0; for (let a = 0; a < x.length; a++) for (let b = 0; b < x.length; b++) s += x[a] * M[a][b] * x[b]; return s; };

/**
 * (Generalised) variance inflation per term from the coefficient covariance,
 * as car::vif: GVIF = det(R11)·det(R22)/det(R) on the correlation of the
 * non-intercept coefficients. `adjusted` is GVIF^(1/(2·df)).
 */
function vifTable(V, kept) {
  const idx = kept.map((c, i) => ({ ...c, i })).filter(c => c.term !== null);
  const terms = [...new Set(idx.map(c => c.term))];
  if (terms.length < 2) return terms.map(term => ({ term, df: idx.filter(c => c.term === term).length, gvif: 1, adjusted: 1 }));
  const all = idx.map(c => c.i);
  const C = all.map(a => all.map(b => V[a][b] / Math.sqrt(V[a][a] * V[b][b])));
  const detR = detSPD(C);
  return terms.map(term => {
    const inT = idx.map((c, k) => c.term === term ? k : -1).filter(k => k >= 0);
    const outT = idx.map((c, k) => c.term !== term ? k : -1).filter(k => k >= 0);
    const gvif = detR > 0 ? detSPD(sub(C, inT)) * detSPD(sub(C, outT)) / detR : Infinity;
    return { term, df: inT.length, gvif, adjusted: gvif ** (1 / (2 * inT.length)) };
  });
}

// ---- shared result shaping ------------------------------------------------------

function coefficientRows(d, fit, se, statFn, crit) {
  const pos = new Map(fit.keep.map((j, k) => [j, k]));
  return d.columns.map((c, j) => {
    const base = { name: c.name, term: c.term, level: c.level };
    if (!pos.has(j)) return { ...base, aliased: true, estimate: null, se: null, statistic: null, p: null, ci: null };
    const k = pos.get(j), est = fit.coef[k], s = se[k], stat = est / s;
    return { ...base, aliased: false, estimate: est, se: s, statistic: stat, p: statFn(stat), ci: [est - crit * s, est + crit * s] };
  });
}
function aliasWarning(d, fit) {
  if (!fit.aliased.length) return [];
  const names = fit.aliased.map(j => d.names[j]);
  return [{ code: 'aliased', terms: names, message: `Not estimable (linear combination of other columns): ${names.join(', ')}` }];
}
function modelMeta(d) {
  return { nUsed: d.nUsed, nDropped: d.nDropped, rowIndex: d.rowIndex, names: d.names, levels: d.levels, predictors: d.specs };
}

// ---- linear model -----------------------------------------------------------------

/**
 * Ordinary least squares, as lm().
 * @param {object[]} rows @param {string} outcome @param {object[]} predictors
 * @param {{robust?:boolean, level?:number}} [opts] robust: HC3 standard errors (sandwich::vcovHC type "HC3").
 */
export function linearRegression(rows, outcome, predictors, { robust = false, level = 0.95 } = {}) {
  const d = designMatrix(rows, outcome, predictors);
  const n = d.nUsed;
  if (!n) throw new Error('No complete cases');
  const fit = qrFit(d.X, d.y);
  const p = fit.rank, df = n - p;
  if (df <= 0) throw new Error(`Too few complete cases (${n}) for ${p} coefficients`);
  const Xk = d.X.map(r => fit.keep.map(j => r[j]));
  const fitted = Xk.map(x => dot(x, fit.coef));
  const residuals = d.y.map((y, i) => y - fitted[i]);
  const rss = dot(residuals, residuals);
  const ybar = d.y.reduce((a, b) => a + b, 0) / n;
  const tss = d.y.reduce((a, y) => a + (y - ybar) ** 2, 0);
  const s2 = rss / df, sigma = Math.sqrt(s2);
  const leverage = Xk.map(x => quad(x, fit.XtXinv));

  let V;
  if (robust) {
    const k = p, meat = Array.from({ length: k }, () => new Array(k).fill(0));
    Xk.forEach((x, i) => {
      const om = residuals[i] ** 2 / (1 - leverage[i]) ** 2;
      for (let a = 0; a < k; a++) for (let b = 0; b < k; b++) meat[a][b] += x[a] * x[b] * om;
    });
    const B = fit.XtXinv;
    const BM = B.map(r => r.map((_, b) => r.reduce((s, v, m) => s + v * meat[m][b], 0)));
    V = BM.map(r => B.map(col => dot(r, col)));
  } else V = fit.XtXinv.map(r => r.map(v => v * s2));
  const se = V.map((r, k) => Math.sqrt(r[k]));
  const crit = qt(1 - (1 - level) / 2, df);
  const tp = t => Number.isFinite(t) ? pbeta(df / (df + t * t), df / 2, 0.5) : (Number.isNaN(t) ? NaN : 0);
  const coefficients = coefficientRows(d, fit, se, tp, crit);

  const r2 = tss > 0 ? 1 - rss / tss : NaN;
  const adjR2 = 1 - (1 - r2) * (n - 1) / df;
  const df1 = p - 1;
  let fTest = null;
  if (df1 > 0) {
    // With robust SEs R's summary still reports the classical F; kept that way here.
    const F = ((tss - rss) / df1) / s2;
    fTest = { F, df1, df2: df, p: pbeta(df / (df + df1 * F), df / 2, df1 / 2) };
  }
  const standardized = residuals.map((e, i) => e / (sigma * Math.sqrt(1 - leverage[i])));
  const studentized = residuals.map((e, i) => {
    const si2 = (rss - e * e / (1 - leverage[i])) / (df - 1);
    return e / Math.sqrt(si2 * (1 - leverage[i]));
  });
  const cooks = residuals.map((e, i) => e * e * leverage[i] / (p * s2 * (1 - leverage[i]) ** 2));
  const keptCols = fit.keep.map(j => d.columns[j]);
  const Vunscaled = fit.XtXinv;
  return {
    family: 'gaussian', measure: 'beta', ...modelMeta(d), coefficients, aliased: fit.aliased.map(j => d.names[j]),
    rank: p, df, level, robust, seType: robust ? 'HC3' : 'classical',
    r2, adjR2, sigma, fTest, vif: vifTable(Vunscaled, keptCols),
    residuals, fitted, leverage, cooks, standardized, studentized,
    warnings: aliasWarning(d, fit),
  };
}

// ---- generalised linear models ------------------------------------------------------

const FAMILIES = {
  binomial: {
    init: y => y.map(v => (v + 0.5) / 2),
    link: mu => Math.log(mu / (1 - mu)),
    inv: eta => { const e = Math.min(Math.max(eta, -30), 30); return 1 / (1 + Math.exp(-e)); },
    // canonical link: working weight = variance = mu.eta; R floors mu.eta at DBL_EPS
    weight: (mu, eta) => { const e = Math.exp(-Math.abs(eta)); return Math.max(e / (1 + e) ** 2, DBL_EPS); },
    dev: (y, mu) => {
      let s = 0;
      for (let i = 0; i < y.length; i++) s += y[i] ? -2 * Math.log(mu[i]) : -2 * Math.log(1 - mu[i]);
      return s;
    },
    loglik: (y, mu) => -FAMILIES.binomial.dev(y, mu) / 2,
  },
  poisson: {
    init: y => y.map(v => v + 0.1),
    link: mu => Math.log(mu),
    inv: eta => Math.max(Math.exp(eta), DBL_EPS),
    weight: mu => mu,
    dev: (y, mu) => {
      let s = 0;
      for (let i = 0; i < y.length; i++) s += 2 * ((y[i] > 0 ? y[i] * Math.log(y[i] / mu[i]) : 0) - (y[i] - mu[i]));
      return s;
    },
    loglik: (y, mu) => y.reduce((s, v, i) => s + v * Math.log(mu[i]) - mu[i] - lgammaFn(v + 1), 0),
  },
};

/** log Γ(x), Lanczos (g = 7, n = 9). */
function lgammaFn(x) {
  if (Number.isInteger(x) && x > 0 && x < 171) { let s = 0; for (let k = 2; k < x; k++) s += Math.log(k); return s; }
  if (x < 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * x))) - lgammaFn(1 - x);
  const g = 7, c = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
    -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
  x -= 1; let a = c[0]; const t = x + g + 0.5;
  for (let i = 1; i < 9; i++) a += c[i] / (x + i);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}

/** IRLS as glm.fit. X may have zero columns (a fully fixed model). */
function irls(X, y, offset, fam, { maxit = 25, epsilon = 1e-8 } = {}) {
  const n = y.length, p = X.length ? X[0].length : 0;
  const off = offset || new Array(n).fill(0);
  if (!p) {
    const mu = off.map(fam.inv);
    return { coef: [], keep: [], aliased: [], rank: 0, XtXinv: [], mu, eta: off.slice(), deviance: fam.dev(y, mu), converged: true, iterations: 0 };
  }
  let eta = fam.init(y).map(fam.link);
  let mu = eta.map(fam.inv);
  let devold = fam.dev(y, mu), fit = null, converged = false, iter = 0, prevCoef = null;
  for (iter = 1; iter <= maxit; iter++) {
    const w = mu.map((m, i) => fam.weight(m, eta[i]));
    const z = eta.map((e, i) => e - off[i] + (y[i] - mu[i]) / w[i]);
    fit = qrFit(X, z, w);
    const fullCoef = new Array(p).fill(0); fit.keep.forEach((j, k) => { fullCoef[j] = fit.coef[k]; });
    let newEta = X.map((r, i) => dot(r, fullCoef) + off[i]);
    let newMu = newEta.map(fam.inv), dev = fam.dev(y, newMu);
    // step halving when the deviance is not finite, as glm.fit
    for (let h = 0; !Number.isFinite(dev) && prevCoef && h < 30; h++) {
      for (let j = 0; j < p; j++) fullCoef[j] = (fullCoef[j] + prevCoef[j]) / 2;
      newEta = X.map((r, i) => dot(r, fullCoef) + off[i]); newMu = newEta.map(fam.inv); dev = fam.dev(y, newMu);
      fit.coef = fit.keep.map(j => fullCoef[j]);
    }
    prevCoef = fullCoef; eta = newEta; mu = newMu;
    if (Math.abs(dev - devold) / (Math.abs(dev) + 0.1) < epsilon) { converged = true; devold = dev; break; }
    devold = dev;
  }
  // covariance at the final estimates (glm's summary uses the last IRLS weights,
  // which differ from these only below the convergence tolerance)
  const w = mu.map((m, i) => fam.weight(m, eta[i]));
  const fin = qrFit(X, eta.map((e, i) => e - off[i]), w);
  return { coef: fit.coef, keep: fit.keep, aliased: fit.aliased, rank: fit.rank, XtXinv: fin.XtXinv, mu, eta, deviance: devold, converged, iterations: Math.min(iter, maxit) };
}

/** Profile-likelihood interval for coefficient column j (as MASS/R confint on a glm). */
function profileInterval(Xk, y, off, fam, fit, k, se, level) {
  const zc = qnorm(1 - (1 - level) / 2);
  const bhat = fit.coef[k], D0 = fit.deviance, n = y.length;
  const Xo = Xk.map(r => r.filter((_, m) => m !== k));
  const devAt = t => irls(Xo, y, off.map((o, i) => o + Xk[i][k] * t), fam).deviance;
  const h = t => Math.sqrt(Math.max(0, devAt(t) - D0)) - zc;
  const bound = dir => {
    let a = bhat, step = Number.isFinite(se) && se > 0 ? se * zc : 1, b = bhat + dir * step, hb = h(b);
    for (let i = 0; hb < 0; i++) {
      if (i >= 40 || !Number.isFinite(hb)) return dir * Infinity;
      a = b; step *= 2; b = bhat + dir * step; hb = h(b);
    }
    let ha = a === bhat ? -zc : h(a);
    // Illinois false position between a (h<0) and b (h>=0)
    let side = 0, t = b;
    for (let i = 0; i < 100; i++) {
      t = (a * hb - b * ha) / (hb - ha);
      if (!Number.isFinite(t) || (t - a) * (t - b) > 0) t = (a + b) / 2;
      const ht = h(t);
      if (Math.abs(ht) < 1e-10 || Math.abs(b - a) < 1e-10 * (1 + Math.abs(t))) break;
      if (ht < 0) { a = t; ha = ht; if (side === -1) hb /= 2; side = -1; }
      else { b = t; hb = ht; if (side === 1) ha /= 2; side = 1; }
    }
    return t;
  };
  if (!n) return [NaN, NaN];
  return [bound(-1), bound(1)];
}

function hosmerLemeshow(y, mu, g = 10) {
  const n = y.length, sorted = mu.slice().sort((a, b) => a - b);
  const q = pr => { const h = (n - 1) * pr, lo = Math.floor(h), hi = Math.ceil(h); return sorted[lo] + (h - lo) * (sorted[hi] - sorted[lo]); };
  const breaks = [...new Set(Array.from({ length: g + 1 }, (_, k) => q(k / g)))];
  const G = breaks.length - 1;
  if (G < 3) return null;
  const groups = Array.from({ length: G }, (_, k) => ({ lower: breaks[k], upper: breaks[k + 1], n: 0, observed: 0, expected: 0 }));
  mu.forEach((m, i) => {
    let k = 0; while (k < G - 1 && m > breaks[k + 1]) k++;
    const grp = groups[k]; grp.n++; grp.observed += y[i]; grp.expected += m;
  });
  let chisq = 0;
  for (const grp of groups) {
    const e0 = grp.n - grp.expected, o0 = grp.n - grp.observed;
    if (grp.expected > 0) chisq += (grp.observed - grp.expected) ** 2 / grp.expected;
    if (e0 > 0) chisq += (o0 - e0) ** 2 / e0;
  }
  const df = G - 2;
  return { chisq, df, p: 1 - pchisq(chisq, df), groups };
}

/** Area under the ROC curve (c-statistic); ties count one half. */
function cStatistic(y, mu) {
  const idx = mu.map((m, i) => i).sort((a, b) => mu[a] - mu[b]);
  const ranks = new Array(mu.length);
  for (let i = 0; i < idx.length;) {
    let j = i; while (j + 1 < idx.length && mu[idx[j + 1]] === mu[idx[i]]) j++;
    for (let k = i; k <= j; k++) ranks[idx[k]] = (i + j) / 2 + 1;
    i = j + 1;
  }
  const n1 = y.reduce((a, b) => a + b, 0), n0 = y.length - n1;
  if (!n1 || !n0) return NaN;
  const s = y.reduce((a, v, i) => a + (v ? ranks[i] : 0), 0);
  return (s - n1 * (n1 + 1) / 2) / (n1 * n0);
}

function fitGlm(d, famName, { level = 0.95, profile = true } = {}) {
  const fam = FAMILIES[famName], n = d.nUsed;
  if (!n) throw new Error('No complete cases');
  const off = d.offset || new Array(n).fill(0);
  // structural aliasing is decided once, on the unweighted design
  const struct = qrFit(d.X, d.y);
  if (n <= struct.rank) throw new Error(`Too few complete cases (${n}) for ${struct.rank} coefficients`);
  let Xk = d.X.map(r => struct.keep.map(j => r[j]));
  let fit = irls(Xk, d.y, off, fam);
  if (fit.aliased.length) {
    // a column aliased only under the IRLS weights: drop it and refit
    Xk = Xk.map(r => fit.keep.map(k => r[k]));
    const keep = fit.keep.map(k => struct.keep[k]);
    struct.aliased = [...struct.aliased, ...fit.aliased.map(k => struct.keep[k])].sort((a, b) => a - b);
    struct.keep = keep; struct.rank = keep.length;
    fit = irls(Xk, d.y, off, fam);
  }
  const keepMap = { keep: struct.keep, aliased: struct.aliased, coef: fit.coef };
  const se = fit.XtXinv.map((r, k) => Math.sqrt(r[k]));
  const crit = qnorm(1 - (1 - level) / 2);
  const zp = z => Number.isFinite(z) ? 2 * pnorm(-Math.abs(z)) : (Number.isNaN(z) ? NaN : 0);
  const coefficients = coefficientRows(d, keepMap, se, zp, crit);
  let pk = 0;
  for (const c of coefficients) {
    if (c.aliased) { Object.assign(c, { ratio: null, ratioCI: null, profileCI: null, ratioProfileCI: null }); continue; }
    const k = pk++;
    c.ratio = Math.exp(c.estimate);
    c.ratioCI = c.ci.map(Math.exp);
    if (profile) {
      c.profileCI = profileInterval(Xk, d.y, off, fam, fit, k, se[k], level);
      c.ratioProfileCI = c.profileCI.map(Math.exp);
    }
  }
  // null model: intercept (and offset) only
  let nullDev;
  if (famName === 'binomial' && !d.offset) {
    const ybar = d.y.reduce((a, b) => a + b, 0) / n;
    nullDev = fam.dev(d.y, d.y.map(() => ybar));
  } else nullDev = irls(d.X.map(() => [1]), d.y, off, fam).deviance;
  const rank = struct.rank, dfResidual = n - rank, dfNull = n - 1;
  const lr = nullDev - fit.deviance, lrDf = rank - 1;
  const aic = -2 * fam.loglik(d.y, fit.mu) + 2 * rank;
  const warnings = aliasWarning(d, struct);
  if (!fit.converged) warnings.push({ code: 'not-converged', message: `The fit did not converge in ${fit.iterations} iterations` });
  const keptCols = struct.keep.map(j => d.columns[j]);
  return {
    fam, off, Xk, fit, warnings,
    result: {
      ...modelMeta(d), coefficients, aliased: struct.aliased.map(j => d.names[j]), rank, level,
      deviance: fit.deviance, dfResidual, nullDeviance: nullDev, dfNull,
      lrTest: lrDf > 0 ? { chisq: lr, df: lrDf, p: 1 - pchisq(lr, lrDf) } : null,
      aic, converged: fit.converged, iterations: fit.iterations,
      vif: vifTable(fit.XtXinv, keptCols), fitted: fit.mu, linearPredictor: fit.eta, warnings,
    },
  };
}

function eventCoder(event) {
  if (event !== undefined && event !== null) {
    const ev = String(event).trim();
    return v => isMissing(v) ? null : (String(v).trim() === ev ? 1 : 0);
  }
  return v => {
    if (isMissing(v)) return null;
    if (v === true || v === false) return v ? 1 : 0;
    const x = Number(String(v).trim());
    if (x === 0 || x === 1) return x;
    throw new Error(`Outcome value '${v}' is not 0/1; choose the event level`);
  };
}

/**
 * Logistic regression by IRLS, as glm(family = binomial).
 * @param {object[]} rows @param {string} outcome @param {object[]} predictors
 * @param {{event?:any, level?:number, profile?:boolean}} [opts] event: the outcome value counted as 1
 *   (otherwise the outcome must be 0/1 or boolean); profile: compute profile-likelihood CIs (default true).
 */
export function logisticRegression(rows, outcome, predictors, opts = {}) {
  const d = designMatrix(rows, outcome, predictors, { outcomeValue: eventCoder(opts.event) });
  const events = d.y.reduce((a, b) => a + b, 0);
  if (d.nUsed && (events === 0 || events === d.nUsed)) throw new Error('The outcome does not vary among the complete cases');
  const { fit, warnings, result } = fitGlm(d, 'binomial', opts);
  // separation: fitted probabilities at 0 or 1, or coefficients that kept growing
  const tiny = 1e-8;
  const extreme = fit.mu.filter(m => m < tiny || m > 1 - tiny).length;
  if (extreme || !fit.converged) warnings.push({
    code: 'separation', fittedAtBounds: extreme,
    message: `Possible complete or quasi-complete separation: ${extreme} fitted probabilit${extreme === 1 ? 'y is' : 'ies are'} numerically 0 or 1; estimates and Wald intervals are unreliable`,
  });
  return {
    family: 'binomial', measure: 'OR', event: opts.event ?? 1, events, ...result,
    hosmerLemeshow: hosmerLemeshow(d.y, fit.mu), cStatistic: cStatistic(d.y, fit.mu), warnings,
  };
}

/**
 * Poisson regression by IRLS, as glm(family = poisson).
 * @param {object[]} rows @param {string} outcome @param {object[]} predictors
 * @param {{offset?:string, exposure?:string, level?:number, profile?:boolean}} [opts]
 *   offset: column already on the log scale (R's offset = log(time)); exposure: column logged here.
 */
export function poissonRegression(rows, outcome, predictors, opts = {}) {
  const d = designMatrix(rows, outcome, predictors, { offset: opts.offset, exposure: opts.exposure });
  if (d.y.some(v => v < 0)) throw new Error('A Poisson outcome cannot be negative');
  const { fit, warnings, result } = fitGlm(d, 'poisson', opts);
  const pearson = d.y.reduce((s, v, i) => s + (v - fit.mu[i]) ** 2 / fit.mu[i], 0);
  const dispersion = result.dfResidual > 0 ? pearson / result.dfResidual : NaN;
  if (dispersion > 1.5) warnings.push({ code: 'overdispersion', dispersion, message: `Pearson dispersion ${dispersion.toFixed(2)} exceeds 1.5; standard errors are too small (consider quasi-Poisson or negative binomial)` });
  return { family: 'poisson', measure: 'RR', ...result, pearsonChisq: pearson, dispersion, warnings };
}

// ---- screen and publication table -------------------------------------------------------

const FIT = { linear: linearRegression, gaussian: linearRegression, logistic: logisticRegression, binomial: logisticRegression, poisson: poissonRegression };

/**
 * Fit one unadjusted model per predictor. Each model uses its own complete cases.
 * @param {'linear'|'logistic'|'poisson'} family
 * @returns {{predictor:string, model:object|null, error?:string}[]}
 */
export function univariableScreen(rows, outcome, predictors, family, opts = {}) {
  const f = FIT[family];
  if (!f) throw new Error(`Unknown family '${family}'`);
  return normalizeSpecs(predictors).map(spec => {
    try { return { predictor: spec.column, model: f(rows, outcome, [spec], opts) }; }
    catch (e) { return { predictor: spec.column, model: null, error: e.message }; }
  });
}

function pick(model, c, ci) {
  if (!c || c.aliased) return { est: null, ci: null, p: null };
  if (model.family === 'gaussian') return { est: c.estimate, ci: c.ci, p: c.p };
  const prof = ci !== 'wald' && c.ratioProfileCI && c.ratioProfileCI.every(v => !Number.isNaN(v));
  return { est: c.ratio, ci: prof ? c.ratioProfileCI : c.ratioCI, p: c.p };
}

/**
 * Rows for a univariable/multivariable publication table. Estimates are OR (logistic),
 * RR (Poisson) or β (linear). A categorical predictor contributes a reference row.
 * @param {{predictor:string, model:object|null}[]} univariable from univariableScreen
 * @param {object|null} multivariable a model result
 * @param {{ci?:'profile'|'wald'}} [opts] interval for ratio models (profile by default, Wald when absent)
 */
export function regressionTable(univariable, multivariable, { ci = 'profile' } = {}) {
  const key = (t, l) => `${t}\u0000${l ?? ''}`;
  const uni = new Map(), specs = new Map(), lv = {};
  for (const u of univariable || []) {
    if (!u.model) continue;
    for (const c of u.model.coefficients) if (c.term !== null) uni.set(key(c.term, c.level), { model: u.model, c });
    for (const s of u.model.predictors) if (!specs.has(s.column)) specs.set(s.column, s);
    Object.assign(lv, u.model.levels);
  }
  const multi = new Map();
  if (multivariable) {
    for (const c of multivariable.coefficients) if (c.term !== null) multi.set(key(c.term, c.level), c);
    Object.assign(lv, multivariable.levels);
  }
  const order = [...(multivariable?.predictors || []), ...(univariable || []).flatMap(u => u.model?.predictors || [])];
  const seen = new Set(), rows = [];
  for (const s of order) {
    if (seen.has(s.column)) continue; seen.add(s.column);
    const levels = s.type === 'categorical' ? lv[s.column] : null;
    const entries = levels ? [{ level: levels.reference, reference: true }, ...levels.levels.filter(l => l !== levels.reference).map(level => ({ level }))]
      : [{ level: null }];
    for (const e of entries) {
      const u = uni.get(key(s.column, e.level)), m = multi.get(key(s.column, e.level));
      const a = u ? pick(u.model, u.c, ci) : { est: null, ci: null, p: null };
      const b = m ? pick(multivariable, m, ci) : { est: null, ci: null, p: null };
      rows.push({
        term: s.column, level: e.level, ...(e.reference ? { reference: true } : {}),
        uniEst: a.est, uniCI: a.ci, uniP: a.p, multiEst: b.est, multiCI: b.ci, multiP: b.p,
        ...((u?.c.aliased || m?.aliased) ? { aliased: true } : {}),
      });
    }
  }
  return rows;
}

// Contingency tables, correlation and effect sizes in plain JavaScript.
//
// Every function is pure: it takes counts or numbers and returns a plain object
// with the statistic, its degrees of freedom, a p-value, estimates with
// confidence intervals (option `conf`, default 0.95) and an R-style `method`
// string naming what was computed. Where R has the same test, the algorithm is
// R's own (chisq.test, fisher.test, mcnemar.test, mantelhaen.test, cor.test)
// and the method string matches; where an interval is a convention rather than
// R's (Spearman, Kendall, Cramér's V, the effect sizes), the method or `ciMethod`
// names the convention used. Root finding is by bisection to machine precision,
// so a conditional MLE may differ from R's `uniroot` (tolerance ~1e-4) in the
// fifth significant figure.
//
// A 2×2 table is [[a, b], [c, d]]: rows are the groups (exposed first), columns
// the outcome (event first). Degenerate input (no counts, fewer than two rows or
// columns with data) returns null, as `describe.chiSquare` does.
//
// Checked by app/test/stats-tables.test.mjs against published R output and
// hand derivations; not benchmarked against native R (no `bench/` entry).
import { pnorm, qnorm, pchisq, pt, qt, pbeta } from './dist.mjs';
import { pchisqUpper } from './describe.mjs';

// ---- numerical helpers ----------------------------------------------------

const LANCZOS = [
  676.5203681218851, -1259.1392167224028, 771.32342877765313,
  -176.61502916214059, 12.507343278686905, -0.13857109526572012,
  9.9843695780195716e-6, 1.5056327351493116e-7,
];
function logGamma(x) {
  if (x < 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * x))) - logGamma(1 - x);
  x -= 1;
  let a = 0.99999999999980993;
  const t = x + 7.5;
  for (let i = 0; i < LANCZOS.length; i++) a += LANCZOS[i] / (x + i + 1);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}
const LOG_FACT = [0];
function logFact(n) {
  if (n < 0) return -Infinity;
  if (n < 5000) {
    while (LOG_FACT.length <= n) LOG_FACT.push(LOG_FACT[LOG_FACT.length - 1] + Math.log(LOG_FACT.length));
    return LOG_FACT[n];
  }
  return logGamma(n + 1);
}
const logChoose = (n, k) => (k < 0 || k > n ? -Infinity : logFact(n) - logFact(k) - logFact(n - k));

/** Root of f on [lo, hi] (f(lo), f(hi) of opposite sign) by bisection. */
function bisectRoot(f, lo, hi) {
  let flo = f(lo);
  for (let i = 0; i < 400; i++) {
    const m = (lo + hi) / 2, fm = f(m);
    if (fm === 0) return m;
    if ((fm < 0) === (flo < 0)) { lo = m; flo = fm; } else hi = m;
    if (hi - lo <= 1e-15 * Math.max(Math.abs(lo), Math.abs(hi), 1e-300)) break;
  }
  return (lo + hi) / 2;
}

function checkConf(conf) {
  if (!(conf > 0 && conf < 1)) throw new RangeError(`conf must be between 0 and 1, got ${conf}`);
  return conf;
}
const zCrit = conf => qnorm(1 - (1 - checkConf(conf)) / 2);
/** Two-sided upper-tail normal p, accurate in the far tail. */
const pNorm2 = z => Math.min(1, 2 * pnorm(-Math.abs(z)));
/** Two-sided t p-value. */
const pT2 = (t, df) => Math.min(1, 2 * pt(-Math.abs(t), df));
const pChi = (x, df) => pchisqUpper(x, df);
const sumOf = xs => xs.reduce((a, b) => a + b, 0);

/** Poisson-mixture CDF of the noncentral chi-square. */
function pnchisq(x, df, ncp) {
  if (!(ncp > 0)) return pchisq(x, df);
  const h = ncp / 2, jmax = Math.ceil(h + 12 * Math.sqrt(h) + 40);
  let s = 0;
  for (let j = 0; j <= jmax; j++) {
    const w = Math.exp(-h + j * Math.log(h) - logFact(j));
    if (w > 1e-300) s += w * pchisq(x, df + 2 * j);
  }
  return Math.min(1, s);
}
/** Poisson-mixture CDF of the noncentral F. */
function pnf(f, df1, df2, ncp) {
  const y = df1 * f / (df1 * f + df2);
  const h = Math.max(0, ncp) / 2, jmax = Math.ceil(h + 12 * Math.sqrt(h) + 40);
  let s = 0;
  for (let j = 0; j <= jmax; j++) {
    const w = h === 0 ? (j === 0 ? 1 : 0) : Math.exp(-h + j * Math.log(h) - logFact(j));
    if (w > 1e-300) s += w * pbeta(y, df1 / 2 + j, df2 / 2);
  }
  return Math.min(1, s);
}
/**
 * Two-sided interval for a noncentrality parameter by inverting `cdf(ncp)`,
 * which decreases in ncp: the lower bound puts `obs` at the 1 − α/2 quantile,
 * the upper at α/2. A bound that would be negative is 0.
 */
function ncpInterval(cdf, conf) {
  const a = (1 - checkConf(conf)) / 2;
  const solve = target => {
    if (cdf(0) <= target) return 0;
    let hi = 10;
    while (cdf(hi) > target && hi < 1e7) hi *= 2;
    return bisectRoot(l => cdf(l) - target, 0, hi);
