    }
    if (out) {
      out.sort((a, b) => a.v - b.v);
      const top = out[out.length - 1].v, prefix = [0];
      for (const { v, c } of out) prefix.push(prefix[prefix.length - 1] + c * Math.exp(v - top));
      out = { list: out, top, prefix };
    }
