          work++;
        }
        if (work > maxWork) return null;
      }
    }
    stage = next;
  }
  return Math.min(1, p);
}

// ---- McNemar --------------------------------------------------------------

/**
 * McNemar's test from the discordant counts b and c of a paired 2×2 table,
 * as R's `mcnemar.test`, with the exact binomial (conditional) variant and the
 * conditional odds ratio b/c with its exact (Clopper–Pearson based) interval.
 */
export function mcnemarTest(b, c, { correct = true, conf = 0.95 } = {}) {
  checkConf(conf);
  if (!(Number.isFinite(b) && Number.isFinite(c) && b >= 0 && c >= 0)) throw new TypeError('b and c must be non-negative counts');
  const n = b + c;
  if (!n) return null;
  const useCorrection = correct && b !== c;
  const y = useCorrection ? Math.abs(b - c) - 1 : b - c;
  const statistic = y * y / n;
  const lo = Math.min(b, c);
  let tail = 0;
  for (let i = 0; i <= lo; i++) tail += Math.exp(logChoose(n, i) - n * Math.LN2);
  const exactP = Math.min(1, 2 * tail);
  const [pl, pu] = clopperPearson(b, n, conf);
  return {
    method: useCorrection ? "McNemar's Chi-squared test with continuity correction" : "McNemar's Chi-squared test",
    statistic, df: 1, p: pChi(statistic, 1), n,
    exact: { method: 'Exact McNemar test (binomial, p = 0.5)', p: exactP },
    oddsRatio: { estimate: c ? b / c : Infinity, ci: [pl / (1 - pl), pu >= 1 ? Infinity : pu / (1 - pu)], conf, method: 'conditional odds ratio b/c, Clopper–Pearson' },
  };
}

function qbetaRoot(p, a, b) { return bisectRoot(x => pbeta(x, a, b) - p, 0, 1); }
/** Clopper–Pearson interval for x successes in n. */
function clopperPearson(x, n, conf) {
  const a = (1 - conf) / 2;
  return [x === 0 ? 0 : qbetaRoot(a, x, n - x + 1), x === n ? 1 : qbetaRoot(1 - a, x + 1, n - x)];
}

// ---- Mantel–Haenszel ------------------------------------------------------

/**
 * Stratified 2×2 tables [[a, b], [c, d]], one per stratum. The MH chi-square
 * and common odds ratio with its Robins–Breslow–Greenland interval follow R's
 * `mantelhaen.test`; the MH risk ratio uses the Greenland–Robins variance; the
 * Breslow–Day test of homogeneous odds ratios carries Tarone's correction.
 * Strata with fewer than two observations are left out, as in R.
 */
export function mantelHaenszel(tables, { correct = true, conf = 0.95 } = {}) {
  checkConf(conf);
  if (!Array.isArray(tables) || !tables.length) throw new TypeError('an array of 2×2 tables is required');
  const all = tables.map(check2x2);
  const strata = all.filter(([[a, b], [c, d]]) => a + b + c + d >= 2);
  const warnings = [];
  const dropped = all.length - strata.length;
  if (dropped) warnings.push(`${dropped} strat${dropped > 1 ? 'a' : 'um'} with fewer than two observations ${dropped > 1 ? 'were' : 'was'} left out.`);
  if (!strata.length) return null;
  const z = zCrit(conf);
  let delta = 0, varSum = 0;
  let sR = 0, sS = 0, sPR = 0, sPSQR = 0, sQS = 0;
  let rrNum = 0, rrDen = 0, rrVar = 0;
  for (const [[a, b], [c, d]] of strata) {
    const n = a + b + c + d, n1 = a + b, n0 = c + d, m1 = a + c, m0 = b + d;
    delta += a - n1 * m1 / n;
    varSum += n1 * n0 * m1 * m0 / (n * n * (n - 1));
    const R = a * d / n, S = b * c / n, P = (a + d) / n, Q = (b + c) / n;
    sR += R; sS += S; sPR += P * R; sPSQR += P * S + Q * R; sQS += Q * S;
    rrNum += a * n0 / n; rrDen += c * n1 / n;
    rrVar += (n1 * n0 * m1 - a * c * n) / (n * n);
  }
  const yates = correct && Math.abs(delta) >= 0.5 ? 0.5 : 0;
  const statistic = (Math.abs(delta) - yates) ** 2 / varSum;
  const or = sR / sS;
  const seLogOr = Math.sqrt(sPR / (2 * sR * sR) + sPSQR / (2 * sR * sS) + sQS / (2 * sS * sS));
  const rr = rrNum / rrDen, seLogRr = Math.sqrt(rrVar / (rrNum * rrDen));
  const bd = breslowDay(strata, or);
  return {
    method: yates ? 'Mantel-Haenszel chi-squared test with continuity correction' : 'Mantel-Haenszel chi-squared test without continuity correction',
    statistic, df: 1, p: pChi(statistic, 1), strata: strata.length,
    oddsRatio: { estimate: or, ci: [or * Math.exp(-z * seLogOr), or * Math.exp(z * seLogOr)], seLog: seLogOr, conf, method: 'Mantel-Haenszel, Robins–Breslow–Greenland variance' },
    riskRatio: { estimate: rr, ci: [rr * Math.exp(-z * seLogRr), rr * Math.exp(z * seLogRr)], seLog: seLogRr, conf, method: 'Mantel-Haenszel, Greenland–Robins variance' },
    breslowDay: bd, warnings,
  };
}

function breslowDay(strata, psi) {
  let bd = 0, sumDiff = 0, sumVar = 0, used = 0;
  for (const [[a, b], [c, d]] of strata) {
    const n1 = a + b, n0 = c + d, m1 = a + c;
    const lo = Math.max(0, m1 - n0), hi = Math.min(n1, m1);
    if (lo === hi) continue;          // no information on the odds ratio
    // expected a under the common odds ratio: the root in (lo, hi) of
    // A (n0 − m1 + A) = psi (n1 − A)(m1 − A)
    const qa = 1 - psi, qb = n0 - m1 + psi * (n1 + m1), qc = -psi * n1 * m1;
    let A;
    if (Math.abs(qa) < 1e-12) A = -qc / qb;
    else {
      const disc = Math.sqrt(qb * qb - 4 * qa * qc);
      const r1 = (-qb + disc) / (2 * qa), r2 = (-qb - disc) / (2 * qa);
      A = r1 >= lo - 1e-9 && r1 <= hi + 1e-9 ? r1 : r2;
    }
    const v = 1 / (1 / A + 1 / (n1 - A) + 1 / (m1 - A) + 1 / (n0 - m1 + A));
    bd += (a - A) ** 2 / v;
    sumDiff += a - A; sumVar += v; used++;
  }
  const df = used - 1;
  if (df < 1) return null;
  const tarone = bd - sumDiff * sumDiff / sumVar;
  return { method: "Breslow-Day test with Tarone's correction", statistic: tarone, df, p: pChi(tarone, df), uncorrected: bd, pUncorrected: pChi(bd, df) };
}

// ---- 2×2 effect measures --------------------------------------------------

/** Adds 0.5 to every cell of a 2×2 only when a cell is zero (Haldane). */
function haldane(table) {
  const x = check2x2(table);
  const zero = x.flat().some(v => v === 0);
  return { x: zero ? x.map(r => r.map(v => v + 0.5)) : x, corrected: zero };
}
const corrNote = 'Haldane correction: 0.5 added to every cell because a cell was zero.';

/** Odds ratio (ad)/(bc) with a Wald interval on the log scale. */
export function oddsRatio(table, { conf = 0.95 } = {}) {
  const z = zCrit(conf);
  const { x: [[a, b], [c, d]], corrected } = haldane(table);
  const est = a * d / (b * c), se = Math.sqrt(1 / a + 1 / b + 1 / c + 1 / d);
  return {
    method: 'odds ratio, Wald interval on the log scale', estimate: est, logEstimate: Math.log(est), seLog: se,
    ci: [est * Math.exp(-z * se), est * Math.exp(z * se)], conf, corrected, warnings: corrected ? [corrNote] : [],
  };
}

/** Risk ratio (a/(a+b)) / (c/(c+d)) with a Wald interval on the log scale. */
export function riskRatio(table, { conf = 0.95 } = {}) {
  const z = zCrit(conf);
  const { x: [[a, b], [c, d]], corrected } = haldane(table);
  const n1 = a + b, n0 = c + d;
  const est = (a / n1) / (c / n0), se = Math.sqrt(1 / a - 1 / n1 + 1 / c - 1 / n0);
  return {
    method: 'risk ratio, Wald interval on the log scale', estimate: est, logEstimate: Math.log(est), seLog: se,
    ci: [est * Math.exp(-z * se), est * Math.exp(z * se)], conf, corrected, warnings: corrected ? [corrNote] : [],
  };
}

function wilson(x, n, z) {
  const p = x / n, den = 1 + z * z / n;
  const mid = (p + z * z / (2 * n)) / den, half = z * Math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / den;
  return [Math.max(0, mid - half), Math.min(1, mid + half)];
}
/**
 * Risk difference a/(a+b) − c/(c+d) with Newcombe's hybrid score interval
 * (method 10, from two Wilson intervals). No zero-cell correction is needed.
 */
export function riskDifference(table, { conf = 0.95 } = {}) {
  const z = zCrit(conf);
  const [[a, b], [c, d]] = check2x2(table);
  const n1 = a + b, n0 = c + d;
  if (!n1 || !n0) return null;
  const p1 = a / n1, p2 = c / n0, rd = p1 - p2;
  const [l1, u1] = wilson(a, n1, z), [l2, u2] = wilson(c, n0, z);
  const se = Math.sqrt(p1 * (1 - p1) / n1 + p2 * (1 - p2) / n0);
  return {
    method: 'risk difference, Newcombe hybrid score interval', estimate: rd, conf,
    ci: [rd - Math.sqrt((p1 - l1) ** 2 + (u2 - p2) ** 2), rd + Math.sqrt((u1 - p1) ** 2 + (p2 - l2) ** 2)],
    se, waldCi: [rd - z * se, rd + z * se], p1, p2,
  };
}

// ---- correlation ----------------------------------------------------------

/** Average ranks, ties sharing their mean rank. */
function rank(xs) {
  const idx = xs.map((v, i) => i).sort((i, j) => xs[i] - xs[j]);
  const r = new Array(xs.length);
  for (let i = 0; i < idx.length;) {
    let j = i;
    while (j + 1 < idx.length && xs[idx[j + 1]] === xs[idx[i]]) j++;
    for (let k = i; k <= j; k++) r[idx[k]] = (i + j) / 2 + 1;
    i = j + 1;
  }
  return r;
}
function pearsonR(x, y) {
  const n = x.length, mx = sumOf(x) / n, my = sumOf(y) / n;
  let sxy = 0, sxx = 0, syy = 0;
  for (let i = 0; i < n; i++) { const dx = x[i] - mx, dy = y[i] - my; sxy += dx * dy; sxx += dx * dx; syy += dy * dy; }
  return sxy / Math.sqrt(sxx * syy);
}
const hasTies = xs => new Set(xs).size < xs.length;
const tieGroups = xs => {
  const m = new Map();
  for (const v of xs) m.set(v, (m.get(v) || 0) + 1);
  return [...m.values()].filter(k => k > 1);
};
function completePairs(x, y) {
  if (!Array.isArray(x) || !Array.isArray(y) || x.length !== y.length) throw new TypeError('x and y must be arrays of equal length');
  const xs = [], ys = [];
  for (let i = 0; i < x.length; i++) {
    const a = x[i], b = y[i];
    if (a === null || b === null || a === '' || b === '') continue;
    const na = Number(a), nb = Number(b);
    if (Number.isFinite(na) && Number.isFinite(nb)) { xs.push(na); ys.push(nb); }
  }
  return [xs, ys];
}
const fisherCi = (r, se, z) => [Math.tanh(Math.atanh(r) - z * se), Math.tanh(Math.atanh(r) + z * se)];

/** Probabilities of 0..n(n−1)/2 inversions in a random permutation of n. */
function kendallDist(n) {
  let d = [1];
  for (let i = 2; i <= n; i++) {
    const next = new Array(d.length + i - 1).fill(0);
    for (let k = 0; k < d.length; k++) for (let j = 0; j < i; j++) next[k + j] += d[k] / i;
    d = next;
  }
  return d;
}
/** Exact null distribution of Σ d² for Spearman's rho, by enumeration (n ≤ 9). */
function spearmanExactP(s, n) {
  const used = new Array(n).fill(false);
  let le = 0, ge = 0, total = 0;
  (function rec(i, acc) {
    if (i === n) { total++; if (acc <= s + 1e-9) le++; if (acc >= s - 1e-9) ge++; return; }
    for (let v = 0; v < n; v++) if (!used[v]) { used[v] = true; rec(i + 1, acc + (i - v) ** 2); used[v] = false; }
  })(0, 0);
  return Math.min(1, 2 * Math.min(le, ge) / total);
}

/**
 * Correlation of x and y over complete pairs, as R's `cor.test`.
 * - pearson: t test on n − 2 df; Fisher z interval.
 * - spearman: rho on average ranks; exact permutation p for n ≤ 9 without ties,
 *   otherwise R's t approximation; Fisher z interval with the Bonett–Wright SE
 *   sqrt((1 + rho²/2)/(n − 3)).
 * - kendall: tau-b; exact p for n < 50 without ties (as R), otherwise the
 *   tie-corrected normal approximation; Fisher z interval with the
 *   Fieller–Hartley–Pearson SE sqrt(0.437/(n − 4)).
 */
export function correlation(x, y, { method = 'pearson', conf = 0.95 } = {}) {
  const z = zCrit(conf);
  const [xs, ys] = completePairs(x, y);
  const n = xs.length;
  if (method === 'pearson') {
    if (n < 3) return null;
    const r = pearsonR(xs, ys);
    if (!Number.isFinite(r)) return null;
    const df = n - 2, t = r * Math.sqrt(df / (1 - r * r));
    return {
      method: "Pearson's product-moment correlation", estimate: r, statistic: t, statisticName: 't', df, n,
      p: Math.abs(r) === 1 ? 0 : pT2(t, df),
      ci: n > 3 ? fisherCi(r, 1 / Math.sqrt(n - 3), z) : null, conf, ciMethod: 'Fisher z',
    };
  }
  if (method === 'spearman') {
    if (n < 3) return null;
    const rho = pearsonR(rank(xs), rank(ys));
    if (!Number.isFinite(rho)) return null;
    const ties = hasTies(xs) || hasTies(ys);
    const S = (n ** 3 - n) * (1 - rho) / 6;
    let p, pMethod;
    if (!ties && n <= 9) { p = spearmanExactP(Math.round(S), n); pMethod = 'exact permutation'; }
    else {
      const df = n - 2, t = rho / Math.sqrt((1 - rho * rho) / df);
      p = Math.abs(rho) === 1 ? 0 : pT2(t, df); pMethod = 't approximation';
    }
    return {
      method: "Spearman's rank correlation rho", estimate: rho, statistic: S, statisticName: 'S', n, p, pMethod,
      ci: n > 3 ? fisherCi(rho, Math.sqrt((1 + rho * rho / 2) / (n - 3)), z) : null, conf,
      ciMethod: 'Fisher z with the Bonett–Wright standard error', warnings: ties ? ['Ties present: p uses the t approximation.'] : [],
    };
  }
  if (method === 'kendall') {
    if (n < 2) return null;
    let S = 0;
    for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) S += Math.sign(xs[i] - xs[j]) * Math.sign(ys[i] - ys[j]);
    const T0 = n * (n - 1) / 2, xt = tieGroups(xs), yt = tieGroups(ys);
    const T1 = sumOf(xt.map(k => k * (k - 1) / 2)), T2 = sumOf(yt.map(k => k * (k - 1) / 2));
    const tau = S / Math.sqrt((T0 - T1) * (T0 - T2));
    if (!Number.isFinite(tau)) return null;
    const ties = xt.length > 0 || yt.length > 0;
    let p, statistic, statisticName, pMethod;
    if (!ties && n < 50) {
      const dist = kendallDist(n), q = Math.round((tau + 1) * n * (n - 1) / 4);
      const le = sumOf(dist.slice(0, q + 1)), ge = sumOf(dist.slice(q));
      p = Math.min(1, 2 * (q > n * (n - 1) / 4 ? ge : le));
      statistic = q; statisticName = 'T'; pMethod = 'exact';
    } else {
      const f = (ks, g) => sumOf(ks.map(g));
      const v0 = n * (n - 1) * (2 * n + 5);
      const vt = f(xt, k => k * (k - 1) * (2 * k + 5)), vu = f(yt, k => k * (k - 1) * (2 * k + 5));
      const v1 = f(xt, k => k * (k - 1)) * f(yt, k => k * (k - 1));
      const v2 = f(xt, k => k * (k - 1) * (k - 2)) * f(yt, k => k * (k - 1) * (k - 2));
      const varS = (v0 - vt - vu) / 18 + v1 / (2 * n * (n - 1)) + (n > 2 ? v2 / (9 * n * (n - 1) * (n - 2)) : 0);
      statistic = S / Math.sqrt(varS); statisticName = 'z'; p = pNorm2(statistic); pMethod = 'normal approximation';
    }
    return {
      method: "Kendall's rank correlation tau", estimate: tau, statistic, statisticName, n, p, pMethod,
      ci: n > 4 && Math.abs(tau) < 1 ? fisherCi(tau, Math.sqrt(0.437 / (n - 4)), z) : null, conf,
      ciMethod: 'Fisher z with the Fieller–Hartley–Pearson standard error',
    };
  }
  throw new RangeError(`method must be pearson, spearman or kendall, got ${method}`);
}

/**
 * Pairwise-complete correlation matrix of named columns: estimate, n, p and
 * interval for every pair (the diagonal is 1 with the column's own n).
 */
export function correlationMatrix(columns, method = 'pearson', { conf = 0.95 } = {}) {
  const k = columns.length, names = columns.map(c => c.name);
  const blank = () => Array.from({ length: k }, () => new Array(k).fill(null));
  const r = blank(), n = blank(), p = blank(), ci = blank();
  for (let i = 0; i < k; i++) {
    r[i][i] = 1; n[i][i] = completePairs(columns[i].values, columns[i].values)[0].length;
    for (let j = i + 1; j < k; j++) {
      const res = correlation(columns[i].values, columns[j].values, { method, conf });
      const m = completePairs(columns[i].values, columns[j].values)[0].length;
      r[i][j] = r[j][i] = res ? res.estimate : null;
      p[i][j] = p[j][i] = res ? res.p : null;
      ci[i][j] = ci[j][i] = res ? res.ci : null;
      n[i][j] = n[j][i] = m;
    }
  }
  return { method, names, r, n, p, ci, conf };
}

/** Least-squares residuals of y on the columns of X (with an intercept). */
function residualize(y, X) {
  const n = y.length, k = X.length + 1;
  const col = j => (j === 0 ? null : X[j - 1]);
  const at = (j, i) => (j === 0 ? 1 : col(j)[i]);
  const A = Array.from({ length: k }, (_, a) => Array.from({ length: k + 1 }, (_, b) => {
    let s = 0;
    for (let i = 0; i < n; i++) s += at(a, i) * (b === k ? y[i] : at(b, i));
    return s;
  }));
  for (let c = 0; c < k; c++) {                // Gauss–Jordan with partial pivoting
    let piv = c;
    for (let r = c + 1; r < k; r++) if (Math.abs(A[r][c]) > Math.abs(A[piv][c])) piv = r;
    [A[c], A[piv]] = [A[piv], A[c]];
    if (Math.abs(A[c][c]) < 1e-12 * Math.max(1, Math.abs(A[0][0]))) throw new RangeError('control variables are collinear');
    for (let r = 0; r < k; r++) if (r !== c) {
      const f = A[r][c] / A[c][c];
      for (let b = c; b <= k; b++) A[r][b] -= f * A[c][b];
    }
  }
  const beta = A.map((row, c) => row[k] / row[c]);
  return y.map((v, i) => v - beta.reduce((s, b, j) => s + b * at(j, i), 0));
}

/**
 * Partial Pearson correlation of x and y given `controls` (an array of
 * variables), over rows complete on all of them: t test on n − 2 − k df, Fisher
 * z interval with SE 1/sqrt(n − 3 − k). With `method: 'spearman'` every
 * variable is ranked first.
 */
export function partialCorrelation(x, y, controls = [], { conf = 0.95, method = 'pearson' } = {}) {
  const z = zCrit(conf);
  const all = [x, y, ...controls];
  const len = x.length;
  if (!all.every(v => Array.isArray(v) && v.length === len)) throw new TypeError('x, y and every control must be arrays of equal length');
  const keep = [];
  for (let i = 0; i < len; i++) if (all.every(v => v[i] !== null && v[i] !== '' && Number.isFinite(Number(v[i])))) keep.push(i);
  let cols = all.map(v => keep.map(i => Number(v[i])));
  if (method === 'spearman') cols = cols.map(rank);
  else if (method !== 'pearson') throw new RangeError('method must be pearson or spearman');
  const k = controls.length, n = keep.length, df = n - 2 - k;
  if (df < 1) return null;
  const [cx, cy, ...cz] = cols;
  const r = k ? pearsonR(residualize(cx, cz), residualize(cy, cz)) : pearsonR(cx, cy);
  if (!Number.isFinite(r)) return null;
  const t = r * Math.sqrt(df / (1 - r * r));
  return {
    method: `partial ${method === 'spearman' ? 'Spearman' : 'Pearson'} correlation`, estimate: r, statistic: t, df, n, controls: k,
    p: Math.abs(r) === 1 ? 0 : pT2(t, df),
    ci: n - 3 - k > 0 ? fisherCi(r, 1 / Math.sqrt(n - 3 - k), z) : null, conf, ciMethod: 'Fisher z',
  };
}

// ---- standardized mean differences ----------------------------------------

function checkSummary({ m1, s1, n1, m2, s2, n2 }) {
  for (const [k, v] of Object.entries({ m1, s1, n1, m2, s2, n2 }))
    if (!Number.isFinite(v)) throw new TypeError(`${k} must be a number`);
  if (!(s1 > 0 && s2 > 0 && n1 > 1 && n2 > 1)) throw new RangeError('SDs must be positive and each group needs n > 1');
}
const smdVar = (d, n1, n2) => (n1 + n2) / (n1 * n2) + d * d / (2 * (n1 + n2));
/** Exact small-sample correction J(df) = Γ(df/2) / (sqrt(df/2) Γ((df − 1)/2)). */
const hedgesJ = df => Math.exp(logGamma(df / 2) - 0.5 * Math.log(df / 2) - logGamma((df - 1) / 2));

/**
 * Cohen's d from group summaries, using the pooled SD; normal-approximation
 * interval with variance (n1 + n2)/(n1 n2) + d²/(2(n1 + n2)).
 */
export function cohenD(s, { conf = 0.95 } = {}) {
  checkSummary(s);
  const z = zCrit(conf);
  const { m1, s1, n1, m2, s2, n2 } = s, df = n1 + n2 - 2;
  const sp = Math.sqrt(((n1 - 1) * s1 * s1 + (n2 - 1) * s2 * s2) / df);
  const d = (m1 - m2) / sp, v = smdVar(d, n1, n2);
  return { method: "Cohen's d (pooled SD)", estimate: d, variance: v, se: Math.sqrt(v), ci: [d - z * Math.sqrt(v), d + z * Math.sqrt(v)], conf, sdPooled: sp, df };
}

/** Hedges' g: Cohen's d times the exact correction J(n1 + n2 − 2). */
export function hedgesG(s, { conf = 0.95 } = {}) {
  const d = cohenD(s, { conf });
  const z = zCrit(conf), J = hedgesJ(d.df), g = J * d.estimate, v = J * J * d.variance;
  return { method: "Hedges' g (exact J correction)", estimate: g, variance: v, se: Math.sqrt(v), ci: [g - z * Math.sqrt(v), g + z * Math.sqrt(v)], conf, j: J, df: d.df };
}

/**
 * Glass's delta, (m1 − m2)/s2, standardizing by the second (control) group;
 * variance (n1 + n2)/(n1 n2) + Δ²/(2(n2 − 1)).
 */
export function glassDelta(s, { conf = 0.95 } = {}) {
  checkSummary(s);
  const z = zCrit(conf);
  const { m1, n1, m2, s2, n2 } = s;
  const est = (m1 - m2) / s2, v = (n1 + n2) / (n1 * n2) + est * est / (2 * (n2 - 1));
  return { method: "Glass's delta (control SD)", estimate: est, variance: v, se: Math.sqrt(v), ci: [est - z * Math.sqrt(v), est + z * Math.sqrt(v)], conf };
}

// ---- variance explained from F --------------------------------------------

function fInterval(F, df1, df2, conf) {
  if (!(F >= 0 && df1 > 0 && df2 > 0)) throw new RangeError('F must be ≥ 0 and both df positive');
  const [lo, hi] = ncpInterval(l => pnf(F, df1, df2, l), conf);
  return [lo / df1, hi / df1];          // bounds as F-equivalents λ/df1
}
const eta2Of = (F, df1, df2) => F * df1 / (F * df1 + df2);
const omega2Of = (F, df1, df2) => Math.max(0, (F - 1) * df1 / (F * df1 + df2 + 1));
const eps2Of = (F, df1, df2) => Math.max(0, (F - 1) * df1 / (F * df1 + df2));
const ciNote = 'noncentral F inversion; bounds are the same formula at F = λ/df1';

/** Partial eta squared from F(df1, df2), F df1 / (F df1 + df2). */
export function etaSquared({ F, df1, df2 }, { conf = 0.95 } = {}) {
  const [lo, hi] = fInterval(F, df1, df2, conf);
  return { method: 'partial eta squared', estimate: eta2Of(F, df1, df2), ci: [eta2Of(lo, df1, df2), eta2Of(hi, df1, df2)], conf, ciMethod: ciNote };
}
/** Partial omega squared from F, (F − 1) df1 / (F df1 + df2 + 1), floored at 0. */
export function omegaSquared({ F, df1, df2 }, { conf = 0.95 } = {}) {
  const [lo, hi] = fInterval(F, df1, df2, conf);
  return { method: 'partial omega squared', estimate: omega2Of(F, df1, df2), ci: [omega2Of(lo, df1, df2), omega2Of(hi, df1, df2)], conf, ciMethod: ciNote };
}
/** Partial epsilon squared from F, (F − 1) df1 / (F df1 + df2), floored at 0. */
export function epsilonSquared({ F, df1, df2 }, { conf = 0.95 } = {}) {
  const [lo, hi] = fInterval(F, df1, df2, conf);
  return { method: 'partial epsilon squared', estimate: eps2Of(F, df1, df2), ci: [eps2Of(lo, df1, df2), eps2Of(hi, df1, df2)], conf, ciMethod: ciNote };
}

// ---- conversions (Borenstein et al. 2009, ch. 7) --------------------------

const LOGIT_K = Math.sqrt(3) / Math.PI;
/** log odds ratio → d: d = ln(OR) √3/π, V_d = V_lnOR · 3/π². */
export const logOrToD = (logOr, v) => ({ d: logOr * LOGIT_K, variance: v == null ? undefined : v * LOGIT_K * LOGIT_K });
/** d → log odds ratio: ln(OR) = d π/√3, V = V_d π²/3. */
export const dToLogOr = (d, v) => ({ logOr: d / LOGIT_K, variance: v == null ? undefined : v / (LOGIT_K * LOGIT_K) });
/** r → d: d = 2r/√(1 − r²), V_d = 4 V_r/(1 − r²)³. */
export const rToD = (r, v) => ({ d: 2 * r / Math.sqrt(1 - r * r), variance: v == null ? undefined : 4 * v / (1 - r * r) ** 3 });
/**
 * d → r: r = d/√(d² + a), a = (n1 + n2)²/(n1 n2) (4 when group sizes are not
 * given), V_r = a² V_d/(d² + a)³.
 */
export function dToR(d, v, n1, n2) {
  const a = n1 > 0 && n2 > 0 ? (n1 + n2) ** 2 / (n1 * n2) : 4;
  return { r: d / Math.sqrt(d * d + a), variance: v == null ? undefined : a * a * v / (d * d + a) ** 3 };
}

/**
 * Convert one effect to d, r, odds ratio and log odds ratio. `from` is 'd',
 * 'r', 'or' or 'logor'; `variance` (of that measure; for 'or' of ln OR) gives
 * each result an interval.
 */
export function convertEffect({ from, value, variance, n1, n2 }, { conf = 0.95 } = {}) {
  const z = zCrit(conf);
  let d, vd;
  if (from === 'd') { d = value; vd = variance; }
  else if (from === 'r') ({ d, variance: vd } = rToD(value, variance));
  else if (from === 'or') ({ d, variance: vd } = logOrToD(Math.log(value), variance));
  else if (from === 'logor') ({ d, variance: vd } = logOrToD(value, variance));
  else throw new RangeError(`from must be d, r, or or logor, got ${from}`);
  const r = from === 'r' ? { r: value, variance } : dToR(d, vd, n1, n2);
  const lo = dToLogOr(d, vd);
  const band = (est, v) => (v == null ? null : [est - z * Math.sqrt(v), est + z * Math.sqrt(v)]);
  const rCi = r.variance == null ? null : [Math.max(-1, r.r - z * Math.sqrt(r.variance)), Math.min(1, r.r + z * Math.sqrt(r.variance))];
  const lorCi = band(lo.logOr, lo.variance);
  return {
    method: 'Borenstein et al. (2009) conversions', conf,
    d: { estimate: d, variance: vd, ci: band(d, vd) },
    r: { estimate: r.r, variance: r.variance, ci: rCi },
    logOr: { estimate: lo.logOr, variance: lo.variance, ci: lorCi },
    or: { estimate: Math.exp(lo.logOr), ci: lorCi && lorCi.map(Math.exp) },
  };
}

/**
 * Standardized mean difference d from a reported test statistic.
 * - t with n1, n2: d = t √(1/n1 + 1/n2); with only df: d = 2t/√df (equal groups).
 * - F with df1 = 1: as t = √F (sign unknown).
 * - chi2 with df 1 and n: phi = √(χ²/n), then r → d (sign unknown).
 * - p (two-sided) with n1, n2: t = qt(1 − p/2, n1 + n2 − 2) (sign unknown).
 * The interval uses the Borenstein variance of d.
 */
export function effectFromTestStat(input, { conf = 0.95 } = {}) {
  const z = zCrit(conf);
  const { t, F, chi2, p, df, df1, n1, n2, n } = input;
  const warnings = [];
  let d, v, from;
  const groups = n1 > 0 && n2 > 0;
  const fromT = (tv, source) => {
    from = source;
    if (groups) { d = tv * Math.sqrt(1 / n1 + 1 / n2); v = smdVar(d, n1, n2); return; }
    if (!(df > 0)) throw new RangeError('give n1 and n2, or df');
    d = 2 * tv / Math.sqrt(df);
    const h = (df + 2) / 2; v = smdVar(d, h, h);
    warnings.push('Group sizes not given: equal groups of (df + 2)/2 assumed.');
  };
  if (Number.isFinite(t)) fromT(t, 't');
  else if (Number.isFinite(F)) {
    const d1 = df1 ?? 1;
    if (d1 !== 1) throw new RangeError('d is defined only for F with one numerator df');
    fromT(Math.sqrt(F), 'F');
    warnings.push('The sign of d is not recoverable from F; d is reported as positive.');
  } else if (Number.isFinite(chi2)) {
    if ((df ?? 1) !== 1) throw new RangeError('d is defined only for a chi-square with 1 df');
    const N = n ?? (groups ? n1 + n2 : NaN);
    if (!(N > 1)) throw new RangeError('give n (or n1 and n2) with chi2');
    const r = Math.sqrt(chi2 / N), vr = (1 - r * r) ** 2 / (N - 1);
    ({ d, variance: v } = rToD(r, vr)); from = 'chi2';
    warnings.push('The sign of d is not recoverable from chi-square; d is reported as positive.');
  } else if (Number.isFinite(p)) {
    if (!(p > 0 && p <= 1)) throw new RangeError('p must be in (0, 1]');
    if (!groups) throw new RangeError('give n1 and n2 with p');
    fromT(qt(1 - p / 2, n1 + n2 - 2), 'p');
    warnings.push('The sign of d is not recoverable from a two-sided p; d is reported as positive.');
  } else throw new TypeError('give one of t, F, chi2 or p');
  return { method: `standardized mean difference from ${from}`, estimate: d, variance: v, se: Math.sqrt(v), ci: [d - z * Math.sqrt(v), d + z * Math.sqrt(v)], conf, warnings };
}

// Classical hypothesis tests, effect sizes and interval estimates for one
// numeric variable, in plain JavaScript.
//
// Each function follows the R function it is named after (stats::t.test,
// oneway.test, aov + TukeyHSD, bartlett.test, car::leveneTest, wilcox.test,
// kruskal.test, friedman.test, binom.test, shapiro.test, nortest::ad.test,
// p.adjust) and reports the `method` line R prints. The results are checked in
// test/stats-tests.test.mjs against R's documented outputs on the sleep,
// PlantGrowth, mtcars and RoundingTimes data, and against identities that
// recompute them independently (Student t² = one-way F, Tukey and
// Games-Howell with two groups = Student and Welch t).
//
// Inputs are arrays of numbers; null, '' and non-finite entries are ignored and
// the n actually used is reported. Functions return null when there is not
// enough data for the test to be defined.

import { pt, qt, pnorm, qnorm, pchisq, pbeta } from './dist.mjs';
import { quantile, kruskalWallis } from './describe.mjs';

// ---- small helpers ---------------------------------------------------------

const LANCZOS = [
  676.5203681218851, -1259.1392167224028, 771.32342877765313,
  -176.61502916214059, 12.507343278686905, -0.13857109526572012,
  9.9843695780195716e-6, 1.5056327351493116e-7,
];
function lgam(x) {
  if (x < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * x)) - lgam(1 - x);
  x -= 1;
  let a = 0.99999999999980993;
  const t = x + 7.5;
  for (let i = 0; i < LANCZOS.length; i++) a += LANCZOS[i] / (x + i + 1);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}

const isVal = v => v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v));
const clean = xs => (xs || []).filter(isVal).map(Number);
/** Complete pairs only, as R's paired tests. */
function pairs(x, y) {
  const a = [], b = [];
  const n = Math.min(x?.length || 0, y?.length || 0);
  for (let i = 0; i < n; i++) if (isVal(x[i]) && isVal(y[i])) { a.push(Number(x[i])); b.push(Number(y[i])); }
  return [a, b];
}
const sum = xs => xs.reduce((a, b) => a + b, 0);
const mean = xs => sum(xs) / xs.length;
function variance(xs) {
  const m = mean(xs);
  return xs.reduce((a, v) => a + (v - m) ** 2, 0) / (xs.length - 1);
}
const sortNum = xs => [...xs].sort((a, b) => a - b);
const med = xs => quantile(sortNum(xs), 0.5);
const alphaOf = conf => 1 - (conf ?? 0.95);

/** Upper normal tail 1 - Φ(z), accurate far into the tail. */
function normUpper(z) {
  if (z < 0) return 1 - normUpper(-z);
  const x = z * z / 2;
  if (x < 1.5) return 1 - pnorm(z);
  // Q(1/2, x) by Lentz's continued fraction
  const TINY = 1e-300, s = 0.5;
  let b = x + 1 - s, c = 1 / TINY, d = 1 / b, h = d;
  for (let i = 1; i < 1000; i++) {
    const an = -i * (i - s);
    b += 2;
    d = an * d + b; if (Math.abs(d) < TINY) d = TINY;
    c = b + an / c; if (Math.abs(c) < TINY) c = TINY;
    d = 1 / d;
    const del = d * c;
    h *= del;
    if (Math.abs(del - 1) < 1e-16) break;
  }
  return 0.5 * h * Math.exp(-x + s * Math.log(x) - 0.5 * Math.log(Math.PI));
}
const twoSidedZ = z => Math.min(1, 2 * normUpper(Math.abs(z)));
const twoSidedT = (t, df) => Math.min(1, 2 * pt(-Math.abs(t), df));

/** Mid-ranks and the sizes of tied runs. */
function rank(xs) {
  const n = xs.length;
  const order = xs.map((v, i) => [v, i]).sort((a, b) => a[0] - b[0]);
  const r = new Array(n), ties = [];
  for (let i = 0; i < n;) {
    let j = i;
    while (j + 1 < n && order[j + 1][0] === order[i][0]) j++;
    const mid = (i + j) / 2 + 1;
    for (let k = i; k <= j; k++) r[order[k][1]] = mid;
    if (j > i) ties.push(j - i + 1);
    i = j + 1;
  }
  return { ranks: r, ties };
}
const tieSum = ties => ties.reduce((a, t) => a + t ** 3 - t, 0);

function bisect(f, lo, hi, iters = 200) {
  let flo = f(lo);
  for (let i = 0; i < iters; i++) {
    const m = (lo + hi) / 2, fm = f(m);
    if (fm === 0) return m;
    if ((fm < 0) === (flo < 0)) { lo = m; flo = fm; } else hi = m;
    if (hi - lo <= 1e-14 * Math.max(1, Math.abs(m))) break;
  }
  return (lo + hi) / 2;
}

/** Binomial(n, 1/2) cumulative P(X ≤ k). */
function pbinomHalf(k, n) {
  if (k < 0) return 0;
  if (k >= n) return 1;
  let s = 0;
  const base = lgam(n + 1) - n * Math.LN2;
  for (let i = 0; i <= k; i++) s += Math.exp(base - lgam(i + 1) - lgam(n - i + 1));
  return Math.min(1, s);
}

function cleanGroups(groups) {
  return (groups || [])
    .map((g, i) => ({ name: g.name ?? `Group ${i + 1}`, values: clean(g.values) }))
    .filter(g => g.values.length);
}

// ---- distributions not in dist.mjs -------------------------------------------

/** F distribution P(F ≤ f); `lower = false` for the upper tail. */
export function pf(f, d1, d2, lower = true) {
  if (!(f > 0)) return lower ? 0 : 1;
  if (f === Infinity) return lower ? 1 : 0;
  // upper tail through the complementary beta keeps small p-values accurate
  const up = pbeta(d2 / (d2 + d1 * f), d2 / 2, d1 / 2);
  return lower ? 1 - up : up;
}
export function qf(p, d1, d2) {
  if (p <= 0) return 0;
  let hi = 10;
  while (pf(hi, d1, d2) < p) hi *= 2;
  return bisect(f => pf(f, d1, d2) - p, 0, hi);
}

/** Noncentral t P(T ≤ t; df, ncp), by R's pnt (Lenth 1989, AS 243). */
export function pnt(t, df, ncp) {
  if (ncp === 0) return pt(t, df);
  if (!Number.isFinite(t)) return t < 0 ? 0 : 1;
  let negdel, tt, del;
  if (t >= 0) { negdel = false; tt = t; del = ncp; }
  else { if (ncp > 40) return 0; negdel = true; tt = -t; del = -ncp; }
  if (df > 4e5 || del * del > 2 * Math.LN2 * 1021) {
    const s = 1 / (4 * df);
    const z = (tt * (1 - s) - del) / Math.sqrt(1 + tt * tt * 2 * s);
    return negdel ? 1 - pnorm(z) : pnorm(z);
  }
  const x0 = t * t, x = x0 / (x0 + df);
  let tnc = 0;
  if (x > 0) {
    const lambda = del * del;
    let p = 0.5 * Math.exp(-0.5 * lambda);
    let q = Math.sqrt(2 / Math.PI) * p * del;
    let s = 0.5 - p;
    if (s < 1e-7) s = -0.5 * Math.expm1(-0.5 * lambda);
    let a = 0.5;
    const b = 0.5 * df;
    const rxb = Math.pow(1 - x, b);
    const albeta = 0.5 * Math.log(Math.PI) + lgam(b) - lgam(0.5 + b);
    let xodd = pbeta(x, a, b);
    let godd = 2 * rxb * Math.exp(a * Math.log(x) - albeta);
    let tn = b * x;
    let xeven = tn < Number.EPSILON ? tn : 1 - rxb;
    let geven = tn * rxb;
    tnc = p * xodd + q * xeven;
    for (let it = 1; it <= 1000; it++) {
      a += 1;
      xodd -= godd;
      xeven -= geven;
      godd *= x * (a + b - 1) / a;
      geven *= x * (a + b - 0.5) / (a + 0.5);
      p *= lambda / (2 * it);
      q *= lambda / (2 * it + 1);
      tnc += p * xodd + q * xeven;
      s -= p;
      if (s < -1e-10) break;
      if (s <= 0 && it > 1) break;
      if (Math.abs(2 * s * (xodd - godd)) < 1e-12) break;
    }
  }
  tnc += pnorm(-del);
  tnc = Math.min(tnc, 1);
  return negdel ? 1 - tnc : tnc;
}

// Gauss–Legendre nodes on [-1, 1], computed once.
const GL = (() => {
  const n = 20, x = [], w = [];
  for (let i = 1; i <= n; i++) {
    let z = Math.cos(Math.PI * (i - 0.25) / (n + 0.5)), pp;
    for (let it = 0; it < 100; it++) {
      let p1 = 1, p2 = 0;
      for (let j = 1; j <= n; j++) { const p3 = p2; p2 = p1; p1 = ((2 * j - 1) * z * p2 - (j - 1) * p3) / j; }
      pp = n * (z * p1 - p2) / (z * z - 1);
      const z1 = z; z = z1 - p1 / pp;
      if (Math.abs(z - z1) < 1e-15) break;
    }
    x.push(z); w.push(2 / ((1 - z * z) * pp * pp));
  }
  return { x, w };
})();
function integrate(f, a, b, panels) {
  const h = (b - a) / panels;
  let s = 0;
  for (let p = 0; p < panels; p++) {
    const c = a + (p + 0.5) * h;
    for (let i = 0; i < GL.x.length; i++) s += GL.w[i] * f(c + GL.x[i] * h / 2);
  }
  return s * h / 2;
}

// Φ from a table and its Taylor series (Hermite polynomials), for the
// studentized range, where it is evaluated a few hundred thousand times.
const PHI_STEP = 0.01, PHI_MAX = 9;
let PHI_TABLE = null;
function Phi(x) {
  if (x <= -PHI_MAX) return normUpper(-x);
  if (x >= PHI_MAX) return 1;
  if (!PHI_TABLE) {
    PHI_TABLE = [];
    for (let i = 0; i <= 2 * PHI_MAX / PHI_STEP; i++) PHI_TABLE.push(normUpper(PHI_MAX - i * PHI_STEP));
  }
  const i = Math.round((x + PHI_MAX) / PHI_STEP), a = -PHI_MAX + i * PHI_STEP, h = x - a;
  const phi = Math.exp(-a * a / 2) / Math.sqrt(2 * Math.PI);
  // Φ(a+h) = Φ(a) + φ(a) Σ (-1)^n He_n(a) h^(n+1)/(n+1)!
  let hePrev = 1, he = a, s = h, term = h;
  for (let n = 1; n <= 9; n++) {
    term *= h / (n + 1);
    s += (n % 2 ? -1 : 1) * he * term;
    const next = a * he - n * hePrev;
    hePrev = he; he = next;
  }
  return PHI_TABLE[i] + phi * s;
}

/** P(range of k standard normals < w). */
function rangeCdf(w, k) {
  if (w <= 0) return 0;
  const c = k / Math.sqrt(2 * Math.PI);
  return Math.min(1, c * integrate(z => {
    const d = Phi(z) - Phi(z - w);
    return d > 0 ? Math.exp(-z * z / 2) * d ** (k - 1) : 0;
  }, -8.5, 8.5, 12));
}

/**
 * Studentized range P(Q ≤ q; k groups, df), by direct numerical integration of
 * the range distribution over the distribution of s (Gauss–Legendre).
 */
export function ptukey(q, k, df) {
  if (!(q > 0)) return 0;
  if (!Number.isFinite(df)) return rangeCdf(q, k);
  // integrate over t = log s; s = sqrt(chi²_df / df)
  const c = Math.LN2 + (df / 2) * Math.log(df / 2) - lgam(df / 2);
  const logg = t => c + df * t - df * Math.exp(2 * t) / 2;
  const top = logg(0);
  const lo = bisect(t => logg(t) - top + 45, -200, 0);
  const hi = bisect(t => top - 45 - logg(t), 0, 10);
  return Math.min(1, integrate(t => Math.exp(logg(t)) * rangeCdf(q * Math.exp(t), k), lo, hi, 12));
}
export function qtukey(p, k, df) {
  let hi = 8;
  while (ptukey(hi, k, df) < p) hi *= 2;
  // Illinois (regula falsi) on the bracket
  let a = 0, fa = -p, b = hi, fb = ptukey(hi, k, df) - p, side = 0, c = b;
  for (let i = 0; i < 80; i++) {
    c = (a * fb - b * fa) / (fb - fa);
    const fc = ptukey(c, k, df) - p;
    if (Math.abs(fc) < 1e-12 || Math.abs(b - a) < 1e-10 * c) break;
    if ((fc > 0) === (fb > 0)) { b = c; fb = fc; if (side === -1) fa /= 2; side = -1; }
    else { a = c; fa = fc; if (side === 1) fb /= 2; side = 1; }
  }
  return c;
}

// ---- effect sizes ----------------------------------------------------------

/** Exact small-sample correction J(df) that turns Cohen's d into Hedges' g. */
const hedgesJ = df => Math.exp(lgam(df / 2) - 0.5 * Math.log(df / 2) - lgam((df - 1) / 2));

/** Noncentrality parameters bracketing an observed t at the given confidence. */
function ncpInterval(t, df, conf) {
  const a = alphaOf(conf);
  const w = 10 + 2 * Math.abs(t);
  const lo = bisect(ncp => pnt(t, df, ncp) - (1 - a / 2), t - w, t + w);
  const hi = bisect(ncp => pnt(t, df, ncp) - a / 2, t - w, t + w);
  return [lo, hi];
}
/** Cohen's d and Hedges' g from a t statistic; `scale` turns ncp into d. */
function effectSizes(d, t, df, scale, conf) {
  const [l, u] = ncpInterval(t, df, conf);
  const J = hedgesJ(df);
  const ci = [l * scale, u * scale];
  return {
    cohensD: { estimate: d, ci, method: 'noncentral t' },
    hedgesG: { estimate: d * J, ci: ci.map(v => v * J), method: 'noncentral t; exact gamma-function correction' },
  };
}

// ---- t tests ---------------------------------------------------------------

/** One-sample t test of H0: mean = mu (R t.test(x, mu = mu)). */
export function tTestOne(x, { mu = 0, conf = 0.95 } = {}) {
  const xs = clean(x), n = xs.length;
  if (n < 2) return null;
  const m = mean(xs), sd = Math.sqrt(variance(xs)), se = sd / Math.sqrt(n), df = n - 1;
  const t = (m - mu) / se, h = qt(1 - alphaOf(conf) / 2, df) * se;
  return {
    method: 'One Sample t-test', n, missing: (x?.length || 0) - n, mu,
    estimate: m, ci: [m - h, m + h], conf, difference: m - mu, se, sd,
    statistic: t, df, p: twoSidedT(t, df),
    ...effectSizes((m - mu) / sd, t, df, 1 / Math.sqrt(n), conf),
  };
}

/**
 * Two-sample t test of mean(x) - mean(y) (R t.test(x, y)). Welch by default;
 * Student with `equalVar`. Cohen's d uses the pooled SD in both cases, and its
 * interval inverts the noncentral t of the pooled-variance statistic.
 */
export function tTestTwo(x, y, { equalVar = false, conf = 0.95 } = {}) {
  const xs = clean(x), ys = clean(y), nx = xs.length, ny = ys.length;
  if (nx < 2 || ny < 2) return null;
  const mx = mean(xs), my = mean(ys), vx = variance(xs), vy = variance(ys);
  const dfPool = nx + ny - 2;
  const vp = ((nx - 1) * vx + (ny - 1) * vy) / dfPool;
  const sePool = Math.sqrt(vp * (1 / nx + 1 / ny));
  let se, df;
  if (equalVar) { se = sePool; df = dfPool; }
  else {
    const a = vx / nx, b = vy / ny;
    se = Math.sqrt(a + b);
    df = (a + b) ** 2 / (a * a / (nx - 1) + b * b / (ny - 1));
  }
  const diff = mx - my, t = diff / se, h = qt(1 - alphaOf(conf) / 2, df) * se;
  return {
    method: equalVar ? 'Two Sample t-test' : 'Welch Two Sample t-test',
    n: [nx, ny], missing: [(x?.length || 0) - nx, (y?.length || 0) - ny],
    means: [mx, my], estimate: diff, ci: [diff - h, diff + h], conf, se,
    statistic: t, df, p: twoSidedT(t, df),
    ...effectSizes(diff / Math.sqrt(vp), diff / sePool, dfPool, Math.sqrt(1 / nx + 1 / ny), conf),
  };
}

/** Paired t test on x - y over complete pairs (R t.test(x, y, paired = TRUE)). Cohen's d is d_z. */
export function tTestPaired(x, y, { conf = 0.95 } = {}) {
  const [a, b] = pairs(x, y);
  const d = a.map((v, i) => v - b[i]), n = d.length;
  if (n < 2) return null;
  const m = mean(d), sd = Math.sqrt(variance(d)), se = sd / Math.sqrt(n), df = n - 1;
  const t = m / se, h = qt(1 - alphaOf(conf) / 2, df) * se;
  return {
    method: 'Paired t-test', n, missing: Math.max(x?.length || 0, y?.length || 0) - n,
    estimate: m, ci: [m - h, m + h], conf, se, sd,
    statistic: t, df, p: twoSidedT(t, df),
    ...effectSizes(m / sd, t, df, 1 / Math.sqrt(n), conf),
  };
}

// ---- one-way ANOVA and variances ---------------------------------------------

function oneWayCore(gs) {
  const k = gs.length, all = gs.flatMap(g => g.values), N = all.length;
  const grand = mean(all);
  const ssb = sum(gs.map(g => g.values.length * (mean(g.values) - grand) ** 2));
  const ssw = sum(gs.map(g => { const m = mean(g.values); return g.values.reduce((a, v) => a + (v - m) ** 2, 0); }));
  const dfb = k - 1, dfw = N - k, msb = ssb / dfb, msw = ssw / dfw, F = msb / msw;
  return { k, N, ssb, ssw, dfb, dfw, msb, msw, F, p: pf(F, dfb, dfw, false) };
}

/**
 * One-way ANOVA (R summary(aov(y ~ g))), or Welch's heteroscedastic F with
 * `welch` (R oneway.test). eta² and omega² come from the classical table.
 */
export function anovaOneWay(groups, { welch = false } = {}) {
  const gs = cleanGroups(groups);
  if (gs.length < 2) return null;
  const c = oneWayCore(gs);
  if (!(c.dfw > 0)) return null;
  const sst = c.ssb + c.ssw;
  const out = {
    method: 'One-way analysis of means',
    groups: gs.map(g => ({ name: g.name, n: g.values.length, mean: mean(g.values), sd: Math.sqrt(variance(g.values)) })),
    n: c.N,
    table: {
      between: { ss: c.ssb, df: c.dfb, ms: c.msb },
      within: { ss: c.ssw, df: c.dfw, ms: c.msw },
      total: { ss: sst, df: c.N - 1 },
    },
    statistic: c.F, df: [c.dfb, c.dfw], p: c.p,
    eta2: c.ssb / sst,
    omega2: (c.ssb - c.dfb * c.msw) / (sst + c.msw),
  };
  if (!welch) return out;
  if (gs.some(g => g.values.length < 2)) return null;
  const k = gs.length;
  const w = gs.map(g => g.values.length / variance(g.values)), sw = sum(w);
  const ms = gs.map(g => mean(g.values));
  const mw = sum(ms.map((m, i) => w[i] * m)) / sw;
  const tmp = sum(gs.map((g, i) => (1 - w[i] / sw) ** 2 / (g.values.length - 1))) / (k * k - 1);
  const F = sum(ms.map((m, i) => w[i] * (m - mw) ** 2)) / ((k - 1) * (1 + 2 * (k - 2) * tmp));
  const df2 = 1 / (3 * tmp);
  return { ...out, method: 'One-way analysis of means (not assuming equal variances)', statistic: F, df: [k - 1, df2], p: pf(F, k - 1, df2, false) };
}

/** Levene's test: ANOVA on |x - centre| (car::leveneTest; median centre is Brown–Forsythe). */
export function leveneTest(groups, { center = 'median' } = {}) {
  const gs = cleanGroups(groups);
  if (gs.length < 2) return null;
  const dev = gs.map(g => {
    const c = center === 'mean' ? mean(g.values) : med(g.values);
    return { name: g.name, values: g.values.map(v => Math.abs(v - c)) };
  });
  const c = oneWayCore(dev);
  if (!(c.dfw > 0)) return null;
  return {
    method: `Levene's Test for Homogeneity of Variance (center = ${center === 'mean' ? 'mean' : 'median'})`,
    n: c.N, statistic: c.F, df: [c.dfb, c.dfw], p: c.p,
  };
}

/** Bartlett's test of equal variances (R bartlett.test). */
export function bartlettTest(groups) {
  const gs = cleanGroups(groups).filter(g => g.values.length >= 2);
  if (gs.length < 2) return null;
  const k = gs.length, ni = gs.map(g => g.values.length - 1), vi = gs.map(g => variance(g.values));
  const nt = sum(ni), vt = sum(ni.map((n, i) => n * vi[i])) / nt;
  const K = (nt * Math.log(vt) - sum(ni.map((n, i) => n * Math.log(vi[i])))) /
    (1 + (sum(ni.map(n => 1 / n)) - 1 / nt) / (3 * (k - 1)));
  return { method: 'Bartlett test of homogeneity of variances', n: nt + k, statistic: K, df: k - 1, p: 1 - pchisq(K, k - 1) };
}

// ---- multiple comparisons --------------------------------------------------

/** R p.adjust for 'bonferroni', 'holm', 'hochberg', 'BH' (alias 'fdr') and 'BY'. Non-finite entries stay null. */
export function pAdjust(ps, method = 'holm') {
  const idx = [], vals = [];
  (ps || []).forEach((p, i) => { if (isVal(p)) { idx.push(i); vals.push(Number(p)); } });
  const n = vals.length, out = (ps || []).map(() => null);
  if (!n) return out;
  let adj;
  if (method === 'bonferroni') adj = vals.map(p => Math.min(1, n * p));
  else if (method === 'holm') {
    const o = vals.map((p, i) => [p, i]).sort((a, b) => a[0] - b[0]);
    adj = new Array(n); let run = 0;
    o.forEach(([p, i], r) => { run = Math.max(run, (n - r) * p); adj[i] = Math.min(1, run); });
  } else if (['hochberg', 'BH', 'fdr', 'BY'].includes(method)) {
    const q = method === 'BY' ? sum(Array.from({ length: n }, (_, i) => 1 / (i + 1))) : 1;
    const o = vals.map((p, i) => [p, i]).sort((a, b) => b[0] - a[0]);
    adj = new Array(n); let run = Infinity;
    o.forEach(([p, i], r) => {
      const rankAsc = n - r;                         // i in R's `i <- lp:1`
      const f = method === 'hochberg' ? (n - rankAsc + 1) : q * n / rankAsc;
      run = Math.min(run, f * p); adj[i] = Math.min(1, run);
    });
  } else throw new Error(`pAdjust: unknown method ${method}`);
  idx.forEach((j, k) => { out[j] = adj[k]; });
  return out;
}

function pairwise(gs, fn) {
  const out = [];
  for (let i = 0; i < gs.length; i++)
    for (let j = i + 1; j < gs.length; j++) out.push({ a: gs[i].name, b: gs[j].name, label: `${gs[j].name}-${gs[i].name}`, ...fn(gs[i], gs[j]) });
  return out;
}

/** Tukey HSD on the one-way ANOVA (R TukeyHSD(aov(y ~ g))); diff is later group minus earlier, as R. */
export function tukeyHSD(groups, { conf = 0.95 } = {}) {
  const gs = cleanGroups(groups);
  if (gs.length < 2) return null;
  const c = oneWayCore(gs);
  if (!(c.dfw > 0)) return null;
  const qc = qtukey(conf, c.k, c.dfw);
  return {
    method: 'Tukey multiple comparisons of means', conf, df: c.dfw, mse: c.msw,
    comparisons: pairwise(gs, (a, b) => {
      const diff = mean(b.values) - mean(a.values);
      const se = Math.sqrt(c.msw / 2 * (1 / a.values.length + 1 / b.values.length));
      return { diff, ci: [diff - qc * se, diff + qc * se], statistic: Math.abs(diff) / se, p: 1 - ptukey(Math.abs(diff) / se, c.k, c.dfw) };
    }),
  };
}

/** Games–Howell pairwise comparisons: Welch SE and df per pair, studentized range reference. */
export function gamesHowell(groups, { conf = 0.95 } = {}) {
  const gs = cleanGroups(groups).filter(g => g.values.length >= 2);
  if (gs.length < 2) return null;
  const k = gs.length;
  return {
    method: 'Games-Howell test', conf,
    comparisons: pairwise(gs, (a, b) => {
      const va = variance(a.values) / a.values.length, vb = variance(b.values) / b.values.length;
      const diff = mean(b.values) - mean(a.values);
      const se = Math.sqrt((va + vb) / 2);
      const df = (va + vb) ** 2 / (va * va / (a.values.length - 1) + vb * vb / (b.values.length - 1));
      const qc = qtukey(conf, k, df), q = Math.abs(diff) / se;
      return { diff, ci: [diff - qc * se, diff + qc * se], statistic: q, df, p: 1 - ptukey(q, k, df) };
    }),
  };
}

// ---- rank tests ------------------------------------------------------------

/** P(U ≤ u) for the Mann–Whitney U with sample sizes m, n (no ties). */
function wilcoxCdfTable(m, n) {
  // number of m-subsets of ranks 1..m+n by rank sum, then shift to U
  const N = m + n, maxS = m * (2 * N - m + 1) / 2;
  let dp = Array.from({ length: m + 1 }, () => new Float64Array(maxS + 1));
  dp[0][0] = 1;
  for (let r = 1; r <= N; r++)
    for (let j = Math.min(r, m); j >= 1; j--) {
      const cur = dp[j], prev = dp[j - 1];
      for (let s = maxS; s >= r; s--) cur[s] += prev[s - r];
    }
  const off = m * (m + 1) / 2, total = Math.exp(lgam(N + 1) - lgam(m + 1) - lgam(n + 1));
  const cdf = new Float64Array(m * n + 1);
  let run = 0;
  for (let u = 0; u <= m * n; u++) { run += dp[m][u + off]; cdf[u] = run / total; }
  return cdf;
}
/** P(V ≤ v) for the signed-rank statistic with n non-zero differences (no ties). */
function signrankCdfTable(n) {
  const M = n * (n + 1) / 2, c = new Float64Array(M + 1);
  c[0] = 1;
  for (let r = 1; r <= n; r++) for (let s = M; s >= r; s--) c[s] += c[s - r];
  const out = new Float64Array(M + 1), total = Math.pow(2, n);
  let run = 0;
  for (let v = 0; v <= M; v++) { run += c[v]; out[v] = run / total; }
  return out;
}
const cdfAt = (cdf, v) => v < 0 ? 0 : v >= cdf.length - 1 ? 1 : cdf[Math.floor(v)];
/** Smallest q with P(X ≤ q) ≥ p (R's qwilcox/qsignrank). */
const cdfQuantile = (cdf, p) => { let q = 0; while (q < cdf.length - 1 && cdf[q] < p * (1 - 64 * Number.EPSILON)) q++; return q; };
const exactTwoSided = (cdf, stat, centre) =>
  Math.min(1, 2 * (stat > centre ? 1 - cdfAt(cdf, stat - 1) : cdfAt(cdf, stat)));

/**
 * Wilcoxon rank-sum (Mann–Whitney) test of x against y, as R wilcox.test(x, y,
 * conf.int = TRUE): exact when both samples have fewer than 50 values and there
 * are no ties, otherwise the normal approximation with tie and continuity
 * correction. The Hodges–Lehmann shift is the median of pairwise differences
 * (exact case) or the zero of the corrected z statistic (normal case, as R).
 */
export function mannWhitney(x, y, { conf = 0.95, exact } = {}) {
  const xs = clean(x), ys = clean(y), nx = xs.length, ny = ys.length;
  if (!nx || !ny) return null;
  const { ranks, ties } = rank([...xs, ...ys]);
  const W = sum(ranks.slice(0, nx)) - nx * (nx + 1) / 2;
  const useExact = exact ?? (nx < 50 && ny < 50 && !ties.length);
  const a = alphaOf(conf);
  const base = { n: [nx, ny], missing: [(x?.length || 0) - nx, (y?.length || 0) - ny], statistic: W, conf };
  if (useExact && !ties.length) {
    const cdf = wilcoxCdfTable(nx, ny);
    const diffs = sortNum(xs.flatMap(u => ys.map(v => u - v)));
    let qu = cdfQuantile(cdf, a / 2); if (qu === 0) qu = 1;
    const ql = nx * ny - qu;
    return {
      ...base, method: 'Wilcoxon rank sum exact test',
      p: exactTwoSided(cdf, W, nx * ny / 2),
      estimate: med(diffs), ci: [diffs[qu - 1], diffs[ql]], achievedConf: 1 - 2 * cdfAt(cdf, qu - 1),
    };
  }
  const N = nx + ny;
  const sigmaOf = t => Math.sqrt((nx * ny / 12) * ((N + 1) - tieSum(t) / (N * (N - 1))));
  const sigma = sigmaOf(ties);
  const z0 = W - nx * ny / 2;
  const z = (z0 - Math.sign(z0) * 0.5) / sigma;
  const out = { ...base, method: 'Wilcoxon rank sum test with continuity correction', p: twoSidedZ(z), z };
  // Hodges–Lehmann by inverting the corrected statistic (R's wdiff)
  const wdiff = (d, zq) => {
    const r = rank([...xs.map(v => v - d), ...ys]);
    const dz = sum(r.ranks.slice(0, nx)) - nx * (nx + 1) / 2 - nx * ny / 2;
    const s = sigmaOf(r.ties);
    return s > 0 ? (dz - Math.sign(dz) * 0.5) / s - zq : NaN;
  };
  const lo0 = Math.min(...xs) - Math.max(...ys), hi0 = Math.max(...xs) - Math.min(...ys);
  const root = zq => {
    const fl = wdiff(lo0, zq), fu = wdiff(hi0, zq);
    if (!(fl > 0)) return lo0;
    if (!(fu < 0)) return hi0;
    return bisect(d => wdiff(d, zq), lo0, hi0, 100);
  };
  if (sigma > 0 && N > 2) {
    const zc = qnorm(1 - a / 2);
    out.estimate = root(0);
    out.ci = [root(zc), root(-zc)];
  }
  return out;
}

/**
 * Wilcoxon signed-rank test of x - y (paired, complete pairs) or of x - mu, as
 * R wilcox.test(..., paired = TRUE, conf.int = TRUE). Zero differences are
 * dropped. Exact below 50 differences without ties or zeros; otherwise the
 * normal approximation with tie and continuity correction.
 */
export function wilcoxonSignedRank(x, y, { mu = 0, conf = 0.95, exact } = {}) {
  let d;
  if (y) { const [a, b] = pairs(x, y); d = a.map((v, i) => v - b[i] - mu); }
  else d = clean(x).map(v => v - mu);
  const nAll = d.length;
  const zeros = d.filter(v => v === 0).length;
  d = d.filter(v => v !== 0);
  const n = d.length;
  if (!n) return null;
  const { ranks, ties } = rank(d.map(Math.abs));
  const V = sum(ranks.filter((r, i) => d[i] > 0));
  const a = alphaOf(conf);
  const base = { n: nAll, nNonZero: n, zeros, statistic: V, conf };
  const useExact = exact ?? (n < 50 && !ties.length && !zeros);
  if (useExact && !ties.length && !zeros) {
    const cdf = signrankCdfTable(n), M = n * (n + 1) / 2;
    const walsh = [];
    for (let i = 0; i < n; i++) for (let j = i; j < n; j++) walsh.push((d[i] + d[j]) / 2);
    walsh.sort((p, q) => p - q);
    let qu = cdfQuantile(cdf, a / 2); if (qu === 0) qu = 1;
    const ql = M - qu;
    return {
      ...base, method: 'Wilcoxon signed rank exact test',
      p: exactTwoSided(cdf, V, M / 2),
      estimate: med(walsh) + mu, ci: [walsh[qu - 1] + mu, walsh[ql] + mu], achievedConf: 1 - 2 * cdfAt(cdf, qu - 1),
    };
  }
  const sigmaOf = (m, t) => Math.sqrt(m * (m + 1) * (2 * m + 1) / 24 - tieSum(t) / 48);
  const z0 = V - n * (n + 1) / 4;
  const z = (z0 - Math.sign(z0) * 0.5) / sigmaOf(n, ties);
  const out = { ...base, method: 'Wilcoxon signed rank test with continuity correction', p: twoSidedZ(z), z };
  const wdiff = (s, zq) => {
    const xd = d.map(v => v - s).filter(v => v !== 0), m = xd.length;
    const r = rank(xd.map(Math.abs));
    const zd = sum(r.ranks.filter((q, i) => xd[i] > 0)) - m * (m + 1) / 4;
    const sg = sigmaOf(m, r.ties);
    return sg > 0 ? (zd - Math.sign(zd) * 0.5) / sg - zq : NaN;
  };
  const lo0 = Math.min(...d), hi0 = Math.max(...d);
  const root = zq => {
    const fl = wdiff(lo0, zq), fu = wdiff(hi0, zq);
    if (!(fl > 0)) return lo0;
    if (!(fu < 0)) return hi0;
    return bisect(s => wdiff(s, zq), lo0, hi0, 100);
  };
  if (n > 1) {
    const zc = qnorm(1 - a / 2);
    out.estimate = root(0) + mu;
    out.ci = [root(zc) + mu, root(-zc) + mu];
  }
  return out;
}

/**
 * Dunn's pairwise z tests on pooled mid-ranks with the tie correction, adjusted
 * by `adjust` (Holm by default). z is the earlier group's mean rank minus the later's.
 */
export function dunnTest(groups, { adjust = 'holm' } = {}) {
  const gs = cleanGroups(groups);
  if (gs.length < 2) return null;
  const all = gs.flatMap(g => g.values), N = all.length;
  const { ranks, ties } = rank(all);
  let at = 0;
  const rg = gs.map(g => { const r = ranks.slice(at, at + g.values.length); at += g.values.length; return { name: g.name, n: r.length, meanRank: mean(r) }; });
  const s2 = N * (N + 1) / 12 - tieSum(ties) / (12 * (N - 1));
  const comps = pairwise(rg.map(g => ({ ...g, values: [] })), () => ({}));
  let c = 0;
  for (let i = 0; i < rg.length; i++) for (let j = i + 1; j < rg.length; j++) {
    const z = (rg[i].meanRank - rg[j].meanRank) / Math.sqrt(s2 * (1 / rg[i].n + 1 / rg[j].n));
    Object.assign(comps[c++], { label: `${rg[i].name} - ${rg[j].name}`, z, pUnadjusted: twoSidedZ(z) });
  }
  const adj = pAdjust(comps.map(x => x.pUnadjusted), adjust);
  comps.forEach((x, i) => { x.p = adj[i]; });
  return { method: `Dunn's test (${adjust} adjustment)`, n: N, meanRanks: rg, comparisons: comps };
}

/** Kruskal–Wallis rank sum test (R kruskal.test), with Dunn post-hoc comparisons (Holm). */
export function kruskalTest(groups, { adjust = 'holm' } = {}) {
  const gs = cleanGroups(groups);
  const kw = kruskalWallis(gs);
  if (!kw) return null;
  return {
    method: 'Kruskal-Wallis rank sum test', n: sum(gs.map(g => g.values.length)),
    statistic: kw.statistic, df: kw.df, p: kw.p, posthoc: dunnTest(gs, { adjust }),
  };
}

/** Friedman rank sum test (R friedman.test) on rows = subjects, columns = conditions; incomplete rows dropped. */
export function friedmanTest(matrix) {
  const rows = (matrix || []).filter(r => r?.length && r.every(isVal)).map(r => r.map(Number));
  if (!rows.length) return null;
  const k = rows[0].length;
  const full = rows.filter(r => r.length === k);
  const n = full.length;
  if (n < 1 || k < 2) return null;
  const R = new Array(k).fill(0);
  let t = 0;
  for (const r of full) { const rr = rank(r); rr.ranks.forEach((v, j) => { R[j] += v; }); t += tieSum(rr.ties); }
  const Q = 12 * sum(R.map(v => (v - n * (k + 1) / 2) ** 2)) / (n * k * (k + 1) - t / (k - 1));
  return { method: 'Friedman rank sum test', n, dropped: (matrix?.length || 0) - n, rankSums: R, statistic: Q, df: k - 1, p: 1 - pchisq(Q, k - 1) };
}

/**
 * Sign test: exact two-sided binomial test (p = 1/2) on the number of positive
 * differences x - y (or x - mu), zeros dropped (R binom.test). The estimate is
 * the median difference with its distribution-free order-statistic interval.
 */
export function signTest(x, y, { mu = 0, conf = 0.95 } = {}) {
  let d;
  if (y) { const [a, b] = pairs(x, y); d = a.map((v, i) => v - b[i] - mu); }
  else d = clean(x).map(v => v - mu);
  const nz = d.filter(v => v !== 0), n = nz.length;
  if (!n) return null;
  const pos = nz.filter(v => v > 0).length;
  const p = Math.min(1, 2 * Math.min(pbinomHalf(pos, n), 1 - pbinomHalf(pos - 1, n)));
  const mci = medianCI(sortNum(d.map(v => v + mu)), conf);
  return {
    method: 'Exact binomial test', n: d.length, nNonZero: n, statistic: pos, p,
    proportion: pos / n, estimate: med(d) + mu, ci: mci.ci, achievedConf: mci.achievedConf, conf,
  };
}

// ---- normality -------------------------------------------------------------

const poly = (c, x) => { let r = 0; for (let i = c.length - 1; i >= 0; i--) r = r * x + c[i]; return r; };

/** Shapiro–Wilk W and p (Royston 1995, AS R94, as R's swilk), 3 ≤ n ≤ 5000. */
export function shapiroWilk(x) {
  const xs = sortNum(clean(x)), n = xs.length;
  if (n < 3 || n > 5000) return null;
  const range = xs[n - 1] - xs[0];
  if (range < 1e-10) return null;
  const nn2 = Math.floor(n / 2), a = new Array(nn2 + 1).fill(0);
  const an = n;
  if (n === 3) a[1] = Math.SQRT1_2;
  else {
    const an25 = an + 0.25;
    let summ2 = 0;
    for (let i = 1; i <= nn2; i++) { a[i] = qnorm((i - 0.375) / an25); summ2 += a[i] * a[i]; }
    summ2 *= 2;
    const ssumm2 = Math.sqrt(summ2), rsn = 1 / Math.sqrt(an);
    const a1 = poly([0, 0.221157, -0.147981, -2.07119, 4.434685, -2.706056], rsn) - a[1] / ssumm2;
    let i1, fac;
    if (n > 5) {
      i1 = 3;
      const a2 = -a[2] / ssumm2 + poly([0, 0.042981, -0.293762, -1.752461, 5.682633, -3.582633], rsn);
      fac = Math.sqrt((summ2 - 2 * a[1] * a[1] - 2 * a[2] * a[2]) / (1 - 2 * a1 * a1 - 2 * a2 * a2));
      a[2] = a2;
    } else {
      i1 = 2;
      fac = Math.sqrt((summ2 - 2 * a[1] * a[1]) / (1 - 2 * a1 * a1));
    }
    a[1] = a1;
    for (let i = i1; i <= nn2; i++) a[i] /= -fac;
  }
  // W as the squared correlation between the scaled data and the coefficients
  const coef = i => { const j = n - 1 - i; return i === j ? 0 : Math.sign(i - j) * a[1 + Math.min(i, j)]; };
  let sa = 0, sx = 0;
  for (let i = 0; i < n; i++) { sa += coef(i); sx += xs[i] / range; }
  sa /= n; sx /= n;
  let ssa = 0, ssx = 0, sax = 0;
  for (let i = 0; i < n; i++) {
    const asa = coef(i) - sa, xsx = xs[i] / range - sx;
    ssa += asa * asa; ssx += xsx * xsx; sax += asa * xsx;
  }
  const ssassx = Math.sqrt(ssa * ssx);
  const w1 = (ssassx - sax) * (ssassx + sax) / (ssa * ssx);
  const W = 1 - w1;
  let p;
  if (n === 3) {
    p = Math.max(0, 1.90985931710274 * (Math.asin(Math.sqrt(W)) - 1.04719755119660));
  } else {
    let y = Math.log(w1), m, s;
    if (n <= 11) {
      const gamma = poly([-2.273, 0.459], an);
      if (y >= gamma) return { method: 'Shapiro-Wilk normality test', n, statistic: W, p: 1e-99 };
      y = -Math.log(gamma - y);
      m = poly([0.544, -0.39978, 0.025054, -6.714e-4], an);
      s = Math.exp(poly([1.3822, -0.77857, 0.062767, -0.0020322], an));
    } else {
      const xx = Math.log(an);
      m = poly([-1.5861, -0.31082, -0.083751, 0.0038915], xx);
      s = Math.exp(poly([-0.4803, -0.082676, 0.0030302], xx));
    }
    p = normUpper((y - m) / s);
  }
  return { method: 'Shapiro-Wilk normality test', n, statistic: W, p };
}

/** Anderson–Darling normality test (nortest::ad.test), n ≥ 8. `statistic` is A; p from the adjusted A*. */
export function andersonDarling(x) {
  const xs = sortNum(clean(x)), n = xs.length;
  if (n < 8) return null;
  const m = mean(xs), sd = Math.sqrt(variance(xs));
  if (!(sd > 0)) return null;
  const z = xs.map(v => (v - m) / sd);
  let h = 0;
  for (let i = 0; i < n; i++) h += (2 * i + 1) * (Math.log(normUpper(-z[i])) + Math.log(normUpper(z[n - 1 - i])));
  const A = -n - h / n;
  const AA = (1 + 0.75 / n + 2.25 / (n * n)) * A;
  const p = AA < 0.2 ? 1 - Math.exp(-13.436 + 101.14 * AA - 223.73 * AA * AA)
    : AA < 0.34 ? 1 - Math.exp(-8.318 + 42.796 * AA - 59.938 * AA * AA)
      : AA < 0.6 ? Math.exp(0.9177 - 4.279 * AA - 1.38 * AA * AA)
        : AA < 10 ? Math.exp(1.2937 - 5.709 * AA + 0.0186 * AA * AA) : 3.7e-24;
  return { method: 'Anderson-Darling normality test', n, statistic: A, p };
}

/**
 * Normal Q–Q points (R qqnorm, plotting positions ppoints) and the qqline
 * through the first and third quartiles.
 */
export function qqPoints(x) {
  const xs = sortNum(clean(x)), n = xs.length;
  if (!n) return null;
  const a = n <= 10 ? 3 / 8 : 1 / 2;
  const points = xs.map((v, i) => ({ theoretical: qnorm((i + 1 - a) / (n + 1 - 2 * a)), sample: v }));
  const q1 = quantile(xs, 0.25), q3 = quantile(xs, 0.75), z1 = qnorm(0.25), z3 = qnorm(0.75);
  const slope = (q3 - q1) / (z3 - z1);
  return { n, points, line: { slope, intercept: q1 - slope * z1 } };
}

// ---- description -----------------------------------------------------------

/**
 * Distribution-free interval for the median from order statistics
 * [x(k), x(n-k+1)], the widest k with P(Bin(n, 1/2) ≤ k-1) ≤ α/2.
 */
function medianCI(sorted, conf) {
  const n = sorted.length, a = alphaOf(conf);
  let k = 0;
  while (k + 1 <= n / 2 && pbinomHalf(k, n) <= a / 2) k++;
  if (k < 1) return { ci: [NaN, NaN], achievedConf: NaN };
  return { ci: [sorted[k - 1], sorted[n - k]], achievedConf: 1 - 2 * pbinomHalf(k - 1, n), ranks: [k, n - k + 1] };
}

/**
 * Descriptive summary with intervals. Skewness and kurtosis are the
 * bias-adjusted type 2 estimators (G1, G2; SPSS, SAS, e1071 type = 2), with
 * SPSS's standard errors; kurtosis is excess kurtosis.
 */
export function describeWithCI(x, { conf = 0.95 } = {}) {
  const xs = sortNum(clean(x)), n = xs.length, missing = (x?.length || 0) - n;
  if (!n) return { n, missing };
  const m = mean(xs), sd = n > 1 ? Math.sqrt(variance(xs)) : NaN, se = sd / Math.sqrt(n);
  const h = n > 1 ? qt(1 - alphaOf(conf) / 2, n - 1) * se : NaN;
  const m2 = xs.reduce((s, v) => s + (v - m) ** 2, 0) / n;
  const m3 = xs.reduce((s, v) => s + (v - m) ** 3, 0) / n;
  const m4 = xs.reduce((s, v) => s + (v - m) ** 4, 0) / n;
  const g1 = m3 / m2 ** 1.5, g2 = m4 / (m2 * m2) - 3;
  const skew = n > 2 ? g1 * Math.sqrt(n * (n - 1)) / (n - 2) : NaN;
  const kurt = n > 3 ? ((n + 1) * g2 + 6) * (n - 1) / ((n - 2) * (n - 3)) : NaN;
  const ses = n > 2 ? Math.sqrt(6 * n * (n - 1) / ((n - 2) * (n + 1) * (n + 3))) : NaN;
  const sek = n > 3 ? 2 * ses * Math.sqrt((n * n - 1) / ((n - 3) * (n + 5))) : NaN;
  const q1 = quantile(xs, 0.25), q3 = quantile(xs, 0.75);
  const mci = medianCI(xs, conf);
  return {
    n, missing, conf,
    mean: { estimate: m, ci: [m - h, m + h], method: 't interval' },
    sd, se,
    median: { estimate: quantile(xs, 0.5), ci: mci.ci, achievedConf: mci.achievedConf, method: 'order statistics (binomial)' },
    q1, q3, iqr: q3 - q1, min: xs[0], max: xs[n - 1],
    skewness: { estimate: skew, se: ses, type: 2 },
    kurtosis: { estimate: kurt, se: sek, type: 2, excess: true },
  };
}

// The submission tracker (scratchpad plan SUBMISSIONS.md; views/submissions.mjs draws it): each journal the manuscript went to, what
// the journal decided and when, and the next step. One attempt is one journal:
//
//   { id, v: 1, journal: { id, label }, manuscriptId, system, file: { rel, name } | null, coverLetter: { rel, name } | null,
//     chaseOn: 'YYYY-MM-DD' | '', chaseTaskId, notes, events: [{ id, at, kind, ...extra }] }
//
// The status of an attempt is the kind of its last event (no separate status field: one source of truth). Dates are days, never
// times: a journal's decision has a date, not a clock. Elapsed days are computed from a `today` the caller passes, never stored.
// state.submissions is read through normaliseSubmissions on load (store.mjs); absent or malformed is an empty list, and an item
// keeps every key it does not know, so an older app never loses what a newer one wrote.
//
// Nothing here writes on its own: a person's dialog or an accepted proposal does (lib/submission-proposals.mjs). No web lookups,
// no status changed by time. Pure: no store, no clock (ids and the time come in through `opts`).
import { makeTask, normaliseTask, patchTask } from './tasks.mjs';
import { day, plural } from './dates.mjs';

/** Event kinds and their words, in the order the Record outcome menu lists them. No submission-system status words (owner, 2026-10-11). */
export const KINDS = Object.freeze([
  ['planned', 'Planned'], ['submitted', 'Submitted'], ['revise', 'Revision requested'], ['revised', 'Revision sent'],
  ['accepted', 'Accepted'], ['rejected', 'Rejected'], ['withdrawn', 'Withdrawn'], ['published', 'Published'],
]);
const WORD = Object.fromEntries(KINDS);
/** An attempt whose last event is one of these is over: nothing is chased, nothing is due. */
const CLOSED = new Set(['rejected', 'withdrawn', 'accepted', 'published']);
/** An attempt that ended without the paper: the next journal is chosen after it. */
export const ENDED = new Set(['rejected', 'withdrawn']);
const SENT = new Set(['submitted', 'revised']);
const LETTER_KINDS = new Set(['revise', 'rejected', 'accepted']);
export const LETTER_MAX = 100000;

const DAY_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
/** A real calendar day as YYYY-MM-DD, or ''. */
export function dayOf(v) {
  const m = DAY_RE.exec(String(v ?? '').trim());
  if (!m) return '';
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return d.getUTCFullYear() === +m[1] && d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3] ? `${m[1]}-${m[2]}-${m[3]}` : '';
}
const utc = d => { const [y, m, dd] = d.split('-').map(Number); return Date.UTC(y, m - 1, dd); };
/** Whole days from one day to another (negative when `to` is earlier), or null when either is not a day. */
const daysBetween = (from, to) => {
  const a = dayOf(from), b = dayOf(to);
  return a && b ? Math.round((utc(b) - utc(a)) / 86400000) : null;
};
const text = (v, max = 400) => (typeof v === 'string' ? v : v == null ? '' : String(v)).slice(0, max);
const nameOfRel = rel => String(rel).slice(String(rel).lastIndexOf('/') + 1);
/** A file of the project folder as { rel, name }, or null. Nothing is copied: the reference points into the folder. */
export function fileRef(x) {
  if (!x || typeof x !== 'object' || typeof x.rel !== 'string' || !x.rel.trim()) return null;
  return { rel: x.rel, name: typeof x.name === 'string' && x.name ? x.name : nameOfRel(x.rel) };
}
const journalOf = j => {
  if (typeof j === 'string') return { id: '', label: text(j, 200).trim() };
  if (!j || typeof j !== 'object') return { id: '', label: '' };
  return { id: text(j.id, 120), label: text(j.label, 200).trim() };
};

function normaliseEvent(e, i) {
  if (!e || typeof e !== 'object' || !WORD[e.kind]) return null;
  const out = { ...e, id: text(e.id, 80) || `e${i + 1}`, kind: e.kind, at: dayOf(e.at) };
  delete out.desk;
  if (e.kind === 'rejected' && e.desk === true) out.desk = true;
  if ('due' in e) out.due = dayOf(e.due);
  for (const k of ['note', 'roundId', 'doi', 'taskId']) if (k in e) out[k] = text(e[k], 400);
  if ('letter' in e) out.letter = text(e.letter, LETTER_MAX);
  if ('file' in e) out.file = fileRef(e.file);
  return out;
}
/** An attempt as this version reads it, every field present; other fields kept as they were. Null for something that is not one. */
export function normaliseAttempt(x, i = 0) {
  if (!x || typeof x !== 'object' || Array.isArray(x)) return null;
  const events = (Array.isArray(x.events) ? x.events : []).map(normaliseEvent).filter(Boolean);
  return {
    ...x, id: text(x.id, 80) || `sb${i + 1}`, v: 1, journal: journalOf(x.journal),
    manuscriptId: text(x.manuscriptId, 200), system: text(x.system, 200),
    file: fileRef(x.file), coverLetter: fileRef(x.coverLetter),
    chaseOn: dayOf(x.chaseOn), chaseTaskId: text(x.chaseTaskId, 80), notes: text(x.notes, 4000),
    // history reads down: oldest first; a day-less event stays where it was put among the others of no day
    events: events.map((e, n) => [e, n]).sort((a, b) => (a[0].at || '').localeCompare(b[0].at || '') || a[1] - b[1]).map(([e]) => e),
  };
}
/** state.submissions as this version reads it: always a list. */
export const normaliseSubmissions = list => (Array.isArray(list) ? list : []).map(normaliseAttempt).filter(Boolean);

/** The word for an event: a rejection without review says so. */
export const wordOf = e => (e?.kind === 'rejected' && e.desk ? 'Rejected without review' : WORD[e?.kind] || '');
/** Where one attempt stands: the kind of its last event, its word and day. */
export function statusOf(a) {
  const last = a?.events?.at?.(-1);
  return last ? { kind: last.kind, word: wordOf(last), at: last.at || '', desk: !!last.desk } : { kind: '', word: '', at: '', desk: false };
}
export const isClosed = a => CLOSED.has(statusOf(a).kind);
const label = a => a?.journal?.label || 'Untitled journal';
const startOf = a => a?.events?.find(e => e.at)?.at || '';
/** The attempts newest first: by the day each began, then the order they were added. */
export function ordered(list) {
  const all = normaliseSubmissions(list);
  return all.map((a, i) => [a, i]).sort((x, y) => (startOf(y[0]) || '').localeCompare(startOf(x[0]) || '') || y[1] - x[1]).map(([a]) => a);
}
/** The attempt the paper is in now: the latest that is not rejected or withdrawn, else the latest. */
export function current(list) {
  const all = ordered(list);
  return all.find(a => !ENDED.has(statusOf(a).kind)) || all[0] || null;
}
/** Days since the manuscript last went to the journal (submitted or revision sent); null when the attempt is closed, planned or undated. */
export function elapsedDays(a, today) {
  if (!a || isClosed(a)) return null;
  const sent = [...(a.events || [])].reverse().find(e => SENT.has(e.kind));
  if (!sent?.at) return null;
  const n = daysBetween(sent.at, today);
  return n == null || n < 0 ? null : n;
}
/** The revision a journal asked for and not yet sent back: the last revise event with no revised after it. */
export function openRevision(a) {
  const ev = a?.events || [];
  for (let i = ev.length - 1; i >= 0; i--) {
    if (ev[i].kind === 'revised') return null;
    if (ev[i].kind === 'revise') return ev[i];
  }
  return null;
}

/** The head's one line: "Submitted · Neuro-Oncology · 42 d", "Rejected without review · 2 journals", "Published · 10.1093/…", or ''. */
export function summaryLine(list, today) {
  const all = normaliseSubmissions(list);
  const a = current(all);
  if (!a) return '';
  const st = statusOf(a);
  if (!st.kind) return label(a);
  if (ENDED.has(st.kind)) return `${st.word} · ${all.length > 1 ? plural(all.length, 'journal') : label(a)}`;
  if (st.kind === 'published') return `Published · ${a.events.at(-1).doi || label(a)}`;
  if (st.kind === 'accepted' || st.kind === 'planned') return `${st.word} · ${label(a)}`;
  const rev = openRevision(a);
  if (st.kind === 'revise') return `${st.word} · ${label(a)}${rev?.due ? ` · due ${day(rev.due, today)}` : ''}`;
  const n = elapsedDays(a, today);
  return `${st.word} · ${label(a)}${n == null ? '' : ` · ${n} d`}`;
}
/** Status words by key for other readers (All projects): the event kinds, and 'rejected-desk' for a rejection without review. */
export const STATUS_LABELS = Object.freeze({ ...WORD, 'rejected-desk': 'Rejected without review' });
/**
 * Where the paper stands, as data for a project summary (lib/dashboard.mjs): { journal, status, since, due, last, doi } of the current
 * attempt, or null with none. `status` is a key of STATUS_LABELS; `since` the day it was last sent (submitted or revision sent); `due` the
 * open revision's due day; `last` the day of the last event; `doi` once published. Dates are days, ''-filled when absent.
 */
export function submissionSummary(list, today) {
  const a = current(list);
  if (!a) return null;
  const st = statusOf(a), sent = [...a.events].reverse().find(e => SENT.has(e.kind));
  return { journal: label(a), status: st.kind === 'rejected' && st.desk ? 'rejected-desk' : st.kind, since: sent?.at || '',
    due: openRevision(a)?.due || '', last: st.at, doi: st.kind === 'published' ? a.events.at(-1).doi || '' : '', line: summaryLine(list, today) };
}
/** The Overview's Submission stage: { state: 'todo' | 'active' | 'done', line }. */
export function stageOf(list, today) {
  const all = normaliseSubmissions(list);
  if (!all.length) return { state: 'todo', line: 'Not submitted' };
  const k = statusOf(current(all)).kind;
  return { state: k === 'accepted' || k === 'published' ? 'done' : 'active', line: summaryLine(all, today) };
}

/**
 * What needs a person, for the Overview (lib/progress.mjs unresolved()): a revision due or overdue (block), a chase day reached and a
 * decision letter not read into comments (gap). Only open attempts: a closed one asks for nothing. Nothing on elapsed time alone.
 * Each is { severity, view: 'submissions', text, attemptId, go? }.
 */
export function attentionItems(list, today) {
  const out = [];
  for (const a of normaliseSubmissions(list)) {
    if (isClosed(a)) continue;
    const rev = openRevision(a);
    const left = rev?.due ? daysBetween(today, rev.due) : null;
    if (left != null) out.push({ severity: 'block', view: 'submissions', attemptId: a.id,
      text: left > 0 ? `Revision due in ${plural(left, 'day')}` : left === 0 ? 'Revision due today' : `Revision overdue by ${plural(-left, 'day')}` });
    const wait = a.chaseOn ? daysBetween(a.chaseOn, today) : null;
    if (wait != null && wait >= 0 && statusOf(a).kind !== 'planned') out.push({ severity: 'gap', view: 'submissions', attemptId: a.id, text: `Chase ${label(a)} (planned ${day(a.chaseOn, today)})` });
    const unread = [...a.events].reverse().find(e => LETTER_KINDS.has(e.kind) && e.letter?.trim() && !e.roundId);
    if (unread) out.push({ severity: 'gap', view: 'submissions', attemptId: a.id, go: 'submissions:read', text: 'Decision letter not read' });
  }
  return out;
}

// ---- edits (each returns a new list; the view and the proposal handler both use them) ----------------------------------------
const idsOf = opts => ({ newId: opts?.newId || (p => `${p}${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`), now: opts?.now || (() => new Date().toISOString()) });
const cleanEvent = (e, newId) => {
  if (!e || !WORD[e.kind]) throw new Error(`Unknown event kind${e?.kind ? ` "${String(e.kind).slice(0, 40)}"` : ''}. Use one of: ${KINDS.map(([k]) => k).join(', ')}.`);
  const out = normaliseEvent({ ...e, id: e.id || newId('e') }, 0);
  for (const k of Object.keys(out)) if (out[k] === '' && k !== 'at') delete out[k];
  if (out.file === null) delete out.file;
  return out;
};
/** A new attempt with its first event (submitted, or planned for a journal chosen next). */
export function addAttempt(list, { journal, at = '', kind = 'submitted', manuscriptId = '', system = '', file = null, coverLetter = null } = {}, opts) {
  const { newId } = idsOf(opts);
  const a = normaliseAttempt({ id: newId('sb'), journal, manuscriptId, system, file, coverLetter, events: [cleanEvent({ kind, at }, newId)] });
  return [...normaliseSubmissions(list), a];
}
/** Adds an event to an attempt, kept in date order. */
export function addEvent(list, attemptId, event, opts) {
  const { newId } = idsOf(opts);
  const e = cleanEvent(event, newId);
  return normaliseSubmissions(list).map(a => a.id === attemptId ? normaliseAttempt({ ...a, events: [...a.events, e] }) : a);
}
export const patchAttempt = (list, attemptId, patch) => normaliseSubmissions(list).map(a => a.id === attemptId ? normaliseAttempt({ ...a, ...patch, id: a.id }) : a);
export const patchEvent = (list, attemptId, eventId, patch) => normaliseSubmissions(list).map(a => a.id !== attemptId ? a
  : normaliseAttempt({ ...a, events: a.events.map(e => e.id === eventId ? { ...e, ...patch, id: e.id } : e) }));
export const removeEvent = (list, attemptId, eventId) => normaliseSubmissions(list).map(a => a.id !== attemptId ? a : normaliseAttempt({ ...a, events: a.events.filter(e => e.id !== eventId) }));
/** Removes an attempt. Its review rounds stay in reviewRounds (only the link goes); its open tasks go at the next syncTasks. */
export const removeAttempt = (list, attemptId) => normaliseSubmissions(list).filter(a => a.id !== attemptId);

// ---- tasks (lib/tasks.mjs): the chase and the revision, real tasks on the Tasks page -------------------------------------------
/**
 * Keeps the two kinds of task a submission makes in the to-do list: "Chase <journal> about <id>" due on chaseOn, and "Send revision to
 * <journal>" due on the open revision's due day. A changed day patches the task's due; a cleared one removes the open task; a task ticked
 * done clears chaseOn (the attempt keeps chaseTaskId, so a second tick never makes a second task); a revision sent marks its task done;
 * an attempt closed or removed loses its open tasks. Returns { todos, submissions }, new lists; the inputs are not touched.
 * The view and the proposal handler call it after every change of state.submissions, and the shell after the to-do list changes.
 */
export function syncTasks(list, todos, opts) {
  const { newId, now } = idsOf(opts);
  const subs = normaliseSubmissions(list).map(a => structuredClone(a));
  let tasks = (Array.isArray(todos) ? todos : []).filter(t => t && typeof t === 'object').map(t => ({ ...t }));
  const byId = id => tasks.find(t => t.id === id) || null;
  const drop = id => { tasks = tasks.filter(t => t.id !== id); };
  const owned = new Set();
  const ensure = (task, want, link) => {
    const make = () => {
      const t = makeTask({ text: want.text, due: want.due, link }, { id: newId('t'), at: now() });
      t.submissionId = want.submissionId; t.submissionTask = want.kind;
      tasks.push(t); owned.add(t.id); return t;
    };
    if (!task) return make();
    owned.add(task.id);
    if (!task.done && (task.due !== want.due || task.text !== want.text)) patchTask(tasks, task.id, { due: want.due, text: want.text });
    return task;
  };
  for (const a of subs) {
    const name = label(a), link = { view: 'submissions', label: name }, closed = isClosed(a);
    // the chase
    const chase = a.chaseTaskId ? byId(a.chaseTaskId) : null;
    if (chase?.done) { owned.add(chase.id); a.chaseOn = ''; }
    else if (a.chaseOn && !closed) a.chaseTaskId = ensure(chase, { text: a.manuscriptId ? `Chase ${name} about ${a.manuscriptId}` : `Chase ${name}`, due: a.chaseOn, submissionId: a.id, kind: 'chase' }, link).id;
    else if (chase) drop(chase.id);
    // the revision
    for (const e of a.events.filter(x => x.kind === 'revise')) {
      const t = e.taskId ? byId(e.taskId) : null, open = openRevision(a) === e;
      if (t?.done) { owned.add(t.id); continue; }
      if (open && e.due && !closed) e.taskId = ensure(t, { text: `Send revision to ${name}`, due: e.due, submissionId: a.id, kind: 'revision' }, link).id;
      else if (t && !open && !closed) { owned.add(t.id); patchTask(tasks, t.id, { done: true }, { now: () => new Date(now()) }); }
      else if (t) drop(t.id);
    }
  }
  // a task this tracker made for an attempt that is gone (or no longer wants it) goes while it is open
  tasks = tasks.filter(t => !t.submissionId || owned.has(t.id) || normaliseTask(t).done);
  return { todos: tasks, submissions: subs };
}

// ---- the assistant (lib/submission-proposals.mjs files them; lib/chat-tools.mjs exposes them) ----------------------------------
/** The attempts for list_submissions: status, dates, events; letters cut to 2,000 characters. */
export function listForAssistant(list, today) {
  const all = ordered(list);
  return {
    summary: summaryLine(all, today), total: all.length,
    items: all.map(a => ({ id: a.id, journal: label(a), manuscript_id: a.manuscriptId, system: a.system, status: statusOf(a).word,
      file: a.file?.name || '', chase_on: a.chaseOn, elapsed_days: elapsedDays(a, today),
      events: a.events.map(e => ({ id: e.id, kind: e.kind, word: wordOf(e), at: e.at, ...(e.due ? { due: e.due } : {}), ...(e.note ? { note: e.note } : {}),
        ...(e.doi ? { doi: e.doi } : {}), ...(e.letter ? { letter: e.letter.length > 2000 ? `${e.letter.slice(0, 2000)}…` : e.letter } : {}), ...(e.roundId ? { read_into_round: true } : {}) })) })),
    note: 'Recorded by the person. Nothing here was looked up; a proposal needs the quoted email or letter.',
  };
}
/**
 * Validates an assistant's proposal { attemptId?, journal?, event: { kind, at, due?, doi?, note?, letter?, desk? }, source } against the
 * list. Returns { error } with the reason, or { data, label, detail } where data is what applyProposal writes (never chaseOn: a follow-up
 * date is the person's decision) and label reads "Submission · Neuro-Oncology · Rejected · 3 Oct".
 */
export function proposalFor(payload, list, today) {
  const p = payload && typeof payload === 'object' ? payload : {};
  const source = text(p.source, 4000).trim();
  const e = p.event && typeof p.event === 'object' ? p.event : {};
  if (!WORD[e.kind]) return { error: `Unknown event kind "${text(e.kind, 40)}". Use one of: ${KINDS.map(([k]) => k).join(', ')}.` };
  const at = dayOf(e.at);
  if (!at) return { error: 'The event needs its date as YYYY-MM-DD, as the letter or email states it. Do not infer a date.' };
  if (dayOf(today) && at > dayOf(today)) return { error: 'The date is in the future. A decision has happened; use the date the letter or email states.' };
  if ('due' in e && e.due && !dayOf(e.due)) return { error: 'The response due date must be YYYY-MM-DD.' };
  if (source.length < 3) return { error: 'Quote the email or letter the person gave in this chat as source.' };
  const all = normaliseSubmissions(list);
  const a = p.attemptId ? all.find(x => x.id === p.attemptId) : null;
  if (p.attemptId && !a) return { error: `No submission "${text(p.attemptId, 40)}"; use an id from list_submissions.` };
  const journal = a ? a.journal : journalOf(p.journal);
  if (!a && !journal.label) return { error: 'Name the journal for a new submission, or give attemptId from list_submissions.' };
  const event = { kind: e.kind, at };
  if (e.kind === 'rejected' && e.desk === true) event.desk = true;
  if (dayOf(e.due) && e.kind === 'revise') event.due = dayOf(e.due);
  for (const k of ['note', 'doi']) if (typeof e[k] === 'string' && e[k].trim()) event[k] = text(e[k], 400).trim();
  if (typeof e.letter === 'string' && e.letter.trim()) event.letter = text(e.letter, LETTER_MAX);
  const data = { ...(a ? { attemptId: a.id } : { journal }), event, source };
  return { data, label: `Submission · ${journal.label} · ${wordOf(event)} · ${day(at, today)}`, detail: source };
}
/** Writes an accepted proposal: an event on its attempt, or a new attempt starting with it. */
export function applyProposal(list, data, opts) {
  if (data?.attemptId) {
    if (!normaliseSubmissions(list).some(a => a.id === data.attemptId)) throw new Error('That submission was removed. Ask for an updated proposal.');
    return addEvent(list, data.attemptId, data.event, opts);
  }
  const { newId } = idsOf(opts);
  const a = normaliseAttempt({ id: newId('sb'), journal: data.journal, events: [cleanEvent(data.event, newId)] });
  return [...normaliseSubmissions(list), a];
}

// The pure part of lib/swim.mjs: the directions, the combining rule, the sign test, the effect-direction rows, the risk-of-bias level and the nine reporting
// items. lib/swim-state.mjs (read by the store on every load) imports these; the harvest plot drawing stays in lib/swim.mjs and loads with the page that draws it.

export const DIRECTIONS = ['benefit', 'harm', 'no clear', 'mixed'];
const MARK = { benefit: '▲', harm: '▼', 'no clear': '◄►', mixed: '◄►' };

/**
 * Several results in one study and outcome domain combine by the rule of
 * Thomson & Thomas: 70% or more in one direction gives that direction;
 * otherwise the domain is mixed. Results with no clear direction count in the
 * denominator; only when every result is "no clear" is the domain "no clear".
 */
export function combineDirections(list) {
  const d = list.filter(x => DIRECTIONS.includes(x));
  if (!d.length) return '';
  if (d.length === 1) return d[0];
  if (d.every(x => x === 'no clear')) return 'no clear';
  for (const x of ['benefit', 'harm']) if (d.filter(y => y === x).length / d.length >= 0.7) return x;
  return 'mixed';
}

const lchoose = (n, k) => { let s = 0; for (let i = 1; i <= k; i++) s += Math.log(n - k + i) - Math.log(i); return s; };

/**
 * Exact two-sided sign test: `benefit` of `n` studies with a clear direction,
 * against 0.5. p = min(1, 2 · P(X ≤ min(benefit, harm))).
 */
export function signTest(benefit, harm) {
  const n = benefit + harm;
  if (!n) return { n: 0, benefit, harm, p: null };
  const m = Math.min(benefit, harm);
  let tail = 0;
  for (let k = 0; k <= m; k++) tail += Math.exp(lchoose(n, k) - n * Math.LN2);
  return { n, benefit, harm, p: Math.min(1, 2 * tail) };
}

/**
 * The effect direction table: one row per study, a direction per outcome
 * domain, with per-outcome vote counts and a sign test on benefit against harm
 * (studies with no clear or mixed direction are left out of the test, as in
 * the effect direction plot).
 * rows: [{ study, outcome, direction, n?, rob? }]
 */
export function effectDirection(rows = []) {
  const studies = [], outcomes = [];
  const cells = new Map(), meta = new Map();
  for (const r of rows) {
    const study = String(r?.study ?? '').trim(), outcome = String(r?.outcome ?? '').trim();
    if (!study || !outcome || !DIRECTIONS.includes(r.direction)) continue;
    if (!studies.includes(study)) studies.push(study);
    if (!outcomes.includes(outcome)) outcomes.push(outcome);
    const key = `${study}\u0000${outcome}`;
    (cells.get(key) || cells.set(key, []).get(key)).push(r.direction);
    const m = meta.get(study) || meta.set(study, {}).get(study);
    if (m.n == null && Number.isFinite(Number(r.n)) && r.n !== '' && r.n != null) m.n = Number(r.n);
    if (m.rob == null && r.rob) m.rob = String(r.rob);
  }
  const table = studies.map(study => ({
    study, n: meta.get(study).n ?? null, rob: meta.get(study).rob ?? '',
    directions: Object.fromEntries(outcomes.map(o => [o, combineDirections(cells.get(`${study}\u0000${o}`) || [])])),
    results: Object.fromEntries(outcomes.map(o => [o, (cells.get(`${study}\u0000${o}`) || []).length])),
  }));
  const byOutcome = outcomes.map(outcome => {
    const v = { benefit: 0, harm: 0, 'no clear': 0, mixed: 0 };
    for (const t of table) if (t.directions[outcome]) v[t.directions[outcome]]++;
    const k = v.benefit + v.harm + v['no clear'] + v.mixed;
    return { outcome, k, votes: v, signTest: signTest(v.benefit, v.harm),
      text: `${v.benefit} of ${k} studies favour the intervention, ${v.harm} favour the comparator, ${v['no clear'] + v.mixed} show no clear or mixed direction` };
  });
  const votes = { benefit: 0, harm: 0, 'no clear': 0, mixed: 0 };
  for (const o of byOutcome) for (const k of DIRECTIONS) votes[k] += o.votes[k];
  return { studies, outcomes, table, byOutcome, votes, marks: MARK };
}


/** Risk-of-bias level of a judgement in any shipped instrument's vocabulary: 'low' | 'some' | 'high' | ''. */
export function robLevel(v) {
  const t = String(v ?? '').trim().toLowerCase();
  if (!t) return '';
  if (/^(low|good)$/.test(t)) return 'low';
  if (/^(high|very high|serious|critical|poor)$/.test(t)) return 'high';
  if (/^(some concerns|moderate|unclear|fair|can't tell)$/.test(t)) return 'some';
  return '';
}

